local __library_sources = {}
__library_sources["core"] = function(...)
-- core v2 (source version 0.2). Edit this file for this version.
-- Libraries: {}
local __external_require = ...
local __modules, __cache, __loading = {}, {}, {}
local function require(name)
    if __cache[name] ~= nil then return __cache[name] end
    if not __modules[name] then
        assert(__external_require, "Missing library dependency: " .. tostring(name))
        return __external_require(name)
    end
    assert(not __loading[name], "Circular library dependency: " .. name)
    __loading[name] = true
    local ok, result = pcall(__modules[name], require)
    __loading[name] = nil
    if not ok then error(result, 2) end
    if result == nil then result = true end
    __cache[name] = result
    return result
end

__modules["core/Config"] = function(require)
local Util = require("core/Util")
local Signal = require("core/Signal")
local Scope = require("core/Scope")
local Config = {}
Config.__index = Config

function Config.new(options)
    local self = setmetatable({
        path = options.path, storage = options.storage, codec = options.codec,
        defaults = Util.copy(options.defaults), scope = Scope.new(), Changed = Signal.new(),
        dirty = false, revision = 0, pending = nil, lastError = nil,
        migrate = options.migrate, validate = options.validate,
    }, Config)
    self.data = Util.copy(self.defaults)
    self.scope:Add(self.Changed)
    self:Load()
    return self
end

function Config:Load()
    if not self.storage then return false end
    local ok, result = pcall(function()
        if not self.storage.exists(self.path) then return nil end
        local decoded = self.codec.decode(self.storage.read(self.path))
        assert(type(decoded) == "table", "Config must be an object")
        return self.migrate and self.migrate(decoded) or decoded
    end)
    if ok then
        self.data = Util.merge(self.defaults, result)
        if self.validate then self.validate(self.data) end
        return true
    end
    -- Do not overwrite a corrupted/user-edited file during loading.
    self.lastError = tostring(result)
    warn("[SaintHub config] " .. self.lastError)
    return false
end

function Config:Get(path)
    return Util.get(self.data, path)
end

function Config:Set(path, value)
    if not self.scope.alive or self:Get(path) == value then return false end
    local default = Util.get(self.defaults, path)
    assert(default ~= nil and type(value) == type(default), "Invalid config value: " .. path)
    Util.set(self.data, path, value)
    if self.validate then self.validate(self.data) end
    self.dirty = true
    self.revision = self.revision + 1
    self:Save()
    self.Changed:Fire(path, self:Get(path))
    return true
end

function Config:Save()
    if not self.storage or not self.scope.alive then return end
    if self.pending then return end
    self.pending = self.scope:Delay(0.4, function()
        self.pending = nil
        self:Flush()
    end)
end

-- Replace a validated snapshot atomically; listeners never see half-imported state.
function Config:Apply(data)
    if not self.scope.alive or type(data) ~= "table" then return false end
    local nextData = Util.merge(self.defaults, data)
    if self.validate then self.validate(nextData) end
    local changes = {}
    local function visit(before, after, path)
        for key, value in pairs(after) do
            local current = path == "" and tostring(key) or path .. "." .. tostring(key)
            if type(value) == "table" then visit(before[key] or {}, value, current)
            elseif before[key] ~= value then changes[#changes + 1] = {current, value} end
        end
    end
    visit(self.data, nextData, "")
    if #changes == 0 then return true end
    self.data, self.dirty, self.revision = nextData, true, self.revision + 1
    self:Save()
    table.sort(changes, function(a, b) return a[1] < b[1] end)
    for _, change in ipairs(changes) do self.Changed:Fire(change[1], change[2]) end
    return true
end

function Config:Flush()
    if not self.dirty or not self.storage then return true end
    local revision = self.revision
    local ok, message = pcall(function()
        self.storage.write(self.path, self.codec.encode(self.data))
    end)
    if ok then
        if revision == self.revision then self.dirty = false end
        self.lastError = nil
    else
        self.lastError = tostring(message)
        warn("[SaintHub config] " .. self.lastError)
    end
    return ok
end

function Config:Destroy()
    if not self.scope.alive then return end
    self:Flush()
    self.scope:Destroy()
end

return Config
end

__modules["core/HTTP"] = function(require)
-- Executor adapters keep the rest of the app independent of response spelling.
local HTTP = {}

local function firstFunction(...)
    for index = 1, select("#", ...) do
        local value = select(index, ...)
        if type(value) == "function" then return value end
    end
end

local function member(value, name)
    return type(value) == "table" and value[name] or nil
end

function HTTP.request(env, globals)
    env, globals = env or {}, globals or {}
    return firstFunction(env.request, env.http_request, env.httprequest, env.krnl_request, env.secure_request,
        member(env.http, "request"), member(env.syn, "request"), member(env.fluxus, "request"),
        globals.request, globals.http_request, globals.httprequest, globals.krnl_request, globals.secure_request,
        member(globals.http, "request"), member(globals.syn, "request"), member(globals.fluxus, "request"))
end

function HTTP.response(response)
    assert(type(response) == "table", "Invalid HTTP response")
    local status = tonumber(response.StatusCode or response.statusCode or response.status_code or response.Status or response.status)
    if status == 0 and response.Success == false then
        error("HTTP connection failed", 0)
    end
    if not status or status % 1 ~= 0 or status < 100 or status > 599 then status = 0 end
    local body = response.Body or response.body or response.ResponseBody or response.responseBody or ""
    local headers = response.Headers or response.headers or {}
    return status, type(body) == "string" and body or "", type(headers) == "table" and headers or {}
end

return HTTP
end

__modules["core/init"] = function(require)
local Core = {
    Signal = require("core/Signal"),
    Scope = require("core/Scope"),
    Scheduler = require("core/Scheduler"),
    Config = require("core/Config"),
    Util = require("core/Util"),
    Transfer = require("core/Transfer"),
}
return Core
end

__modules["core/Scheduler"] = function(require)
local Scope = require("core/Scope")
local Scheduler = {}
Scheduler.__index = Scheduler

function Scheduler.new(scope)
    return setmetatable({ scope = scope or Scope.new(), jobs = {} }, Scheduler)
end

-- No Heartbeat connection, overlapping invocations, or loops for disabled jobs.
function Scheduler:Set(name, interval, callback, immediate)
    self:Remove(name)
    assert(interval > 0, "Scheduler interval must be positive")
    local scope = self.scope:Child()
    self.jobs[name] = scope
    scope:Add(function() if self.jobs[name] == scope then self.jobs[name] = nil end end)
    local tick
    tick = function()
        if not scope.alive then return end
        local ok, message = pcall(callback)
        if not ok then warn("[SaintHub " .. name .. "] " .. tostring(message)) end
        if scope.alive then scope:Delay(interval, tick) end
    end
    scope:Delay(immediate and 0 or interval, tick)
end

function Scheduler:Remove(name)
    local job = self.jobs[name]
    if job then job:Destroy() end
end

function Scheduler:Destroy()
    self.scope:Destroy()
end

return Scheduler
end

__modules["core/Scope"] = function(require)
-- Owns connections, instances, tasks, child scopes and cleanup callbacks.
local Scope = {}
Scope.__index = Scope

function Scope.new(errorHandler)
    return setmetatable({ alive = true, resources = {}, serial = 0, errorHandler = errorHandler }, Scope)
end

function Scope:SetErrorHandler(handler)
    self.errorHandler = type(handler) == "function" and handler or nil
    return self
end

function Scope:_Report(stage, message)
    if self.errorHandler then
        local ok, handlerError = pcall(self.errorHandler, stage, message)
        if not ok then warn("[SaintHub error handler] " .. tostring(handlerError)) end
    end
    warn("[SaintHub " .. tostring(stage) .. "] " .. tostring(message))
end

local function clean(resource)
    local kind = typeof(resource)
    if kind == "RBXScriptConnection" then resource:Disconnect()
    elseif kind == "Instance" then resource:Destroy()
    elseif kind == "thread" then
        if resource ~= coroutine.running() and coroutine.status(resource) ~= "dead" then task.cancel(resource) end
    elseif type(resource) == "function" then resource()
    elseif type(resource) == "table" and resource.Destroy then resource:Destroy()
    end
end

function Scope:Add(resource)
    if not self.alive then
        local ok, message = pcall(clean, resource)
        if not ok then self:_Report("cleanup", message) end
        return resource, nil
    end
    self.serial = self.serial + 1
    self.resources[self.serial] = resource
    return resource, self.serial
end

function Scope:Remove(id, dispose)
    if id == nil then return end
    local resource = self.resources[id]
    self.resources[id] = nil
    if dispose and resource then pcall(clean, resource) end
end

function Scope:Connect(signal, callback)
    return self:Add(signal:Connect(function(...)
        if self.alive then
            local ok, message = pcall(callback, ...)
            if not ok then self:_Report("callback", message) end
        end
    end))
end

function Scope:Child()
    local child = Scope.new(self.errorHandler)
    local _, id = self:Add(child)
    child:Add(function() self:Remove(id) end)
    return child
end

function Scope:Delay(seconds, callback)
    if not self.alive then return nil end
    local id
    local thread = task.delay(seconds, function()
        if self.alive then
            local ok, message = pcall(callback)
            if not ok then self:_Report("task", message) end
        end
        self:Remove(id)
    end)
    local resource
    resource, id = self:Add(thread)
    return thread
end

function Scope:Spawn(callback)
    -- defer avoids the task completing before its ownership ID is assigned.
    return self:Delay(0, callback)
end

function Scope:Destroy()
    if not self.alive then return end
    self.alive = false
    local resources = self.resources
    self.resources = {}
    local ids = {}
    for id in pairs(resources) do ids[#ids + 1] = id end
    table.sort(ids, function(a, b) return a > b end)
    for _, id in ipairs(ids) do
        local ok, message = pcall(clean, resources[id])
        if not ok then self:_Report("cleanup", message) end
    end
end

return Scope
end

__modules["core/SessionLogs"] = function(require)
local SessionLogs = {}
SessionLogs.__index = SessionLogs

local MAX_BYTES, MAX_FILES, MAX_FIELDS = 512 * 1024, 30, 48
local FILE_PATTERN = "^session%-%d%d%d%d%d%d%d%dT%d%d%d%d%d%dZ%-%d%d%d%d%d%d%.log$"
local LEVELS = {DEBUG = true, INFO = true, WARN = true, ERROR = true}
local RESERVED = {timestamp = true, level = true, event = true, seq = true, session_ms = true}

local function label(value)
    return type(value) == "string" and #value <= 64 and value:match("^[%a][%w_%-]*$") ~= nil
end

local function fieldName(value)
    return type(value) == "string" and #value <= 64 and value:match("^[%a][%w_%.%-]*$") ~= nil
end

local function valueType(value)
    if type(typeof) == "function" then
        local ok, kind = pcall(typeof, value)
        if ok and type(kind) == "string" then return kind end
    end
    return type(value)
end

local function sensitive(name)
    name = name:lower()
    return name == "key" or name:find("password", 1, true) ~= nil or name:find("secret", 1, true) ~= nil
        or name:find("token", 1, true) ~= nil or name:find("cookie", 1, true) ~= nil
        or name:find("authorization", 1, true) ~= nil or name:find("credential", 1, true) ~= nil
        or name:sub(-4) == "_url" or name:sub(-4) == ".url"
end

local function redact(value)
    local text = tostring(value or "")
    text = text:gsub("[%z\1-\8\11\12\14-\31\127]", "?")
    text = text:gsub("[\r\n\t]+", " "):gsub("%s%s+", " ")
    text = text:gsub("https?://[^%s\"']+", "<redacted_url>")
    text = text:gsub("/api/v?%d*/?webhooks/%d+/[%w_%-]+", "/api/webhooks/<redacted>")
    text = text:gsub("%d%d%d%d%d+:[%w_%-]+", "<redacted_token>")
    if #text > 1024 then text = text:sub(1, 1021) .. "..." end
    return text
end

local function quote(value)
    return '"' .. value:gsub("\\", "\\\\"):gsub('"', '\\"') .. '"'
end

local function scalar(name, value)
    if sensitive(name) then return "<redacted>" end
    local kind = type(value)
    if kind == "string" then return redact(value) end
    if kind == "boolean" then return value end
    if kind == "number" then
        if value ~= value or value == math.huge or value == -math.huge then return tostring(value) end
        return value
    end
    if value == nil then return nil end
    return "<" .. valueType(value) .. ">"
end

local function copyFields(source)
    local result = {}
    if type(source) == "table" and getmetatable(source) == nil then
        local count = 0
        for key, value in pairs(source) do
            if fieldName(key) and not RESERVED[key] then
                count = count + 1
                if count > MAX_FIELDS then break end
                result[key] = scalar(key, value)
            end
        end
    end
    return result
end

local function merge(target, source)
    for key, value in pairs(copyFields(source)) do
        if target[key] == nil then target[key] = value end
    end
end

function SessionLogs.new(context)
    local self = setmetatable({
        scope = context.scope:Child(), config = context.config, path = context.path,
        storage = context.runtime:Storage(), startedClock = os.clock(), startedTime = os.time(),
        context = context.context, contents = "", sequence = 0, part = 1,
        sessionId = string.format("%08x", math.random(0, 0x7fffffff)),
    }, SessionLogs)
    if self.config.Changed then
        self.scope:Connect(self.config.Changed, function(path, enabled)
            if path == "settings.sessionLogs" and enabled == true then
                self:Info("logging_enabled", {format = 2})
            end
        end)
    end
    self:Info("session_started", {format = 2})
    return self
end

function SessionLogs:Enabled()
    return self.scope.alive and self.storage ~= nil and self.config:Get("settings.sessionLogs") == true
end

function SessionLogs:_Prune(keep)
    local storage = self.storage
    if not storage or not storage.list or not storage.delete then return false, 0 end
    local ok, entries = pcall(storage.list, self.path)
    if not ok or type(entries) ~= "table" then return false, 0 end
    local files, seen = {}, {}
    for _, entry in ipairs(entries) do
        local normalized = type(entry) == "string" and entry:gsub("\\", "/")
        local name = normalized and normalized:match("([^/]+)$")
        local full = name and self.path .. "/" .. name
        local owned = full and (normalized == name or normalized == full or normalized:sub(-#full - 1) == "/" .. full)
        if owned and name ~= self.filename and name:match(FILE_PATTERN) and not seen[name] then
            files[#files + 1], seen[name] = name, true
        end
    end
    table.sort(files, function(a, b) return a > b end)
    local success, removed = true, 0
    for index = keep + 1, #files do
        local deleted, result = pcall(storage.delete, self.path .. "/" .. files[index])
        if deleted and result ~= false then removed = removed + 1 else success = false end
    end
    return success, removed
end

function SessionLogs:ClearOld()
    if not self.scope.alive then return false, 0 end
    return self:_Prune(0)
end

function SessionLogs:_Filename()
    if self.filename then return self.filename end
    local prefix = "session-" .. os.date("!%Y%m%dT%H%M%SZ", self.startedTime)
    for _ = 1, 8 do
        local candidate = string.format("%s-%06d.log", prefix, math.random(0, 999999))
        local ok, exists = pcall(self.storage.exists, self.path .. "/" .. candidate)
        if not ok then self.lastError = "exists_failed"; return nil end
        if not exists then self.filename = candidate; return candidate end
    end
    self.lastError = "filename_failed"
end

function SessionLogs:_Fields(fields)
    local result = copyFields(fields)
    if type(self.context) == "function" then
        local ok, current = pcall(self.context)
        if ok then merge(result, current) else result.context = "unavailable" end
    end
    result.session_id, result.part = self.sessionId, self.part
    return result
end

function SessionLogs:_Line(level, event, fields)
    self.sequence = self.sequence + 1
    local columns = {
        os.date("!%Y-%m-%dT%H:%M:%SZ"),
        "level=" .. level,
        "event=" .. event,
        "seq=" .. tostring(self.sequence),
        "session_ms=" .. tostring(math.max(0, math.floor((os.clock() - self.startedClock) * 1000 + 0.5))),
    }
    local rendered = self:_Fields(fields)
    local keys = {}
    for key, value in pairs(rendered) do if value ~= nil then keys[#keys + 1] = key end end
    table.sort(keys)
    for _, key in ipairs(keys) do
        local value = rendered[key]
        local encoded
        if type(value) == "number" or type(value) == "boolean" then encoded = tostring(value)
        else encoded = quote(tostring(value)) end
        columns[#columns + 1] = key .. "=" .. encoded
    end
    return table.concat(columns, " ") .. "\n"
end

function SessionLogs:_Write(line)
    if #self.contents + #line > MAX_BYTES then
        self.filename, self.contents, self.part = nil, "", self.part + 1
    end
    local filename = self:_Filename()
    if not filename then return false end
    local contents = self.contents .. line
    local ok, result = pcall(self.storage.write, self.path .. "/" .. filename, contents)
    if not ok or result == false then self.lastError = "write_failed"; return false end
    local firstWrite = self.contents == ""
    self.contents, self.lastError = contents, nil
    if firstWrite then self:_Prune(MAX_FILES - 1) end
    return true
end

-- Backwards compatible: Record("event", "code") still works. New callers pass a field table and level.
function SessionLogs:Record(event, fields, level)
    level = level or "INFO"
    if not self:Enabled() or not label(event) or not LEVELS[level] then return false end
    if type(fields) == "string" then fields = {code = fields}
    elseif fields ~= nil and type(fields) ~= "table" then fields = {value = fields} end
    return self:_Write(self:_Line(level, event, fields))
end

function SessionLogs:Debug(event, fields) return self:Record(event, fields, "DEBUG") end
function SessionLogs:Info(event, fields) return self:Record(event, fields, "INFO") end
function SessionLogs:Warn(event, fields) return self:Record(event, fields, "WARN") end

function SessionLogs:Error(event, failure, fields)
    local details = copyFields(fields)
    local kind = type(failure)
    details.error_type = valueType(failure)
    if kind == "table" and getmetatable(failure) == nil then
        for _, key in ipairs({"code", "status", "discordCode", "attempts", "reason", "message", "error"}) do
            if failure[key] ~= nil and details[key] == nil then details[key] = scalar(key, failure[key]) end
        end
    elseif failure ~= nil then
        local message = redact(failure)
        if label(message) then details.code = details.code or message else details.message = message end
    end
    return self:Record(event, details, "ERROR")
end

function SessionLogs:Destroy()
    if self:Enabled() then self:Info("session_finished") end
    self.scope:Destroy()
end

return SessionLogs
end

__modules["core/Signal"] = function(require)
local Signal = {}
Signal.__index = Signal

function Signal.new()
    return setmetatable({ listeners = {}, serial = 0, alive = true }, Signal)
end

function Signal:Connect(callback)
    assert(self.alive, "Signal is destroyed")
    self.serial = self.serial + 1
    local id, signal = self.serial, self
    self.listeners[id] = callback
    local connection = { Connected = true }
    function connection:Disconnect()
        if not self.Connected then return end
        self.Connected = false
        signal.listeners[id] = nil
    end
    connection.Destroy = connection.Disconnect
    return connection
end

function Signal:Fire(...)
    if not self.alive then return end
    local snapshot = {}
    for id, callback in pairs(self.listeners) do snapshot[#snapshot + 1] = {id, callback} end
    table.sort(snapshot, function(a, b) return a[1] < b[1] end)
    for _, entry in ipairs(snapshot) do
        if self.listeners[entry[1]] == entry[2] then
            local ok, message = pcall(entry[2], ...)
            if not ok then warn("[SaintHub signal] " .. tostring(message)) end
        end
    end
end

function Signal:Destroy()
    self.alive = false
    self.listeners = {}
end

return Signal
end

__modules["core/Transfer"] = function(require)
local Util = require("core/Util")
local Transfer = {}
Transfer.__index = Transfer

local SECRET_KEYS = {auth = true, authentication = true, credentials = true, password = true,
    secret = true, token = true, accesstoken = true, authtoken = true, apikey = true,
    licensekey = true, savedkey = true, rememberkey = true, key = true, cookie = true}

local function forbidden(key)
    return type(key) == "string" and SECRET_KEYS[key:lower():gsub("[^%w]", "")] == true
end

local function schemaCopy(value)
    if type(value) ~= "table" then return value end
    local result = {}
    for key, item in pairs(value) do if not forbidden(key) then result[key] = schemaCopy(item) end end
    return result
end

local function pathFor(path, key)
    return path == "" and tostring(key) or path .. "." .. tostring(key)
end

-- Codec output must still be plain JSON data, including unknown fields we will strip.
local function jsonData(value, maxBytes)
    local seen, nodes = {}, 0
    local function visit(item, depth)
        nodes = nodes + 1
        if nodes > 20000 or depth > 32 then return false, "too_complex" end
        local kind = type(item)
        if kind == "table" then
            if getmetatable(item) ~= nil or seen[item] then return false, "invalid_data" end
            seen[item] = true
            local numeric, strings, count = false, false, 0
            for key, child in pairs(item) do
                count = count + 1
                if type(key) == "string" then
                    strings = true
                    if #key > maxBytes then return false, "too_large" end
                elseif type(key) == "number" and key >= 1 and key % 1 == 0 and key <= 20000 then
                    numeric = true
                else return false, "invalid_data" end
                local ok, message = visit(child, depth + 1)
                if not ok then return false, message end
            end
            if numeric and strings then return false, "invalid_data" end
            if numeric then for index = 1, count do if item[index] == nil then return false, "invalid_data" end end end
            seen[item] = nil
            return true
        elseif kind == "number" then
            return item == item and math.abs(item) ~= math.huge, "invalid_data"
        elseif kind == "string" then
            return #item <= maxBytes, "too_large"
        elseif kind == "boolean" then return true
        end
        return false, "invalid_data"
    end
    return visit(value, 0)
end

local function checkTypes(defaults, data, path, allowNumericMigration)
    if data == nil then return true end
    if type(defaults) ~= type(data) then
        local before, after = type(data), type(defaults)
        if allowNumericMigration and ((before == "string" and after == "number") or (before == "number" and after == "string")) then return true end
        return false, "invalid_type: " .. (path == "" and "root" or path)
    end
    if type(defaults) == "table" then
        for key, value in pairs(defaults) do
            local ok, message = checkTypes(value, data[key], pathFor(path, key), allowNumericMigration)
            if not ok then return false, message end
        end
    end
    return true
end

local function knownRoot(defaults, data)
    for key in pairs(data) do
        if defaults[key] == nil then return false, "unknown_field: " .. tostring(key) end
    end
    return true
end

-- Export emits a plain config object, not executable Lua or a live Config reference.
-- Defaults are the allow-list; nested unknown/auth fields are never exported.
function Transfer.new(options)
    options = options or {}
    assert(type(options.defaults) == "table", "Transfer defaults must be an object")
    local maxBytes = options.maxBytes or 128 * 1024
    assert(type(maxBytes) == "number" and maxBytes >= 1 and maxBytes < math.huge and maxBytes % 1 == 0, "Invalid transfer byte limit")
    -- Validate before copying: copying would erase metatables and recurse on cycles.
    local valid = jsonData(options.defaults, maxBytes)
    assert(valid, "Transfer defaults must be plain JSON data")
    local defaults = schemaCopy(options.defaults)
    return setmetatable({defaults = defaults, codec = options.codec, validate = options.validate,
        migrate = options.migrate, maxBytes = maxBytes}, Transfer)
end

function Transfer:_Normalize(data, importing)
    if type(data) ~= "table" then return nil, "invalid_object" end
    local valid, message = jsonData(data, self.maxBytes)
    if not valid then return nil, message end
    if importing then
        valid, message = knownRoot(self.defaults, data)
        if not valid then return nil, message end
    end
    valid, message = checkTypes(self.defaults, data, "", importing and self.migrate ~= nil)
    if not valid then return nil, message end
    data = Util.copy(data)
    if importing and self.migrate then
        local ok, migrated = pcall(self.migrate, data)
        if not ok or type(migrated) ~= "table" then
            self.lastError = tostring(migrated)
            return nil, "migration_failed"
        end
        data = migrated
        valid, message = jsonData(data, self.maxBytes)
        if not valid then return nil, message end
        valid, message = knownRoot(self.defaults, data)
        if not valid then return nil, message end
    end
    valid, message = checkTypes(self.defaults, data, "", false)
    if not valid then return nil, message end
    data = Util.merge(self.defaults, data)
    if self.validate then
        local ok, result, detail = pcall(self.validate, data)
        if not ok or result == false then
            self.lastError = tostring(ok and detail or result)
            return nil, "validation_failed"
        end
        if type(result) == "table" then data = result end
        valid, message = jsonData(data, self.maxBytes)
        if not valid then return nil, message end
        valid, message = checkTypes(self.defaults, data, "", false)
        if not valid then return nil, message end
        data = Util.merge(self.defaults, data)
    end
    self.lastError = nil
    return data
end

function Transfer:Export(data, options)
    if not self.codec or type(self.codec.encode) ~= "function" then return nil, "unsupported" end
    if options ~= nil and type(options) ~= "table" then return nil, "invalid_options" end
    if options and options.includeSecrets ~= nil and type(options.includeSecrets) ~= "boolean" then return nil, "invalid_options" end
    local normalized, message = self:_Normalize(data, false)
    if not normalized then return nil, message end
    if type(normalized.webhook) == "table" then
        if not (options and options.includeSecrets == true) then normalized.webhook.ds_url = nil end
        normalized.webhook.tg_token = nil
        normalized.webhook.tg_chat_id = nil
    end
    local ok, text = pcall(self.codec.encode, normalized)
    if not ok or type(text) ~= "string" then self.lastError = tostring(text); return nil, "encode_failed" end
    if #text > self.maxBytes then return nil, "too_large" end
    return text
end

function Transfer:Import(text)
    if type(text) ~= "string" then return nil, "invalid_text" end
    if #text > self.maxBytes then return nil, "too_large" end
    if not self.codec or type(self.codec.decode) ~= "function" then return nil, "unsupported" end
    local ok, data = pcall(self.codec.decode, text)
    if not ok then self.lastError = tostring(data); return nil, "invalid_json" end
    return self:_Normalize(data, true)
end

return Transfer
end

__modules["core/Util"] = function(require)
local Util = {}

function Util.copy(value)
    if type(value) ~= "table" then return value end
    local result = {}
    for key, item in pairs(value) do result[key] = Util.copy(item) end
    return result
end

-- Preserve only known fields and valid types. Defaults are never aliased.
function Util.merge(defaults, saved)
    if type(saved) ~= type(defaults) then return Util.copy(defaults) end
    if type(defaults) ~= "table" then return saved end
    local result = {}
    for key, value in pairs(defaults) do result[key] = Util.merge(value, saved[key]) end
    return result
end

function Util.trim(value)
    return tostring(value or ""):match("^%s*(.-)%s*$")
end

function Util.number(value, default, minimum, maximum)
    local number = tonumber(value)
    if not number or number ~= number or math.abs(number) == math.huge then return default end
    return math.max(minimum, math.min(maximum, number))
end

function Util.get(root, path)
    for segment in path:gmatch("[^.]+") do
        if type(root) ~= "table" then return nil end
        root = root[segment]
    end
    return root
end

function Util.set(root, path, value)
    local segments = {}
    for segment in path:gmatch("[^.]+") do segments[#segments + 1] = segment end
    for index = 1, #segments - 1 do
        root = root[segments[index]]
        assert(type(root) == "table", "Unknown config path: " .. path)
    end
    root[segments[#segments]] = value
end

-- Non-yielding traversal; an absent game object is not a startup deadlock.
function Util.find(root, path)
    for segment in path:gmatch("[^.]+") do
        root = root and root:FindFirstChild(segment)
        if not root then return nil end
    end
    return root
end

return Util
end

return require

end
__library_sources["sainthub-core"] = function(...)
-- sainthub-core v7 (source version 0.7.0). Generated from projects/sainthub-core/v7/src.
-- Libraries: {"core":"v2"}
local externalRequire = ...
local __modules, cache, loading = {}, {}, {}
local function require(name)
    if cache[name] ~= nil then return cache[name] end
    if not __modules[name] then
        assert(type(externalRequire) == 'function', 'Missing library dependency: ' .. tostring(name))
        return externalRequire(name)
    end
    assert(not loading[name], 'Circular library dependency: ' .. name)
    loading[name] = true
    local ok, value = pcall(__modules[name], require)
    loading[name] = nil
    if not ok then error(value, 2) end
    if value == nil then value = true end
    cache[name] = value
    return value
end

__modules["sainthub-core/Auth"] = function(require)
-- Shared, fail-closed encrypted authentication and isolated credential storage.
-- Remembered keys are plain executor-workspace JSON, never an offline grant.
local Util = require("core/Util")
local Keyring = require("sainthub-core/Keyring")
local Crypto = require("sainthub-core/Crypto")
local AuthProvider = {}
AuthProvider.__index = AuthProvider
AuthProvider.LegacyURL = "https://pastebin.com/raw/MX0xx7LW"
AuthProvider.ConfigURL = Keyring.ConfigURL

local MAX_KEY_BYTES, MAX_BODY_BYTES, MAX_FILE_BYTES = 512, 4096, 4096
local fileFields = {version = true, endpoint = true, key = true}

local function timeout(value)
    if type(value) ~= "number" or value ~= value or math.abs(value) == math.huge then return 12 end
    return math.max(0.1, math.min(30, value))
end

local function url(value)
    return type(value) == "string" and #value > 0 and #value <= 2048
        and not value:find("%c") and value:match("^https?://%S+$") ~= nil
end

local function keyPath(value)
    if type(value) ~= "string" or #value == 0 or #value > 512 or value:find("%c")
        or value:find('[<>:"|?*]') or value:match("^[/\\]") or value:sub(-5):lower() ~= ".json" then return false end
    -- A misconfigured path must not put a credential into config.json or an
    -- unrelated JSON file. Callers may choose a folder, not a config filename.
    local filename = (value:match("([^/\\]+)$") or ""):lower()
    if filename ~= "auth.json" and filename ~= "key-v2.json" then return false end
    for part in value:gsub("\\", "/"):gmatch("[^/]+") do
        if part == "." or part == ".." then return false end
    end
    return true
end

local function captured(env, name, fallback)
    if env[name] ~= nil then return env[name] end
    return fallback
end

-- Explicit adapters (including false) win, then the captured executor API,
-- then the chunk's native fallback. Do not re-fetch or modify getgenv().
local function filesystemFunction(env, options, name, nativeName, fallback)
    if options[name] ~= nil then return options[name] end
    if options.filesystem ~= nil then
        local filesystem = options.filesystem
        if type(filesystem) ~= "table" then return nil end
        if filesystem[name] ~= nil then return filesystem[name] end
        return filesystem[nativeName]
    end
    return captured(env, nativeName, fallback)
end

local function codecFunction(options, name, method, fallback)
    if options[name] ~= nil then return options[name] end
    if options.codec ~= nil then
        local codec = options.codec
        if type(codec) ~= "table" then return nil end
        if codec[name] ~= nil then return codec[name] end
        if type(codec[method]) == "function" then return function(value) return codec[method](codec, value) end end
        return nil
    end
    return fallback
end

local function current(self, guard)
    if not self:IsAlive() then return false end
    if guard == nil then return true end
    if type(guard) ~= "function" then return false end
    local ok, alive = pcall(guard)
    return ok and alive == true and self:IsAlive()
end

local function usableBody(body, headers)
    if type(body) ~= "string" or #body == 0 or #body > MAX_BODY_BYTES then return nil end
    local expected = Util.trim(body)
    if #expected == 0 or expected:find("[%z\1-\8\11\12\14-\31\127]") then return nil end
    local lower = expected:lower()
    if expected:sub(1, 3) == "\239\187\191" or expected:match("^[<{%[]")
        or lower:find("<html", 1, true) or lower:find("<!doctype", 1, true)
        or lower:find("<script", 1, true) then return nil end
    if type(headers) == "table" then
        local inspected = 0
        for name, value in pairs(headers) do
            inspected = inspected + 1
            if inspected > 64 then return nil end
            if type(name) == "string" and name:lower() == "content-type" and type(value) == "string" then
                if #value > 512 then return nil end
                local contentType = value:lower()
                if contentType:find("html", 1, true) or contentType:find("json", 1, true)
                    or contentType:find("xml", 1, true) then return nil end
            end
        end
    end
    -- Some native HttpGet implementations return an error page as a string.
    if lower == "error" or lower == "not found" or lower == "forbidden" or lower == "unauthorized"
        or lower == "bad gateway" or lower == "service unavailable" or lower == "bad request"
        or lower == "too many requests" or lower:match("^error[%s:]")
        or lower:match("^[45]%d%d[%s: %-]") or lower:match("^http/%d%.%d%s+[45]%d%d")
        or lower:match("^forbidden[%s:]") or lower:match("^unauthorized[%s:]")
        or lower:match("^not found[%s:]") or lower:match("^internal server error")
        or lower:match("^bad gateway[%s:]") or lower:match("^service unavailable[%s:]")
        or lower:match("^gateway timeout") or lower:match("^request failed[%s:]")
        or lower:match("^rate limit exceeded") or lower:match("^upstream connect error")
        or lower:match("^access denied") or lower:match("^pastebin%.com has blocked")
        or lower:match("^this paste has been removed") or lower:match("^this paste is unavailable")
        or lower:match("^this paste is private") or lower:match("^paste not found") then return nil end
    return expected
end

function AuthProvider.new(env, options)
    options = type(options) == "table" and options or {}
    env = type(env) == "table" and env or {}
    local host = env.game or game
    local mode = options.mode == nil and "encrypted" or options.mode
    local crypto = options.crypto
    if crypto == nil then crypto = Crypto end
    if type(crypto) == "table" then
        crypto = {decrypt = crypto.decrypt, hash = crypto.hash, base64_decode = crypto.base64_decode}
    end
    return setmetatable({env = env,
        mode = mode, crypto = crypto, gameId = options.gameId or host and host.GameId,
        keyURL = options.keyURL == nil and (mode == "legacy" and AuthProvider.LegacyURL or AuthProvider.ConfigURL) or options.keyURL,
        keyPath = options.keyPath, scope = options.scope, HTTP = options.HTTP,
        timeout = timeout(options.timeout), preview = options.preview == true, isCurrent = options.isCurrent,
        read = filesystemFunction(env, options, "read", "readfile", readfile),
        write = filesystemFunction(env, options, "write", "writefile", writefile),
        exists = filesystemFunction(env, options, "exists", "isfile", isfile),
        makefolder = filesystemFunction(env, options, "makefolder", "makefolder", makefolder),
        encode = codecFunction(options, "encode", "JSONEncode", function(value) return host:GetService("HttpService"):JSONEncode(value) end),
        decode = codecFunction(options, "decode", "JSONDecode", function(value) return host:GetService("HttpService"):JSONDecode(value) end),
    }, AuthProvider)
end

function AuthProvider:IsAlive()
    if self.preview or self.scope and not self.scope.alive then return false end
    if type(self.isCurrent) ~= "function" then return true end
    local ok, current = pcall(self.isCurrent)
    return ok and current == true
end

function AuthProvider:CanCheckSaved()
    return not self.preview and keyPath(self.keyPath) and type(self.read) == "function" and type(self.decode) == "function"
end

function AuthProvider:CanRemember()
    return not self.preview and keyPath(self.keyPath) and type(self.write) == "function" and type(self.encode) == "function"
end

local function readKey(self, endpoint, guard)
    if not current(self, guard) then return nil, "unavailable" end
    if not self:CanCheckSaved() then return nil, "fileUnavailable" end
    if not url(endpoint) or endpoint ~= self.keyURL then return nil, "invalidFile" end
    if type(self.exists) == "function" then
        local ok, exists = pcall(self.exists, self.keyPath)
        if not current(self, guard) then return nil, "unavailable" end
        if not ok or type(exists) ~= "boolean" then return nil, "fileUnavailable" end
        if not exists then return nil, "missing" end
    end
    local read, source = pcall(self.read, self.keyPath)
    if not current(self, guard) then return nil, "unavailable" end
    if not read or type(source) ~= "string" then return nil, "fileUnavailable" end
    if #source == 0 or #source > MAX_FILE_BYTES then return nil, "invalidFile" end
    local decoded, data = pcall(self.decode, source)
    source = nil
    if not current(self, guard) then return nil, "unavailable" end
    if not decoded or type(data) ~= "table" or getmetatable(data) ~= nil or type(data.key) ~= "string" then return nil, "invalidFile" end
    if self.keyPath:match("([^/\\]+)$") == "key-v2.json" then
        for name in pairs(data) do if name ~= "key" then return nil, "invalidFile" end end
    else
        if data.version ~= 1 or data.endpoint ~= endpoint then return nil, "invalidFile" end
        for name in pairs(data) do if not fileFields[name] then return nil, "invalidFile" end end
    end
    local key = data.key
    if #key == 0 or #key > MAX_KEY_BYTES or Util.trim(key) ~= key or key:find("[%z\1-\8\11\12\14-\31\127]") then
        return nil, "invalidFile"
    end
    return key
end

local function rememberKey(self, key, endpoint, guard)
    if not current(self, guard) or not self:CanRemember() or endpoint ~= self.keyURL then return false end
    local record = self.keyPath:match("([^/\\]+)$") == "key-v2.json" and {key = key}
        or {version = 1, endpoint = endpoint, key = key}
    local encoded, source = pcall(self.encode, record)
    record = nil
    key = nil
    if not current(self, guard) then return false end
    if not encoded or type(source) ~= "string" or #source == 0 or #source > MAX_FILE_BYTES then return false end
    local folder = self.keyPath:match("^(.*)[/\\][^/\\]+$")
    if folder and #folder > 0 and type(self.makefolder) == "function" then
        pcall(self.makefolder, folder)
        if not current(self, guard) then return false end
    end
    -- Native file operations are best-effort. Check the request's generation
    -- immediately before this side effect, including after yielding adapters.
    local written, result = pcall(self.write, self.keyPath, source)
    source = nil
    return written and result ~= false and current(self, guard)
end

local function validate(self, key, keyURL, guard)
    if not current(self, guard) then return {ok = false, code = "unavailable"} end
    if type(key) ~= "string" or #key > MAX_BODY_BYTES then return {ok = false, code = "invalid"} end
    key = Util.trim(key)
    if #key == 0 or #key > MAX_KEY_BYTES then return {ok = false, code = "invalid"} end
    keyURL = keyURL == nil and self.keyURL or keyURL
    if not url(keyURL) or self.mode ~= "legacy" and self.mode ~= "encrypted"
        or self.mode == "encrypted" and (not keyURL:match("^https://") or keyURL ~= self.keyURL) then
        return {ok = false, code = "unavailable"}
    end

    local env = self.env
    local requestAPI = captured(env, "request", request)
    local httpRequestAPI = captured(env, "http_request", http_request)
    local httpAPI = captured(env, "http", http)
    local send = type(requestAPI) == "function" and requestAPI or type(httpRequestAPI) == "function" and httpRequestAPI
        or type(httpAPI) == "table" and type(httpAPI.request) == "function" and httpAPI.request
    local started = os.clock()
    local status, body, headers
    if type(self.HTTP) == "function" then
        local ok, responseStatus, responseBody, responseHeaders = pcall(self.HTTP, keyURL)
        if not ok then return {ok = false, code = "unavailable"} end
        status, body, headers = responseStatus, responseBody, responseHeaders
    elseif type(send) == "function" then
        -- The submitted key is deliberately absent from URL, headers and body.
        local ok, response = pcall(send, {Url = keyURL, Method = "GET",
            Headers = {Accept = self.mode == "encrypted" and "application/json" or "text/plain",
                ["Cache-Control"] = "no-cache", Pragma = "no-cache"}, Timeout = self.timeout})
        if not ok or type(response) ~= "table" or rawget(response, "Success") == false or rawget(response, "success") == false then
            return {ok = false, code = "unavailable"}
        end
        local statusValue = rawget(response, "StatusCode") or rawget(response, "statusCode") or rawget(response, "status_code")
            or rawget(response, "Status") or rawget(response, "status")
        if type(statusValue) == "number" then status = statusValue
        elseif type(statusValue) == "string" and #statusValue <= 16 then status = tonumber(statusValue) end
        body, headers = rawget(response, "Body") or rawget(response, "body"), rawget(response, "Headers") or rawget(response, "headers")
    else
        local host = env.game or game
        local ok, response = pcall(function() return host:HttpGet(keyURL, true) end)
        if not ok then return {ok = false, code = "unavailable"} end
        status, body = 200, response
    end
    if not current(self, guard) or os.clock() - started >= self.timeout or status ~= 200 then
        return {ok = false, code = "unavailable"}
    end
    local expected, code
    if self.mode == "encrypted" then
        expected, code = Keyring.Open(body, self.decode, self.crypto, self.gameId)
    else expected = usableBody(body, headers) end
    if not current(self, guard) or os.clock() - started >= self.timeout then return {ok = false, code = "unavailable"} end
    if not expected then return {ok = false, code = code or "unavailable"} end
    if key == expected then return {ok = true} end
    return {ok = false, code = "invalid"}
end

function AuthProvider:Validate(key, keyURL, guard)
    keyURL = keyURL == nil and self.keyURL or keyURL
    local result = validate(self, key, keyURL, guard)
    if not result.ok then return result end
    local remembered = rememberKey(self, Util.trim(key), keyURL, guard)
    key = nil
    if not current(self, guard) then return {ok = false, code = "unavailable"} end
    return {ok = true, remembered = remembered}
end

function AuthProvider:ValidateSaved(keyURL, guard)
    keyURL = keyURL == nil and self.keyURL or keyURL
    -- The key never leaves this provider or appears in a result/input. Every
    -- launch makes a fresh GET; invalid/offline replies cannot reuse prior OK.
    local key, reason = readKey(self, keyURL, guard)
    if not key then return {ok = false, code = reason} end
    local result = validate(self, key, keyURL, guard)
    key = nil
    if result.ok then return {ok = true, remembered = true} end
    return result
end

-- Public validator adapter retains AA's legacy/http/callback contracts in one place.
local Validator = {}
Validator.__index = Validator

function Validator.new(runtime, settings, player, options)
    options = options or {}
    local provider = AuthProvider.new(runtime.env or {}, {mode = settings.Mode,
        keyURL = settings.Mode == "legacy" and settings.LegacyURL or settings.ConfigURL,
        gameId = options.gameId, scope = options.scope, isCurrent = options.isCurrent, timeout = settings.Timeout,
        HTTP = function(url) return runtime:HTTP(url) end})
    return setmetatable({runtime = runtime, settings = settings, player = player, legacy = provider}, Validator)
end

function Validator:Validate(key, keyURL, guard)
    key = Util.trim(key)
    if key == "" or #key > 512 then return {ok = false, code = "invalid"} end
    local settings = self.settings
    if settings.Mode == "legacy" or settings.Mode == "encrypted" then return self.legacy:Validate(key, keyURL, guard)
    elseif settings.Mode == "callback" then
        assert(type(settings.Validate) == "function", "Configure Auth.Validate")
        return settings.Validate(key, self.player, keyURL)
    elseif settings.Mode == "http" then
        local status, body = self.runtime:HTTP(settings.Endpoint, "POST", self.runtime:Codec().encode({
            key = key, userId = self.player.UserId, gameId = game.GameId}))
        if status == 401 or status == 403 then return {ok = false, code = "invalid"} end
        if status ~= 200 then return {ok = false, code = "unavailable"} end
        local decoded = self.runtime:Codec().decode(body)
        return {ok = type(decoded) == "table" and decoded.ok == true, code = "invalid"}
    end
    return {ok = false, code = "unavailable"}
end

AuthProvider.Validator = Validator
return AuthProvider
end

__modules["sainthub-core/Bootstrap"] = function(require)
local Bootstrap = {}

-- A one-use handoff belongs to the current coroutine, so yielding startups
-- cannot bypass another invocation's routing or leave a permanent test flag.
function Bootstrap.Execute(environment, url, chunk)
    local entries = type(environment.SaintHubEntry) == "table" and environment.SaintHubEntry or {}
    environment.SaintHubEntry = entries
    local thread = coroutine.running() or "main"
    local previous = entries[thread]
    entries[thread] = {url = url, claimed = false}
    local result = table.pack(pcall(chunk))
    entries[thread] = previous
    if next(entries) == nil and environment.SaintHubEntry == entries then environment.SaintHubEntry = nil end
    if not result[1] then error(result[2], 0) end
    return table.unpack(result, 2, result.n)
end

function Bootstrap.Load(environment, url)
    assert(type(url) == "string" and url:match("^https://%S+$"), "SaintHub: main URL must use HTTPS")
    local loader = environment.loadstring or loadstring
    assert(type(loader) == "function", "SaintHub: loadstring is unavailable")
    local source = game:HttpGet(url)
    assert(type(source) == "string" and source ~= "", "SaintHub: empty script response from " .. tostring(url))
    local chunk, reason = loader(source, "@SaintHubMain.lua")
    assert(type(chunk) == "function", reason or "SaintHub: failed to compile main script")
    return Bootstrap.Execute(environment, url, chunk)
end

function Bootstrap.Run(environment, settings, start)
    local entries = environment.SaintHubEntry
    local entry = type(entries) == "table" and entries[coroutine.running() or "main"]
    if type(entry) == "table" and entry.url == settings.MainURL and entry.claimed == false then
        entry.claimed = true
    elseif settings.SaintTest and type(settings.MainURL) == "string" and settings.MainURL ~= "" then
        return Bootstrap.Load(environment, settings.MainURL)
    end
    return start()
end

local function validPath(value)
    if type(value) ~= "string" or value == "" or #value > 512 or value:find("%c")
        or value:find('[<>:"|?*]') or value:match("^[/\\]") then return false end
    for part in value:gsub("\\", "/"):gmatch("[^/]+") do
        if part == "." or part == ".." then return false end
    end
    return value:sub(-4):lower() == ".lua"
end

function Bootstrap.CanReload(settings)
    if type(settings.MainURL) == "string" and settings.MainURL ~= "" then
        return settings.MainURL:match("^https://%S+$") ~= nil
    end
    return validPath(settings.MainPath)
end

-- Serialize only deployment routes. Keys, user config and injected UI never enter the queue.
function Bootstrap.TeleportCode(settings)
    assert(Bootstrap.CanReload(settings), "Configure MainURL or MainPath for teleport reload")
    local mainURL = type(settings.MainURL) == "string" and settings.MainURL or ""
    local mainPath = validPath(settings.MainPath) and settings.MainPath or ""
    local uiPath = validPath(settings.UIPath) and settings.UIPath or ""
    return string.format([=[task.spawn(function()
print("[SaintHub teleport] bootstrap_started")
local function failed(stage, detail)
    warn("[SaintHub teleport] " .. stage .. ": " .. tostring(detail):sub(1, 200))
end
local deadline = os.clock() + 60
while not game:IsLoaded() and os.clock() < deadline do task.wait(0.1) end
if not game:IsLoaded() then failed("readiness", "game_load_timeout"); return end
local players = game:GetService("Players")
deadline = os.clock() + 30
while not players.LocalPlayer and os.clock() < deadline do task.wait(0.1) end
local player = players.LocalPlayer
if not player then failed("readiness", "player_timeout"); return end
if not player:WaitForChild("PlayerGui", 30) then failed("readiness", "player_gui_timeout"); return end
local environment = (getgenv and getgenv()) or _G
local previousOwner = environment.SaintHubTeleportBootstrapOwner
if environment.SaintHubTeleportBootstrap == game.JobId and type(previousOwner) == "table" and previousOwner.game == game then return end
local owner = {game = game}
environment.SaintHubTeleportBootstrap = game.JobId
environment.SaintHubTeleportBootstrapOwner = owner
local function bootstrapFailed(stage, detail)
    if environment.SaintHubTeleportBootstrapOwner == owner then
        environment.SaintHubTeleportBootstrap = nil
        environment.SaintHubTeleportBootstrapOwner = nil
