__modules["sainthub-core/Deployment"] = function(require)
local Util = require("core/Util")
local Deployment = {}

function Deployment.Resolve(defaults, options, environment, requiredTestURLs)
    local settings = Util.copy(defaults)
    for key, value in pairs(type(options) == "table" and options or {}) do
        if type(value) == "table" and type(settings[key]) == "table" then
            for field, item in pairs(value) do settings[key][field] = item end
        else settings[key] = value end
    end
    settings.SaintTest = environment.sainttest == true
    if settings.SaintTest then
        local required = {}
        for _, key in ipairs(requiredTestURLs or {}) do required[key] = true end
        for _, key in ipairs({"MainURL", "UIURL"}) do
            local value = type(settings.TestURLs) == "table" and settings.TestURLs[key]
            if required[key] or type(value) == "string" and value ~= "" then
                assert(type(value) == "string" and value:match("^https://%S+$"),
                    "sainttest: configure TestURLs." .. key .. " in settings or SaintHubOptions")
                settings[key] = value
            elseif key == "MainURL" then settings[key] = "" end
        end
    end
    return settings
end

return Deployment
end

