            if registry[self.id] == self then registry[self.id] = nil end
            if next(registry) == nil and environment.SaintHubInstances == registry then environment.SaintHubInstances = nil end
        end)
        if type(previous) == "table" and type(previous.Destroy) == "function" then pcall(previous.Destroy, previous) end
