    assert(self:IsCurrent(), "Application is unloaded")
    local settings = {}
    for key, value in pairs(options or {}) do settings[key] = value end
    settings.path = settings.path or self.configPath
    settings.scope = settings.scope or self.scope
    settings.preview = self.preview or settings.preview
    return Core.Profile.new(bridge, settings)
end

function App:Auth(options)
    assert(self:IsCurrent(), "Application is unloaded")
    local settings = {}
    for key, value in pairs(options or {}) do settings[key] = value end
    settings.keyPath = settings.keyPath or self.keyPath
    settings.gameId = settings.gameId or self.gameId
    settings.scope = settings.scope or self.scope
    settings.preview = self.preview or settings.preview
