__modules["sainthub-core/Keyring"] = function(require)
-- Client-side secrecy is concealment, not a server trust boundary.
-- Python tools/keys.py reads these versioned constants; do not rotate them casually.
local Keyring = {}
Keyring.ConfigURL = "https://raw.githubusercontent.com/saint-tools/SaintHub/main/Keys.json"
Keyring.EncryptionKey = "fez6LD/uZqY08k9cjPwFB8PLz4kiGChlvxtOSMg7hKg="
