local function integer(value)
    return type(value) == "number" and value >= 1 and value <= 9007199254740991 and value % 1 == 0
end

local function object(value)
    return type(value) == "table" and getmetatable(value) == nil
end

local function base64(value, max)
    return type(value) == "string" and #value > 0 and #value <= max and #value % 4 == 0
        and value:match("^[A-Za-z0-9+/]+=?=?$") ~= nil
end

local function rawHash(crypto, data)
    local digest = crypto.hash(data, "sha256")
    assert(type(digest) == "string" and #digest == 64 and digest:match("^[0-9a-fA-F]+$"), "Invalid digest")
    return (digest:gsub("..", function(pair) return string.char(tonumber(pair, 16)) end))
end

