local function equal(a, b)
    if #a ~= #b then return false end
    local difference = 0
    for i = 1, #a do difference = bit32.bor(difference, bit32.bxor(a:byte(i), b:byte(i))) end
    return difference == 0
end

function Keyring.Open(source, decode, crypto, gameId)
    if type(source) ~= "string" or #source == 0 or #source > Keyring.MaxBytes or type(decode) ~= "function"
        or not integer(gameId) or type(crypto) ~= "table" or type(crypto.decrypt) ~= "function"
        or type(crypto.hash) ~= "function" then return nil, "unavailable" end
    local decode64 = crypto.base64_decode
    if type(decode64) ~= "function" then return nil, "unavailable" end
    local ok, expected, code = pcall(function()
        local envelope = decode(source)
        if not object(envelope) then return nil, "unavailable" end
        for name in pairs(envelope) do if not envelopeFields[name] then return nil, "unavailable" end end
        if envelope.format ~= 1 or envelope.algorithm ~= Keyring.Algorithm or not integer(envelope.revision)
            or not base64(envelope.iv, 24) or not base64(envelope.ciphertext, Keyring.MaxBytes)
            or type(envelope.mac) ~= "string" or #envelope.mac ~= 64 or not envelope.mac:match("^[0-9a-f]+$") then
            return nil, "unavailable"
        end
        local iv, ciphertext = decode64(envelope.iv), decode64(envelope.ciphertext)
        if type(iv) ~= "string" or #iv ~= 16 or type(ciphertext) ~= "string" or #ciphertext < 16 or #ciphertext % 16 ~= 0 then
            return nil, "unavailable"
        end
        local message = "SaintHub.Keys.v1\n" .. envelope.algorithm .. "\n" .. string.format("%.0f", envelope.revision)
            .. "\n" .. envelope.iv .. "\n" .. envelope.ciphertext
        if not equal(hmac(crypto, decode64, message), envelope.mac) then return nil, "unavailable" end
        -- Authenticate before decrypting; the portable adapter fixes CBC/PKCS7.
        local plaintext = crypto.decrypt(envelope.ciphertext, Keyring.EncryptionKey, envelope.iv)
        if type(plaintext) ~= "string" or #plaintext == 0 or #plaintext > Keyring.MaxBytes then return nil, "unavailable" end
        local config = decode(plaintext)
        plaintext = nil
        if not object(config) or config.format ~= 1 or config.revision ~= envelope.revision or not object(config.games) then
            return nil, "unavailable"
        end
        for name in pairs(config) do if name ~= "format" and name ~= "revision" and name ~= "games" then return nil, "unavailable" end end
        local record = config.games[string.format("%.0f", gameId)]
        if not object(record) then return nil, "invalid" end
        for name in pairs(record) do if name ~= "key" and name ~= "enabled" then return nil, "unavailable" end end
        if record.enabled ~= true then return nil, "invalid" end
        local key = record.key
        if type(key) ~= "string" or #key == 0 or #key > 512 or key:match("^%s") or key:match("%s$") or key:find("%c") then
            return nil, "unavailable"
        end
        return key
    end)
    if not ok then return nil, "unavailable" end
    return expected, code
end

return Keyring
end

__modules["sainthub-core/Paths"] = function(require)
-- Shared GameId/UserId storage layout, never match PlaceId.
local Paths = {}

function Paths.For(gameId, userId)
    assert(type(gameId) == "number" and gameId >= 0 and gameId % 1 == 0, "Invalid game identity")
    assert(type(userId) == "number" and userId > 0 and userId % 1 == 0, "Invalid player identity")
    local base = "SaintHub/" .. tostring(gameId) .. "/" .. tostring(userId)
    return base .. "/config.json", base .. "/key-v2.json"
end

function Paths.Base(gameId, userId)
    local config = Paths.For(gameId, userId)
    return config:sub(1, -13)
end

function Paths.KeyPath(gameId, userId)
    local _, key = Paths.For(gameId, userId)
    return key
end

-- Retain AA's explicit old PlaceId migration without importing root/local files.
function Paths.MigratePlaceKey(storage, codec, gameId, placeId, userId)
    if not storage then return false end
    local target, previous = Paths.KeyPath(gameId, userId), Paths.KeyPath(placeId, userId)
    if target == previous then return false end
    local ok, migrated = pcall(function()
        if storage.exists(target) or not storage.exists(previous) then return false end
        local legacy = codec.decode(storage.read(previous))
        local key = type(legacy) == "table" and type(legacy.key) == "string" and legacy.key:match("^%s*(.-)%s*$") or ""
        if key == "" or #key > 512 or key:find("%c") then return false end
        storage.write(target, codec.encode({key = key}))
        return true
    end)
    return ok and migrated == true
end

return Paths
end

__modules["sainthub-core/Profile"] = function(require)
local Paths = require("sainthub-core/Paths")
local Signal = require("core/Signal")
local ConfigStore = {}
ConfigStore.__index = ConfigStore

local maxBytes = 128 * 1024
local fileFields = {version = true, autoLoad = true, settings = true, ui = true}
local uiFields = {language = true, theme = true}

local function plain(value)
    return type(value) == "table" and getmetatable(value) == nil
end

local function copy(value)
    if type(value) ~= "table" then return value end
    local result = {}
    for key, entry in pairs(value) do result[key] = copy(entry) end
    return result
end

local function equal(a, b)
    if a == b then return true end
    if type(a) ~= "table" or type(b) ~= "table" then return false end
    for key, entry in pairs(a) do if not equal(entry, b[key]) then return false end end
    for key in pairs(b) do if a[key] == nil then return false end end
    return true
end

local function filesystemFunction(options, name, nativeName, fallback)
    if options[name] ~= nil then return options[name] end
    if options.filesystem ~= nil then
        local filesystem = options.filesystem
        if type(filesystem) ~= "table" then return nil end
        if filesystem[name] ~= nil then return filesystem[name] end
        return filesystem[nativeName]
    end
    return fallback
end

local function codecFunction(options, name, method, fallback)
    if options[name] ~= nil then return options[name] end
    if options.codec ~= nil then
        local codec = options.codec
        if type(codec) ~= "table" then return nil end
        if codec[name] ~= nil then return codec[name] end
        if type(codec[method]) == "function" then return function(value) return codec[method](codec, value) end end
        return nil
    end
    return fallback
end

local function normalizeUI(ui)
    if ui == nil then return {language = "en", theme = "dark"} end
    if not plain(ui) then return nil end
    for key in pairs(ui) do if not uiFields[key] then return nil end end
    local language, theme = ui.language, ui.theme
    if language == nil then language = "en" end
    if theme == nil then theme = "dark" end
    if type(language) ~= "string" or #language == 0 or #language > 32 or not language:match("^[%w_%-]+$")
        or type(theme) ~= "string" or #theme == 0 or #theme > 96 or not theme:match("^[%w_%-]+$") then return nil end
    return {language = language, theme = theme}
end

function ConfigStore.new(bridge, options)
    options = options or {}
    assert(type(options.schema) == "table", "Profile requires a game schema")
    local path = options.path
    if path == nil then path = Paths.For(game.GameId, game:GetService("Players").LocalPlayer.UserId) end
    local self = setmetatable({
        bridge = bridge, schema = options.schema, preview = options.preview == true or bridge.preview == true, autoLoad = false,
        path = path, getUI = options.getUI, normalizeUI = options.normalizeUI or normalizeUI,
        read = filesystemFunction(options, "read", "readfile", readfile),
        write = filesystemFunction(options, "write", "writefile", writefile),
        exists = filesystemFunction(options, "exists", "isfile", isfile),
        makefolder = filesystemFunction(options, "makefolder", "makefolder", makefolder),
        encode = codecFunction(options, "encode", "JSONEncode", function(value) return game:GetService("HttpService"):JSONEncode(value) end),
        decode = codecFunction(options, "decode", "JSONDecode", function(value) return game:GetService("HttpService"):JSONDecode(value) end),
        Changed = Signal.new(), baseline = nil,
    }, ConfigStore)
    local scope = options.scope or bridge.scope
    if scope then scope:Add(self.Changed) end
    if not self.preview then
        local initial = self:_Snapshot(false)
        if initial then self:_Baseline(initial.settings, initial.ui) end
    else
        -- Construction and disabled preview file actions must not even call
        -- getUI/codecs/filesystem adapters. Retain the initial private settings;
        -- the UI baseline is completed by the first IsDirty/CaptureBaseline.
        self.initialSettings = self:_SettingsSnapshot()
    end
    return self
end

function ConfigStore:_Read()
    if self.preview then return nil, "preview" end
    if type(self.path) ~= "string" or #self.path == 0 then return nil, "invalid" end
    if type(self.exists) ~= "function" then return nil, "unavailable" end
