    if not exists then return nil, "missing" end
    if type(self.read) ~= "function" or type(self.decode) ~= "function" then return nil, "unavailable" end
    local read, source = pcall(self.read, self.path)
    if not read or type(source) ~= "string" then return nil, "readFailed" end
    if #source > maxBytes then return nil, "invalid" end
    local decoded, data = pcall(self.decode, source)
    if not decoded or not plain(data) or data.version ~= 1 or type(data.autoLoad) ~= "boolean" then return nil, "invalid" end
    for key in pairs(data) do if not fileFields[key] then return nil, "invalid" end end
    local valid, settings = pcall(self.schema.Deserialize, data.settings)
    local ui = self.normalizeUI(data.ui)
    if not valid or not settings or not ui then return nil, "invalid" end
    -- Keep the saved JSON snapshot separate from normalized runtime settings:
    -- an AutoLoad checkbox must not resave the current configuration or UI.
    return copy(data), nil, settings, ui
end

function ConfigStore:_SettingsSnapshot()
    local read, config = pcall(function()
        local values = {}
        for key in pairs(self.schema.Defaults) do values[key] = self.bridge:Get(key) end
        return values
    end)
    if not read then return nil, "invalid" end
    local valid, settings = pcall(self.schema.Serialize, config)
    if not valid or not settings then return nil, "invalid" end
    return settings
end

function ConfigStore:_Snapshot(autoLoad)
    if type(autoLoad) ~= "boolean" then return nil, "invalid" end
    local settings, reason = self:_SettingsSnapshot()
    if not settings then return nil, reason end
    local ui
    if self.getUI ~= nil then
        if type(self.getUI) ~= "function" then return nil, "invalid" end
        local ok, value = pcall(self.getUI)
        if not ok then return nil, "invalid" end
        ui = value
    end
    ui = self.normalizeUI(ui)
    if not ui then return nil, "invalid" end
    return {version = 1, autoLoad = autoLoad, settings = settings, ui = ui}
end

function ConfigStore:_Baseline(settings, ui, reason)
    -- Both fields are canonical JSON-like values, never runtime table aliases.
    -- autoLoad is deliberately absent: toggling it is not a settings edit.
    self.baseline = {settings = copy(settings), ui = copy(ui)}
    self.initialSettings = nil
    if reason then self.Changed:Fire(reason) end
end

function ConfigStore:CaptureBaseline()
    local data, reason = self:_Snapshot(self.autoLoad)
    if not data then return false, reason end
    self:_Baseline(data.settings, data.ui, "baseline")
    return true
end

function ConfigStore:IsDirty()
    local data, reason = self:_Snapshot(self.autoLoad)
    if not data then return true, reason end
    if not self.baseline and self.preview then
        self:_Baseline(self.initialSettings or data.settings, data.ui)
    end
    if not self.baseline then return true end
    return not equal(data.settings, self.baseline.settings) or not equal(data.ui, self.baseline.ui)
end

function ConfigStore:_Write(data)
    if self.preview then return false, "preview" end
    if type(self.path) ~= "string" or #self.path == 0 then return false, "invalid" end
    if type(self.write) ~= "function" or type(self.encode) ~= "function" then return false, "unavailable" end
    local encoded, source = pcall(self.encode, data)
    if not encoded or type(source) ~= "string" or #source > maxBytes then return false, "writeFailed" end
