    local written, result = pcall(self.write, self.path, source)
    if not written or result == false then return false, "writeFailed" end
    return true
end

function ConfigStore:Load(startup)
    if self.preview then return false, "preview" end
    if startup ~= nil and type(startup) ~= "boolean" then return false, "invalid" end
    local data, reason, settings, ui = self:_Read()
    if not data then return false, reason end
    local valid, normalized = pcall(self.schema.Serialize, settings)
    if not valid or not normalized then return false, "invalid" end
    if startup == true and not data.autoLoad then
        self.autoLoad = false
        self:_Baseline(normalized, ui, "autoOff")
        return false, "autoOff"
    end
    local applied, result = pcall(function() return self.bridge:Apply(settings) end)
    if not applied or result == false then return false, "invalid" end
    self.autoLoad = data.autoLoad
    self:_Baseline(normalized, ui, "loaded")
    return true, "loaded", ui
end

function ConfigStore:Save()
    if self.preview then return false, "preview" end
    if type(self.write) ~= "function" or type(self.encode) ~= "function" then return false, "unavailable" end
    local data, reason = self:_Snapshot(self.autoLoad)
    if not data then return false, reason end
    -- Save is the explicit overwrite action; it does not read another profile.
    local written, failure = self:_Write(data)
    if not written then return false, failure end
    self:_Baseline(data.settings, data.ui, "saved")
    return true, "saved"
end

function ConfigStore:SetAutoLoad(value)
    if self.preview then return false, "preview" end
    if type(value) ~= "boolean" then return false, "invalid" end
    if type(self.write) ~= "function" or type(self.encode) ~= "function" then return false, "unavailable" end
    local data, reason, settings, ui = self:_Read()
    local normalized
    if not data then
        if reason ~= "missing" then return false, reason end
        data, reason = self:_Snapshot(value)
        if not data then return false, reason end
        normalized = data.settings
    else
        local valid
        valid, normalized = pcall(self.schema.Serialize, settings)
        if not valid or not normalized then return false, "invalid" end
        data.autoLoad = value
    end
    local written, failure = self:_Write(data)
    if not written then return false, failure end
    self.autoLoad = value
    self:_Baseline(normalized, ui or data.ui, "autoSaved")
    return true, "autoSaved"
end

function ConfigStore:Destroy() self.Changed:Destroy() end

return ConfigStore
end

__modules["sainthub-core/Runtime"] = function(require)
local Util = require("core/Util")
local HTTP = require("core/HTTP")
local Keyring = require("sainthub-core/Keyring")
local HttpService = game:GetService("HttpService")
local Runtime = {}
Runtime.__index = Runtime

function Runtime.FindTeleportQueue(environment, globals)
    for _, source in ipairs({environment or {}, globals or {}}) do
        for _, name in ipairs({"queue_on_teleport", "queueonteleport"}) do
            if type(source[name]) == "function" then return source[name] end
        end
        for _, name in ipairs({"syn", "fluxus"}) do
            local namespace = source[name]
            if type(namespace) == "table" then
                for _, alias in ipairs({"queue_on_teleport", "queueonteleport"}) do
                    if type(namespace[alias]) == "function" then return namespace[alias] end
                end
            end
        end
    end
end

function Runtime.new(environment)
    local env = environment or (getgenv and getgenv()) or _G
    local self = setmetatable({ env = env }, Runtime)
    self.request = HTTP.request(env, {request = request, http_request = http_request, httprequest = httprequest,
        krnl_request = krnl_request, secure_request = secure_request, http = http, syn = syn, fluxus = fluxus})
    self.read = env.readfile or readfile
    self.write = env.writefile or writefile
    self.isfile = env.isfile or isfile
    self.isfolder = env.isfolder or isfolder
    self.makefolder = env.makefolder or makefolder
    self.listfiles = env.listfiles or listfiles
    self.delfile = env.delfile or delfile
    self.clipboard = env.setclipboard or setclipboard
    self.fps = env.setfpscap or setfpscap
    self.getfps = env.getfpscap or getfpscap
    self.queue = Runtime.FindTeleportQueue(env, {queue_on_teleport = queue_on_teleport,
        queueonteleport = queueonteleport, syn = syn, fluxus = fluxus})
    return self
end

function Runtime:Storage()
    if not (self.read and self.write and self.isfile and self.isfolder and self.makefolder) then return nil end
    return {
        exists = self.isfile, read = self.read,
        list = type(self.listfiles) == "function" and function(path)
            if not self.isfolder(path) then return {} end
            return self.listfiles(path)
        end or nil,
        delete = type(self.delfile) == "function" and self.delfile or nil,
        write = function(path, text)
            local directory = path:match("^(.*)/[^/]+$")
            local prefix = ""
            for part in (directory or ""):gmatch("[^/]+") do
                prefix = prefix == "" and part or prefix .. "/" .. part
                if not self.isfolder(prefix) then self.makefolder(prefix) end
            end
            return self.write(path, text)
        end,
    }
end

function Runtime:Codec()
    return {
        encode = function(value) return HttpService:JSONEncode(value) end,
        decode = function(text) return HttpService:JSONDecode(text) end,
    }
end

function Runtime:HTTP(url, method, body)
    assert(url:match("^https://"), "HTTPS is required")
    if self.request then
        local options = {Url = url, Method = method or "GET", Headers = {["Content-Type"] = "application/json"}, Body = body}
        if url == Keyring.ConfigURL and (not method or method == "GET") then
            options.Headers["Cache-Control"], options.Headers.Pragma = "no-cache", "no-cache"
        end
        -- Keep POST compatible with the minimal request shape used by v1.
        -- Some executors reject an otherwise optional Redirect field.
        if not method or method == "GET" then options.Redirect = true end
        local response = self.request(options)
        return HTTP.response(response)
    end
    assert(not method or method == "GET", "HTTP POST is unavailable")
    if url == Keyring.ConfigURL then return 200, game:HttpGet(url, true) end
    return 200, game:HttpGet(url)
end

function Runtime:Parent()
    local hidden = self.env.gethui or gethui
    if hidden then
        local ok, parent = pcall(hidden)
        if ok and parent then return parent end
    end
    local player = game:GetService("Players").LocalPlayer
    return player and player:FindFirstChildOfClass("PlayerGui") or game:GetService("CoreGui")
end

function Runtime:LoadUI(settings)
    if type(settings.UI) == "table" then return settings.UI end
    if self.ui then return self.ui end
    local source
    if settings.UIPath and settings.UIPath ~= "" and self.read and self.isfile and self.isfile(settings.UIPath) then
        source = self.read(settings.UIPath)
    elseif type(settings.UIURL) == "string" and settings.UIURL ~= "" then
        local status
        status, source = self:HTTP(settings.UIURL)
        assert(status == 200, "Could not download SaintUI")
    else
        error("SaintUI not found. Supply SaintHubOptions.UI or configure UIURL.")
    end
    local loader = self.env.loadstring or loadstring
    assert(loader, "This environment cannot load a Lua source string; supply SaintHubOptions.UI")
    local chunk, message = loader(source, "@SaintUI.lua")
    assert(chunk, message)
    local library = chunk()
    assert(type(library) == "table" and type(library.new) == "function", "Invalid SaintUI bundle")
    self.ui = library
    return library
end

function Runtime:Copy(text)
    if not self.clipboard then return false end
    return pcall(self.clipboard, text)
end

function Runtime:ApplyFPS(value)
    if not self.fps then return false end
    return pcall(self.fps, Util.number(value, 60, 15, 360))
end

return Runtime
end

__modules["sainthub-core/Servers"] = function(require)
-- Shared, scoped discovery. A returned public row is not a teleport receipt.
local Servers = {}
Servers.__index = Servers

local function finite(value)
    return type(value) == "number" and value == value and math.abs(value) < math.huge
end
local function validId(value)
    return type(value) == "string" and #value > 0 and #value <= 128 and value:match("^[%w%-]+$") ~= nil
end

function Servers.new(session)
    return setmetatable({session = session, model = game, placeId = game.PlaceId, jobId = game.JobId,
        known = {}, loading = false, pending = false, nextRequestAt = 0}, Servers)
end

function Servers:_Current(guard)
    if not self.session.scope.alive or game ~= self.model or game.PlaceId ~= self.placeId or game.JobId ~= self.jobId then return false end
    if guard then local ok, current = pcall(guard); return ok and current == true end
    return true
end

function Servers:List(cursor, limit, guard)
    if not self:_Current(guard) then return false, "SERVER_SEARCH_CANCELLED" end
    if self.loading then return false, "SERVER_SEARCH_BUSY" end
    if os.clock() < self.nextRequestAt then return false, "SERVER_SEARCH_RATE_LIMIT" end
    limit = limit or 25
    if limit ~= 10 and limit ~= 25 and limit ~= 50 and limit ~= 100 then return false, "INVALID_SERVER_PAGE_SIZE" end
    if cursor ~= nil and (type(cursor) ~= "string" or #cursor > 1024 or cursor:find("%c")) then return false, "INVALID_SERVER_CURSOR" end
    local http = self.model:GetService("HttpService")
    local url = string.format("https://games.roblox.com/v1/games/%s/servers/Public?sortOrder=Asc&limit=%d", tostring(self.placeId), limit)
    if cursor and cursor ~= "" then url = url .. "&cursor=" .. http:UrlEncode(cursor) end
    local request = {done = false, cancelled = false}
    self.loading = request
    local _, cleanupId = self.session.scope:Add(function() request.cancelled = true end)
    -- A native HTTP waiter is drained, never force-cancelled. Late replies cannot
    -- enter the cache or dispatch a teleport after their logical owner retires.
    local spawned = pcall(task.spawn, function()
        request.results = table.pack(pcall(self.session.runtime.HTTP, self.session.runtime, url))
        request.done = true
        if self.loading == request then self.loading = false end
        self.session.scope:Remove(cleanupId)
    end)
    if not spawned then self.loading = false; self.session.scope:Remove(cleanupId); return false, "SERVER_SEARCH_FAILED" end
    local deadline = os.clock() + 12
    while not request.done and not request.cancelled and self:_Current(guard) and os.clock() < deadline do task.wait(0.05) end
    if not self:_Current(guard) then return false, "SERVER_SEARCH_CANCELLED" end
    if not request.done then return false, "SERVER_SEARCH_TIMEOUT" end
    local ok, status, body = table.unpack(request.results, 1, request.results.n)
    if not ok or status ~= 200 or type(body) ~= "string" or #body > 1024 * 1024 then
        self.nextRequestAt = os.clock() + 2
        return false, status == 429 and "SERVER_SEARCH_RATE_LIMIT" or "SERVER_SEARCH_FAILED"
    end
    local decoded, data = pcall(http.JSONDecode, http, body)
    if not self:_Current(guard) then return false, "SERVER_SEARCH_CANCELLED" end
    if not decoded or type(data) ~= "table" or type(data.data) ~= "table" then return false, "INVALID_SERVER_RESPONSE" end
    local nextCursor = data.nextPageCursor
    if nextCursor ~= nil and (type(nextCursor) ~= "string" or #nextCursor > 1024 or nextCursor:find("%c")) then return false, "INVALID_SERVER_RESPONSE" end
    local now, rows, seen = os.clock(), {}, {}
    for id, row in pairs(self.known) do if now - row.observedAt > 60 then self.known[id] = nil end end
    for index, row in ipairs(data.data) do
        if index > limit then break end
        if type(row) == "table" and validId(row.id) and not seen[row.id]
            and finite(row.playing) and row.playing >= 0 and row.playing % 1 == 0
            and finite(row.maxPlayers) and row.maxPlayers >= 1 and row.maxPlayers <= 1000 and row.maxPlayers % 1 == 0
            and row.playing <= row.maxPlayers then
            seen[row.id] = true
            local safe = {id = row.id, playing = row.playing, maxPlayers = row.maxPlayers,
                joinable = row.id ~= self.jobId and row.playing < row.maxPlayers, observedAt = now}
            if finite(row.ping) and row.ping >= 0 and row.ping <= 100000 then safe.ping = row.ping end
            if finite(row.fps) and row.fps >= 0 and row.fps <= 10000 then safe.fps = row.fps end
            rows[#rows + 1] = safe
            self.known[row.id] = safe.joinable and safe or nil
        end
    end
    local count = 0
    for id in pairs(self.known) do count += 1; if count > 512 then self.known[id] = nil end end
    if not self:_Current(guard) then return false, "SERVER_SEARCH_CANCELLED" end
    return true, {servers = rows, nextCursor = nextCursor ~= "" and nextCursor or nil, observedAt = now}
end

function Servers:_Join(id, guard, sameServer)
    if not self:_Current(guard) then return false, "SERVER_HOP_CANCELLED" end
    if self.pending or self.preparing then return false, "SERVER_HOP_ALREADY_PENDING" end
    if not validId(id) then return false, "INVALID_SERVER_ID" end
    if not sameServer then
        local row = self.known[id]
        if not row or not row.joinable or os.clock() - row.observedAt > 60 then return false, "SERVER_SELECTION_EXPIRED" end
