    self.preparing = reservation
    local flushed, accepted = pcall(self.session.config.Flush, self.session.config)
    local function releasePreparation()
        if self.preparing == reservation then self.preparing = nil end
    end
    if not self:_Current(guard) then releasePreparation(); return false, "SERVER_HOP_CANCELLED" end
    if not flushed or accepted == false then releasePreparation(); return false, "SESSION_WRITE_FAILED" end
    if self.pending then releasePreparation(); return false, "SERVER_HOP_ALREADY_PENDING" end
    local ok = pcall(function()
        if not self:_Current(guard) then error("SERVER_HOP_CANCELLED", 0) end
