        -- pre-dispatch cancellation. A thrown invocation remains ambiguous.
        self.pending = true
        releasePreparation()
        self.model:GetService("TeleportService"):TeleportToPlaceInstance(self.placeId, id, self.session.adapter.player)
    end)
    releasePreparation()
    return ok, not ok and (self.pending and "SERVER_JOIN_OUTCOME_UNKNOWN" or "SERVER_HOP_CANCELLED") or nil
