                    if not previous.releasing then previous.release() end
                    return
                end
                players = model:GetService("Players")
                if not players or not current() then return end
                local world = model:GetService("Workspace")
                if not world or not current() then return end
                local camera = world.CurrentCamera
                local frame = camera and camera.CFrame
                if not frame or not current() then return end
                local input = model:GetService("UserInputService")
                if not input or not current() then return end
                local virtual = model:GetService("VirtualUser")
                if not virtual or not current() then return end
                local down, up = inputMethod(virtual, "Button2Down"), inputMethod(virtual, "Button2Up")
