function Session:_Servers()
    if not self.servers then self.servers = Servers.new(self) end
    return self.servers
end

function Session:BrowseServers(cursor, limit, guard)
    return self:_Servers():List(cursor, limit, guard)
end

function Session:JoinServer(id, guard)
    return self:_Servers():Join(id, guard)
end

function Session:ServerHop(guard)
    local cursor
    for _ = 1, 3 do
        local ok, page = self:BrowseServers(cursor, 100, guard)
        if not ok then return false, page end
        for _, server in ipairs(page.servers) do
            if server.joinable then return self:JoinServer(server.id, guard) end
        end
        cursor = page.nextCursor
        if not cursor or cursor == "" then break end
    end
    return false, "NO_PUBLIC_SERVER"
end

function Session:Rejoin(guard)
    return self:_Servers():Rejoin(guard)
end

function Session:Destroy() self.scope:Destroy() end

return Session
end

