__modules["app/App"] = function(require)
local Scope = require("core/Scope")
local HubCore = require("sainthub-core/init")
local Config = require("core/Config")
local Util = require("core/Util")
local Transfer = require("core/Transfer")
local Locales = require("app/Locales")
local MacroLibrary = require("app/MacroLibrary")
local AutoPlacePresets = require("app/AutoPlacePresets")
local Defaults = require("app/Defaults")
local Runtime = require("app/Runtime")
local UI = require("app/UI")
local Deployment = require("app/Deployment")
local AuthProvider = require("app/AuthProvider")
local Adapter = require("game/Adapter")
local Units = require("game/Units")
local Webhook = require("game/Webhook")
local SessionLogs = require("core/SessionLogs")
local Telegram = require("game/Telegram")
local DropNotifications = require("game/DropNotifications")
local GameService = require("game/GameService")
local Session = require("game/Session")
local Macros = require("game/Macros")
local MacroRouter = require("game/MacroRouter")
local MacroCapture = require("game/MacroCapture")
local Visuals = require("game/Visuals")
local AutoCodes = require("game/AutoCodes")
local AutoSummon = require("game/AutoSummon")
local LobbyShops = require("game/LobbyShops")
local MatchStats = require("game/MatchStats")
local CombatAutomation = require("game/CombatAutomation")
local SmartFarm = require("game/SmartFarm")
local InventoryAutomation = require("game/InventoryAutomation")
local LobbyUtilities = require("game/LobbyUtilities")
local PortalFarm = require("game/PortalFarm")
local View = require("app/View")
local App = {}
App.__index = App

local function configLogValue(path, value)
    local lower = tostring(path):lower()
    if lower:find("token", 1, true) or lower:find("secret", 1, true) or lower:find("password", 1, true)
        or lower:find("ds_url", 1, true) or lower:find("key", 1, true) then return "<redacted>" end
    if type(value) == "string" then return #value <= 128 and value or value:sub(1, 125) .. "..." end
    if type(value) == "number" or type(value) == "boolean" or value == nil then return value end
    return "<" .. type(value) .. ">"
end

function App.KeyPath(gameId, userId)
    return HubCore.Paths.KeyPath(gameId, userId)
end

function App.PlaceKeyPath(placeId, userId)
    return HubCore.Paths.KeyPath(placeId, userId)
end

function App.MigratePlaceKey(storage, codec, gameId, placeId, userId)
    return HubCore.Paths.MigratePlaceKey(storage, codec, gameId, placeId, userId)
end

local function languagePacksWith(overrides)
    local packs = Util.copy(Locales)
    for code, pack in pairs(overrides or {}) do
        local merged = packs[code] or {name = code, strings = {}}
        if type(pack) == "table" then
            if pack.name then merged.name = pack.name end
            for key, text in pairs(pack.strings or {}) do merged.strings[key] = text end
        end
        packs[code] = merged
    end
    return packs
end

function App.new(options, environment)
    environment = environment or (getgenv and getgenv()) or _G
    local settings = Deployment.Resolve(options, environment)
    local self = setmetatable({ scope = Scope.new(), settings = settings, services = {}, started = false, destroyed = false }, App)
    self.base = HubCore.new({environment = environment, scope = self.scope})
    self.runtime = self.base.runtime
    UI.Configure(self.runtime, self.settings)
    local ok, message = pcall(function() self:_Init() end)
    if not ok then
        if self.logs then self.logs:Error("app_init_failed", message) end
        self:Destroy()
        error(message, 2)
    end
    return self
end

function App:_LogContext()
    local result = {app_version = self.settings.Version, game_id = game.GameId, place_id = game.PlaceId, job_id = game.JobId}
    if self.player then result.user_id, result.player = self.player.UserId, self.player.Name end
    if self.adapter and self.adapter.GameData then
        local ok, data = pcall(self.adapter.GameData, self.adapter)
        if ok and type(data) == "table" then
            result.level_id, result.mode, result.location, result.challenge = data.id, data.mode, data.location, data.challenge
        end
    end
    local wave = workspace and workspace:FindFirstChild("_wave_num")
    if wave and wave:IsA("ValueBase") then result.wave = wave.Value end
    return result
end

function App:_Init()
    if not game:IsLoaded() then game.Loaded:Wait() end
    local players = game:GetService("Players")
    local player = players.LocalPlayer
    assert(player, "Saint Hub must run on the client")
    if not self.settings.AllowAnyGame then assert(game.GameId == self.settings.GameId, "Unsupported game for Saint Hub") end
    assert(player:WaitForChild("PlayerGui", 10), "PlayerGui did not load")
    self.player = player
    -- Observe battle start before storage, UI download and authorization can
    -- yield. This passive clock does not enable recording/playback or bypass auth.
    self.macroClock = Macros.new({scope = self.scope, adapter = {}})
    self.storage = self.runtime:Storage()
    local codec = self.runtime:Codec()
    self.base:SetIdentity(game.GameId, player.UserId)
    local base = self.base.basePath
    self.basePath, self.codec = base, codec
    self.transfer = Transfer.new({codec = codec, defaults = Defaults.config(), migrate = Defaults.migrate, validate = Defaults.validate})
    self.config = self.base:Config({ path = base .. "/config.json", defaults = Defaults.config(), storage = self.storage,
        codec = codec, migrate = Defaults.migrate, validate = Defaults.validate })
    self.logs = SessionLogs.new({scope = self.scope, runtime = self.runtime, config = self.config,
        path = self.basePath .. "/logs", context = function() return self:_LogContext() end})
    self.services.sessionLogs = self.logs
    self.scope:SetErrorHandler(function(stage, message)
        if self.logs then self.logs:Error("scope_" .. tostring(stage) .. "_failed", message) end
    end)
    self.logs:Info("app_initializing", {storage = self.storage ~= nil})
    self.keyPath = App.KeyPath(game.GameId, player.UserId)
    if App.MigratePlaceKey(self.storage, codec, game.GameId, game.PlaceId, player.UserId) then
        self.logs:Info("auth_key_migrated")
    end
    self.keyConfig = self.base:Credentials({storage = self.storage, codec = codec})
    local savedKey = Util.trim(self.keyConfig:Get("key"))
    if #savedKey > 512 or savedKey:find("%c") then self:ForgetKey(); savedKey = "" end
    self.unitsConfig = self.base:Config({ path = base .. "/units-v2.json", defaults = Defaults.units(), storage = self.storage, codec = codec })
    self:_ImportUnits(base, codec)
    self.autoPlacePresets = AutoPlacePresets.new({codec = codec, storage = self.storage,
        path = base .. "/autoplace-presets-v1.json"})
    self.scope:Add(self.autoPlacePresets)
    local ui = self.runtime:LoadUI(self.settings)
    self.window = ui.new({
        id = "SaintHubV2", title = self.settings.Name .. " v" .. self.settings.Version .. " · " .. self.settings.GameName,
        width = 940, height = 600, showInfoIcons = true,
        language = self.config:Get("settings.language"), languagePacks = languagePacksWith(self.settings.LanguagePacks),
        reducedMotion = self.config:Get("settings.reducedMotion"), parent = self.runtime:Parent(),
        codec = codec, themeStorage = self.storage, themeProfile = "custom_deep_amethyst",
        keybindStorage = self.storage, keybindPath = self.basePath .. "/binds-v2.json",
        onLanguage = function(code) self.config:Set("settings.language", code) end,
        clipboard = function(text) return self.runtime:Copy(text) end,
    })
    self.scope:Add(self.window)
    local loading = self.window:ShowLoading({statusKey = "loading.interface"})
    loading:SetProgress(0.6, "loading.interface")
    self.scope:Add(self.window.Closed:Connect(function() self:Destroy() end))
    self.scope:Add(self.config.Changed:Connect(function(path, value)
        if self.logs then self.logs:Info("config_changed", {setting = path, value = configLogValue(path, value)}) end
        if path == "settings.language" then self.window.i18n:SetLanguage(value)
        elseif path == "settings.reducedMotion" then self.window:SetReducedMotion(value)
        elseif self.started and path == "settings.render" then self:_Render(value)
        elseif self.started and path == "settings.fps_cap" then self.runtime:ApplyFPS(value) end
        if self.started and (path == "visuals" or path:match("^visuals%.")) then self:_ApplyVisuals() end
    end))
    local grant
    local function authCurrent() return self.scope.alive and not self.destroyed and not self.started end
    local provider = AuthProvider.new(self.runtime, self.settings.Auth, player,
        {gameId = game.GameId, scope = self.scope, isCurrent = authCurrent})
    local auth = self.window:ShowAuth({
        keyURL = self.settings.Auth.ConfigURL,
        savedKey = savedKey,
        validate = function(key, keyURL, guard)
            local result = provider:Validate(key, keyURL, guard)
            grant = authCurrent() and type(result) == "table" and result.ok == true and result or nil
            if self.logs then
                if type(result) == "table" and result.ok == true then self.logs:Info("auth_validated")
                else self.logs:Warn("auth_rejected", {code = type(result) == "table" and result.code or "invalid_response"}) end
            end
            if type(result) == "table" and result.ok ~= true and result.code == "invalid" and key == self.keyConfig:Get("key") then
                self:ForgetKey()
            end
            return result
        end,
        timeout = self.settings.Auth.Timeout,
        onLanguage = function(code) self.config:Set("settings.language", code) end,
        getKey = function()
            self.window:Notify("home.title", self.runtime:Copy(self.settings.DiscordURL) and "ui.copy" or "ui.clipboardUnavailable")
        end,
        onSuccess = function(result, key)
            if not authCurrent() or not grant or type(result) ~= "table" or result.ok ~= true
                or result.remembered ~= (grant.remembered == true) then return false end
            grant = nil
            if self.logs then self.logs:Info("auth_succeeded") end
            self:SaveKey(key)
            if not authCurrent() then return false end
            self:Start()
            return true
        end,
    })
    if savedKey ~= "" then
        self.scope:Spawn(function()
            task.wait()
            if auth.scope.alive and not auth.busy then auth:Submit() end
        end)
    end
    loading:SetProgress(0.9, "loading.auth")
    loading:Finish()
end

function App:SaveKey(key)
    key = Util.trim(key)
    if not self.keyConfig or key == "" or #key > 512 or key:find("%c") then
        if self.logs then self.logs:Warn("auth_key_save_rejected", {code = "invalid_key"}) end
        return false
    end
    self.keyConfig:Set("key", key)
    local ok = self.keyConfig:Flush()
    if self.logs then
        if ok then self.logs:Info("auth_key_saved") else self.logs:Error("auth_key_save_failed", self.keyConfig.lastError or "write_failed") end
    end
    return ok
end

function App:ForgetKey()
    if not self.keyConfig then return false end
    self.keyConfig:Set("key", "")
    local ok = self.keyConfig:Flush()
    if self.logs then
        if ok then self.logs:Info("auth_key_forgotten") else self.logs:Error("auth_key_forget_failed", self.keyConfig.lastError or "write_failed") end
    end
    return ok
end

function App:_ImportUnits(base, codec)
    if not self.storage then return end
    local ok, decoded = pcall(function()
        if self.storage.exists(base .. "/units-v2.json") or not self.storage.exists(base .. "/units.json") then return nil end
        return codec.decode(self.storage.read(base .. "/units.json"))
    end)
    if not ok or type(decoded) ~= "table" then
        if not ok and self.logs then self.logs:Error("units_migration_failed", decoded) end
        return
    end
    for index = 1, 6 do
        local record = decoded[index] or decoded[tostring(index)]
        if type(record) == "table" then
            self.unitsConfig:Set("unit" .. index .. ".name", type(record.name) == "string" and record.name or "")
            self.unitsConfig:Set("unit" .. index .. ".uuid", type(record.uuid) == "string" and record.uuid or "")
            self.unitsConfig:Set("unit" .. index .. ".cost", Util.number(record.cost, 0, 0, 1000000000))
        end
    end
end

function App:_Render(value)
    local ok, message = pcall(function() game:GetService("RunService"):Set3dRenderingEnabled(value) end)
    if not ok and self.logs then self.logs:Error("render_setting_failed", message, {enabled = value}) end
    return ok
end

function App:ExportConfig(includeSecrets)
    return self.transfer:Export(self.config.data, {includeSecrets = includeSecrets == true})
end

function App:ImportConfig(text)
    local data, errorCode = self.transfer:Import(text)
    if not data then
        if self.logs then self.logs:Error("config_import_failed", errorCode) end
        return false, errorCode
    end
    local ok, supplied = pcall(self.codec.decode, text)
    if not ok and self.logs then self.logs:Warn("config_import_decode_warning", {code = "decode_failed"}) end
    if ok then
        for _, key in ipairs({"ds_url", "tg_token", "tg_chat_id"}) do
            if type(supplied.webhook) ~= "table" or supplied.webhook[key] == nil then
                data.webhook[key] = self.config:Get("webhook." .. key)
            end
        end
    end
    self.config:Apply(data)
    if self.logs then self.logs:Info("config_imported") end
    return true
end

function App:ListMacros() return self.macroStore:List() end

function App:_AutoPlaceSettings()
    local source = self.config.data.autoplace
    local result = {lane = source.lane}
    for index = 1, 6 do
        local unit = source["unit" .. index]
        result["unit" .. index] = {lane = unit.lane, count = unit.count, place_priority = unit.place_priority,
            upgrade_priority = unit.upgrade_priority, path_percent = unit.path_percent,
            place_type = unit.place_type, target_priority = unit.target_priority,
            auto_ability = unit.auto_ability, auto_upgrade = unit.auto_upgrade}
    end
    return result
end

function App:ListAutoPlacePresets() return self.autoPlacePresets:List() end
function App:SaveAutoPlacePreset(name)
    local ok, result, detail = self.autoPlacePresets:Save(name, self:_AutoPlaceSettings())
    if self.logs then
        if ok then
            self.logs:Info("autoplace_preset_saved", {preset = name})
            if detail then self.logs:Error("autoplace_preset_storage_failed", detail, {preset = name}) end
        else self.logs:Error("autoplace_preset_save_failed", result, {preset = name}) end
    end
    return ok, result, detail
end
function App:DeleteAutoPlacePreset(name)
    local ok, reason = self.autoPlacePresets:Delete(name)
    if self.logs then
        if ok then
            self.logs:Info("autoplace_preset_deleted", {preset = name})
            if reason then self.logs:Error("autoplace_preset_storage_failed", reason, {preset = name}) end
        else self.logs:Error("autoplace_preset_delete_failed", reason, {preset = name}) end
    end
    return ok, reason
end
function App:ExportAutoPlacePreset(name)
    local text, reason = self.autoPlacePresets:Export(name)
    if not text and self.logs then self.logs:Error("autoplace_preset_export_failed", reason, {preset = name}) end
    return text, reason
end
function App:ImportAutoPlacePreset(text)
    local ok, name, detail = self.autoPlacePresets:Import(text)
    if self.logs then
        if ok then
            self.logs:Info("autoplace_preset_imported", {preset = name})
            if detail then self.logs:Error("autoplace_preset_storage_failed", detail, {preset = name}) end
        else self.logs:Error("autoplace_preset_import_failed", name) end
    end
    return ok, name, detail
end
function App:ApplyAutoPlacePreset(name)
    local settings = self.autoPlacePresets:Get(name)
    if not settings then
        if self.logs then self.logs:Error("autoplace_preset_apply_failed", "missing_preset", {preset = name}) end
        return false, "missing_preset"
    end
    local data = Util.copy(self.config.data)
    settings.enabled = data.autoplace.enabled
    settings.upgrade_mode = data.autoplace.upgrade_mode
    for index = 1, 6 do
        local key = "unit" .. index
        if settings[key].auto_upgrade == nil then settings[key].auto_upgrade = data.autoplace[key].auto_upgrade end
    end
    data.autoplace = settings
    local ok = self.config:Apply(data)
    if self.logs then
        if ok ~= false then self.logs:Info("autoplace_preset_applied", {preset = name})
        else self.logs:Error("autoplace_preset_apply_failed", "config_rejected", {preset = name}) end
    end
    return ok, name
end

function App:SaveMacro(document)
    local ok, name, errorCode = self.macroStore:Save(document)
    self.macroLibrary = self.macroStore.items
    if ok then
        self.config:Set("macros.selected", name)
        self.config:Set("macros.level_id", self.macroStore.mapBindings[name] or "")
        if self.logs then self.logs:Info("macro_saved", {macro = name, steps = document and document.steps and #document.steps or 0}) end
        if errorCode and self.logs then self.logs:Error("macro_storage_failed", errorCode, {macro = name}) end
    elseif self.logs then
        self.logs:Error("macro_save_failed", errorCode, {macro = document and document.name})
    end
    return ok, name, errorCode
end
function App:DeleteMacro(name)
    local ok, errorCode = self.macroStore:Delete(name)
    self.macroLibrary = self.macroStore.items
    if ok and self.config:Get("macros.selected") == name then
        self.config:Set("macros.selected", "")
        self.config:Set("macros.level_id", "")
    end
    if self.logs then
        if ok then
            self.logs:Info("macro_deleted", {macro = name})
            if errorCode then self.logs:Error("macro_storage_failed", errorCode, {macro = name}) end
        else self.logs:Error("macro_delete_failed", errorCode, {macro = name}) end
    end
    return ok, errorCode
end
function App:ExportMacro(name)
    local text, reason = self.macroStore:Export(name)
    if not text and self.logs then self.logs:Error("macro_export_failed", reason, {macro = name}) end
    return text, reason
end
function App:ImportMacro(text)
    local ok, name, errorCode = self.macroStore:Import(text)
    self.macroLibrary = self.macroStore.items
    if ok then
        self.config:Set("macros.selected", name)
        self.config:Set("macros.level_id", self.macroStore.mapBindings[name] or "")
        if self.logs then self.logs:Info("macro_imported", {macro = name}) end
        if errorCode and self.logs then self.logs:Error("macro_storage_failed", errorCode, {macro = name}) end
    elseif self.logs then
        self.logs:Error("macro_import_failed", errorCode)
    end
    return ok, name, errorCode
end
function App:BeginMacroRecording(name)
    if self.services.macros.playing or self.services.macros.recording then
        if self.logs then self.logs:Warn("macro_record_rejected", {macro = name, code = "busy"}) end
        return false, "busy"
    end
    if self.adapter:InLobby() then
        if self.logs then self.logs:Warn("macro_record_rejected", {macro = name, code = "lobby"}) end
        return false, "lobby"
    end
    self.services.units:Refresh()
    local ok, reason = self.services.macros:StartRecording(name)
    if ok and self.services.capture and self.services.capture.Status then
        local ready, captureReason = self.services.capture:Status()
        if not ready then
            reason = captureReason or "capture_hook_failed"
            self.services.macros:CancelRecording(reason)
            ok = false
        end
    end
    if not ok and self.logs then self.logs:Error("macro_record_failed", reason, {macro = name}) end
    return ok, reason
end
function App:FinishMacroRecording()
    local document, errorCode = self.services.macros:StopRecording()
    if not document then
        if self.logs then self.logs:Error("macro_record_finish_failed", errorCode) end
        return false, errorCode
    end
    if type(document.steps) ~= "table" or #document.steps == 0 then
        if self.logs then self.logs:Warn("macro_record_finish_rejected", {code = "empty_macro"}) end
        return false, "empty_macro"
    end
    return self:SaveMacro(document)
end
function App:PlayMacro(name)
    if self.services.macros.playing or self.services.macros.recording then
        if self.logs then self.logs:Warn("macro_play_rejected", {macro = name, code = "busy"}) end
        return false, "busy"
    end
    local macro = self.macroLibrary[name]
    if not macro then
        if self.logs then self.logs:Error("macro_play_failed", "missing_macro", {macro = name}) end
        return false, "missing_macro"
    end
    local normalized, errorCode = self.services.macros:Validate(macro)
    if not normalized then
        if self.logs then self.logs:Error("macro_play_failed", errorCode, {macro = name, stage = "validation"}) end
        return false, errorCode
    end
    local level
    if self.macroStore then level = self.macroStore.mapBindings[name] or "" else level = self.config:Get("macros.level_id") or "" end
    if level ~= "" and self.adapter:GameData().id ~= level then
        if self.logs then self.logs:Warn("macro_play_rejected", {macro = name, code = "wrong_level", expected_level = level}) end
        return false, "wrong_level"
    end
    -- Refresh equipped IDs before playback is queued. Units still performs a
    -- bounded lazy refresh per step, but starting from the current hotbar keeps
    -- slot/ordinal resolution deterministic when a loadout changed in lobby.
    self.services.units:Refresh()
    local ok, reason = self.services.macros:Play(normalized)
    if not ok and self.logs then self.logs:Error("macro_play_failed", reason, {macro = name, stage = "queue"}) end
    return ok, reason
end
function App:StopMacro()
    if self.services.macroRouter then self.services.macroRouter:Stop() end
    return self.services.macros:Stop()
end

function App:GetMacroMap(name) return self.macroStore.mapBindings[name] or "" end
function App:SetMacroMap(name, id, mode)
    local ok, _, errorCode = self.macroStore:BindMap(name, id, mode)
    if ok then self.config:Set("macros.level_id", id) end
    if self.logs then
        if ok then self.logs:Info("macro_map_bound", {macro = name, level_id = id, mode = mode})
        else self.logs:Error("macro_map_bind_failed", errorCode, {macro = name, level_id = id, mode = mode}) end
    end
    return ok, errorCode
end
function App:BindMacroToMap()
    local id, mode
    if not self.adapter:InLobby() then
        local data = self.adapter:GameData(); id, mode = data.id, MacroRouter.mode(data.mode, data.id)
        if id == self.config:Get("game.events.event_id") then mode = "event" end
    elseif self.config:Get("game.type") == "event" then id = self.adapter:ResolveEventId(self.config:Get("game.events.event_id"))
    elseif self.config:Get("game.type") == "portals" then
        local target = self.services.portalFarm and self.services.portalFarm:Preview()
        id = target and target.levelId
    else
        local mode = self.config:Get("game.type")
        local field = ({story = "storymode", raids = "raids", legend = "legend", infinity = "infinity"})[mode]
        if field then
            if not self.adapter.mapCatalog then self.adapter:MapCatalog(false) end
            id = self.adapter:SelectedLevel(mode, self.config:Get("game." .. field .. ".world_id"), self.config:Get("game." .. field .. ".level_id"))
        end
    end
    if self.adapter:InLobby() then mode = self.config:Get("game.type") end
    if not id or id == "" then return false, "missing_level" end
    local ok, errorCode = self:SetMacroMap(self.config:Get("macros.selected"), id, mode)
    return ok, ok and id or errorCode
end

function App:GetMacroAuto(name) return self.macroStore.autoEnabled[name] == true end
function App:GetMacroMode(name) return self.macroStore.modeBindings[name] or self.config:Get("game.type") end
function App:SetMacroMode(name, mode)
    local ok, reason = self.macroStore:SetMode(name, mode)
    if self.logs then
        if ok then self.logs:Info("macro_mode_changed", {macro = name, mode = mode})
        else self.logs:Error("macro_mode_change_failed", reason, {macro = name, mode = mode}) end
    end
    return ok, reason
end
function App:SetMacroAuto(name, enabled)
    local ok, errorCode = self.macroStore:SetAuto(name, enabled)
    if ok and enabled then
        -- Enabling a bound macro is an explicit choice of combat strategy. Do
        -- not leave the router armed while farm.method still selects units.
        self.config:Set("farm.method", "macro")
        self.config:Set("macros.autoPlay", true)
    end
    if self.logs then
        if ok then self.logs:Info("macro_auto_changed", {macro = name, enabled = enabled == true})
        else self.logs:Error("macro_auto_change_failed", errorCode, {macro = name, enabled = enabled == true}) end
    end
    return ok, errorCode
end

function App:ActivateMacroOnMap()
    local name = self.config:Get("macros.selected")
    local macro = self.macroLibrary[name]
    if not macro or #macro.steps == 0 then return false, "missing_macro" end
    local bound, level = self:BindMacroToMap()
    if not bound then return false, level end
    local enabled, reason = self:SetMacroAuto(name, true)
    if not enabled then return false, reason end
    self.config:Set("farm.method", "macro")
    return true, level
end

function App:_ApplyVisuals()
    local visuals = self.config.data.visuals
    local traits = {}
    for slot, trait in pairs(visuals.traits) do
        if trait ~= "" then traits[slot] = trait end
    end
    return self.services.visuals:Apply({enabled = visuals.enabled, nickname = visuals.nickname,
        resources = visuals.resources, traits = traits, shiny = visuals.shiny})
end

function App:Start()
    if self.started or self.destroyed then return end
    self.started = true
    if self.logs then self.logs:Info("app_starting") end
    self.serviceScope = self.scope:Child()
    local context = { scope = self.serviceScope, runtime = self.runtime, settings = self.settings,
        config = self.config, unitsConfig = self.unitsConfig, sessionLogs = self.logs }
    self.adapter = Adapter.new(self.player, self.serviceScope, self.settings.LobbyId)
    self.api = self.adapter -- AnimeApi v2 is integrated; distribution still contains two files.
    self.serviceScope:Add(self.adapter)
    context.adapter = self.adapter
    local ok, message = pcall(function()
        local logs = self.logs
        self.services.sessionLogs = logs
        self.serviceScope:Connect(self.adapter.BeforeCall, function(name)
            logs:Debug("game_action_started", {action = name})
        end)
        self.serviceScope:Connect(self.adapter.Succeeded, function(name, _, duration)
            logs:Info("game_action_succeeded", {action = name, duration_ms = math.floor((duration or 0) + 0.5)})
        end)
        self.serviceScope:Connect(self.adapter.Failed, function(name, reason, duration)
            local fields = {action = name, duration_ms = math.floor((duration or 0) + 0.5)}
            if reason == "busy" then fields.code = reason; logs:Warn("game_action_rejected", fields)
            else logs:Error("game_action_failed", reason, fields) end
        end)
        self.services.webhook = Webhook.new(context)
        context.webhook = self.services.webhook
        self.services.telegram = Telegram.new(context)
        context.telegram = self.services.telegram
        self.services.drops = DropNotifications.new(context)
        self.services.autoSummon = AutoSummon.new(context)
        context.autoSummon = self.services.autoSummon
        self.services.lobbyShops = LobbyShops.new(context)
        self.services.lobbyUtilities = LobbyUtilities.new(context)
        context.lobbyUtilities = self.services.lobbyUtilities
        self.services.matchStats = MatchStats.new({storage = self.storage, codec = self.codec,
            path = self.basePath .. "/match-stats-v1.json"})
        self.serviceScope:Add(self.services.matchStats)
        context.matchStats = self.services.matchStats
        self.services.combat = CombatAutomation.new(context)
        self.services.inventory = InventoryAutomation.new(context)
        context.executeStep = function(step) return self.services.units:ExecuteMacroStep(step) end
        context.clockSource = self.macroClock
        self.services.macros = Macros.new(context)
        context.macros = self.services.macros
        local previousMacro = self.services.macros:State()
        self.serviceScope:Connect(self.services.macros.Changed, function(state)
            if state.error and state.error ~= previousMacro.error then
                logs:Error("macro_runtime_failed", state.error, {macro = state.name, step = state.index})
            end
            if state.recording and not previousMacro.recording then logs:Info("macro_recording_started", {macro = state.name})
            elseif previousMacro.recording and not state.recording then
                logs:Info("macro_recording_finished", {macro = previousMacro.name, steps = previousMacro.index})
            end
            if state.playing and not previousMacro.playing then logs:Info("macro_playback_started", {macro = state.name})
            elseif previousMacro.playing and not state.playing then
                logs:Info("macro_playback_finished", {macro = previousMacro.name, steps = previousMacro.index,
                    success = state.error == nil})
            elseif state.playing and state.index ~= previousMacro.index then
                logs:Debug("macro_step_started", {macro = state.name, step = state.index})
            end
            previousMacro = {recording = state.recording, playing = state.playing, name = state.name,
                index = state.index, error = state.error}
        end)
        self.macroStore = MacroLibrary.new({codec = self.codec, storage = self.storage, path = self.basePath .. "/macros-v2.json",
            validator = function(document) return self.services.macros:Validate(document) end})
        self.serviceScope:Add(self.macroStore)
        self.macroLibrary = self.macroStore.items
        self.services.macroRouter = MacroRouter.new({scope = self.serviceScope, library = self.macroStore,
            engine = self.services.macros, play = function(name) return self:PlayMacro(name) end})
        context.challengeMethod = function(levelId, kind)
            -- Daily maps rotate behind a shared level ID, so a level-bound macro cannot identify them.
            if kind == "normal" and self.config:Get("farm.method") == "macro" and self.config:Get("macros.autoPlay")
                and #MacroRouter.matches(self.macroStore, levelId, "challenge") == 1 then return "macro" end
            if self.config:Get("autoplace.enabled") then return "units" end
        end
        local match = not self.adapter:InLobby() and self.adapter:GameData()
        local events = self.config.data.game.events
        local priorityMatch = match and self.config:Get("game.enabled") and self.config:Get("game.type") == "event"
            and ((match.challenge == "daily" and events.priorityDaily) or (match.challenge == "normal" and events.priorityNormal))
        if priorityMatch then
            context.useChallengeUnits = context.challengeMethod(match.id, match.challenge) == "units"
        end
        self.services.capture = MacroCapture.new(context)
        self.services.visuals = Visuals.new({scope = self.serviceScope, player = self.player,
            traitDescriptors = self.adapter:TraitDescriptors(),
            traitGradientSources = self.adapter:TraitGradientSources(),
            allowedResources = {"GemsLegacy", "SummerPearls"}, resourceFields = {GemsLegacy = "_resourceGemsLegacy", SummerPearls = "_resourceSummerPearls"}})
        context.onStart = function()
            local data = self.adapter:GameData()
            logs:Info("match_started", {level_id = data.id, mode = data.mode, location = data.location,
                challenge = data.challenge, farm_method = self.config:Get("farm.method")})
            if not context.useChallengeUnits and self.config:Get("farm.method") == "macro" and self.config:Get("macros.autoPlay") then
                local mode = data.id == self.config:Get("game.events.event_id") and "event" or data.mode
                local started, reason = self.services.macroRouter:Start(data.id, mode)
                if not started then logs:Error("macro_autoplay_failed", reason, {level_id = data.id, mode = mode}) end
            end
        end
        self.services.units = Units.new(context)
        self.services.portalFarm = PortalFarm.new({scope = self.serviceScope, config = self.config, adapter = self.adapter,
            storage = self.storage, codec = self.codec, path = self.basePath .. "/portal-farm-run-v1.json"})
        context.portalFarm = self.services.portalFarm
        self.services.game = GameService.new(context)
        self.services.smartFarm = SmartFarm.new({scope = self.serviceScope, config = self.config, adapter = self.adapter,
            storage = self.storage, codec = self.codec, path = self.basePath .. "/smartfarm-run-v1.json",
            challengeMethod = context.challengeMethod,
            startSelected = function(automatic) return self.services.game:StartSelected(automatic) end})
        self.services.game.smartFarm = self.services.smartFarm
        self.services.session = Session.new(context)
        self.services.codes = AutoCodes.new({scope = self.serviceScope, runtime = self.runtime, adapter = self.adapter,
            config = self.config, storage = self.storage, codec = self.codec, path = self.basePath .. "/used-codes-v2.json"})
        self.serviceScope:Connect(self.services.codes.Changed, function(result)
            local fields = {code = result.code, found = result.found or 0, used = result.used or 0,
                submitted = result.submitted or 0, skipped = result.skipped or 0, failed = result.failed or 0}
            if result.code == "done" then logs:Info("autocodes_finished", fields)
            else logs:Error("autocodes_failed", result.code, fields) end
            if result.storage then logs:Error("autocodes_storage_failed", result.storage) end
            self.window:Notify("lobby.activeCodes", result.code == "done" and "codes.result" or "codes.error",
                result.code == "done" and "info" or "error", 6, {found = result.found or 0, used = result.used or 0,
                    submitted = result.submitted or 0, skipped = result.skipped or 0, failed = result.failed or 0, code = result.code})
            if result.storage then self.window:Notify("lobby.activeCodes", "codes.unsaved", "error", 6, {code = result.storage}) end
        end)
        self:_ApplyVisuals()
        View.mount(self)
    end)
    if not ok then
        if self.logs then self.logs:Error("app_start_failed", message) end
        self.started = false
        self.serviceScope:Destroy()
        self.services = {}
        local tabs = Util.copy(self.window.tabOrder)
        for _, id in ipairs(tabs) do self.window:RemoveTab(id) end
        error(message, 2)
    end
    local previousFPS
    if self.runtime.getfps then
        local success, value = pcall(self.runtime.getfps)
        if success then previousFPS = value end
    end
    local renderKnown, previousRender = pcall(function() return game:GetService("RunService"):Is3dRenderingEnabled() end)
    if not renderKnown then previousRender = true end
    self.runtime:ApplyFPS(self.config:Get("settings.fps_cap"))
    self:_Render(self.config:Get("settings.render"))
    self.serviceScope:Add(function()
        self:_Render(previousRender)
        if previousFPS and self.runtime.fps then pcall(self.runtime.fps, previousFPS) end
    end)
    if self.config:Get("autoplace.enabled") then
        self.serviceScope:Spawn(function() self.services.units:Refresh() end)
    end
    if self.logs then self.logs:Info("app_started", {in_lobby = self.adapter:InLobby()}) end
end

function App:Destroy()
    if self.destroyed then return end
    self.destroyed = true
    if self.logs then
        self.logs:Info("app_destroying", {started = self.started})
        self.logs:Destroy()
        self.logs = nil
    end
    self.scope:Destroy()
    local env = self.runtime and self.runtime.env
    if env and env.SaintHub == self then env.SaintHub = nil end
    self.services = {}
end

return App
end

__modules["app/AuthProvider"] = function(require)
return require("sainthub-core/Auth").Validator
end

__modules["app/AutoPlacePage"] = function(require)
local Util = require("core/Util")
local Page = {}

local MAX_JSON = 128 * 1024

function Page.mount(app, create)
    local Assets = require("app/UI").Require("ui/Assets")
    local UIAssets = require("app/UIAssets")
    local cfg, window = app.config, app.window
    local frame = create:Frame({id = "autoPlacePage"})
    local build, scope = frame.Create, frame.scope
    local controls, selected = {}, ""

    local function notify(key, failure, parameters)
        window:Notify(failure and "ui.error" or "units.title", key, failure and "error" or "info", 4, parameters)
    end
    local function bind(control, path)
        scope:Connect(cfg.Changed, function(changed, value)
            if changed == path and control.scope.alive then control:Set(value, false) end
        end)
        return control
    end
    local function numeric(parent, key, path, minimum, maximum)
        return bind(parent:Input({key = key, value = cfg:Get(path), onChanged = function(value)
            local number = tonumber(value)
            if not number or number ~= number or number % 1 ~= 0 or number < minimum or number > maximum then
                notify("ui.invalidNumber", true); return false
            end
            cfg:Set(path, number)
        end}), path)
    end
    local function dropdown(parent, key, path, items)
        local control = bind(parent:Dropdown({key = key, value = cfg:Get(path), items = items,
            onChanged = function(value) cfg:Set(path, value) end}), path)
        UIAssets.DecorateDropdownModels(control)
        return control
    end
    local function toggle(parent, key, path, options)
        options = options or {}
        options.key, options.value = key, cfg:Get(path)
        options.onChanged = function(value) cfg:Set(path, value) end
        return bind(parent:Toggle(options), path)
    end
    local function slider(parent, key, path, minimum, maximum)
        return bind(parent:Slider({key = key, min = minimum, max = maximum, step = 1, value = cfg:Get(path),
            onChanged = function(value) cfg:Set(path, math.floor(tonumber(value) or minimum)) end}), path)
    end
    local function action(parent, key, callback, primary)
        return parent:Button({key = key, primary = primary, onChanged = function()
            local ok, success, value, detail = pcall(callback)
            if not ok then
                if app.logs then app.logs:Error("ui_action_failed", success, {action = key}) end
                notify("units.presetFailed", true, {code = "action_failed"}); return
            end
            if success ~= true then
                if app.logs then app.logs:Error("ui_action_failed", value or "action_failed", {action = key}) end
                notify("units.presetFailed", true, {code = tostring(value or "action_failed")}); return
            end
            return value, detail
        end})
    end

    local activePage = "team"
    local navigation = build:Pages({id = "teamNavigation", selected = "team", pages = {
        UIAssets.With({id = "team", key = "workflow.team.team"}, UIAssets.GameIcon("units")),
        UIAssets.With({id = "inventory", key = "inventory.preview"}, UIAssets.GameIcon("items")),
        {id = "presets", key = "workflow.team.presets", image = Assets.Icons.Presets}},
        onChanged = function(id) activePage = id end})
    local pages = navigation.pages
    local team = pages.team.Create
    local inventoryBuild, presetBuild = pages.inventory.Create, pages.presets.Create
    local topActions = team:Columns({id = "unitActions", columns = 3, breakpoint = 500}).Columns
    topActions[1]:Button({key = "units.refresh", onChanged = function()
        notify("units.loaded", false, {count = app.services.units:Refresh()})
    end})
    topActions[2]:Button({key = "units.autoFill", onChanged = function()
        if app.adapter:InLobby() then notify("units.autoFillMatchOnly", true); return end
        local count, skipped = app.services.units:AutoFill()
        notify("units.autoFillResult", count == 0, {count = count, skipped = skipped})
    end})
    topActions[3]:Button({key = "tab.macros", onChanged = function() window:SelectTab("macros") end})
    local automation = team:Badge({text = ""})
    local function refreshAutomation()
        automation:SetText(window.i18n:T("workflow.autoPlace") .. ": " .. window.i18n:T(cfg:Get("autoplace.enabled") and "ui.enabled" or "home.off"))
    end
    scope:Connect(cfg.Changed, function(path) if path == "autoplace.enabled" then refreshAutomation() end end)
    scope:Connect(window.i18n.Changed, refreshAutomation)
    refreshAutomation()
    local selectedSlot = 1
    local selectors, editors = {}, {}
    local refreshPortrait
    local function selectSlot(index)
        selectedSlot = index
        for slot, editor in ipairs(editors) do editor:Visible(slot == index) end
        for slot, selector in ipairs(selectors) do
            selector.outline.Transparency = slot == index and 0 or 0.8
            selector.root.BackgroundColor3 = slot == index and window.theme.AccentSoft or window.theme.Surface
        end
        if refreshPortrait then refreshPortrait() end
    end
    local strip = team:Horizontal({id = "teamPortraits", height = 78, gap = 8})
    for index = 1, 6 do
        local card = strip.Create:Card({id = "unitSelect" .. index, text = tostring(index), height = 76})
        selectors[index] = card
        card.root.Size = UDim2.fromOffset(108, 76)
        card.label.Position = UDim2.new(0, 3, 1, -19)
        card.label.Size = UDim2.new(1, -6, 0, 16)
        card.label.TextSize = 10
        card.label.TextXAlignment = Enum.TextXAlignment.Center
        local accent = card.root:FindFirstChild("Accent")
        if accent then accent.Visible = false end
        card.outline = card.root:FindFirstChildOfClass("UIStroke")
        local hit = Instance.new("TextButton")
        hit.Name = "Select"
        hit.Text = ""
        hit.BackgroundTransparency = 1
        hit.Size = UDim2.fromScale(1, 1)
        hit.ZIndex = 5
        hit.Parent = card.root
        function card:Activate() selectSlot(index); return true end
        card.scope:Connect(hit.Activated, function() card:Activate() end)
        if window.themes then window.themes:Bind(card.root, "BackgroundColor3", function(colors)
            return selectedSlot == index and colors.AccentSoft or colors.Surface
        end, card.scope) end
    end
    for index = 1, 6 do
        local editor = team:Frame({id = "unitEditor" .. index})
        editors[index] = editor
        local path = "autoplace.unit" .. index .. "."
        local edit = editor.Create
        local coreRules = edit:Group({id = "unitCoreRules", key = "workflow.team.placement", open = true}).Create
        local placement = coreRules:Columns({id = "placementFields", columns = 3, breakpoint = 500}).Columns
        numeric(placement[1], "units.count", path .. "count", 0, 20)
        numeric(placement[2], "units.lane", path .. "lane", 1, 16)
        numeric(placement[3], "units.placePriority", path .. "place_priority", 1, 6)
        local position = coreRules:Columns({id = "positionFields", columns = 2, breakpoint = 420}).Columns
        slider(position[1], "units.position", path .. "path_percent", 0, 100)
        dropdown(position[2], "units.type", path .. "place_type", {
            {value = "ground", key = "units.ground"}, {value = "hill", key = "units.hill"}})
        local automationFields = coreRules:Columns({id = "unitAutomation", columns = 2, breakpoint = 420}).Columns
        toggle(automationFields[1], "units.autoUpgrade", path .. "auto_upgrade", {field = true})
        numeric(automationFields[2], "units.upgradePriority", path .. "upgrade_priority", 1, 6)
        local combat = coreRules:Columns({id = "unitCombat", columns = 2, breakpoint = 420}).Columns
        toggle(combat[1], "units.autoAbility", path .. "auto_ability", {field = true})
        dropdown(combat[2], "combat.priority", path .. "target_priority", {
            {value = "original", key = "combat.original"}, {value = "first", key = "combat.first"},
            {value = "last", key = "combat.last"}, {value = "strongest", key = "combat.strongest"},
            {value = "weakest", key = "combat.weakest"}, {value = "air", key = "combat.air"}})
    end
    local policy = team:Group({id = "upgradePolicy", key = "units.upgradeMode", collapsible = true}).Create
    dropdown(policy, "units.upgradeMode", "autoplace.upgrade_mode", {
        {value = "available", key = "units.upgradeAvailable"}, {value = "strict", key = "units.upgradeStrict"}})
    policy:Label({key = "units.upgradeStrictHint"})
    refreshPortrait = function()
        if not scope.alive then return end
        local hotbar = app.adapter.Hotbar and app.adapter:Hotbar() or {}
        for index = 1, 6 do
            local current = hotbar[index]
            local name = current and current.name or app.unitsConfig and app.unitsConfig:Get("unit" .. index .. ".name")
            name = type(name) == "string" and name ~= "" and name or window.i18n:T("ui.none")
            selectors[index]:SetText(string.format("%d · %s", index, name))
            selectors[index]:SetViewport(current and current.viewport)
            selectors[index].label.Position = UDim2.new(0, 3, 1, -19)
            selectors[index].label.Size = UDim2.new(1, -6, 0, 16)
            local viewport = selectors[index].viewport
            if viewport then
                viewport.AnchorPoint = Vector2.new(0.5, 0)
                viewport.Position = UDim2.new(0.5, 0, 0, 2)
                viewport.Size = UDim2.fromOffset(46, 46)
            end
        end
    end
    if app.unitsConfig then scope:Connect(app.unitsConfig.Changed, refreshPortrait) end
    scope:Connect(window.i18n.Changed, refreshPortrait)
    local function poll()
        if activePage == "team" and (not window.selected or window.selected == "units") then refreshPortrait() end
        scope:Delay(3, poll)
    end
    scope:Delay(3, poll)
    selectSlot(1)
    navigation:Select("team")
    presetBuild:Section({key = "units.presets"})
    presetBuild:Label({key = "units.presetsDescription"})
    local presetTop = presetBuild:Columns({id = "presetTop", columns = 2}).Columns
    controls.name = presetTop[1]:Input({key = "units.presetName", placeholderKey = "units.presetNamePlaceholder", maxLength = 64})
    controls.selected = presetTop[2]:Dropdown({key = "units.presetSelected", value = "", items = {{value = "", key = "units.presetNone"}},
        onChanged = function(value) selected = value end})

    local function refreshPresets(preferred)
        local items, seen = {{value = "", key = "units.presetNone"}}, {[''] = true}
        for _, item in ipairs(app:ListAutoPlacePresets()) do
            items[#items + 1], seen[item.value] = item, true
        end
        controls.selected:SetItems(items)
        selected = seen[preferred or selected] and (preferred or selected) or ""
        controls.selected:Set(selected, false)
        return true
    end

    local presetActions = presetBuild:Columns({id = "presetActions", columns = 3}).Columns
    action(presetActions[1], "units.presetSave", function()
        local name = Util.trim(controls.name:Get())
        local ok, saved, storageError = app:SaveAutoPlacePreset(name)
        if not ok then return false, saved end
        refreshPresets(saved); controls.name:Set(saved, false)
        notify(storageError and "units.presetMemory" or "units.presetSaved", storageError ~= nil, {name = saved})
        return true
    end, true)
    action(presetActions[2], "units.presetApply", function()
        local ok, reason = app:ApplyAutoPlacePreset(selected)
        if ok then notify("units.presetApplied", false, {name = selected}) end
        return ok, reason
    end)
    action(presetActions[3], "units.presetDelete", function()
        local name = selected
        local ok, reason = app:DeleteAutoPlacePreset(name)
        if not ok then return false, reason end
        refreshPresets(""); notify("units.presetDeleted", false, {name = name})
        return true
    end)

    local transferBuild = presetBuild:Group({id = "presetTransferGroup", key = "workflow.team.transfer", collapsible = true}).Create
    controls.json = transferBuild:Input({key = "units.presetJson", placeholderKey = "units.presetJsonPlaceholder",
        multiline = true, height = 120, maxLength = MAX_JSON})
    local transfer = transferBuild:Columns({id = "presetTransfer", columns = 2}).Columns
    action(transfer[1], "units.presetImport", function()
        local ok, name, storageError = app:ImportAutoPlacePreset(controls.json:Get())
        if not ok then return false, name end
        refreshPresets(name); controls.name:Set(name, false)
        notify(storageError and "units.presetMemory" or "units.presetImported", storageError ~= nil, {name = name})
        return true
    end)
    action(transfer[2], "units.presetExport", function()
        local text, reason = app:ExportAutoPlacePreset(selected)
        if not text then return false, reason end
        controls.json:Set(text, false)
        local copied = app.runtime and app.runtime:Copy(text)
        notify(copied and "units.presetExportCopied" or "units.presetExportReady")
        return true
    end)

    refreshPresets()
    if app.services.inventory then
        inventoryBuild:Section({key = "inventory.preview"})
        inventoryBuild:Label({key = "inventory.previewHint"})
        local preview = inventoryBuild:Label({key = "inventory.previewEmpty"})
        dropdown(inventoryBuild, "inventory.teamStrategy", "inventory.team_strategy", {
            {value = "balanced", key = "inventory.strategyBalanced"},
            {value = "rarity", key = "inventory.strategyRarity"},
            {value = "level", key = "inventory.strategyLevel"}})
        local rarity = inventoryBuild:Columns({id = "sellPreviewRarities", columns = 3}).Columns
        toggle(rarity[1], "inventory.rare", "inventory.sell_preview.rare")
        toggle(rarity[2], "inventory.epic", "inventory.sell_preview.epic")
        toggle(rarity[3], "inventory.legendary", "inventory.sell_preview.legendary")
        local actions = inventoryBuild:Columns({id = "inventoryPreviewActions", columns = 2}).Columns
        local function line(unit) return string.format("%s · %s · Lv%d%s", unit.name, unit.rarity, unit.level,
            unit.score and " · " .. tostring(math.floor(unit.score)) or "") end
        actions[1]:Button({key = "inventory.bestTeam", onChanged = function()
            local rows = {}; for _, unit in ipairs(app.services.inventory:BestTeam(6, cfg:Get("inventory.team_strategy"))) do rows[#rows + 1] = line(unit) end
            preview.options.text = #rows > 0 and table.concat(rows, "\n") or window.i18n:T("inventory.previewEmpty")
            preview.label.Text = preview.options.text
        end})
        actions[2]:Button({key = "inventory.sellPreview", onChanged = function()
            local plan, rows = app.services.inventory:SellPlan(), {}
            for _, unit in ipairs(plan.units) do rows[#rows + 1] = line(unit) end
            preview.options.text = window.i18n:T("inventory.sellPreviewResult", {
                units = #rows > 0 and table.concat(rows, "\n") or window.i18n:T("inventory.noneSafe"),
                protected = plan.protected, batches = #plan.batches})
            preview.label.Text = preview.options.text
        end})
        local equipActions = inventoryBuild:Columns({id = "inventoryEquipActions", columns = 2}).Columns
        equipActions[1]:Button({key = "inventory.equipPlan", onChanged = function()
            local plan, rows = app.services.inventory:EquipPlan(6), {}
            for _, change in ipairs(plan.changes) do
                rows[#rows + 1] = string.format("%d · %s", change.slot, line(change.unit))
            end
            preview.options.text = window.i18n:T("inventory.equipPlanResult", {
                units = #rows > 0 and table.concat(rows, "\n") or window.i18n:T("inventory.teamAlreadyBest"),
                unchanged = plan.unchanged})
            preview.label.Text = preview.options.text
        end})
        equipActions[2]:Button({key = "inventory.equipBest", primary = true, onChanged = function()
            local plan = app.services.inventory:EquipPlan(6)
            if #plan.changes == 0 then
                window:Notify("inventory.preview", "inventory.teamAlreadyBest", "info", 4); return
            end
            window:Confirm({titleKey = "inventory.equipBestConfirmTitle", messageKey = "inventory.equipBestConfirm",
                parameters = {changes = #plan.changes}, onConfirm = function()
                    scope:Spawn(function()
                        local ok, result = app.services.inventory:EquipBest(6)
                        result = type(result) == "table" and result or {code = "unknown", restored = false}
                        if ok then
                            window:Notify("inventory.preview", "inventory.equipBestDone", "info", 5,
                                {receipts = result.receipts or 0})
                            preview.options.text = window.i18n:T("inventory.equipBestDone", {receipts = result.receipts or 0})
                        else
                            window:Notify("ui.error", "inventory.equipBestFailed", "error", 6,
                                {code = result.code or "unknown", restored = tostring(result.restored == true)})
                            preview.options.text = window.i18n:T("inventory.equipBestFailed", {
                                code = result.code or "unknown", restored = tostring(result.restored == true)})
                        end
                        preview.label.Text = preview.options.text
                    end)
                    return true
                end})
        end})
    end
    return frame
end

return Page
end

__modules["app/AutoPlacePresets"] = function(require)
local Util = require("core/Util")
local Presets = {}
Presets.__index = Presets

local MAX_PRESETS, MAX_JSON = 32, 128 * 1024
local surfaces = {ground = true, hill = true}
local targetPriorities = {original = true, first = true, last = true, strongest = true, weakest = true, air = true}

local function integer(value, minimum, maximum)
    return type(value) == "number" and value == value and value % 1 == 0 and value >= minimum and value <= maximum
end

local function name(value)
    return type(value) == "string" and #value > 0 and #value <= 64 and value:find("%S") and not value:find("%c")
end

local function keys(value, allowed)
    if type(value) ~= "table" or getmetatable(value) ~= nil then return false end
    for key in next, value do if not allowed[key] then return false end end
    return true
end

local unitFields = {count = true, place_priority = true, upgrade_priority = true,
    lane = true, path_percent = true, place_pos = true, place_type = true, target_priority = true,
    auto_ability = true, auto_upgrade = true}

local function normalizeSettings(settings, legacy)
    local allowed = {lane = true}
    for index = 1, 6 do allowed["unit" .. index] = true end
    if not keys(settings, allowed) then return nil, "invalid_preset" end
    local legacyLane = legacy and settings.lane or nil
    if legacy and not integer(legacyLane, 1, 16) then return nil, "invalid_preset" end
    local result = {}
    for index = 1, 6 do
        local unit = settings["unit" .. index]
        local lane = type(unit) == "table" and (unit.lane or legacyLane)
        local percent = type(unit) == "table" and unit.path_percent
        local targetPriority = type(unit) == "table" and (unit.target_priority or "original")
        if percent == nil and type(unit) == "table" then
            percent = unit.place_pos == "spawn" and 100 or (unit.place_pos == "end" and 0 or 50)
        end
        if not keys(unit, unitFields) or not integer(lane, 1, 16) or not integer(unit.count, 0, 20)
            or not integer(unit.place_priority, 1, 6) or not integer(unit.upgrade_priority, 1, 6)
            or not integer(percent, 0, 100) or not surfaces[unit.place_type]
            or not targetPriorities[targetPriority]
            or type(unit.auto_ability) ~= "boolean" or (unit.auto_upgrade ~= nil and type(unit.auto_upgrade) ~= "boolean") then
            return nil, "invalid_preset"
        end
        result["unit" .. index] = {lane = lane, count = unit.count, place_priority = unit.place_priority,
            upgrade_priority = unit.upgrade_priority, path_percent = percent,
            place_type = unit.place_type, target_priority = targetPriority,
            auto_ability = unit.auto_ability, auto_upgrade = unit.auto_upgrade}
    end
    return result
end

local function normalizePreset(value)
    if not keys(value, {version = true, name = true, settings = true}) or
        (value.version ~= 1 and value.version ~= 2) or not name(value.name) then
        return nil, "invalid_preset"
    end
    local settings, errorCode = normalizeSettings(value.settings, value.version == 1)
    if not settings then return nil, errorCode end
    return {version = 2, name = value.name, settings = settings}
end

function Presets.new(options)
    local self = setmetatable({items = {}, codec = options.codec, storage = options.storage,
        path = options.path, dirty = false}, Presets)
    if self.storage then
        local ok, document = pcall(function()
            if not self.storage.exists(self.path) then return nil end
            local text = self.storage.read(self.path)
            assert(type(text) == "string" and #text <= 512 * 1024)
            return self.codec.decode(text)
        end)
        if ok and type(document) == "table" and document.version == 1 and type(document.presets) == "table"
            and #document.presets <= MAX_PRESETS then
            local valid = true
            for _, raw in ipairs(document.presets) do
                local preset = normalizePreset(raw)
                if not preset or self.items[preset.name] then valid = false; break end
                self.items[preset.name] = preset
            end
            if not valid then self.items, self.lastError = {}, "invalid_library" end
        elseif not ok then self.lastError = "read_failed" end
    end
    return self
end

function Presets:List()
    local result = {}
    for presetName in pairs(self.items) do result[#result + 1] = {value = presetName, label = presetName} end
    table.sort(result, function(a, b) return a.value < b.value end)
    return result
end

function Presets:Flush()
    if not self.dirty then return true end
    if not self.storage then return false, "unsupported" end
    local list = {}
    for _, item in ipairs(self:List()) do list[#list + 1] = self.items[item.value] end
    local ok = pcall(function()
        local text = self.codec.encode({version = 1, presets = list})
        assert(type(text) == "string" and #text <= 512 * 1024)
        assert(self.storage.write(self.path, text) ~= false)
    end)
    if ok then self.dirty = false end
    return ok, not ok and "write_failed" or nil
end

function Presets:Save(presetName, settings)
    if not name(presetName) then return false, "invalid_name" end
    -- Accept the previous in-memory shape once and migrate its shared lane into
    -- every slot; all newly saved/exported presets use per-unit lanes.
    local normalized, errorCode = normalizeSettings(settings, settings.lane ~= nil)
    if not normalized then return false, errorCode end
    if not self.items[presetName] and #self:List() >= MAX_PRESETS then return false, "library_full" end
    self.items[presetName] = {version = 2, name = presetName, settings = normalized}
    self.dirty = true
    local _, storageError = self:Flush()
    return true, presetName, storageError
end

function Presets:Delete(presetName)
    if not self.items[presetName] then return false, "missing_preset" end
    self.items[presetName], self.dirty = nil, true
    local _, storageError = self:Flush()
    return true, storageError
end

function Presets:Get(presetName)
    local preset = self.items[presetName]
    return preset and Util.copy(preset.settings) or nil
end

function Presets:Export(presetName)
    local preset = self.items[presetName]
    if not preset then return nil, "missing_preset" end
    local ok, text = pcall(self.codec.encode, preset)
    if not ok or type(text) ~= "string" or #text > MAX_JSON then return nil, "encode_failed" end
    return text
end

function Presets:Import(text)
    if type(text) ~= "string" or #text > MAX_JSON then return false, "invalid_json" end
    local ok, raw = pcall(self.codec.decode, text)
    if not ok then return false, "invalid_json" end
    local preset, errorCode = normalizePreset(raw)
    if not preset then return false, errorCode end
    return self:Save(preset.name, preset.settings)
end

function Presets:Destroy()
    self:Flush()
    self.items = {}
end

return Presets
end

__modules["app/Bootstrap"] = function(require)
local Shared = require("sainthub-core/Bootstrap")
local Deployment = require("app/Deployment")
local Bootstrap = {Execute = Shared.Execute, Load = Shared.Load}

function Bootstrap.Run(environment, start)
    return Shared.Run(environment, Deployment.Resolve(environment.SaintHubOptions, environment), start)
end

return Bootstrap
end

__modules["app/Defaults"] = function(require)
local Util = require("core/Util")
local TraitIcons = require("game/TraitIcons")
local Defaults = {}

function Defaults.config()
    local data = {
        version = 4,
        settings = { language = "en", reducedMotion = false, sakura = true, render = true, fps_cap = 60, sessionLogs = false },
        farm = {method = "units"},
        macros = {selected = "", autoPlay = false, level_id = ""},
        visuals = {enabled = false, nickname = "", traits = {}, shiny = {}, showResourcesOnHome = false,
            resources = {Gems = 1000000, Gold = 1000000, GemsLegacy = 1000000, SummerPearls = 1000000, Yen = 1000000}},
        session = { antiAfk = true, reconnect = true, teleport = true },
        webhook = { ds_url = "", tg_token = "", tg_chat_id = "", settings = { ongamestart = false, ongameend = false },
            summons = {enabled = true},
            drops = {enabled = false, units_secret = true, units_mythic = true, units_other = false},
            telegram = {settings = {ongamestart = false, ongameend = false}, summons = {enabled = false},
                drops = {enabled = false, units_secret = true, units_mythic = true, units_other = false}} },
        autocaptcha = true, autocodes = false, fastsummon = "",
        autosummon = {banner = "", target = "", mode = "luck", limit = 10, reserve = 0, batch = "gems", lobby_enabled = false},
        autoclaim = { quests = true, battlepass = true, dailylogin = true },
        lobby = {shops = {
            merchant = {enabled = false, food = false, stars = true, tickets = false, use_selection = false,
                selected_items = "", gem_reserve = 0, gold_reserve = 0},
            gold = {enabled = false, food = false, stars = false, use_selection = false, selected_items = "",
                quantity = 1, gold_reserve = 0, max_spend = 0},
        }, utilities = {capsules = {enabled = false, batch = 1}, party = {auto_accept = false}}},
        combat = {wave_skip = {enabled = false, stop_wave = 0}},
        smartfarm = {enabled = false, strategy = "story", goal_matches = 0, goal_minutes = 0},
        portals = {selected = "", order = "", minimum_tier = 0, friends_only = false,
            after_victory = "continue", after_defeat = "retry_once"},
        inventory = {team_strategy = "balanced", sell_preview = {rare = false, epic = false, legendary = false}},
        game = {
            type = "event", play_mode = "solo", friends_only = false, enabled = false, endless = false, vote_start = false, player_simulate = false,
            events = {event_id = "", replay = false, priorityDaily = false, priorityNormal = false},
            legend = {replay = false, world_id = "", level_id = ""},
            holidayhunt = { replay = false },
            contracts = { game_type = "1" },
            raids = { replay = false, last_id = "", world_id = "", level_id = "" },
            storymode = { replay = false, next = false, world_id = "", level_id = "", difficulty = "Normal" },
            infinity = { replay = false, last_id = "", world_id = "", level_id = "" },
            dungeon = {room_choice = 1, chest = "none", shrine = false},
            infinity_castle = {floor = 0, difficulty = "Hard", advance = true, replay = false},
        },
        autoplace = { enabled = false, upgrade_mode = "available" },
    }
    for index = 1, 6 do
        data.visuals.traits[tostring(index)], data.visuals.shiny[tostring(index)] = "", false
        data.autoplace["unit" .. index] = {lane = 1, place_type = "ground", path_percent = 50, count = 0,
            place_priority = index, upgrade_priority = index, target_priority = "original",
            auto_ability = false, auto_upgrade = true}
    end
    return data
end

function Defaults.units()
    local data = {}
    for index = 1, 6 do data["unit" .. index] = { name = "", uuid = "", cost = 0 } end
    return data
end

local modes = { ["Holiday Hunt"] = "holiday", ["Contracts"] = "contracts", ["Raids"] = "raids", ["Story Mode"] = "story", ["Infinity"] = "infinity" }
local surfaces = { ["Ground (Hibrid)"] = "ground", ["Hill (Not Placing)"] = "hill" }
local positions = { Spawn = "spawn", Middle = "middle", End = "end" }

function Defaults.migrate(data)
    data = Util.copy(data)
    local legacyTargeting = type(data.combat) == "table" and type(data.combat.targeting) == "table"
        and data.combat.targeting or nil
    if legacyTargeting and type(data.autoplace) ~= "table" then data.autoplace = {} end
    if type(data.webhook) == "table" and data.webhook.telegram == nil then
        data.webhook.telegram = {
            settings = type(data.webhook.settings) == "table" and Util.copy(data.webhook.settings) or {},
            drops = type(data.webhook.drops) == "table" and Util.copy(data.webhook.drops) or {},
            summons = {enabled = false},
        }
    end
    if type(data.macros) == "table" then data.macros.repeatCount, data.macros.speed = nil, nil end
    if type(data.game) == "table" then data.game.type = modes[data.game.type] or data.game.type end
    if type(data.game) == "table" and data.game.play_mode == nil then
        local field = ({event = "events", story = "storymode", legend = "legend", raids = "raids", infinity = "infinity"})[data.game.type]
        local previous = field and data.game[field]
        data.game.play_mode = type(previous) == "table" and previous.matchmaking == true and "matchmaking" or "solo"
    end
    if type(data.game) == "table" and (data.game.type == "holiday" or data.game.type == "contracts") then
        data.game.type, data.game.enabled = "event", false -- Never auto-start a different mode after migration.
    end
    if type(data.autoplace) == "table" then
        local legacyLane = tonumber(data.autoplace.lane) or 1
        local legacyUpgrade = data.autoplace.auto_upgrade
        for index = 1, 6 do
            local key = "unit" .. index
            local unit = data.autoplace[key]
            if unit == nil and (legacyUpgrade == false or legacyTargeting ~= nil) then
                unit = {}
                data.autoplace[key] = unit
            end
            if type(unit) == "table" then
                unit.lane = tonumber(unit.lane) or legacyLane
                unit.place_type = surfaces[unit.place_type] or unit.place_type
                unit.place_pos = positions[unit.place_pos] or unit.place_pos
                if unit.path_percent == nil then
                    unit.path_percent = unit.place_pos == "spawn" and 100 or (unit.place_pos == "end" and 0 or 50)
                end
                unit.place_pos = nil
                unit.count = tonumber(unit.count) or 0
                unit.place_priority = tonumber(unit.place_priority) or index
                unit.upgrade_priority = tonumber(unit.upgrade_priority) or index
                if unit.target_priority == nil then
                    unit.target_priority = legacyTargeting and legacyTargeting.enabled == true
                        and legacyTargeting.priority or "original"
                end
                if type(unit.auto_ability) ~= "boolean" then unit.auto_ability = false end
                if unit.auto_upgrade == nil and type(legacyUpgrade) == "boolean" then unit.auto_upgrade = legacyUpgrade end
            end
        end
        data.autoplace.lane = nil
        data.autoplace.auto_upgrade = nil
    end
    if type(data.combat) == "table" then data.combat.targeting = nil end
    data.version = 4
    return data
end

local function oneOf(value, allowed, fallback)
    for _, item in ipairs(allowed) do if value == item then return value end end
    return fallback
end

local function itemSelection(value)
    local result, seen = {}, {}
    for id in tostring(value or ""):gmatch("[^,]+") do
        if #id <= 128 and id:match("^[%w_:%-]+$") and not seen[id] then
            seen[id] = true
            result[#result + 1] = id
            if #result >= 200 then break end
        end
    end
    table.sort(result)
    return table.concat(result, ",")
end

local function portalSelection(value, preserveOrder)
    local result, seen = {}, {}
    for key in tostring(value or ""):gmatch("[^,]+") do
        if #key <= 520 and key:match("^[%w_:%-]+$") and not seen[key] then
            seen[key] = true
            result[#result + 1] = key
            if #result >= 200 then break end
        end
    end
    if not preserveOrder then table.sort(result) end
    return table.concat(result, ",")
end

function Defaults.validate(data)
    data.portals = type(data.portals) == "table" and data.portals or Util.copy(Defaults.config().portals)
    data.lobby = type(data.lobby) == "table" and data.lobby or {}
    data.lobby.shops = type(data.lobby.shops) == "table" and data.lobby.shops or Defaults.config().lobby.shops
    data.lobby.utilities = type(data.lobby.utilities) == "table" and data.lobby.utilities or Defaults.config().lobby.utilities
    data.lobby.utilities.capsules = type(data.lobby.utilities.capsules) == "table"
        and data.lobby.utilities.capsules or {enabled = false, batch = 1}
    data.lobby.utilities.party = type(data.lobby.utilities.party) == "table"
        and data.lobby.utilities.party or {auto_accept = false}
    data.autosummon.lobby_enabled = data.autosummon.lobby_enabled == true
    data.webhook.summons.enabled = data.webhook.summons.enabled == true
    data.webhook.telegram.summons.enabled = data.webhook.telegram.summons.enabled == true
    data.autoplace.upgrade_mode = oneOf(data.autoplace.upgrade_mode, {"available", "strict"}, "available")
    data.farm.method = oneOf(data.farm.method, {"units", "macro"}, "units")
    if type(data.visuals.nickname) ~= "string" or #data.visuals.nickname > 64 or data.visuals.nickname:find("%c") then
        data.visuals.nickname = ""
    else data.visuals.nickname = Util.trim(data.visuals.nickname) end
    for name, value in pairs(data.visuals.resources) do
        data.visuals.resources[name] = value == -1 and -1 or math.floor(Util.number(value, 0, 0, 1e15))
    end
    data.settings.fps_cap = math.floor(Util.number(data.settings.fps_cap, 60, 15, 360))
    data.game.type = oneOf(data.game.type, {"event", "raids", "story", "legend", "infinity", "dungeon", "infinity_castle", "portals"}, "event")
    data.game.play_mode = oneOf(data.game.play_mode, {"solo", "matchmaking"}, "solo")
    data.game.friends_only = data.game.friends_only == true
    data.game.storymode.difficulty = oneOf(data.game.storymode.difficulty, {"Normal", "Hard"}, "Normal")
    data.game.dungeon.room_choice = math.floor(Util.number(data.game.dungeon.room_choice, 1, 1, 3))
    data.game.dungeon.chest = oneOf(data.game.dungeon.chest, {"none", "normal", "rare"}, "none")
    data.game.dungeon.shrine = data.game.dungeon.shrine == true
    data.game.infinity_castle.floor = math.floor(Util.number(data.game.infinity_castle.floor, 0, 0, 10000))
    data.game.infinity_castle.difficulty = oneOf(data.game.infinity_castle.difficulty, {"Normal", "Hard"}, "Hard")
    data.game.infinity_castle.advance = data.game.infinity_castle.advance ~= false
    data.game.infinity_castle.replay = data.game.infinity_castle.replay == true
    local shops = data.lobby.shops
    for _, name in ipairs({"merchant", "gold"}) do
        local shop = type(shops[name]) == "table" and shops[name] or Util.copy(Defaults.config().lobby.shops[name])
        shops[name] = shop
        shop.enabled, shop.food, shop.stars = shop.enabled == true, shop.food == true, shop.stars == true
        shop.use_selection = shop.use_selection == true
        shop.selected_items = itemSelection(shop.selected_items)
        shop.gold_reserve = math.floor(Util.number(shop.gold_reserve, 0, 0, 1e15))
    end
    shops.merchant.tickets = shops.merchant.tickets == true
    shops.merchant.gem_reserve = math.floor(Util.number(shops.merchant.gem_reserve, 0, 0, 1e15))
    shops.gold.quantity = oneOf(math.floor(Util.number(shops.gold.quantity, 1, 1, 100)), {1, 10, 100}, 1)
    shops.gold.max_spend = math.floor(Util.number(shops.gold.max_spend, 0, 0, 1e15))
    data.lobby.utilities.capsules.enabled = data.lobby.utilities.capsules.enabled == true
    data.lobby.utilities.capsules.batch = oneOf(math.floor(Util.number(data.lobby.utilities.capsules.batch, 1, 1, 10)), {1, 10}, 1)
    data.lobby.utilities.party.auto_accept = data.lobby.utilities.party.auto_accept == true
    data.combat.wave_skip.enabled = data.combat.wave_skip.enabled == true
    data.combat.wave_skip.stop_wave = math.floor(Util.number(data.combat.wave_skip.stop_wave, 0, 0, 100000))
    data.smartfarm.enabled = data.smartfarm.enabled == true
    data.smartfarm.strategy = oneOf(data.smartfarm.strategy, {"story", "legend", "raids", "infinity"}, "story")
    data.smartfarm.goal_matches = math.floor(Util.number(data.smartfarm.goal_matches, 0, 0, 100000))
    data.smartfarm.goal_minutes = math.floor(Util.number(data.smartfarm.goal_minutes, 0, 0, 100000))
    data.portals.selected = portalSelection(data.portals.selected, false)
    data.portals.order = portalSelection(data.portals.order, true)
    data.portals.minimum_tier = math.floor(Util.number(data.portals.minimum_tier, 0, 0, 100))
    data.portals.friends_only = data.portals.friends_only == true
    data.portals.after_victory = oneOf(data.portals.after_victory, {"continue", "stop"}, "continue")
    data.portals.after_defeat = oneOf(data.portals.after_defeat, {"retry_once", "skip", "stop"}, "retry_once")
    data.inventory.sell_preview.rare = data.inventory.sell_preview.rare == true
    data.inventory.team_strategy = oneOf(data.inventory.team_strategy, {"balanced", "rarity", "level"}, "balanced")
    data.inventory.sell_preview.epic = data.inventory.sell_preview.epic == true
    data.inventory.sell_preview.legendary = data.inventory.sell_preview.legendary == true
    data.game.contracts.game_type = tostring(math.floor(Util.number(data.game.contracts.game_type, 1, 1, 6)))
    for _, mode in ipairs({"raids", "infinity"}) do
        if data.game[mode].last_id == "none" then data.game[mode].last_id = "" end
    end
    for index = 1, 6 do
        local slot = tostring(index)
        local trait = TraitIcons.default(data.visuals.traits[slot])
        data.visuals.traits[slot] = trait and trait.name or ""
        local unit = data.autoplace["unit" .. index]
        unit.lane = math.floor(Util.number(unit.lane, 1, 1, 16))
        unit.count = math.floor(Util.number(unit.count, 0, 0, 20))
        unit.path_percent = math.floor(Util.number(unit.path_percent, 50, 0, 100))
        unit.place_type = oneOf(unit.place_type, {"ground", "hill"}, "ground")
        unit.place_priority = math.floor(Util.number(unit.place_priority, index, 1, 6))
        unit.upgrade_priority = math.floor(Util.number(unit.upgrade_priority, index, 1, 6))
        unit.target_priority = oneOf(unit.target_priority,
            {"original", "first", "last", "strongest", "weakest", "air"}, "original")
    end
end

return Defaults
end

