__modules["app/FarmWorkflow"] = function(require)
-- UI projection of existing service flags. Reading never rewrites saved settings.
local Workflow = {}
function Workflow.afterVictory(cfg, mode)
    local field = mode == "story" and "storymode" or mode == "event" and "events" or mode
    if mode == "infinity_castle" and cfg:Get("game.infinity_castle.advance") then return "next" end
    if mode == "story" and cfg:Get("game.storymode.next") then return "next" end
    if cfg:Get("game." .. field .. ".replay") then return "replay" end
    if cfg:Get("game.endless") then return "endless" end
    return "stop"
end
function Workflow.setAfterVictory(cfg, mode, action)
    local field = mode == "story" and "storymode" or mode == "event" and "events" or mode
    cfg:Set("game." .. field .. ".replay", action == "replay")
    if mode == "story" then cfg:Set("game.storymode.next", action == "next") end
    if mode == "infinity_castle" then cfg:Set("game.infinity_castle.advance", action == "next") end
    cfg:Set("game.endless", action == "endless")
end
function Workflow.stop(app)
    app.config:Set("game.enabled", false)
    if app.config:Get("smartfarm.enabled") then app.config:Set("smartfarm.enabled", false) end
    app.config:Set("autoplace.enabled", false)
    app.config:Set("macros.autoPlay", false)
    -- StopMacro cancels playback/router only. A recording must still be saved explicitly.
    if app.StopMacro then app:StopMacro() end
end
function Workflow.isRunning(app)
    local cfg = app.config
    if cfg:Get("game.enabled") or cfg:Get("smartfarm.enabled") or cfg:Get("autoplace.enabled") or cfg:Get("macros.autoPlay") then return true end
    local macros = app.services and app.services.macros
    return macros ~= nil and type(macros.State) == "function" and macros:State().playing == true
end
local terminal = {unknown_result = true, target_mismatch = true, stale_pending = true,
    start_failed = true, unavailable = true, unconfirmed = true, timeout = true,
    retry_exhausted = true, defeat_stop = true}
local function serviceStatus(service)
    if not service or type(service.Status) ~= "function" then return end
    local ok, status = pcall(service.Status, service)
    return ok and type(status) == "table" and status or nil
end
function Workflow.status(app)
    local cfg = app.config
    local macros = app.services and app.services.macros
    local macro = macros and type(macros.State) == "function" and macros:State() or {}
    if macro.error then return "error", tostring(macro.error) end
    local portal = serviceStatus(app.services and app.services.portalFarm)
    local smart = serviceStatus(app.services and app.services.smartFarm)
    if not Workflow.isRunning(app) then
        if portal and terminal[portal.lastCode] then return "error", portal.lastCode end
        if smart and terminal[smart.lastCode] then return "error", smart.lastCode end
        return "stopped"
    end
    if macro.playing then return "running", "macro" end
    if portal and (portal.active or portal.lastCode == "starting") then return "waiting", portal.lastCode end
    if smart and cfg:Get("smartfarm.enabled") then
        if smart.activeLevel ~= "" or smart.lastCode == "starting" then return "waiting", smart.lastCode end
    end
    local inLobby = true
    if app.adapter and type(app.adapter.InLobby) == "function" then
        local ok, result = pcall(app.adapter.InLobby, app.adapter)
        if ok then inLobby = result == true end
    end
    if not inLobby then return "running", "match" end
    if cfg:Get("game.enabled") or cfg:Get("smartfarm.enabled") then return "waiting", "lobby" end
    return "ready"
end
function Workflow.start(app)
    local macro = app.config:Get("farm.method") == "macro"
    app.config:Set("autoplace.enabled", not macro)
    app.config:Set("macros.autoPlay", macro)
    app.config:Set("game.enabled", true)
end
function Workflow.toggle(app)
    if Workflow.isRunning(app) then Workflow.stop(app) else Workflow.start(app) end
    return Workflow.isRunning(app)
end
return Workflow
end

