__modules["app/LootGallery"] = function(require)
local UIAssets = require("app/UIAssets")

local Gallery = {}
Gallery.__index = Gallery
Gallery.DEFAULT_COLUMNS = 3

function Gallery.columnsFor(count, maximum)
    count, maximum = math.max(0, tonumber(count) or 0), math.max(2, tonumber(maximum) or Gallery.DEFAULT_COLUMNS)
    if count <= 2 or count == 4 then return 2 end
    return maximum
end

local function copy(source)
    local result = {}
    for key, value in pairs(source or {}) do result[key] = value end
    return result
end

local function amount(value)
    value = tonumber(value)
    if not value or value ~= value or value <= 0 then return "" end
    if value % 1 == 0 then return tostring(math.floor(value)) end
    return string.format("%.1f", value):gsub("%.0$", "")
end

local function valueText(window, item)
    local count = amount(item.amount)
    if count ~= "" then return "×" .. count end
    local minimum, maximum = amount(item.minAmount), amount(item.maxAmount)
    if minimum ~= "" or maximum ~= "" then
        minimum, maximum = minimum ~= "" and minimum or maximum, maximum ~= "" and maximum or minimum
        return minimum == maximum and "×" .. minimum or "×" .. minimum .. "–" .. maximum
    end
    local chance = tonumber(item.chance)
    if chance and chance == chance and chance > 0 then
        if chance <= 1 then chance = chance * 100 end
        local text = string.format("%.2f", chance):gsub("0+$", ""):gsub("%.$", "")
        return text .. "%"
    end
    return window.i18n:T("game.lootChance")
end
Gallery.valueText = valueText

function Gallery.rewardEntries(adapter, rewards)
    local result = {}
    for name, value in pairs(rewards or {}) do
        value = tonumber(value)
        if type(name) == "string" and name ~= "" and value and value == value and value > 0 then
            local row = type(adapter) == "table" and type(adapter.RewardDescriptor) == "function"
                and adapter:RewardDescriptor(name) or nil
            row = copy(row or {kind = "unknown", id = name, name = name})
            row.amount = value
            result[#result + 1] = row
        end
    end
    table.sort(result, function(a, b)
        local rank = {resource = 1, item = 2, unit = 3}
        local left, right = rank[a.kind] or 4, rank[b.kind] or 4
        if left ~= right then return left < right end
        return tostring(a.name) < tostring(b.name) or (a.name == b.name and tostring(a.id) < tostring(b.id))
    end)
    return result
end

function Gallery.mount(create, options)
    options = options or {}
    local frame = create:Frame({id = options.id or "lootGallery"})
    local self = setmetatable({frame = frame, create = frame.Create, window = options.window,
        adapter = options.adapter, columns = options.columns or Gallery.DEFAULT_COLUMNS,
        breakpoint = options.breakpoint or 360,
        body = nil, empty = nil, items = {}, signature = nil}, Gallery)
    self.empty = self.create:Label({key = options.emptyKey or "game.lootUnknown"})
    self:Set(options.items or {})
    if self.window and self.window.i18n and self.window.i18n.Changed then
        self.frame.scope:Connect(self.window.i18n.Changed, function() self:Set(self.items, true) end)
    end
    return self
end

local function signature(items)
    local rows = {}
    for index, item in ipairs(items) do
        rows[index] = table.concat({tostring(item.kind), tostring(item.id), tostring(item.name),
            tostring(item.rarity), tostring(item.amount), tostring(item.minAmount), tostring(item.maxAmount),
            tostring(item.chance), tostring(item.guaranteed)}, "|")
    end
    return table.concat(rows, "\n")
end

function Gallery:Set(items, force)
    items = type(items) == "table" and items or {}
    local nextSignature = signature(items)
    if not force and nextSignature == self.signature then return false end
    self.items, self.signature = items, nextSignature
    if self.body then self.body:Destroy(); self.body = nil end
    self.empty:Visible(#items == 0)
    if #items == 0 then return true end
    self.body = self.create:Frame({id = "cards"})
    local columns = Gallery.columnsFor(#items, self.columns)
    for first = 1, #items, columns do
        local row = self.body.Create:Columns({id = "row" .. tostring(first), columns = columns,
            breakpoint = self.breakpoint, gap = 8, columnGap = 6}).Columns
        for column = 1, columns do
            local item = items[first + column - 1]
            if item then
                local artOK, art = pcall(UIAssets.Loot, item, self.adapter)
                art = artOK and art or nil
                if not art then art = UIAssets.Reward() end
                local card = row[column]:Card({text = item.name or item.id or "?",
                    image = art and art.image, imageRectOffset = art and art.imageRectOffset,
                    imageRectSize = art and art.imageRectSize, value = valueText(self.window, item),
                    height = 48})
                local stripe = card.root:FindFirstChild("Accent")
                if stripe then stripe.Visible = false end
                card.image.Position = UDim2.new(0, 9, 0.5, 0)
                card.image.Size = UDim2.fromOffset(28, 28)
                card.label.Position = UDim2.new(0, 45, 0.5, -10)
                card.label.Size = UDim2.new(1, -105, 0, 20)
                card.label.TextSize = 12
                card.value.Size = UDim2.fromOffset(48, 24)
                card.value.TextSize = 14
            else
                row[column]:Frame({id = "spacer"})
            end
        end
    end
    return true
end

function Gallery:Destroy()
    self.frame:Destroy()
end

return Gallery
end

__modules["app/MacroLibrary"] = function(require)
local Util = require("core/Util")
local MacroLibrary = {}
MacroLibrary.__index = MacroLibrary
local validModes = {event = true, story = true, legend = true, raids = true, infinity = true, portals = true}

function MacroLibrary.new(options)
    local self = setmetatable({items = {}, mapBindings = {}, modeBindings = {}, autoEnabled = {}, codec = options.codec, storage = options.storage,
        path = options.path, validator = options.validator, dirty = false}, MacroLibrary)
    if self.storage then
        local ok, document = pcall(function()
            if not self.storage.exists(self.path) then return nil end
            local text = self.storage.read(self.path)
            assert(type(text) == "string" and #text <= 2 * 1024 * 1024)
            return self.codec.decode(text)
        end)
        if ok and type(document) == "table" and document.version == 1 and type(document.macros) == "table" then
            local items, valid = {}, true
            if #document.macros > 64 then valid = false end
            for _, macro in ipairs(document.macros) do
                local normalized = self.validator(macro)
                if not normalized or items[normalized.name] then valid = false; break end
                items[normalized.name] = normalized
            end
            if valid then
                self.items = items
                for name, id in pairs(type(document.bindings) == "table" and document.bindings or {}) do
                    if items[name] and type(id) == "string" and #id <= 128 and id:match("^[%w_:%-]+$") then self.mapBindings[name] = id end
                end
                for name, mode in pairs(type(document.modes) == "table" and document.modes or {}) do
                    if items[name] and validModes[mode] then self.modeBindings[name] = mode end
                end
                for name, enabled in pairs(type(document.enabled) == "table" and document.enabled or {}) do
                    if enabled == true and self.mapBindings[name] and self.modeBindings[name] then self.autoEnabled[name] = true end
                end
            else self.lastError = "invalid_library" end
        elseif not ok then self.lastError = "read_failed" end
    end
    return self
end

function MacroLibrary:List()
    local items = {}
    for name in pairs(self.items) do items[#items + 1] = {value = name, label = name} end
    table.sort(items, function(a, b) return a.value < b.value end)
    return items
end

function MacroLibrary:Flush()
    if not self.dirty then return true end
    if not self.storage then return false, "unsupported" end
    local macros = {}
    for _, item in ipairs(self:List()) do macros[#macros + 1] = self.items[item.value] end
    local ok = pcall(function()
        local text = self.codec.encode({version = 1, macros = macros, bindings = self.mapBindings, modes = self.modeBindings, enabled = self.autoEnabled})
        assert(type(text) == "string" and #text <= 2 * 1024 * 1024)
        assert(self.storage.write(self.path, text) ~= false)
    end)
    if ok then self.dirty = false end
    return ok, not ok and "write_failed" or nil
end

function MacroLibrary:Save(macro, levelId)
    local normalized, errorCode = self.validator(macro)
    if not normalized then return false, errorCode end
    if levelId ~= nil and (type(levelId) ~= "string" or #levelId > 128 or (levelId ~= "" and not levelId:match("^[%w_:%-]+$"))) then return false, "invalid_level" end
    if not self.items[normalized.name] and #self:List() >= 64 then return false, "library_full" end
    self.items[normalized.name] = Util.copy(normalized)
    if levelId ~= nil then self.mapBindings[normalized.name] = levelId ~= "" and levelId or nil end
    self.dirty = true
    local _, storageError = self:Flush()
    return true, normalized.name, storageError
end

function MacroLibrary:Delete(name)
    if not self.items[name] then return false, "missing_macro" end
    self.items[name] = nil
    self.mapBindings[name] = nil
    self.modeBindings[name], self.autoEnabled[name] = nil, nil
    self.dirty = true
    local _, storageError = self:Flush()
    return true, storageError
end

function MacroLibrary:Export(name)
    if not self.items[name] then return nil, "missing_macro" end
    local payload = self.items[name]
    if self.mapBindings[name] then payload = {version = 1, macro = payload, level_id = self.mapBindings[name], mode = self.modeBindings[name]} end
    local ok, text = pcall(self.codec.encode, payload)
    if not ok or type(text) ~= "string" then return nil, "encode_failed" end
    return text
end

function MacroLibrary:Destroy() self:Flush() end

function MacroLibrary:Import(text)
    if type(text) ~= "string" or #text > 128 * 1024 then return false, "invalid_json" end
    local ok, macro = pcall(self.codec.decode, text)
    if not ok then return false, "invalid_json" end
    if type(macro) == "table" and macro.macro then
        if macro.version ~= 1 then return false, "invalid_version" end
        for key in pairs(macro) do if key ~= "version" and key ~= "macro" and key ~= "level_id" and key ~= "mode" then return false, "invalid_json" end end
        if macro.mode ~= nil and not validModes[macro.mode] then return false, "invalid_mode" end
        local ok, name, errorCode = self:Save(macro.macro, macro.level_id or "")
        if ok then self.modeBindings[name] = macro.mode; self.autoEnabled[name] = nil; self.dirty = true; self:Flush() end
        return ok, name, errorCode
    end
    return self:Save(macro, "")
end

function MacroLibrary:BindMap(name, id, mode)
    if not self.items[name] then return false, "missing_macro" end
    if mode ~= nil and not validModes[mode] then return false, "invalid_mode" end
    if self.autoEnabled[name] then
        local conflict = self:Conflict(name, id, mode or self.modeBindings[name])
        if conflict then self.lastConflict = conflict; return false, "binding_conflict" end
    end
    self.modeBindings[name] = mode or self.modeBindings[name]
    return self:Save(self.items[name], id)
end

function MacroLibrary:Conflict(name, id, mode)
    for other, enabled in pairs(self.autoEnabled) do
        if enabled and other ~= name and self.mapBindings[other] == id and self.modeBindings[other] == mode then
            return {name = other, id = id, mode = mode}
        end
    end
end

function MacroLibrary:SetMode(name, mode)
    if not self.items[name] then return false, "missing_macro" end
    if not validModes[mode] then return false, "invalid_mode" end
    if self.autoEnabled[name] then
        local conflict = self:Conflict(name, self.mapBindings[name], mode)
        if conflict then self.lastConflict = conflict; return false, "binding_conflict" end
    end
    self.modeBindings[name], self.dirty = mode, true
    local _, errorCode = self:Flush()
    return true, errorCode
end

function MacroLibrary:SetAuto(name, enabled)
    if not self.items[name] then return false, "missing_macro" end
    if enabled and (not self.mapBindings[name] or not self.modeBindings[name]) then return false, "missing_binding" end
    if enabled then
        local conflict = self:Conflict(name, self.mapBindings[name], self.modeBindings[name])
        if conflict then self.lastConflict = conflict; return false, "binding_conflict" end
    end
    self.lastConflict = nil
    self.autoEnabled[name], self.dirty = enabled == true or nil, true
    local _, errorCode = self:Flush()
    return true, errorCode
end

return MacroLibrary
end

__modules["app/MacroPage"] = function(require)
local Util = require("core/Util")
local UIAssets = require("app/UIAssets")
local MacroPage = {}

local MAX_JSON = 131072

local function code(value)
    if type(value) == "string" and #value > 0 and #value <= 64 and value:match("^[%w_%-]+$") then return value end
    return "action_failed" -- never retain exceptions, documents or server payloads
end

local function validName(value)
    return type(value) == "string" and #value > 0 and #value <= 64 and
        value:find("%S") ~= nil and value:find("[%z\1-\31\127]") == nil
end

local function finite(value, minimum, maximum)
    return type(value) == "number" and value == value and value >= minimum and value <= maximum
end

function MacroPage.mount(app, create)
    local window, cfg, engine = app.window, app.config, app.services.macros
    -- A Frame owns the entire page, including native controls, connections and
    -- action jobs. Destroying it never stops a service owned by the parent App.
    local frame = create:Frame({id = "macroPage"})
    local scope, build = frame.scope, frame.Create
    local page = {scope = scope, controls = {}, busy = false}
    local controls = page.controls
    local state = engine:State()
    local lastError, selectedExists, selectedValid, selectedCount = nil, false, false, 0
    local statusParameters, summaryParameters = {}, {}
    local items = {{value = "", key = "macro.none"}}
    local sync, refreshLibrary

    local function alive()
        return scope.alive and not app.destroyed and (not window.scope or window.scope.alive)
    end

    local function notify(key, failure, parameters)
        if not alive() then return end
        -- Parent/helper exceptions are caught before they reach Controls.call,
        -- whose generic diagnostics could otherwise print sensitive contents.
        pcall(window.Notify, window, failure and "ui.error" or "macro.title", key,
            failure and "error" or "info", 4, parameters)
    end

    local function failed(reason)
        if not alive() then return end
        lastError = code(reason)
        local conflict = app.macroStore and app.macroStore.lastConflict
        if lastError == "binding_conflict" and conflict then
            notify("macro.bindingConflict", true, {name = conflict.name, id = conflict.id, mode = conflict.mode})
        else notify("macro.failed", true, {code = lastError}) end
        if sync then sync() end
    end

    local function write(path, value)
        if not alive() then return false end
        local ok = pcall(cfg.Set, cfg, path, value)
        if not alive() then return false end
        if not ok then failed("config_failed"); return false end
        return true -- Config:Set also returns false for an unchanged value
    end

    local function enabled(control, value)
        if control and control.scope.alive then control:SetEnabled(value) end
    end

    local function set(control, value)
        if alive() and control and control.scope.alive then return control:Set(value, false) end
        return false
    end

    local function text(control, key)
        if not alive() or not control.scope.alive then return end
        control.options.key = key
        control.label.Text = window.i18n:T(key, control.options.parameters and control.options.parameters())
    end

    local function readSelection()
        local name = cfg:Get("macros.selected")
        return type(name) == "string" and name or ""
    end

    local function inspectSelection()
        local name = readSelection()
        local document = app.macroLibrary and app.macroLibrary[name]
        selectedExists, selectedValid, selectedCount = document ~= nil and name ~= "", false, 0
        if selectedExists then
            local ok, normalized = pcall(engine.Validate, engine, document)
            if not alive() then return end
            if ok and normalized and normalized.name == name then
                selectedValid, selectedCount = true, #normalized.steps
            end
        end
        summaryParameters = {name = name, count = selectedCount}
        if controls.summary then
            text(controls.summary, selectedValid and "macro.documentSummary" or "macro.documentNone")
        end
    end

    sync = function()
        if not alive() then return end
        local recording, playing = state.recording == true, state.playing == true
        local idle = not page.busy and not recording and not playing
        enabled(controls.selected, idle)
        enabled(controls.refresh, idle)
        enabled(controls.recordName, idle)
        if controls.beginRecording then
            text(controls.beginRecording, cfg:Get("autoplace.enabled") and "workflow.pausePlaceRecord" or "macro.beginRecording")
        end
        if controls.stop then controls.stop:Visible(playing) end
        if controls.finishRecording then controls.finishRecording:Visible(recording) end
        enabled(controls.beginRecording, idle)
        enabled(controls.finishRecording, recording and not page.busy)
        enabled(controls.activate, idle and selectedValid and selectedCount > 0)
        enabled(controls.stop, playing and not page.busy)
        enabled(controls.delete, idle and selectedExists)
        enabled(controls.autoThis, idle and selectedValid)
        enabled(controls.mode, idle and selectedValid)
        enabled(controls.levelId, idle and selectedValid)
        enabled(controls.bindMap, idle and selectedValid)
        enabled(controls.json, idle)
        enabled(controls.import, idle)
        enabled(controls.export, idle and selectedValid)

        local name = type(state.name) == "string" and state.name or ""
        local index = finite(state.index, 0, 1000) and state.index or 0
        statusParameters = {name = name ~= "" and name or window.i18n:T("macro.unnamed"), index = index, total = selectedCount}
        local key
        if recording then key = "macro.statusRecording"
        elseif playing then
            local document = app.macroLibrary and app.macroLibrary[name]
            if document and type(document.steps) == "table" then statusParameters.total = #document.steps end
            key = "macro.statusPlaying"
        elseif page.busy then key = "macro.statusWorking"
        elseif lastError or state.error then
            statusParameters.code = code(lastError or state.error)
            key = "macro.statusFailed"
        elseif name ~= "" then key = "macro.statusReady"
        else key = "macro.statusIdle" end
        if controls.status then
            text(controls.status, key)
            controls.status:SetState(recording and "running" or playing and "running" or page.busy and "waiting"
                or (lastError or state.error) and "error" or name ~= "" and "ready" or "idle")
            controls.status:SetValue("")
        end
        if controls.autoThis and app.GetMacroAuto then set(controls.autoThis, app:GetMacroAuto(readSelection())) end
        if controls.mode and app.GetMacroMode then set(controls.mode, app:GetMacroMode(readSelection())) end
    end

    refreshLibrary = function()
        if not alive() then return false, "destroyed" end
        local listed = app:ListMacros()
        if not alive() then return false, "destroyed" end
        if type(listed) ~= "table" then return false, "invalid_library" end
        local nextItems, seen = {{value = "", key = "macro.none"}}, {[""] = true}
        for _, item in ipairs(listed) do
            if type(item) == "table" and validName(item.value) and not seen[item.value] and
                app.macroLibrary and app.macroLibrary[item.value] ~= nil then
                seen[item.value] = true
                nextItems[#nextItems + 1] = {value = item.value, label = type(item.label) == "string" and item.label or item.value}
            end
        end
        table.sort(nextItems, function(a, b) return a.value < b.value end)
        items = nextItems
        controls.selected:SetItems(items)
        local selected = readSelection()
        if not seen[selected] then
            selected = ""
            if not write("macros.selected", selected) then return false, "config_failed" end
        end
        set(controls.selected, selected)
        inspectSelection()
        sync()
        return true
    end

    -- Controls.Button is asynchronous already. The page also owns the actual
    -- helper job and a page-wide lock, so direct calls cannot queue duplicates
    -- and page destruction cancels a yielding helper before it updates widgets.
    local function button(id, key, operation, primary, parent, field)
        local control
        control = (parent or build):Button({id = id, key = key, primary = primary, field = field, onChanged = function()
            if not alive() or page.busy or not control.enabled then return false end
            page.busy, lastError = true, nil
            sync()
            scope:Spawn(function()
                if not alive() then return end
                local ok, success, result = pcall(operation)
                if not alive() then return end
                page.busy = false
                if not ok then failed("action_failed")
                elseif success ~= true then failed(result)
                else state = engine:State(); sync() end
            end)
            return true
        end})
        return control
    end

    controls.status = build:Status({id = "macroStatus", key = "macro.statusIdle", detailKey = "macro.statusHint",
        state = "ready", parameters = function() return statusParameters end})
    controls.stop = button("macroStop", "macro.stop", function() return app:StopMacro() end, false)
    controls.stop:Visible(false)
    local recordGroup = build:Group({id = "macroRecordGroup", key = "workflow.macroStepRecord", collapsible = true,
        open = state.recording == true}).Create
    recordGroup:Label({id = "macroRecordHint", key = "macro.recordHint"})
    local recordingColumns = recordGroup:Columns({id = "macroRecordingRow", columns = 2}).Columns
    controls.recordName = recordingColumns[1]:Input({id = "macroRecordName", key = "macro.recordName", placeholderKey = "macro.recordNamePlaceholder",
        value = "", maxLength = 64, onChanged = function(value)
            if not alive() then return false end
            if value ~= "" and not validName(value) then failed("invalid_name"); return false end
            return true
        end})
    controls.beginRecording = button("macroBeginRecording", "macro.beginRecording", function()
        local name = Util.trim(controls.recordName:Get())
        if not validName(name) then return false, "invalid_name" end
        local wasEnabled = cfg:Get("autoplace.enabled") == true
        if wasEnabled then cfg:Set("autoplace.enabled", false) end
        local ok, success, reason = pcall(app.BeginMacroRecording, app, name)
        if not ok or success ~= true then
            if wasEnabled then cfg:Set("autoplace.enabled", true) end
            return false, ok and reason or "action_failed"
        end
        return true
    end, true, recordingColumns[2], true)

    controls.finishRecording = button("macroFinishRecording", "macro.finishRecording", function()
        local success, name, storageError = app:FinishMacroRecording()
        if not alive() then return false, "destroyed" end
        if not success then return false, name end
        if not validName(name) then return false, "invalid_name" end
        local ok, errorCode = refreshLibrary()
        if not ok then return false, errorCode end
        if not write("macros.selected", name) then return false, "config_failed" end
        set(controls.recordName, name)
        notify(storageError and "macro.memoryOnly" or "macro.saved", storageError == "write_failed", {name = name, code = code(storageError)})
        return true
    end, true, recordGroup)
    controls.finishRecording:Visible(false)
    local libraryGroup = build:Group({id = "macroLibraryGroup", key = "workflow.macrolibrary", collapsible = true, open = true}).Create
    local libraryColumns = libraryGroup:Columns({id = "macroLibraryRow", columns = 2}).Columns
    controls.selected = libraryColumns[1]:Dropdown({id = "macroSelected", key = "macro.selected", items = items,
        value = readSelection(), onChanged = function(value)
            if not alive() then return false end
            local result = write("macros.selected", value)
            if result and app.GetMacroMap then write("macros.level_id", app:GetMacroMap(value)) end
            if result then lastError = nil; inspectSelection(); sync() end
            return result
        end})
    controls.refresh = button("macroRefresh", "macro.refresh", function() return refreshLibrary() end, false, libraryColumns[2], true)
    controls.summary = libraryGroup:Label({key = "macro.documentNone", parameters = function() return summaryParameters end})

    libraryGroup:Label({id = "macroActivationHint", key = "workflow.macroMapHint"})
    local activation = libraryGroup:Columns({id = "macroActivation", columns = 2}).Columns
    controls.bindMap = button("macroBindMap", "macro.bindMap", function()
        if not app.BindMacroToMap then return false, "missing_api" end
        local ok, id = app:BindMacroToMap()
        if not ok then return false, id end
        set(controls.levelId, id)
        notify("macro.mapBound", false, {id = id})
        return true
    end, true, activation[1], true)
    controls.autoThis = activation[2]:Toggle({id = "macroAutoThis", key = "macro.autoThis", field = true,
        value = app.GetMacroAuto and app:GetMacroAuto(readSelection()) or false,
        onChanged = function(value)
            if not app.SetMacroAuto then return false end
            local ok, errorCode = app:SetMacroAuto(readSelection(), value)
            if not ok then failed(errorCode) end
            sync()
            return ok
        end})
    libraryGroup:Label({key = "workflow.macroArmedHint"})

    controls.delete = button("macroDelete", "macro.delete", function()
        local name = readSelection()
        local success, result = app:DeleteMacro(name)
        if not alive() then return false, "destroyed" end
        if not success then return false, result or "delete_failed" end
        local ok, errorCode = refreshLibrary()
        if not ok then return false, errorCode end
        notify("macro.deleted", false, {name = name})
        return true
    end, false, libraryGroup)
    local advanced = build:Group({id = "macroAdvancedMap", key = "workflow.macroAdvanced", collapsible = true}).Create
    local bindingColumns = advanced:Columns({id = "macroBindingOptions", columns = 2}).Columns
    controls.mode = bindingColumns[1]:Dropdown({id = "macroMode", key = "macro.mode", value = app.GetMacroMode and app:GetMacroMode(readSelection()) or "event",
        items = {UIAssets.With({value = "event", key = "game.event"}, UIAssets.Mode("event")),
            UIAssets.With({value = "story", key = "game.story"}, UIAssets.Mode("story")),
            UIAssets.With({value = "legend", key = "game.legend"}, UIAssets.Mode("legend")),
            UIAssets.With({value = "raids", key = "game.raids"}, UIAssets.Mode("raids")),
            UIAssets.With({value = "infinity", key = "game.infinity"}, UIAssets.Mode("infinity")),
            UIAssets.With({value = "portals", key = "game.portals"}, UIAssets.Mode("portals"))}, onChanged = function(mode)
            if not app.SetMacroMode then return false end
            local ok, errorCode = app:SetMacroMode(readSelection(), mode)
            if not ok then failed(errorCode) end
            return ok
        end})
    UIAssets.DecorateDropdownModels(controls.mode)
    controls.levelId = bindingColumns[2]:Input({id = "macroLevelId", key = "macro.levelId", placeholderKey = "macro.levelIdPlaceholder",
        value = cfg:Get("macros.level_id"), maxLength = 128, onChanged = function(value)
            if not alive() then return false end
            if type(value) ~= "string" or #value > 128 or (value ~= "" and not value:match("^[%w_:%-]+$")) then
                failed("invalid_level"); return false
            end
            if app.SetMacroMap then
                local ok, errorCode = app:SetMacroMap(readSelection(), value)
                if not ok then failed(errorCode); return false end
            end
            return write("macros.level_id", value)
        end})

    local transfer = build:Group({id = "macroTransfer", key = "macro.jsonSection", collapsible = true}).Create
    controls.json = transfer:Input({id = "macroJson", key = "macro.json", placeholderKey = "macro.jsonPlaceholder",
        multiline = true, height = 170, maxLength = MAX_JSON, value = "", onChanged = function(value)
            if not alive() then return false end
            if type(value) ~= "string" or #value > MAX_JSON then failed("json_limit"); return false end
            return true -- the parent's ImportMacro performs strict document validation
        end})
    local jsonActions = transfer:Columns({id = "macroJsonActions", columns = 2}).Columns
    controls.import = button("macroImport", "macro.import", function()
        local document = controls.json:Get()
        if type(document) ~= "string" or #document > MAX_JSON then return false, "json_limit" end
        if Util.trim(document) == "" then return false, "empty_json" end
        local success, name, storageError = app:ImportMacro(document)
        if not alive() then return false, "destroyed" end
        if not success then return false, name end
        if not validName(name) then return false, "invalid_name" end
        local ok, errorCode = refreshLibrary()
        if not ok then return false, errorCode end
        if not write("macros.selected", name) then return false, "config_failed" end
        notify(storageError and "macro.memoryOnly" or "macro.imported", storageError == "write_failed", {name = name, code = code(storageError)})
        return true
    end, false, jsonActions[1])
    controls.export = button("macroExport", "macro.export", function()
        local document, errorCode = app:ExportMacro(readSelection())
        if not alive() then return false, "destroyed" end
        if type(document) ~= "string" then return false, errorCode or "export_failed" end
        if #document > MAX_JSON then return false, "json_limit" end
        set(controls.json, document) -- manual copying always works without a clipboard API
        local copied = false
        if app.runtime and type(app.runtime.Copy) == "function" then
            local ok, result = pcall(app.runtime.Copy, app.runtime, document)
            copied = ok and result == true
        end
        if not alive() then return false, "destroyed" end
        notify(copied and "macro.exportCopied" or "macro.exportManualCopy", false)
        return true
    end, false, jsonActions[2])

    local bindings = {
        ["macros.selected"] = controls.selected, ["macros.level_id"] = controls.levelId,
    }
    scope:Connect(cfg.Changed, function(path, value)
        if not alive() then return end
        if path == "macros" then
            for field, control in pairs(bindings) do
                if field ~= "macros.selected" then set(control, cfg:Get(field)) end
            end
            page:Refresh()
        elseif bindings[path] then
            local accepted = set(bindings[path], value)
            if path == "macros.selected" then
                lastError = nil
                if accepted == false then page:Refresh()
                else inspectSelection(); sync() end
            end
        end
    end)
    scope:Connect(engine.Changed, function(nextState)
        if not alive() then return end
        local previousError = state.error
        state = nextState or engine:State()
        if state.error and state.error ~= previousError then
            notify("macro.failed", true, {code = code(state.error)})
        end
        sync() -- no per-frame or timer polling, and no repeated document validation
    end)
    scope:Connect(window.i18n.Changed, function() if alive() then sync() end end)
    scope:Add(function() page.busy = false end)

    function page:Refresh()
        if not alive() then return false, "destroyed" end
        local ok, success, reason = pcall(refreshLibrary)
        if not alive() then return false, "destroyed" end
        if not ok then failed("action_failed"); return false, "action_failed" end
        if not success then failed(reason) end
        return success, reason
    end
    function page:Destroy() frame:Destroy() end
    page:Refresh()
    return page
end

return MacroPage
end

__modules["app/Main"] = function(require)
local Bootstrap = require("app/Bootstrap")
local environment = (getgenv and getgenv()) or _G
return Bootstrap.Run(environment, function()
    local App = require("app/App")
    local existing = environment.SaintHub
    if type(existing) == "table" and type(existing.Destroy) == "function" then existing:Destroy() end
    local app = App.new(environment.SaintHubOptions, environment)
    environment.SaintHub = app
    return app
end)
end

__modules["app/Runtime"] = function(require)
return require("sainthub-core/Runtime")
end

