__modules["app/TestPage"] = function(require)
local UI = require("app/UI")
local UIAssets = require("app/UIAssets")
local TestPage = {}

function TestPage.mount(app, create)
    if app.settings.SaintTest ~= true then return end
    local window, scope = app.window, create.scope
    if type(window.SetSeason) ~= "function" then
        create:Label({key = "test.updateUI"})
        return
    end
    local Factory = UI.Require("ui/Factory").withTheme(window.theme)
    local Season = UI.Require("ui/Season")
    local Controls = UI.Require("ui/Controls")
    local Keybinds = UI.Require("ui/Keybinds")
    create:Label({key = "test.description"})
    local pages = create:Pages({id = "testWorkspaces", pages = {
        {id = "appearance", key = "test.appearance"},
        {id = "controls", key = "test.controls"},
        {id = "diagnostics", key = "test.diagnostics"},
    }})
    local selected, particles, previewSeason, overridden = "auto", true, nil, false
    local appearance = pages.pages.appearance.Create
    local preview, selector, particleToggle
    local function suspendPreview()
        if previewSeason then
            local tab = window.tabs.testMenu
            previewSeason:Suspend(not window.root.Visible or not pages.pages.appearance.root.Visible
                or not tab or not tab.page or not tab.page.Visible)
        end
    end
    local function render(apply)
        local options = selected == "auto" and UIAssets.Season() or UIAssets.SeasonById(selected)
        options.particlesEnabled = particles
        if apply then window:SetSeason(options); overridden = selected ~= "auto" or not particles end
        if previewSeason then previewSeason:Destroy() end
        options.topInset, options.reducedMotion = 0, window.motion.reduced
        previewSeason = Season.new(preview.root, preview.scope, options)
        suspendPreview()
    end
    selector = appearance:Dropdown({key = "test.season", value = selected, items = {
        {value = "auto", key = "test.autoSeason"}, {value = "sakura", key = "season.sakura"},
        {value = "halloween", key = "season.halloween"}, {value = "winter", key = "season.winter"},
    }, onChanged = function(value) selected = value; render(true) end})
    particleToggle = appearance:Toggle({key = "test.particles", value = true, bindable = false,
        onChanged = function(value) particles = value; render(true) end})
    appearance:Label({key = "test.previewHint"})
    preview = appearance:Frame({id = "seasonPreview"})
    preview.root.AutomaticSize = Enum.AutomaticSize.None
    preview.root.Size = UDim2.new(1, 0, 0, 220)
    preview.root.BackgroundTransparency = 0
    window.themes:Bind(preview.root, "BackgroundColor3", "Background", preview.scope)
    local layout = preview.root:FindFirstChildOfClass("UIListLayout")
    if layout then layout:Destroy() end
    Factory.corner(preview.root)
    Factory.stroke(preview.root, window.theme.Border, 0.3, "Border")
    render(false)
    appearance:Button({key = "test.resetSeason", bindable = false, onChanged = function()
        selected, particles = "auto", true
        selector:Set(selected, false)
        particleToggle:Set(particles, false)
        render(true)
    end})
    scope:Connect(pages.pages.appearance.root:GetPropertyChangedSignal("Visible"), suspendPreview)
    scope:Connect(window.tabs.testMenu.page:GetPropertyChangedSignal("Visible"), suspendPreview)
    scope:Connect(window.root:GetPropertyChangedSignal("Visible"), suspendPreview)
    scope:Connect(app.config.Changed, function(path)
        if path == "settings.reducedMotion" then render(false) end
    end)
    scope:Add(function()
        if overridden and not window.destroyed then window:SetSeason(UIAssets.Season()) end
    end)

    -- Local demo registry exercises badge updates without changing the player's bind book.
    local demoKeys = Keybinds.new(scope, {codec = app.codec})
    local proxy = setmetatable({keybinds = demoKeys}, {__index = window})
    local demo = Controls.new(proxy, pages.pages.controls.root, scope, window.theme, "testSamples")
    demo:Label({key = "test.controlsHint"})
    local clicks = 0
    local counter = demo:Badge({key = "test.clicks", parameters = function() return {count = clicks} end})
    local sample = demo:Button({key = "test.sampleButton", primary = true, onChanged = function()
        clicks = clicks + 1
        counter.label.Text = window.i18n:T("test.clicks", {count = clicks})
    end})
    sample:Bind("F6")
    demo:Dropdown({key = "test.sampleKey", value = "F6", items = {
        {value = "", key = "ui.bindUnbound"}, {value = "F6", label = "F6"},
        {value = "Ctrl+K", label = "Ctrl+K"}, {value = "RightShift", label = "RightShift"},
    }, onChanged = function(value)
        if value == "" then demoKeys:Clear(sample.bindId) else sample:Bind(value) end
    end})
    demo:Toggle({key = "test.sampleToggle", value = false, bindable = false})
    demo:Slider({key = "test.sampleSlider", min = 0, max = 100, value = 50})
    demo:Input({key = "test.sampleInput", placeholderKey = "test.samplePlaceholder", maxLength = 120})
    local notifications = demo:Columns({id = "sampleNotifications", columns = 3}).Columns
    for index, kind in ipairs({"info", "success", "error"}) do
        notifications[index]:Button({key = "test.notify." .. kind, bindable = false, onChanged = function()
            window:Notify("test.title", "test.notification", kind, 4)
        end})
    end

    local diagnostics = pages.pages.diagnostics.Create
    diagnostics:Label({key = "test.diagnosticsHint"})
    local report = diagnostics:Input({key = "test.report", multiline = true, height = 240, maxLength = 8192})
    report.input.TextEditable = false
    local function refreshReport()
        local season = window.season
        local snapshot = {
            uiVersion = UI.Require("ui/init").Version,
            testMode = app.settings.SaintTest == true,
            automaticSeason = UIAssets.Season().id,
            displayedSeason = window.seasonOptions and window.seasonOptions.id or "sakura",
            theme = window.themes:Current().id,
            language = window.i18n.language,
            reducedMotion = window.motion.reduced,
            particlesEnabled = season and season.particlesEnabled,
            particles = season and #season.particles or 0,
            particleTweens = season and #season.loops or 0,
            interfaceObjects = #window.root:GetDescendants(),
            registeredActions = #window.keybinds:List(),
        }
        report:Set(app.codec.encode(snapshot), false)
    end
    local actions = diagnostics:Columns({id = "diagnosticActions", columns = 2}).Columns
    actions[1]:Button({key = "test.refreshReport", bindable = false, onChanged = refreshReport})
    actions[2]:Button({key = "test.copyReport", bindable = false, onChanged = function()
        refreshReport()
        local copied = app.runtime:Copy(report:Get())
        window:Notify("test.title", copied and "ui.copy" or "ui.clipboardUnavailable", copied and "success" or "error")
    end})
    refreshReport()
end

return TestPage
end

__modules["app/UI"] = function(require)
local UI = {}
local Runtime = require("app/Runtime")
local runtime, settings, moduleLibrary

function UI.Configure(value, options)
    runtime, settings = value, options
    moduleLibrary = nil
end

local function exported(library, name)
    if type(library.Require) == "function" then return library.Require(name) end
    return library[name:match("^ui/(%w+)$")]
end

function UI.Require(name)
    assert(runtime, "SaintUI runtime has not been configured")
    local library = runtime:LoadUI(settings)
    local value = exported(library, name)
    if value then return value end
    if settings.UI or (settings.UIPath and settings.UIPath ~= "") then
        if not moduleLibrary then
            local hosted = Runtime.new(runtime.env)
            hosted.HTTP = function(_, ...) return runtime:HTTP(...) end
            moduleLibrary = hosted:LoadUI({UIURL = settings.UIURL})
        end
        value = exported(moduleLibrary, name)
    end
    return assert(value, "SaintUI is missing " .. name)
end

return UI
end

__modules["app/UIAssets"] = function(require)
local function assets() return require("app/UI").Require("ui/Assets") end
local UIAssets = {}

-- Resolve services only when artwork is requested. View and MacroPage contract
-- tests import this module before installing their Roblox service doubles.
local function service(name)
    if not game or type(game.GetService) ~= "function" then return end
    local ok, result = pcall(game.GetService, game, name)
    return ok and result or nil
end
local function storage() return service("ReplicatedStorage") end
local function playerGui()
    local players = service("Players")
    local player = players and players.LocalPlayer
    return player and player:FindFirstChildOfClass("PlayerGui")
end

local function child(root, path)
    local current = root
    for part in tostring(path or ""):gmatch("[^%.]+") do
        current = current and current:FindFirstChild(part)
    end
    return current
end

local function descriptor(object)
    if not object or not (object:IsA("ImageLabel") or object:IsA("ImageButton")) or object.Image == "" then return end
    return {image = object.Image, imageRectOffset = object.ImageRectOffset, imageRectSize = object.ImageRectSize,
        imageColor = object.ImageColor3}
end

local function textureDescriptor(object)
    if not object then return end
    if object:IsA("Decal") or object:IsA("Texture") then
        return object.Texture ~= "" and {image = object.Texture} or nil
    end
    if object:IsA("SurfaceAppearance") then
        return object.ColorMap ~= "" and {image = object.ColorMap} or nil
    end
end

local function firstImage(root, names)
    for _, name in ipairs(names or {}) do
        local object = root and root:FindFirstChild(name, true)
        local result = descriptor(object)
        if result then return result end
    end
end

local nativeIconPaths = {
    play = {"LeftUI_test.Buttons.EventTeleport.Main.Icon"},
    story = {"LeftUI_test.Buttons.EventTeleport.Main.Icon"},
    units = {"LeftUI_test.Buttons.Inventory.Main.Icon"},
    items = {"LeftUI_test.Buttons.Items.Main.Icon"},
    shop = {"LeftUI_test.Buttons.Store.Main.Icon"},
    summon = {"LeftUI_test.Buttons.Summon.Main.Icon"},
    dungeon = {"LeftUI_test.Buttons.Dungeon.Main.Icon"},
    event = {"LeftUI_test.Buttons.EventTeleport.Main.Icon"},
    raids = {"LeftUI_test.Buttons.EventTeleport.Main.Icon"},
    infinity = {"LevelSelectGui.LevelSelect.InfoFrame.BackgroundBlack.Infinite"},
    castle = {"LevelSelectGui.LevelSelect.InfoFrame.BackgroundBlack.Infinite"},
    legend = {"LeftUI_test.ButtonsRight.Quests.Main.Icon"},
    portals = {"LeftUI_test.Buttons.Items.Main.Icon"},
    quests = {"LeftUI_test.ButtonsRight.Quests.Main.Icon"},
    guild = {"LeftUI_test.ButtonsRight.Guild.Main.Icon"},
    profile = {"LeftUI_test.ButtonsRight.Profile.Main.Icon"},
}

-- Stable fallbacks are the same native Anime Adventures images exposed by the
-- current PlayerGui. Reading PlayerGui first lets future game updates replace
-- them without requiring a SaintHub release.
local nativeIconFallbacks = {
    play = "rbxassetid://82634775887645", story = "rbxassetid://82634775887645",
    units = "rbxassetid://117774993156931", items = "rbxassetid://82420156250500",
    shop = "rbxassetid://109836798518962", summon = "rbxassetid://118139639656698",
    dungeon = "rbxassetid://116933489417523", event = "rbxassetid://82634775887645",
    raids = "rbxassetid://82634775887645", infinity = "rbxassetid://129663106545016",
    castle = "rbxassetid://129663106545016", legend = "rbxassetid://134106316084943",
    portals = "rbxassetid://82420156250500",
    quests = "rbxassetid://134106316084943", guild = "rbxassetid://111680457997352",
    profile = "rbxassetid://125056716364172", traits = "rbxassetid://99186363801156",
}

function UIAssets.GameIcon(name)
    name = ({team = "units", inventory = "units", reward = "quests", rewards = "quests",
        farm = "play", map = "play", maps = "play", raid = "raids", portal = "portals"})[name] or name
    for _, path in ipairs(nativeIconPaths[name] or {}) do
        local result = descriptor(child(playerGui(), path))
        if result then return result end
    end
    if name == "traits" then
        local result = UIAssets.Resource("_Trait") or UIAssets.Lobby("traits_area")
        if result then return result end
    end
    local fallback = nativeIconFallbacks[name]
    return fallback and {image = fallback} or nil
end

local function aliases(name, metadata)
    local result, seen = {}, {}
    local function add(value)
        if type(value) == "string" and value ~= "" and not seen[value] then
            seen[value] = true
            result[#result + 1] = value
        end
    end
    add(type(metadata) == "table" and metadata.override_item_model)
    add(type(metadata) == "table" and metadata._use_item_model)
    add(type(metadata) == "table" and metadata._use_override_item_model_3D)
    add(name)
    return result
end

function UIAssets.Resource(name)
    local root = child(storage(), "packages.assets.gui._Resource")
    return descriptor(root and root:FindFirstChild(name) and root[name]:FindFirstChild("Icon"))
end

function UIAssets.Item(name, metadata)
    if type(name) ~= "string" or name == "" then return end
    local replicated = storage()
    local names = aliases(name, metadata)
    for _, alias in ipairs(names) do
        if alias:match("^rbxassetid://%d+$") or alias:match("^https?://") then return {image = alias} end
    end
    local overrides = child(replicated, "packages.assets.gui._OverrideItemIcons")
    for _, alias in ipairs(names) do
        local art = descriptor(overrides and overrides:FindFirstChild(alias))
        if art then return art end
    end
    local shop = child(replicated, "packages.assets.gui._ShopItemIcons")
    for _, alias in ipairs(names) do
        local direct = shop and shop:FindFirstChild(alias)
        local art = descriptor(direct) or firstImage(direct)
        if art then return art end
    end
    local models = child(replicated, "packages.assets.ItemModels")
    for _, alias in ipairs(names) do
        local model = models and models:FindFirstChild(alias)
        if model then
            local art = firstImage(model)
            if art then return art end
            for _, object in ipairs(model:GetDescendants()) do
                art = textureDescriptor(object)
                if art then return art end
            end
        end
    end
end

function UIAssets.ItemModel(name, metadata)
    if type(name) ~= "string" or name == "" then return end
    local models = child(storage(), "packages.assets.ItemModels")
    for _, alias in ipairs(aliases(name, metadata)) do
        local model = models and models:FindFirstChild(alias)
        if model and model:IsA("Model") then return model end
    end
end

function UIAssets.ItemViewport(name, metadata)
    local source = UIAssets.ItemModel(name, metadata)
    if not source then return end
    local viewport = Instance.new("ViewportFrame")
    viewport.Name = "ItemModelSource"
    viewport.BackgroundTransparency = 1
    viewport.Ambient = Color3.new(1, 1, 1)
    viewport.LightColor = Color3.new(1, 1, 1)
    viewport.LightDirection = Vector3.new(-1, -1, -1)
    local ok = pcall(function()
        local model = assert(source:Clone(), "item model is not cloneable")
        for _, object in ipairs(model:GetDescendants()) do
            if object:IsA("LuaSourceContainer") then object:Destroy()
            elseif object:IsA("BasePart") then
                object.Anchored, object.CanCollide, object.CanTouch, object.CanQuery = true, false, false, false
                object.LocalTransparencyModifier = 0
            end
        end
        model:PivotTo(CFrame.new())
        model.Parent = viewport
        local bounds, size = model:GetBoundingBox()
        local camera = Instance.new("Camera")
        camera.FieldOfView = 35
        camera.Parent = viewport
        viewport.CurrentCamera = camera
        local direction = Vector3.new(1, 0.35, 0.82).Unit
        local radius = math.max(0.1, math.max(size.X, size.Y, size.Z) * 0.5)
        local distance = radius / math.tan(math.rad(camera.FieldOfView * 0.5)) * 1.1
        camera.CFrame = CFrame.lookAt(bounds.Position + direction * distance, bounds.Position)
    end)
    if not ok then viewport:Destroy(); return end
    return viewport
end

function UIAssets.AttachViewport(source, parent, scope, options)
    if not source or not parent or not scope then return end
    options = options or {}
    scope:Add(source)
    source.Name = options.name or "ItemModel"
    source.AnchorPoint = options.anchorPoint or Vector2.new(0, 0.5)
    source.Position = options.position or UDim2.new(0, 8, 0.5, 0)
    source.Size = options.size or UDim2.fromOffset(52, 52)
    source.BackgroundTransparency = 1
    source.BorderSizePixel = 0
    source.Active = false
    source.Selectable = false
    source.ZIndex = options.zIndex or 2
    source.Parent = parent
    return source
end

-- SaintUI dropdowns remain the owner of selection and popup behavior. This
-- adapter only replaces an item's small 2D glyph with a cloned game model.
function UIAssets.DecorateDropdownModels(control)
    if type(control) ~= "table" or type(control.items) ~= "table" or not control.root or not control.scope then return control end
    local hasModels = false
    for _, item in ipairs(control.items) do
        if type(item) == "table" and type(item.model) == "string" and item.model ~= "" then hasModels = true; break end
    end
    if not hasModels or control.modelDecoration then return control end
    control.modelDecoration = true
    local selectedScope
    local function source(item)
        return type(item) == "table" and type(item.model) == "string"
            and UIAssets.ItemViewport(item.model, item.modelMetadata) or nil
    end
    local function selectedItem()
        for _, item in ipairs(control.items or {}) do if item.value == control.value then return item end end
    end
    local function refreshSelected()
        if selectedScope then selectedScope:Destroy(); selectedScope = nil end
        local viewport = source(selectedItem())
        if not viewport then return end
        local icon = control.root:FindFirstChild("SelectedItemIcon")
        if not icon then viewport:Destroy(); return end
        selectedScope = control.scope:Child()
        UIAssets.AttachViewport(viewport, control.root, selectedScope, {name = "SelectedItemModel",
            anchorPoint = icon.AnchorPoint, position = icon.Position, size = icon.Size, zIndex = icon.ZIndex + 1})
        icon.Visible = false
    end
    local baseSet = control.Set
    function control:Set(value, emit)
        local result = baseSet(self, value, emit)
        refreshSelected()
        return result
    end
    local baseSetItems = control.SetItems
    function control:SetItems(items)
        local result = baseSetItems(self, items)
        refreshSelected()
        return result
    end
    local baseOpen = control.Open
    function control:Open()
        local result = baseOpen(self)
        local popup = self.root:FindFirstChild("DropdownItems")
        if not popup or not self.popupScope then return result end
        local buttons = {}
        for _, child in ipairs(popup:GetChildren()) do
            if child:IsA("TextButton") then buttons[child.LayoutOrder] = child end
        end
        for index, item in ipairs(self.items or {}) do
            local button, viewport = buttons[index], source(item)
            local icon = button and button:FindFirstChild("ItemIcon")
            if viewport and icon then
                UIAssets.AttachViewport(viewport, button, self.popupScope, {name = "ItemModel",
                    anchorPoint = icon.AnchorPoint, position = icon.Position, size = icon.Size, zIndex = icon.ZIndex + 1})
                icon.Visible = false
            elseif viewport then viewport:Destroy() end
        end
        return result
    end
    refreshSelected()
    return control
end

function UIAssets.SetBannerModel(control, source, previous)
    if previous then previous:Destroy(); previous = nil end
    local tile = control and control.art and control.art.Parent
    if not tile then return nil, false end
    if not source then
        control.art.Visible = control.art.Image ~= ""
        tile.Visible = control.art.Visible
        return nil, false
    end
    local scope = control.scope:Child()
    scope:Add(source)
    source.Name = "PortalModel"
    source.AnchorPoint = Vector2.new(0.5, 0.5)
    source.Position = UDim2.fromScale(0.5, 0.5)
    source.Size = UDim2.fromOffset(62, 62)
    source.BackgroundTransparency = 1
    source.ZIndex = control.art.ZIndex + 1
    source.Parent = tile
    tile.Visible = true
    control.art.Visible = false
    return scope, true
end

function UIAssets.Loot(item, adapter)
    if type(item) ~= "table" then return UIAssets.Reward() end
    if item.kind == "resource" then return UIAssets.Resource(item.id) end
    if item.kind == "item" then
        local metadata = adapter and type(adapter.ItemMetadata) == "function" and adapter:ItemMetadata(item.id)
        return UIAssets.Item(item.id, metadata)
            or (type(metadata) == "table" and metadata.item_group == "Skins"
                and UIAssets.GameIcon("items"))
    end
    if item.kind == "unit" then return UIAssets.GameIcon("units") end
    return UIAssets.Reward()
end

UIAssets.ItemAliases = aliases

function UIAssets.Map(map)
    if type(map) ~= "string" or map == "" then return end
    local root = child(storage(), "packages.assets.MapIcons")
    local folder = child(root, map) or (root and root:FindFirstChild(map))
    return descriptor(folder and (folder:FindFirstChild("main") or folder:FindFirstChildWhichIsA("ImageLabel", true)))
end

function UIAssets.Lobby(name)
    if type(name) ~= "string" or name == "" then return end
    local root = child(storage(), "packages.assets.MapIcons.LobbyIcons")
    local folder = root and root:FindFirstChild(name)
    return descriptor(folder and (folder:FindFirstChild("main") or folder:FindFirstChildWhichIsA("ImageLabel", true)))
end

function UIAssets.MapBackground(map)
    local result = UIAssets.Map(map)
    if result then result.background = true end
    return result
end

function UIAssets.Dungeon()
    local root = child(storage(), "packages.assets.gui.DungeonItems")
    return UIAssets.GameIcon("dungeon")
        or firstImage(root, {"key", "key_legendary", "treasure", "chest", "sword_legendary", "axe_legendary"})
end

function UIAssets.Castle()
    return UIAssets.GameIcon("castle")
end

function UIAssets.DungeonBackground()
    local root = child(playerGui(), "DungeonUI")
    local image = child(root, "Main.Main.Outer.MainHolder.Outer.OuterImage")
    local result = descriptor(image)
    if result then result.background = true end
    return result
end

function UIAssets.CastleBackground()
    local root = child(playerGui(), "InfiniteTowerUI")
    local image = child(root, "LevelSelect.InfoFrame.BackgroundBlack.ImageLabel")
    local result = descriptor(image)
    if result then result.background = true end
    return result
end

function UIAssets.BattlePass()
    local root = child(storage(), "packages.assets.gui._Resource")
    local current = root and (root:FindFirstChild("_BattlePassXP_mana_october") or root:FindFirstChild("_BattlePassXP", true))
    return descriptor(current and current:FindFirstChild("Icon")) or UIAssets.GameIcon("quests")
end

function UIAssets.Reward()
    return UIAssets.GameIcon("quests") or UIAssets.GameIcon("items")
end

function UIAssets.Trait()
    return UIAssets.GameIcon("traits")
end

function UIAssets.Summon()
    local frame = child(playerGui(), "SummonGUI.BannerFrames.Summer2026")
    return descriptor(frame and frame:FindFirstChild("ball")) or UIAssets.Resource("SummerPearls")
        or UIAssets.GameIcon("summon")
end

function UIAssets.Navigation(name)
    if name == "lobby" then return (UIAssets.GameIcon("summon") or {}).image end
    if name == "visual" then return UIAssets.Trait().image end
    return ({home = assets().Icons.Overview, farm = (UIAssets.GameIcon("play") or {}).image,
        units = (UIAssets.GameIcon("units") or {}).image,
        macros = assets().Icons.Timeline, settings = assets().Icons.Settings})[name]
end

function UIAssets.SeasonById(id)
    return assets().SeasonById(id)
end

function UIAssets.Season(date)
    return assets().Season(date)
end

function UIAssets.Mode(mode, map)
    if mode == "dungeon" then return UIAssets.Dungeon() end
    if mode == "infinity_castle" then return UIAssets.Castle() end
    if mode == "event" then return UIAssets.GameIcon("event") end
    if mode == "raids" then return UIAssets.With(UIAssets.GameIcon("raids"), {model = "raid_ticket"}) end
    if mode == "story" then return UIAssets.GameIcon("story") end
    if mode == "infinity" then return UIAssets.GameIcon("infinity") end
    if mode == "legend" then return UIAssets.GameIcon("legend") end
    if mode == "portals" then return UIAssets.GameIcon("portals") end
    return UIAssets.GameIcon("play")
end

function UIAssets.With(item, art)
    local result = {}
    for key, value in pairs(item or {}) do result[key] = value end
    for key, value in pairs(art or {}) do result[key] = value end
    return result
end

function UIAssets.DecorateWorlds(worlds)
    local result = {}
    for index, world in ipairs(worlds or {}) do
        result[index] = UIAssets.With(world, UIAssets.GameIcon("play"))
    end
    return result
end

return UIAssets
end

__modules["app/View"] = function(require)
local Util = require("core/Util")
local Webhook = require("game/Webhook")
local MacroPage = require("app/MacroPage")
local AutoPlacePage = require("app/AutoPlacePage")
local CodeRedemption = require("game/CodeRedemption")
local TraitIcons = require("game/TraitIcons")
local UIAssets = require("app/UIAssets")
local LootGallery = require("app/LootGallery")
local View = {}
local UI = require("app/UI")
local FarmWorkflow = require("app/FarmWorkflow")
local TestPage = require("app/TestPage")
local NotificationSettings = require("game/NotificationSettings")
local resourceImages = {
    Gems = "rbxassetid://71405874061254", GemsLegacy = "rbxassetid://88024407794644",
    Gold = "rbxassetid://100751534594369", SummerPearls = "rbxassetid://128058918644138",
}

function View.mount(app)
    local Assets = UI.Require("ui/Assets")
    local window, cfg = app.window, app.config
    local headerSettings = type(window.SetSettingsTab) == "function"
    local function notify(key, errorState, parameters)
        window:Notify(errorState and "ui.error" or "home.title", key, errorState and "error" or "info", 4, parameters)
    end
    local function copy()
        notify(app.runtime:Copy(app.settings.DiscordURL) and "ui.copy" or "ui.clipboardUnavailable")
    end
    local function toggle(create, key, path, bindId, art)
        local options = { key = key, value = cfg:Get(path), bindId = bindId,
            onChanged = function(value) cfg:Set(path, value) end }
        for field, value in pairs(art or {}) do options[field] = value end
        local control = create:Toggle(options)
        control.scope:Add(cfg.Changed:Connect(function(changed, value) if changed == path then control:Set(value, false) end end))
        return control
    end
    local function dropdown(create, key, path, items, after)
        local control = create:Dropdown({ key = key, value = cfg:Get(path), items = items, onChanged = function(value)
            cfg:Set(path, value)
            if after then after(value) end
        end })
        UIAssets.DecorateDropdownModels(control)
        control.scope:Add(cfg.Changed:Connect(function(changed, value) if changed == path then control:Set(value, false) end end))
        return control
    end
    local function segmented(create, key, path, items, after)
        local control = create:Segmented({key = key, value = cfg:Get(path), items = items, onChanged = function(value)
            cfg:Set(path, value)
            if after then after(value) end
        end})
        control.scope:Add(cfg.Changed:Connect(function(changed, value) if changed == path then control:Set(value, false) end end))
        return control
    end
    local function input(create, key, path, placeholderKey, validate)
        local control = create:Input({ key = key, value = cfg:Get(path), placeholderKey = placeholderKey, onChanged = function(value)
            if validate and not validate(value) then return false end
            cfg:Set(path, value)
        end })
        control.scope:Add(cfg.Changed:Connect(function(changed, value) if changed == path then control:Set(value, false) end end))
        return control
    end
    local function numeric(create, key, path, minimum, maximum)
        return create:Input({ key = key, value = cfg:Get(path), onChanged = function(value)
            local number = tonumber(value)
            if not number or number ~= number or number < minimum or number > maximum or number % 1 ~= 0 then
                notify("ui.invalidNumber", true)
                return false
            end
            cfg:Set(path, number)
        end })
    end

    local function pages(create, id, definitions, options)
        options = options or {}
        options.id, options.pages = id, definitions
        return create:Pages(options)
    end
    local function back(create, target)
        create:Button({key = "workflow.back", onChanged = function() window:SelectTab(target) end})
    end

    local function openSettings(id)
        if not window:SelectTab("settings") then return false end
        return not id or not app.settingsNavigation or app.settingsNavigation:Select(id)
    end
    local function levelForMode(mode)
        if mode == "event" then
            local id = cfg:Get("game.events.event_id")
            if app.adapter.Events then
                local events = app.adapter:Events()
                for _, event in ipairs(events) do if event.value == id then return id end end
                if #events == 1 then return events[1].value end
            end
            return id
        end
        if mode == "portals" then
            local target = app.services.portalFarm and app.services.portalFarm:Preview()
            return target and target.levelId or ""
        end
        if mode == "dungeon" or mode == "infinity_castle" then return "" end
        local field = mode == "story" and "storymode" or mode
        local selected, worldId = cfg:Get("game." .. field .. ".level_id"), cfg:Get("game." .. field .. ".world_id")
        local catalog = app.adapter.mapCatalog
        local fallback
        for _, world in ipairs(catalog and catalog[mode] or {}) do
            fallback = fallback or (world.levels and world.levels[1] and world.levels[1].value)
            if world.value == worldId then
                for _, level in ipairs(world.levels or {}) do if level.value == selected then return selected end end
                return world.levels and world.levels[1] and world.levels[1].value or fallback or selected
            end
            for _, level in ipairs(world.levels or {}) do if level.value == selected then return selected end end
        end
        return fallback or selected
    end
    local function lootForLevel(levelId, fallbackMode)
        if fallbackMode == "dungeon" or fallbackMode == "infinity_castle" then
            local context = app.adapter.SpecialModeContext and app.adapter:SpecialModeContext(fallbackMode)
            return context and context.loot or {}
        end
        local loot = levelId ~= "" and app.adapter.LevelLoot and app.adapter:LevelLoot(levelId) or {}
        if #loot == 0 and (fallbackMode == "story" or fallbackMode == "infinity" or fallbackMode == "raids") then
            loot = {{kind = "resource", id = "Gems", name = "Gems"}}
        end
        return loot
    end
    local function primaryLootArt(levelId, mode)
        local first = lootForLevel(levelId, mode)[1]
        if not first then return end
        local art = UIAssets.Loot(first, app.adapter)
            or (first.kind == "resource" and resourceImages[first.id] and {image = resourceImages[first.id]})
        return art and not art.model and art or nil
    end
    local function decorateRouteBanner(control, background)
        local root = control and control.root
        if not root then return end
        root.ClipsDescendants = true
        local image = Instance.new("ImageLabel")
        image.Name = "MapBackground"
        image.BackgroundTransparency = 1
        image.Size = UDim2.fromScale(1, 1)
        image.ScaleType = Enum.ScaleType.Crop
        image.ImageColor3 = Color3.fromRGB(175, 168, 196)
        image.ImageTransparency = 0.4
        image.ZIndex = math.max(0, root.ZIndex)
        image.Parent = root
        -- UICorner on the Banner root does not reliably mask a full-size child
        -- ImageLabel. Give the map layer the exact same live radius so native
        -- artwork preserves the card silhouette across theme changes.
        local rootCorner = root:FindFirstChildOfClass("UICorner")
        local imageCorner = Instance.new("UICorner")
        imageCorner.Name = "MapBackgroundCorner"
        imageCorner.CornerRadius = rootCorner and rootCorner.CornerRadius or UDim.new(0, 12)
        imageCorner.Parent = image
        if rootCorner and control.scope then
            control.scope:Connect(rootCorner:GetPropertyChangedSignal("CornerRadius"), function()
                imageCorner.CornerRadius = rootCorner.CornerRadius
            end)
        end
        for _, child in ipairs(root:GetDescendants()) do
            if child ~= image and child:IsA("GuiObject") then child.ZIndex = math.max(child.ZIndex, image.ZIndex + 1) end
        end
        local function set(art)
            image.Image = art and art.background == true and art.image or ""
            image.ImageRectOffset = art and art.imageRectOffset or Vector2.new()
            image.ImageRectSize = art and art.imageRectSize or Vector2.new()
            image.Visible = image.Image ~= ""
        end
        set(background)
        return set
    end

    window:CreateTab({ id = "home", key = "tab.home", icon = UIAssets.Navigation("home"), build = function(create)
        if not app.adapter.mapCatalog and app.adapter.MapCatalog then app.adapter:MapCatalog(false) end
        local match = not app.adapter:InLobby() and app.adapter.GameData and app.adapter:GameData()
        local function routeMode()
            if not match then return cfg:Get("game.type") or "event" end
            if match.id == cfg:Get("game.events.event_id") then return "event" end
            return ({infinite = "infinity", raid = "raids", storymode = "story",
                legend_stage = "legend", challenge = "event"})[match.mode] or match.mode
        end
        local function levelTitle(id)
            if type(id) ~= "string" or id == "" then return end
            local metadata = app.adapter.LevelMetadata and app.adapter:LevelMetadata(id)
            if metadata and type(metadata.name) == "string" and metadata.name ~= "" then return metadata.name end
            for _, catalogMode in ipairs({"event", "story", "legend", "raids", "infinity"}) do
                for _, world in ipairs(app.adapter.mapCatalog and app.adapter.mapCatalog[catalogMode] or {}) do
                    for _, level in ipairs(world.levels or {}) do
                        if level.value == id then return world.label .. " · " .. level.label end
                    end
                end
            end
        end
        local function targetName(mode)
            if mode == "dungeon" then return "Choice " .. tostring(cfg:Get("game.dungeon.room_choice")) end
            if mode == "infinity_castle" then
                local floor = cfg:Get("game.infinity_castle.floor")
                return floor == 0 and "Latest room" or "Room " .. tostring(floor)
            end
            if mode == "portals" then
                local target = app.services.portalFarm and app.services.portalFarm:Featured()
                return target and string.format("%s · T%d", target.name, target.tier) or nil
            end
            if mode == "event" then
                local id = cfg:Get("game.events.event_id")
                local events = app.adapter.Events and app.adapter:Events() or {}
                if (not id or id == "") and #events == 1 then
                    local event = events[1]
                    return event.label ~= event.value and event.label or levelTitle(event.value)
                end
                for _, event in ipairs(events) do
                    if event.value == id then return event.label ~= id and event.label or levelTitle(id) end
                end
                return levelTitle(id)
            end
            local field = mode == "story" and "storymode" or mode
            local id = cfg:Get("game." .. field .. ".level_id")
            local catalog = app.adapter.mapCatalog
            for _, world in ipairs(catalog and catalog[mode] or {}) do
                for _, level in ipairs(world.levels or {}) do
                    if level.value == id then return world.label .. " · " .. level.label end
                end
            end
            return levelTitle(id)
        end
        local targetLevel
        local function targetArt(mode)
            local levelId = targetLevel and targetLevel(mode)
            local special = (mode == "dungeon" or mode == "infinity_castle")
                and app.adapter.SpecialModeContext and app.adapter:SpecialModeContext(mode)
            local levelMap = levelId and levelId ~= "" and app.adapter.LevelMap and app.adapter:LevelMap(levelId)
                or special and special.map
            local exact = levelMap and UIAssets.MapBackground(levelMap)
            if exact then return exact end
            if mode == "portals" then
                local target = app.services.portalFarm and app.services.portalFarm:Featured()
                return target and target.map and UIAssets.MapBackground(target.map) or nil
            end
            if mode == "dungeon" then return UIAssets.DungeonBackground() end
            if mode == "infinity_castle" then return UIAssets.CastleBackground() end
            local field = mode == "story" and "storymode" or mode
            local worldId = cfg:Get("game." .. field .. ".world_id")
            for _, world in ipairs(app.adapter.mapCatalog and app.adapter.mapCatalog[mode] or {}) do
                if world.value == worldId then return UIAssets.MapBackground(world.map) end
            end
            return nil
        end
        targetLevel = function(mode)
            if match and type(match.id) == "string" and match.id ~= "" then return match.id end
            return levelForMode(mode)
        end
        local function rewardArt(mode)
            local levelId = targetLevel(mode)
            local reward = primaryLootArt(levelId, mode)
            if reward then return reward end
            local background = targetArt(mode)
            if background and background.image then
                return {image = background.image, imageRectOffset = background.imageRectOffset,
                    imageRectSize = background.imageRectSize}
            end
        end
        local function homeFarm()
            local macro = cfg:Get("farm.method") == "macro"
            local mode = routeMode()
            local target = match and levelTitle(match.id) or targetName(mode)
            local methodEnabled = cfg:Get(macro and "macros.autoPlay" or "autoplace.enabled")
            return {state = window.i18n:T(cfg:Get("game.enabled") and "ui.enabled" or "home.off"),
                method = window.i18n:T(macro and "farm.macro" or "farm.units"),
                methodState = window.i18n:T(methodEnabled and "ui.enabled" or "home.off"),
                mode = window.i18n:T(mode == "infinity_castle" and "game.infinityCastle" or "game." .. mode),
                target = target and target ~= "" and target or window.i18n:T("ui.none")}
        end
        local initial = homeFarm()
        local art = targetArt(routeMode())
        local initialReward = rewardArt(routeMode())
        local banner = create:Banner({text = initial.target, subtitle = initial.mode, value = initial.state, height = 104,
            image = initialReward and initialReward.image, imageRectOffset = initialReward and initialReward.imageRectOffset,
            imageRectSize = initialReward and initialReward.imageRectSize})
        local setMapBackground = decorateRouteBanner(banner, art)
        local homePortalScope
        local function setHomePortal(mode)
            local source
            if mode == "portals" then
                local target = app.services.portalFarm and app.services.portalFarm:Featured()
                local metadata = target and app.adapter:ItemMetadata(target.id)
                source = target and UIAssets.ItemViewport(target.id, metadata)
            end
            homePortalScope = select(1, UIAssets.SetBannerModel(banner, source, homePortalScope))
        end
        local function setRewardArt(nextArt)
            banner:SetImage(nextArt and nextArt.image, nextArt and nextArt.imageRectOffset,
                nextArt and nextArt.imageRectSize)
        end
        setRewardArt(initialReward)
        setHomePortal(routeMode())
        local homeLoot
        local automationStatus = create:Status({id = "homeAutomationStatus", key = "workflow.statusStopped",
            detail = "", state = "stopped"})
        local automationButton
        local function refreshPlan()
            local plan, mode = homeFarm(), routeMode()
            banner:SetTitle(plan.target)
            banner:SetSubtitle(plan.mode .. " · " .. (match and match.location ~= "unknown" and match.location or window.i18n:T(app.adapter:InLobby() and "home.lobby" or "home.match")))
            banner:SetValue(plan.state)
            local nextArt = targetArt(mode)
            local nextReward = rewardArt(mode)
            setRewardArt(nextReward)
            setHomePortal(mode)
            if homeLoot then homeLoot:Set(lootForLevel(targetLevel(mode), mode)) end
            if setMapBackground then setMapBackground(nextArt) end
            local running = FarmWorkflow.isRunning(app)
            local lifecycle = FarmWorkflow.status(app)
            local location = window.i18n:T(app.adapter:InLobby() and "home.lobby" or "home.match")
            automationStatus:SetState(lifecycle,
                window.i18n:T("workflow.status." .. lifecycle),
                window.i18n:T("workflow.statusPlan", {method = plan.method, mode = plan.mode, location = location}))
            if automationButton then
                automationButton.options.key = running and "workflow.stopAutomation" or "workflow.startAutomation"
                automationButton.label.Text = window.i18n:T(automationButton.options.key)
                automationButton.icon.Image = running and Assets.Icons.Stop or Assets.Icons.Play
                automationButton:SetTone(running and "danger" or nil)
            end
        end
        automationButton = create:Button({id = "homePrimaryAction", key = "workflow.toggleAutomation", icon = Assets.Icons.Play,
            primary = true,
            bindId = "home/overviewActions/3/workflow.stopAutomation",
            onChanged = function() FarmWorkflow.toggle(app) end})
        local overviewActions = create:Columns({id = "overviewActions", columns = 2, breakpoint = 420}).Columns
        overviewActions[1]:Button({key = "workflow.configure", onChanged = function() window:SelectTab("farm") end})
        overviewActions[2]:Button({key = "stats.title", onChanged = function() window:SelectTab("statistics") end})
        local rewards = create:Group({id = "homeRewards", key = "game.possibleRewards", collapsible = true}).Create
        homeLoot = LootGallery.mount(rewards, {id = "homeLoot", window = window, adapter = app.adapter,
            items = lootForLevel(targetLevel(routeMode()), routeMode())})
        create.scope:Connect(cfg.Changed, refreshPlan)
        create.scope:Connect(window.i18n.Changed, refreshPlan)
        if app.services.macros and app.services.macros.Changed then create.scope:Connect(app.services.macros.Changed, refreshPlan) end
        refreshPlan()
        local resourcesGroup = create:Group({id = "homeAccountResources", key = "lobby.data", collapsible = true}).Create
        local empty = resourcesGroup:Label({key = "ui.none"})
        local balances = resourcesGroup:Columns({id = "homeResources", columns = 2}).Columns
        local player, rows, statsScope = app.adapter.player, {}, nil
        local function refreshResources(stats)
            for _, row in ipairs(rows) do row.scope:Destroy() end
            rows = {}
            local resources = app.adapter.Resources and app.adapter:Resources() or {}
            empty:Visible(#resources == 0)
            for index, resource in ipairs(resources) do
                local valueObject = stats and stats:FindFirstChild(resource.field)
                local function parameters()
                    local value = valueObject and valueObject.Value or resource.value
                    if cfg:Get("visuals.enabled") and cfg:Get("visuals.showResourcesOnHome") then
                        local override = cfg:Get("visuals.resources." .. resource.name)
                        if type(override) == "number" and override >= 0 then value = string.format("%.0f", override) end
                    end
                    return {name = resource.name, value = tostring(value)}
                end
                local resourceArt = UIAssets.Resource(resource.name)
                local row = balances[(index - 1) % 2 + 1]:Card({text = resource.name, height = 58,
                    image = resourceArt and resourceArt.image or resourceImages[resource.name],
                    imageRectOffset = resourceArt and resourceArt.imageRectOffset,
                    imageRectSize = resourceArt and resourceArt.imageRectSize})
                local function refresh()
                    row:SetValue(parameters().value)
                end
                row.scope:Connect(cfg.Changed, function(path)
                    if path == "visuals" or path == "visuals.enabled" or path == "visuals.showResourcesOnHome"
                        or path == "visuals.resources" or path == "visuals.resources." .. resource.name then refresh() end
                end)
                rows[#rows + 1] = row
                if valueObject then row.scope:Connect(valueObject.Changed, refresh) end
                refresh()
            end
        end
        local function bindStats()
            if statsScope then statsScope:Destroy() end
            statsScope = create.scope:Child()
            local stats = player and player:FindFirstChild("_stats")
            if stats then
                local function onFieldChanged() refreshResources(stats) end
                statsScope:Connect(stats.ChildAdded, onFieldChanged)
                statsScope:Connect(stats.ChildRemoved, onFieldChanged)
            end
            refreshResources(stats)
        end
        if player then
            local function onStatsChanged(child)
                if child.Name == "_stats" then bindStats() end
            end
            create.scope:Connect(player.ChildAdded, onStatsChanged)
            create.scope:Connect(player.ChildRemoved, onStatsChanged)
        end
        bindStats()
    end })

    window:CreateTab({ id = "lobby", key = "tab.lobby", icon = UIAssets.Navigation("lobby"), build = function(create)
