                local action = state.lastAction
                local status = action and window.i18n:T(action.confirmed and "lobby.utilityConfirmed" or "lobby.utilityUnconfirmed", {
                    kind = action.kind, name = action.name or action.id or "—", quantity = action.quantity or 1}) or window.i18n:T("ui.none")
                local total = 0
                for _, capsule in ipairs(capsules) do total = total + (tonumber(capsule.count) or 0) end
                utilityStatus:SetState(action and not action.confirmed and "error" or action and "success" or "ready",
                    window.i18n:T("lobby.utilitySummary", {capsules = total, invites = #invites}), status)
        end
        utility:Button({key = "lobby.utilityRefresh", onChanged = refreshUtilities})
        if app.services.lobbyUtilities and app.services.lobbyUtilities.Changed then
            utility.scope:Connect(app.services.lobbyUtilities.Changed, refreshUtilities)
        end
        refreshUtilities()
        local codes = create:Group({id = "codeRedemption", key = "workflow.codes", collapsible = true}).Create
        local codeRow = codes:Columns({id = "codeActions", columns = 2}).Columns
        local code = codeRow[1]:Input({ key = "lobby.redeem", placeholderKey = "lobby.redeemPlaceholder", maxLength = 128 })
        codeRow[2]:Button({ key = "lobby.redeemButton", field = true, onChanged = function()
            local value = Util.trim(code:Get())
            if value == "" then return end
            local ok, response = app.adapter:RedeemCode(value)
            -- The game has already shown its precise refusal; don't replace it
            -- with a misleading endpoint-unavailable error in the hub.
            if not ok and not (type(response) == "table" and response.notified) then
                if response == "needs_social" then notify("codes.needsSocial", true)
                elseif CodeRedemption.outcome(false, response) == "already_used" then notify("codes.alreadyUsed")
                else notify("ui.remoteUnavailable", true) end
            end
        end })
        toggle(codes, "lobby.activeCodes", "autocodes")
        codes:Label({key = "codes.description"})
        if app.services.lobbyShops then
            create = lobbyPages.pages.shops.Create
            create:Section({key = "shops.title"})
            local merchant = create:Group({id = "merchantShop", key = "shops.merchant", collapsible = true, open = true}).Create
            toggle(merchant, "shops.enabled", "lobby.shops.merchant.enabled")
            merchant:Section({key = "shops.chooseItems"})
            local merchantItems = merchant:Frame({id = "merchantItems"})
            local merchantReserve = merchant:Columns({id = "merchantReserve", columns = 2}).Columns
            numeric(merchantReserve[1], "shops.gemReserve", "lobby.shops.merchant.gem_reserve", 0, 1e15)
            numeric(merchantReserve[2], "shops.goldReserve", "lobby.shops.merchant.gold_reserve", 0, 1e15)

            local goldGroup = create:Group({id = "goldShop", key = "shops.gold", collapsible = true})
            local gold = goldGroup.Create
            toggle(gold, "shops.enabled", "lobby.shops.gold.enabled")
            local goldLimits = gold:Columns({id = "goldLimits", columns = 3}).Columns
            dropdown(goldLimits[1], "shops.quantity", "lobby.shops.gold.quantity", {
                {value = 1, label = "1"}, {value = 10, label = "10"}, {value = 100, label = "100"}})
            numeric(goldLimits[2], "shops.goldReserve", "lobby.shops.gold.gold_reserve", 0, 1e15)
            numeric(goldLimits[3], "shops.maxSpend", "lobby.shops.gold.max_spend", 0, 1e15)
            gold:Section({key = "shops.chooseItems"})
            local goldItems = gold:Frame({id = "goldItems"})

            local shopRows = {merchant = nil, gold = nil}
            local function selection(path)
                local result = {}
                for id in tostring(cfg:Get(path) or ""):gmatch("[^,]+") do result[id] = true end
                return result
            end
            local function offerSubtitle(offer, plan)
                local stock = tonumber(offer.available) or 0
                local price = tonumber(offer.price) or 0
                local currency = tostring(offer.currency or "")
                local status = plan and plan.status or "disabled"
                if status == "locked" then return window.i18n:T("shops.status.lockedShort") end
                if status == "sold_out" then return window.i18n:T("shops.status.soldOutShort") end
                return window.i18n:T("shops.offerMeta", {stock = stock, price = price, currency = currency})
            end
            local function renderOffers(kind, holder, offers, plans)
                if shopRows[kind] then shopRows[kind]:Destroy() end
                shopRows[kind] = holder.Create:Frame({id = kind .. "OfferRows"})
                local body = shopRows[kind].Create
                local path = "lobby.shops." .. kind
                local exact = selection(cfg:Get(path .. ".selected_items"))
                local useExact = cfg:Get(path .. ".use_selection") == true
                if #offers == 0 then body:Label({key = "shops.none"}); return end
                for first = 1, #offers, 3 do
                    local columns = body:Columns({id = kind .. "Offer" .. tostring(first), columns = 3,
                        breakpoint = 420, gap = 8, columnGap = 6}).Columns
                    for column = 1, 3 do
                        local index = first + column - 1
                        local offer, plan = offers[index], plans and plans[index]
                        if offer then
                            local metadata = app.adapter.ItemMetadata and app.adapter:ItemMetadata(offer.id)
                            local viewport = UIAssets.ItemViewport(offer.id, metadata)
                            local art = not viewport and (UIAssets.Item(offer.id, metadata) or UIAssets.Reward()) or nil
                            local legacy = offer.policy and cfg:Get(path .. "." .. offer.policy) == true
                            local chosen = useExact and exact[offer.id] == true or not useExact and legacy
                            local choice = columns[column]:Toggle({text = (offer.name or offer.id) .. "\n" .. offerSubtitle(offer, plan), value = chosen,
                                image = art and art.image, imageRectOffset = art and art.imageRectOffset,
                                imageRectSize = art and art.imageRectSize,
                                imageColor = art and art.imageColor or Color3.new(1, 1, 1),
                                onChanged = function(value)
                                    app.services.lobbyShops:SetItemEnabled(kind, offer.id, value)
                                end})
                            choice.root.Size = UDim2.new(1, 0, 0, 68)
                            choice.label.TextSize = 12
                            choice.label.TextYAlignment = Enum.TextYAlignment.Center
                            if viewport then
                                UIAssets.AttachViewport(viewport, choice.panel, choice.scope, {name = "ShopItemModel",
                                    position = UDim2.new(0, 7, 0.5, 0), size = UDim2.fromOffset(54, 54), zIndex = 2})
                                choice.label.Position = UDim2.fromOffset(66, 0)
                                choice.label.Size = UDim2.new(1, -132, 1, 0)
                            elseif choice.leadingIcon then choice.leadingIcon.Size = UDim2.fromOffset(28, 28) end
                        else columns[column]:Frame({id = "spacer"}) end
                    end
                end
            end
            local lastPreview
            local function refreshPreview()
                local state = app.services.lobbyShops:Preview()
                lastPreview = state
                renderOffers("merchant", merchantItems, state.merchant or {}, state.merchantPlan or {})
                if goldGroup:GetOpen() then renderOffers("gold", goldItems, state.gold or {}, state.goldPlan or {})
                elseif shopRows.gold then shopRows.gold:Destroy(); shopRows.gold = nil end
            end
            goldGroup.options.onChanged = function(open)
                if open then
                    local state = lastPreview or app.services.lobbyShops:Preview()
                    renderOffers("gold", goldItems, state.gold or {}, state.goldPlan or {})
                elseif shopRows.gold then shopRows.gold:Destroy(); shopRows.gold = nil end
            end
            create:Button({key = "shops.refresh", onChanged = refreshPreview})
            create.scope:Connect(app.services.lobbyShops.Changed, refreshPreview)
            create.scope:Connect(window.i18n.Changed, refreshPreview)
            refreshPreview()
        end
    end })

    if app.services.matchStats then
        window:CreateTab({id = "statistics", key = "stats.title", hidden = true, backTab = "home", build = function(create)
            back(create, "home")
            local statsPages = pages(create, "statisticsWorkspaces", {
                {id = "overview", key = "stats.overview", image = Assets.Icons.Overview},
                {id = "history", key = "stats.history", image = Assets.Icons.Timeline},
                UIAssets.With({id = "maps", key = "stats.maps"}, UIAssets.GameIcon("play"))})
            local overview = statsPages.pages.overview.Create
            local function metric(parent, options)
                options.height = 58
                local card = parent:Card(options)
                local stripe = card.root:FindFirstChild("Accent")
                if stripe then stripe.Visible = false end
                return card
            end
            overview:Section({key = "stats.title"})
            local columns = overview:Columns({id = "statisticsCards", columns = 3, breakpoint = 500}).Columns
            local allTime = metric(columns[1], {key = "stats.allTime", value = "0"})
            local wins = metric(columns[2], {key = "stats.wins", value = "0"})
            local lifetimeRate = metric(columns[3], {key = "stats.winRate", value = "0%"})
            overview:Section({key = "stats.session"})
            local sessionMetrics = overview:Columns({id = "sessionMetrics", columns = 3, breakpoint = 500}).Columns
            local session = metric(sessionMetrics[1], {key = "stats.sessionMatches", value = "0"})
            local sessionRate = metric(sessionMetrics[2], {key = "stats.winRate", value = "0%"})
            local sessionAverage = metric(sessionMetrics[3], {key = "stats.averageTime", value = "—"})
            local sessionDetails = overview:Group({id = "sessionStatisticsDetails", key = "ui.details", collapsible = true}).Create
            local sessionDetailMetrics = sessionDetails:Columns({id = "sessionDetailMetrics", columns = 3, breakpoint = 500}).Columns
            local sessionElapsed = metric(sessionDetailMetrics[1], {key = "stats.elapsed", value = "00:00"})
            local sessionKills = metric(sessionDetailMetrics[2], {key = "stats.kills", value = "0"})
            local sessionDamage = metric(sessionDetailMetrics[3], {key = "stats.damage", value = "0"})
            sessionDetails:Section({key = "stats.sessionRewards"})
            local sessionRewards = LootGallery.mount(sessionDetails, {id = "sessionRewards", window = window,
                adapter = app.adapter, emptyKey = "stats.noRewards"})
            sessionDetails:Section({key = "stats.hourlyRewards"})
            local hourlyRewards = LootGallery.mount(sessionDetails, {id = "hourlyRewards", window = window,
                adapter = app.adapter, emptyKey = "stats.noRewards"})
            local lifetime = overview:Group({id = "lifetimeStatistics", key = "stats.lifetime", collapsible = true}).Create
            local lifetimeMetrics = lifetime:Columns({id = "lifetimeMetrics", columns = 3, breakpoint = 500}).Columns
            local lifetimeAverage = metric(lifetimeMetrics[1], {key = "stats.averageTime", value = "—"})
            local lifetimeLosses = metric(lifetimeMetrics[2], {key = "stats.losses", value = "0"})
            local bestStreak = metric(lifetimeMetrics[3], {key = "stats.bestStreak", value = "0"})
            local lifetimeCombat = lifetime:Columns({id = "lifetimeCombat", columns = 2, breakpoint = 480}).Columns
            local lifetimeKills = metric(lifetimeCombat[1], {key = "stats.kills", value = "0"})
            local lifetimeDamage = metric(lifetimeCombat[2], {key = "stats.damage", value = "0"})
            local lifetimeRewards = LootGallery.mount(lifetime, {id = "lifetimeRewards", window = window,
                adapter = app.adapter, emptyKey = "stats.noRewards"})
            local mapPage = statsPages.pages.maps.Create
            mapPage:Section({key = "stats.maps"})
            local mapSelect = mapPage:Dropdown({key = "stats.selectMap", items = {{value = "", key = "stats.noMaps"}}, value = ""})
            local mapDetail = mapPage:Label({key = "stats.noMaps"})
            local maps = mapPage:Label({key = "stats.noMaps"})
            local historyPage = statsPages.pages.history.Create
            historyPage:Section({key = "stats.history"})
            local historySelect = historyPage:Dropdown({key = "stats.selectMatch", items = {{value = "", key = "stats.noHistory"}}, value = ""})
            local historyDetail = historyPage:Label({key = "stats.noHistory"})
            local function percent(winsValue, matches)
                return matches > 0 and string.format("%.1f%%", winsValue / matches * 100) or "0%"
            end
            local function duration(value)
                value = math.floor(tonumber(value) or 0)
                if value >= 3600 then
                    return string.format("%02d:%02d:%02d", math.floor(value / 3600), math.floor(value / 60) % 60, value % 60)
                end
                return string.format("%02d:%02d", math.floor(value / 60), value % 60)
            end
            local function rewardLines(rewards)
                local rows = {}; for name, amount in pairs(rewards or {}) do rows[#rows + 1] = "+" .. tostring(amount) .. " " .. name end
                table.sort(rows); return #rows > 0 and table.concat(rows, "\n") or window.i18n:T("stats.noRewards")
            end
            local historyById = {}
            local mapsByKey = {}
            local function showMap(key)
                local bucket = mapsByKey[key]
                if not bucket then mapDetail:SetText(window.i18n:T("stats.noMaps")); return end
                local mode, level, difficulty = key:match("^([^|]*)|([^|]*)|(.*)$")
                local played = bucket.last_played and type(os.date) == "function"
                    and os.date("%d.%m.%Y %H:%M", bucket.last_played) or "—"
                mapDetail:SetText(window.i18n:T("stats.mapDetails", {
                    map = bucket.name or level, mode = mode or "—", difficulty = difficulty or "—",
                    matches = bucket.matches, wins = bucket.wins, losses = bucket.losses,
                    rate = percent(bucket.wins, bucket.matches), streak = bucket.current_streak,
                    best = bucket.best_streak, average = bucket.timed_matches > 0
                        and duration(bucket.duration_seconds / bucket.timed_matches) or "—",
                    kills = string.format("%.0f", bucket.kills or 0), damage = string.format("%.0f", bucket.damage or 0),
                    rewards = rewardLines(bucket.rewards), played = played}))
            end
            mapSelect.options.onChanged = showMap
            local function showHistory(id)
                local row = historyById[id]
                if not row then historyDetail.options.text = window.i18n:T("stats.noHistory"); historyDetail.label.Text = historyDetail.options.text; return end
                local played = type(os.date) == "function" and os.date("%d.%m.%Y %H:%M", row.at) or tostring(row.at)
                historyDetail.options.text = window.i18n:T("stats.matchDetails", {
                    result = window.i18n:T("stats.result." .. row.result), map = row.identity.location ~= "" and row.identity.location or row.identity.name,
                    mode = row.identity.mode, difficulty = row.identity.difficulty ~= "" and row.identity.difficulty or "—",
                    played = played, weather = row.identity.weather ~= "" and row.identity.weather or "—",
                    time = row.duration and duration(row.duration) or "—", wave = row.wave or "—", maxWave = row.maxWave or "—",
                    kills = row.kills or "—", damage = row.damage and string.format("%.0f", row.damage) or "—",
                    rewards = rewardLines(row.rewards)})
                historyDetail.label.Text = historyDetail.options.text
            end
            historySelect.options.onChanged = showHistory
            local function refresh()
                local snapshot = app.services.matchStats:Snapshot()
                local total, current = snapshot.totals, snapshot.session
                allTime:SetValue(tostring(total.matches)); allTime:SetSubtitle("")
                wins:SetValue(tostring(total.wins)); wins:SetSubtitle("")
                bestStreak:SetValue(tostring(total.best_streak)); bestStreak:SetSubtitle("")
                lifetimeRate:SetValue(percent(total.wins, total.matches)); lifetimeRate:SetSubtitle("")
                session:SetValue(tostring(current.matches))
                session:SetSubtitle("")
                sessionAverage:SetValue(current.timed_matches > 0 and duration(current.duration_seconds / current.timed_matches) or "—")
                sessionAverage:SetSubtitle("")
                sessionRate:SetValue(percent(current.wins, current.matches))
                sessionRate:SetSubtitle("")
                sessionElapsed:SetValue(duration(snapshot.sessionElapsed)); sessionElapsed:SetSubtitle("")
                sessionKills:SetValue(string.format("%.0f", current.kills or 0)); sessionKills:SetSubtitle("")
                sessionDamage:SetValue(string.format("%.0f", current.damage or 0)); sessionDamage:SetSubtitle("")
                sessionRewards:Set(LootGallery.rewardEntries(app.adapter, current.rewards))
                local rates, hours = {}, math.max(snapshot.sessionElapsed, 1) / 3600
                for name, amount in pairs(current.rewards or {}) do rates[name] = math.floor(amount / hours * 10 + 0.5) / 10 end
                hourlyRewards:Set(LootGallery.rewardEntries(app.adapter, rates))
                lifetimeAverage:SetValue(total.timed_matches > 0 and duration(total.duration_seconds / total.timed_matches) or "—")
                lifetimeAverage:SetSubtitle("")
                lifetimeLosses:SetValue(tostring(total.losses)); lifetimeLosses:SetSubtitle("")
                lifetimeKills:SetValue(string.format("%.0f", total.kills or 0)); lifetimeKills:SetSubtitle("")
                lifetimeDamage:SetValue(string.format("%.0f", total.damage or 0)); lifetimeDamage:SetSubtitle("")
                lifetimeRewards:Set(LootGallery.rewardEntries(app.adapter, total.rewards))
                local rows = {}
                local mapItems = {{value = "", key = "stats.noMaps"}}
                mapsByKey = {}
                for key, bucket in pairs(snapshot.maps) do
                    mapsByKey[key] = bucket
                    mapItems[#mapItems + 1] = {value = key, label = bucket.name or key}
                    rows[#rows + 1] = {key = key, text = string.format("%s · %dW/%dL · %s · avg %s · K %.0f · D %.0f",
                        bucket.name or key, bucket.wins, bucket.losses, percent(bucket.wins, bucket.matches),
                        bucket.timed_matches > 0 and duration(bucket.duration_seconds / bucket.timed_matches) or "—",
                        bucket.kills or 0, bucket.damage or 0)}
                end
                table.sort(rows, function(a, b) return a.key < b.key end)
                table.sort(mapItems, function(a, b)
                    if a.value == "" then return b.value ~= "" end
                    if b.value == "" then return false end
                    return a.label < b.label or (a.label == b.label and a.value < b.value)
                end)
                local textRows = {}; for index = 1, math.min(20, #rows) do textRows[index] = rows[index].text end
                maps.options.text = #textRows > 0 and table.concat(textRows, "\n") or window.i18n:T("stats.noMaps")
                maps.label.Text = maps.options.text
                local selectedMap = mapSelect:Get()
                mapSelect:SetItems(mapItems)
                if not mapsByKey[selectedMap] then selectedMap = mapItems[2] and mapItems[2].value or "" end
                mapSelect:Set(selectedMap, false); showMap(selectedMap)
                local items = {{value = "", key = "stats.noHistory"}}
                historyById = {}
                for index = #snapshot.history, math.max(1, #snapshot.history - 99), -1 do
                    local row = snapshot.history[index]
                    historyById[row.id] = row
                    local played = type(os.date) == "function" and os.date("%d.%m %H:%M", row.at) or ""
                    items[#items + 1] = {value = row.id, label = string.format("%s · %s · %s · %s",
                        window.i18n:T("stats.result." .. row.result), row.identity.location ~= "" and row.identity.location or row.identity.name,
                        row.duration and duration(row.duration) or "—", played)}
                end
                local selected = historySelect:Get()
                historySelect:SetItems(items)
                if not historyById[selected] then selected = items[2] and items[2].value or "" end
                historySelect:Set(selected, false); showHistory(selected)
            end
            local actions = overview:Columns({id = "statisticsActions", columns = 2}).Columns
            actions[1]:Button({key = "stats.copy", onChanged = function()
                local total = app.services.matchStats:Snapshot().totals
                app.runtime:Copy(string.format("Matches %d · %dW/%dL · best streak %d", total.matches, total.wins, total.losses, total.best_streak))
            end})
            actions[2]:Button({key = "stats.reset", onChanged = function()
                window:Confirm({titleKey = "stats.reset", messageKey = "stats.resetConfirm", onConfirm = function()
                    local ok = app.services.matchStats:Reset(); notify(ok and "stats.resetDone" or "stats.resetFailed", not ok)
                    return ok
                end})
            end})
            create.scope:Connect(app.services.matchStats.Changed, refresh)
            create.scope:Connect(window.i18n.Changed, refresh)
            refresh()
        end})
    end
    window:CreateTab({ id = "farm", key = "tab.farm", icon = UIAssets.Navigation("farm"), build = function(create)
        local farmScope, farmRoot = create.scope, create.parent
        local mode = cfg:Get("game.type")
        if not app.adapter.mapCatalog and app.adapter.MapCatalog then app.adapter:MapCatalog(false) end
        local function planContext(nextMode)
            local levelId = levelForMode(nextMode)
            local map = levelId ~= "" and app.adapter.LevelMap and app.adapter:LevelMap(levelId)
            if nextMode == "portals" then
                local target = app.services.portalFarm and app.services.portalFarm:Featured()
                map = target and target.map or map
            end
            local special = (nextMode == "dungeon" or nextMode == "infinity_castle")
                and app.adapter.SpecialModeContext and app.adapter:SpecialModeContext(nextMode)
            map = map or special and special.map
            local background = map and UIAssets.MapBackground(map)
                or nextMode == "dungeon" and UIAssets.DungeonBackground()
                or nextMode == "infinity_castle" and UIAssets.CastleBackground()
            return levelId, background, primaryLootArt(levelId, nextMode)
        end
