            subtitleKey = "workflow.joinHintShort", value = window.i18n:T(cfg:Get("game.enabled") and "ui.enabled" or "home.off"),
            image = planArt and planArt.image, imageRectOffset = planArt and planArt.imageRectOffset, imageRectSize = planArt and planArt.imageRectSize})
        local setPlanBackground = decorateRouteBanner(planBanner, initialBackground)
        local planPortalScope
        local function setPlanPortal(nextMode)
            local source
            if nextMode == "portals" then
                local target = app.services.portalFarm and app.services.portalFarm:Featured()
                local metadata = target and app.adapter:ItemMetadata(target.id)
                source = target and UIAssets.ItemViewport(target.id, metadata)
            end
            planPortalScope = select(1, UIAssets.SetBannerModel(planBanner, source, planPortalScope))
        end
        setPlanPortal(mode)
        local farmPages = pages(create, "gameWorkspaces", {
            UIAssets.With({id = "setup", key = "workflow.destination"}, UIAssets.GameIcon("play")),
            UIAssets.With({id = "combat", key = "workflow.combat"}, UIAssets.GameIcon("units")),
            {id = "behavior", key = "workflow.behavior", image = Assets.Icons.Restart}})
        create = farmPages.pages.setup.Create
        local farmPrimaryAction = create:Button({id = "farmPrimaryAction", key = "workflow.startAutomation",
            icon = Assets.Icons.Play, primary = true, onChanged = function() FarmWorkflow.toggle(app) end})
        local farmStatus = create:Status({id = "farmAutomationStatus", key = "workflow.statusStopped",
            detailKey = "workflow.statusReadyHint", state = "stopped"})
        local function refreshFarmAction()
            local running = FarmWorkflow.isRunning(app)
            local lifecycle = FarmWorkflow.status(app)
            farmPrimaryAction.options.key = running and "workflow.stopAutomation" or "workflow.startAutomation"
            farmPrimaryAction.label.Text = window.i18n:T(farmPrimaryAction.options.key)
            farmPrimaryAction.icon.Image = running and Assets.Icons.Stop or Assets.Icons.Play
            farmPrimaryAction:SetTone(running and "danger" or nil)
            local currentMode = cfg:Get("game.type")
            farmStatus:SetState(lifecycle,
                window.i18n:T("workflow.status." .. lifecycle),
                window.i18n:T("workflow.statusFarm", {mode = window.i18n:T(currentMode == "infinity_castle"
                    and "game.infinityCastle" or "game." .. currentMode),
                    method = window.i18n:T(cfg:Get("farm.method") == "macro" and "farm.macro" or "farm.units")}))
        end
        create.scope:Connect(cfg.Changed, function(path)
            if path == "game.enabled" or path == "smartfarm.enabled" or path == "autoplace.enabled"
                or path == "macros.autoPlay" or path == "game.type" or path == "farm.method" then refreshFarmAction() end
        end)
        if app.services.macros and app.services.macros.Changed then create.scope:Connect(app.services.macros.Changed, refreshFarmAction) end
        create.scope:Connect(window.i18n.Changed, refreshFarmAction)
        refreshFarmAction()
        local planLoot, lootCatalogText
        local function refreshLootCatalog()
            local catalog = app.adapter.LootCatalog and app.adapter:LootCatalog()
                or {resources = {}, items = {}, units = {}, levels = 0}
            local resources = {}
            for _, row in ipairs(catalog.resources) do
                resources[#resources + 1] = string.format("%s · %d", row.name, row.levels)
            end
            if lootCatalogText then lootCatalogText:SetText(window.i18n:T("game.lootCatalogSummary", {
                levels = catalog.levels, resources = #resources > 0 and table.concat(resources, "\n") or window.i18n:T("ui.none"),
                items = #catalog.items, units = #catalog.units})) end
        end
        local frames = {}
        local methodFrames = {}
        local playMode
        local function show(mode)
            for id, frame in pairs(frames) do frame:Visible(id == mode) end
            if playMode then playMode:Visible(mode ~= "dungeon" and mode ~= "infinity_castle" and mode ~= "portals") end
            local levelId, background, reward = planContext(mode)
            planBanner:SetTitle(window.i18n:T(mode == "infinity_castle" and "game.infinityCastle" or "game." .. mode))
            planBanner:SetSubtitle(window.i18n:T("workflow.joinHintShort"))
            planBanner:SetImage(reward and reward.image, reward and reward.imageRectOffset, reward and reward.imageRectSize)
            if setPlanBackground then setPlanBackground(background) end
            setPlanPortal(mode)
            if planLoot then planLoot:Set(lootForLevel(levelId, mode)) end
        end
        local function showMethod(method)
            for id, frame in pairs(methodFrames) do frame:Visible(id == method) end
        end
        local selectorsRow = create:Columns({id = "farmSelectors", columns = 2, breakpoint = 420}).Columns
        segmented(farmPages.pages.combat.Create, "farm.method", "farm.method",
            {{value = "units", key = "farm.units"}, {value = "macro", key = "farm.macro"}}, showMethod)
        dropdown(selectorsRow[1], "game.mode", "game.type", {
            UIAssets.With({value = "event", key = "game.event"}, UIAssets.Mode("event")),
            UIAssets.With({value = "raids", key = "game.raids"}, UIAssets.Mode("raids")),
            UIAssets.With({value = "story", key = "game.story"}, UIAssets.Mode("story")),
            UIAssets.With({value = "infinity", key = "game.infinity"}, UIAssets.Mode("infinity")),
            UIAssets.With({value = "legend", key = "game.legend"}, UIAssets.Mode("legend")),
            UIAssets.With({value = "dungeon", key = "game.dungeon"}, UIAssets.Dungeon()),
            UIAssets.With({value = "infinity_castle", key = "game.infinityCastle"}, UIAssets.Castle()),
            UIAssets.With({value = "portals", key = "game.portals"}, UIAssets.Mode("portals")),
        }, show)
        playMode = segmented(selectorsRow[2], "game.playMode", "game.play_mode", {
            {value = "solo", key = "game.solo"}, {value = "matchmaking", key = "game.matchmaking"}})
        local friendsOnly = toggle(create, "game.friendsOnly", "game.friends_only")
        local function showFriendsOnly()
            friendsOnly:Visible(cfg:Get("game.play_mode") == "solo"
                and cfg:Get("game.type") ~= "dungeon" and cfg:Get("game.type") ~= "infinity_castle"
                and cfg:Get("game.type") ~= "portals")
        end
        friendsOnly.scope:Connect(cfg.Changed, function(path)
            if path == "game.play_mode" or path == "game.type" then showFriendsOnly() end
        end)
        showFriendsOnly()
        local maps = {story = {}, legend = {}, raids = {}, infinity = {}}
        local selectors = {}
        local modes = {{"event", "events"}, {"raids", "raids"}, {"story", "storymode"}, {"legend", "legend"}, {"infinity", "infinity"},
            {"dungeon", "dungeon"}, {"infinity_castle", "infinity_castle"}, {"portals", "portals"}}
        for _, mode in ipairs(modes) do
            local id, field = mode[1], mode[2]
            local frame = create:Frame({ id = id })
            frames[id] = frame
            local group = frame.Create:Group({ key = "game.options" }).Create
            local behaviorFrame = farmPages.pages.behavior.Create:Frame({id = "behavior_" .. id})
            local function showBehavior() behaviorFrame:Visible(cfg:Get("game.type") == id) end
            showBehavior()
            behaviorFrame.scope:Connect(cfg.Changed, function(path) if path == "game.type" then showBehavior() end end)
            if id == "portals" then
                behaviorFrame.Create:Label({key = "portals.behaviorHint"})
                dropdown(behaviorFrame.Create, "portals.afterVictory", "portals.after_victory", {
                    {value = "continue", key = "portals.continue"}, {value = "stop", key = "workflow.afterStop"}})
                dropdown(behaviorFrame.Create, "portals.afterDefeat", "portals.after_defeat", {
                    {value = "retry_once", key = "portals.retryOnce"}, {value = "skip", key = "portals.skip"},
                    {value = "stop", key = "workflow.afterStop"}})
            elseif id == "dungeon" then
                behaviorFrame.Create:Label({key = "game.dungeonFarmHint"})
            else
                local afterItems = {{value = "stop", key = "workflow.afterStop"}, {value = "replay", key = "game.replay"},
                    {value = "endless", key = "game.endless"}}
                if id == "story" or id == "infinity_castle" then table.insert(afterItems, 2, {value = "next", key = "game.next"}) end
                local after = behaviorFrame.Create:Dropdown({key = "workflow.afterVictory", items = afterItems,
                    value = FarmWorkflow.afterVictory(cfg, id), onChanged = function(value)
                        FarmWorkflow.setAfterVictory(cfg, id, value)
                    end})
                behaviorFrame.scope:Connect(cfg.Changed, function(path)
                    if path:match("^game%.") then after:Set(FarmWorkflow.afterVictory(cfg, id), false) end
                end)
            end
            if id == "portals" then
                local portalFarm = app.services.portalFarm
                local portalRows
                local portalSettings = group:Columns({id = "portalSettings", columns = 2, breakpoint = 420}).Columns
                numeric(portalSettings[1], "portals.minimumTier", "portals.minimum_tier", 0, 100)
                toggle(portalSettings[2], "game.friendsOnly", "portals.friends_only", nil, {field = true})
                local inventoryHolder = group:Frame({id = "portalInventory"})
                local portalStatus = group:Label({key = "portals.none"})
                local function statusText()
                    local state = portalFarm and portalFarm:Status() or {lastCode = "unavailable"}
                    local key = "portals.status." .. tostring(state.lastCode ~= "" and state.lastCode or "ready")
                    return window.i18n:Has(key) and window.i18n:T(key) or tostring(state.lastCode or "")
                end
                local renderPortals
                renderPortals = function()
                    if portalRows then portalRows:Destroy() end
                    portalRows = inventoryHolder.Create:Frame({id = "portalRows"})
                    local rows, status = portalFarm and portalFarm:Inventory() or {}, "unavailable"
                    portalStatus:SetText(window.i18n:T("portals.inventoryStatus", {
                        count = #rows, state = statusText(), source = status}))
                    if #rows == 0 then portalRows.Create:Label({key = "portals.none"}); return end
                    local grid = portalRows.Create:Frame({id = "portalGrid"})
                    local oldLayout = grid.root:FindFirstChildOfClass("UIListLayout")
                    if oldLayout then oldLayout:Destroy() end
                    grid.root.AutomaticSize = Enum.AutomaticSize.None
                    grid.root.Size = UDim2.new(1, 0, 0, math.ceil(#rows / 6) * 84 + math.max(0, math.ceil(#rows / 6) - 1) * 8)
                    local gridLayout = Instance.new("UIGridLayout")
                    gridLayout.Name = "PortalGridLayout"
                    gridLayout.CellSize = UDim2.fromOffset(84, 84)
                    gridLayout.CellPadding = UDim2.fromOffset(8, 8)
                    gridLayout.FillDirection = Enum.FillDirection.Horizontal
                    gridLayout.FillDirectionMaxCells = 6
                    gridLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center
                    gridLayout.VerticalAlignment = Enum.VerticalAlignment.Top
                    gridLayout.SortOrder = Enum.SortOrder.LayoutOrder
                    gridLayout.Parent = grid.root
                    for index, portal in ipairs(rows) do
                        local metadata = app.adapter:ItemMetadata(portal.id)
                        local choice = grid.Create:Card({text = portal.name,
                            subtitle = string.format("T%d · ×%d", portal.tier, portal.count),
                            value = portal.selected and tostring(portal.position or index) or "", height = 84})
                        choice.root.Size = UDim2.fromOffset(84, 84)
                        choice.root.ClipsDescendants = true
                        local source = UIAssets.ItemViewport(portal.id, metadata)
                        if source then choice:SetViewport(source); source:Destroy() end
                        if choice.viewport then
                            choice.viewport.AnchorPoint = Vector2.new(0.5, 0)
                            choice.viewport.Position = UDim2.new(0.5, 0, 0, 2)
                            choice.viewport.Size = UDim2.fromOffset(48, 48)
                        end
                        choice.label.Position = UDim2.fromOffset(4, 49)
                        choice.label.Size = UDim2.new(1, -8, 0, 16)
                        choice.label.TextSize = 11
                        choice.label.TextXAlignment = Enum.TextXAlignment.Center
                        choice.subtitle.Position = UDim2.fromOffset(4, 65)
                        choice.subtitle.Size = UDim2.new(1, -8, 0, 13)
                        choice.subtitle.TextSize = 9
                        choice.subtitle.TextXAlignment = Enum.TextXAlignment.Center
                        choice.value.AnchorPoint = Vector2.new(1, 0)
                        choice.value.Position = UDim2.new(1, -5, 0, 3)
                        choice.value.Size = UDim2.fromOffset(17, 16)
                        choice.value.TextSize = 11
                        local accent = choice.root:FindFirstChild("Accent")
                        if accent then accent.Visible = false end
                        local hit = Instance.new("TextButton")
                        hit.Name, hit.Text, hit.BackgroundTransparency = "SelectPortal", "", 1
                        hit.Size, hit.ZIndex = UDim2.fromScale(1, 1), 5
                        hit.Parent = choice.root
                        function choice:Activate()
                            portalFarm:SetSelected(portal.key, not portal.selected)
                            return true
                        end
                        choice.scope:Connect(hit.Activated, function() choice:Activate() end)
                        if window.themes then
                            window.themes:Bind(choice.root, "BackgroundColor3", function(colors)
                                return portal.selected and colors.AccentSoft or colors.Surface
                            end, choice.scope)
                            local outline = choice.root:FindFirstChildOfClass("UIStroke")
                            if outline then window.themes:Bind(outline, "Color", function(colors)
                                return portal.selected and colors.Accent or colors.Border
                            end, choice.scope) end
                        end
                    end
                    local selectedRows, selectedItems, selectedValue = {}, {}, ""
                    for _, portal in ipairs(rows) do
                        if portal.selected then selectedRows[#selectedRows + 1] = portal end
                    end
                    table.sort(selectedRows, function(a, b)
                        return (a.position or math.huge) < (b.position or math.huge)
                    end)
                    for _, portal in ipairs(selectedRows) do
                        selectedItems[#selectedItems + 1] = {value = portal.key,
                            label = string.format("%d · %s T%d", portal.position or #selectedItems + 1, portal.name, portal.tier)}
                        if selectedValue == "" then selectedValue = portal.key end
                    end
                    if #selectedItems > 0 then
                        local order = portalRows.Create:Columns({id = "portalOrderActions", columns = 3,
                            breakpoint = 420, gap = 8, columnGap = 6}).Columns
                        local selected = order[1]:Dropdown({key = "portals.order", value = selectedValue, items = selectedItems})
                        order[2]:Button({key = "portals.up", field = true, onChanged = function()
                            portalFarm:Move(selected:Get(), -1)
                        end})
                        order[3]:Button({key = "portals.down", field = true, onChanged = function()
                            portalFarm:Move(selected:Get(), 1)
                        end})
                    end
                end
                group:Button({key = "portals.refresh", onChanged = renderPortals})
                if portalFarm and portalFarm.Changed then group.scope:Connect(portalFarm.Changed, renderPortals) end
                group.scope:Connect(window.i18n.Changed, renderPortals)
                renderPortals()
            elseif id == "event" then
                local items = app.adapter.Events and app.adapter:Events() or {}
                local eventActions = group:Columns({id = "eventDestination", columns = 2}).Columns
                local event = dropdown(eventActions[1], "game.currentEvent", "game.events.event_id", items)
                if cfg:Get("game.events.event_id") == "" and #items == 1 then event:Set(items[1].value, false) end
                eventActions[2]:Button({key = "game.refreshEvent", field = true, onChanged = function()
                    items = app.adapter:Events()
                    event:SetItems(items)
                    local selected = cfg:Get("game.events.event_id")
                    if selected == "" and #items == 1 then selected = items[1].value end
                    event:Set(selected, false)
                end})
                local challenges = behaviorFrame.Create:Group({id = "eventChallenges", key = "game.challengePriority"}).Create
                toggle(challenges, "game.priorityDaily", "game.events.priorityDaily")
                toggle(challenges, "game.priorityNormal", "game.events.priorityNormal")
                challenges:Label({key = "game.challengePriorityHint"})
                challenges:Label({key = "workflow.challengeTeam"})
            elseif id == "dungeon" then
                local dungeon = group:Columns({id = "dungeonOptions", columns = 3, breakpoint = 500}).Columns
                dropdown(dungeon[1], "game.roomChoice", "game.dungeon.room_choice", {
                    {value = 1, label = "1"}, {value = 2, label = "2"}, {value = 3, label = "3"}})
                dropdown(dungeon[2], "game.dungeonChest", "game.dungeon.chest", {
                    {value = "none", key = "game.chestNone"}, {value = "normal", key = "game.chestNormal"},
                    {value = "rare", key = "game.chestRare"}})
                toggle(dungeon[3], "game.dungeonShrine", "game.dungeon.shrine", nil, {field = true})
            elseif id == "infinity_castle" then
                local castle = group:Columns({id = "castleOptions", columns = 2}).Columns
                numeric(castle[1], "game.castleFloor", "game.infinity_castle.floor", 0, 10000)
                dropdown(castle[2], "game.difficulty", "game.infinity_castle.difficulty", {
                    {value = "Normal", key = "game.normal"}, {value = "Hard", key = "game.hard"}})
                group:Label({key = "game.castleFloorHint"})
            else
                local level
                local mapFields = group:Columns({id = id .. "Destination", columns = id == "story" and 3 or 2,
                    breakpoint = 500}).Columns
                local function updateLevels(worldId)
                    local items, selectedWorld = {}, nil
                    for _, world in ipairs(maps[id] or {}) do if world.value == worldId then items, selectedWorld = world.levels, world; break end end
                    if level then level:SetItems(items); level:Set(cfg:Get("game." .. field .. ".level_id"), false) end
                    if cfg:Get("game.type") == id and selectedWorld then
                        local levelId = cfg:Get("game." .. field .. ".level_id")
                        local background = UIAssets.MapBackground(app.adapter.LevelMap and app.adapter:LevelMap(levelId) or selectedWorld.map)
                        local reward = primaryLootArt(levelId, id)
                        planBanner:SetSubtitle(selectedWorld.label)
                        planBanner:SetImage(reward and reward.image, reward and reward.imageRectOffset, reward and reward.imageRectSize)
                        if setPlanBackground then setPlanBackground(background) end
                        if planLoot then planLoot:Set(lootForLevel(levelId, id)) end
                    end
                    return items
                end
                local world = dropdown(mapFields[1], "game.map", "game." .. field .. ".world_id", {}, function(value)
                    local items = updateLevels(value)
                    cfg:Set("game." .. field .. ".level_id", items[1] and items[1].value or "")
                end)
                level = dropdown(mapFields[2], "game.level", "game." .. field .. ".level_id", {})
                if id == "story" then
                    dropdown(mapFields[3], "game.difficulty", "game.storymode.difficulty", {
                        {value = "Normal", key = "game.normal"}, {value = "Hard", key = "game.hard"}})
                end
                group:Label({key = "game.mapOrderHint"})
                selectors[id] = {world = world, update = updateLevels, field = field}
            end
        end
        create.scope:Add(cfg.Changed:Connect(function(path, value)
            if path == "game.type" then show(value)
            elseif path == "portals.selected" or path == "portals.order" or path == "portals.minimum_tier" then
                if cfg:Get("game.type") == "portals" then show("portals") end
            elseif path == "farm.method" then showMethod(value)
            elseif path:match("^game%..+%.level_id$") or path == "game.events.event_id" then show(cfg:Get("game.type"))
            elseif path == "game.enabled" then planBanner:SetValue(window.i18n:T(value and "ui.enabled" or "home.off")) end
        end))
        farmScope:Connect(farmRoot:GetPropertyChangedSignal("Visible"), function()
            if farmRoot.Visible then show(cfg:Get("game.type")) end
        end)
        farmScope:Delay(1, function() if farmScope.alive then show(cfg:Get("game.type")) end end)
        local catalogStatus = create:Label({key = "game.catalogNotice"})
        local function refreshMaps(force)
            if not app.adapter.MapCatalog then return end
            local diagnostics
            maps, diagnostics = app.adapter:MapCatalog(force)
            if not create.scope.alive then return end
            for id, selector in pairs(selectors) do
                    selector.world:SetItems(UIAssets.DecorateWorlds(maps[id]))
                selector.world:Set(cfg:Get("game." .. selector.field .. ".world_id"), false)
                selector.update(cfg:Get("game." .. selector.field .. ".world_id"))
            end
            if diagnostics and (diagnostics.failed or 0) + (diagnostics.timedOut or 0) > 0 then
                catalogStatus.options.key = "game.catalogPartial"
                catalogStatus.label.Text = window.i18n:T(catalogStatus.options.key)
            end
        end
        local gameActions = create:Columns({id = "gameActions", columns = 2}).Columns
        gameActions[1]:Button({key = "game.refreshMaps", onChanged = function() refreshMaps(true) end})
        create.scope:Spawn(function() refreshMaps(false) end)
        gameActions[2]:Button({ key = "workflow.joinOnce", primary = true, onChanged = function()
            local ok = app.services.game:StartSelected()
            notify(ok and "game.startAccepted" or "game.startFailed", not ok)
        end })
        local rewards = create:Group({id = "planRewards", key = "game.possibleRewards", collapsible = true}).Create
        planLoot = LootGallery.mount(rewards, {id = "planLoot", window = window, adapter = app.adapter,
            items = lootForLevel(initialLevel, mode)})
        local lootCatalog = create:Group({id = "lootCatalog", key = "game.lootCatalog", collapsible = true}).Create
        lootCatalogText = lootCatalog:Label({key = "game.lootCatalogEmpty"})
        lootCatalog:Button({key = "game.lootCatalogRefresh", onChanged = refreshLootCatalog})
        show(cfg:Get("game.type"))
        create = farmPages.pages.combat.Create
        local unitMethod = create:Frame({id = "unitMethod"}); methodFrames.units = unitMethod
        toggle(unitMethod.Create, "workflow.autoPlace", "autoplace.enabled")
        local macroMethod = create:Frame({id = "macroMethod"}); methodFrames.macro = macroMethod
        toggle(macroMethod.Create, "workflow.autoMacro", "macros.autoPlay")
        showMethod(cfg:Get("farm.method"))
        local configure = create:Columns({id = "combatLinks", columns = 2}).Columns
        configure[1]:Button({key = "workflow.team", onChanged = function() window:SelectTab("units") end})
        configure[2]:Button({key = "tab.macros", onChanged = function() window:SelectTab("macros") end})
        local controls = create:Group({id = "combatAutomation", key = "combat.title", collapsible = true}).Create
        local skip = controls:Columns({id = "waveSkip", columns = 2}).Columns
        toggle(skip[1], "combat.waveSkip", "combat.wave_skip.enabled")
        numeric(skip[2], "combat.stopWave", "combat.wave_skip.stop_wave", 0, 100000)
        create = farmPages.pages.behavior.Create
        if app.services.smartFarm then
            local smart = create:Group({id = "smartFarm", key = "smartfarm.title", collapsible = true}).Create
            toggle(smart, "smartfarm.enabled", "smartfarm.enabled")
            dropdown(smart, "smartfarm.strategy", "smartfarm.strategy", {
                UIAssets.With({value = "story", key = "game.story"}, UIAssets.Mode("story")),
                UIAssets.With({value = "legend", key = "game.legend"}, UIAssets.Mode("legend")),
                UIAssets.With({value = "raids", key = "game.raids"}, UIAssets.Mode("raids")),
                UIAssets.With({value = "infinity", key = "game.infinity"}, UIAssets.Mode("infinity"))})
            local goals = smart:Columns({id = "smartGoals", columns = 2}).Columns
            numeric(goals[1], "smartfarm.goalMatches", "smartfarm.goal_matches", 0, 100000)
            numeric(goals[2], "smartfarm.goalMinutes", "smartfarm.goal_minutes", 0, 100000)
            local preview = smart:Label({key = "smartfarm.noTarget"})
            local function refreshSmart()
                local target = app.services.smartFarm:Preview(true)
                local eventChallenges = app.adapter.EventChallenges and app.adapter:EventChallenges() or {}
                preview.options.text = target and window.i18n:T("smartfarm.preview", {
                    mode = target.mode == "challenge" and window.i18n:T("game.challengePriority")
                        or window.i18n:T("game." .. target.mode), world = target.world,
                    act = target.act, level = target.levelId}) or window.i18n:T("smartfarm.noTarget")
                if target and (target.retryCount or 0) > 0 then
                    preview.options.text = preview.options.text .. "\n" .. window.i18n:T("smartfarm.retryPreview", {attempt = target.retryCount + 1})
                end
                local status = app.services.smartFarm:Status()
                if status.lastCode ~= "" and status.lastCode ~= "starting" and status.lastCode ~= "victory" then
                    local key = "smartfarm.status." .. status.lastCode
                    preview.options.text = preview.options.text .. "\n" .. (window.i18n:Has(key) and window.i18n:T(key) or status.lastCode)
                end
                if #eventChallenges > 0 then
                    preview.options.text = preview.options.text .. "\n" .. window.i18n:T("smartfarm.eventChallengePreview", {
                        count = #eventChallenges, name = eventChallenges[1].name, weather = eventChallenges[1].weather})
                end
                local portals = app.adapter.PortalInventory and app.adapter:PortalInventory() or {}
                if #portals > 0 then
                    preview.options.text = preview.options.text .. "\n" .. window.i18n:T("smartfarm.portalPreview", {
                        count = #portals, name = portals[1].name, tier = portals[1].tier, copies = portals[1].count})
                end
                preview.label.Text = preview.options.text
            end
            smart:Button({key = "smartfarm.refresh", onChanged = refreshSmart})
            smart.scope:Connect(app.services.smartFarm.Changed, refreshSmart)
            smart.scope:Connect(cfg.Changed, function(path)
                if path == "smartfarm.strategy" or path == "game.events.priorityDaily"
                    or path == "game.events.priorityNormal" then refreshSmart() end
            end)
            refreshSmart()
        end
        toggle(create, "workflow.autoJoin", "game.enabled")
        create:Label({key = "workflow.joinHint"})
        create:Section({ key = "game.inMatch" })
        toggle(create, "game.vote", "game.vote_start")
        toggle(create, "game.simulate", "game.player_simulate")
    end })

    window:CreateTab({id = "units", key = "workflow.team", icon = UIAssets.Navigation("units"), build = function(create) AutoPlacePage.mount(app, create) end})

    window:CreateTab({ id = "settings", key = "tab.settings", icon = Assets.Icons.Settings, build = function(create)
        local settingsPages = pages(create, "settingsWorkspaces", {
            {id = "session", key = "settings.session", image = Assets.Icons.Settings},
            {id = "notifications", key = "home.openNotifications", image = Assets.Icons.Notifications},
            UIAssets.With({id = "appearance", key = "tab.visual"}, UIAssets.Trait()),
            {id = "data", key = "settings.transfer", image = Assets.Icons.Export}})
        app.settingsNavigation = settingsPages
        create = settingsPages.pages.session.Create
        local interface = create:Group({id = "interfaceSettings", key = "settings.interface", collapsible = true, open = true}).Create
        local interfaceColumns = interface:Columns({id = "settingsInterface", columns = 3, breakpoint = 500}).Columns
        dropdown(interfaceColumns[1], "ui.language", "settings.language", window.i18n:Options())
        toggle(interfaceColumns[2], "settings.reducedMotion", "settings.reducedMotion",
            "settings/settingsWorkspaces/session/settingsInterface/2/settings.reducedMotion", {field = true})
        interfaceColumns[3]:Button({key = "ui.bindTitle", field = true, onChanged = function() window:SelectTab("binds") end})
        local appearanceLinks = interface:Columns({id = "appearanceLinks", columns = 2}).Columns
        appearanceLinks[1]:Button({key = "tab.themes", icon = Assets.Icons.Appearance,
            onChanged = function() window:SelectTab("themes") end})
        appearanceLinks[2]:Button({key = "tab.visual", onChanged = function() settingsPages:Select("appearance") end})
        local season = window.seasonOptions or UIAssets.Season()
        local seasonBadge = interface:Badge({key = "season." .. season.id})
        interface.scope:Connect(window.i18n.Changed, function()
            seasonBadge.options.key = "season." .. ((window.seasonOptions or UIAssets.Season()).id)
            seasonBadge.label.Text = window.i18n:T(seasonBadge.options.key)
        end)
        local optimization = create:Group({id = "settingsOptimizationGroup", key = "settings.optimization", collapsible = true}).Create
        local optimizationColumns = optimization:Columns({id = "settingsOptimization", columns = 2}).Columns
        numeric(optimizationColumns[1], "settings.fps", "settings.fps_cap", 15, 360)
        toggle(optimizationColumns[2], "settings.render", "settings.render",
            "settings/settingsWorkspaces/session/settingsOptimization/1/settings.render", {field = true})
        local automation = create:Group({id = "sessionAutomation", key = "settings.session", collapsible = true, open = true}).Create
        local sessionColumns = automation:Columns({id = "settingsSession", columns = 3, breakpoint = 560}).Columns
        toggle(sessionColumns[1], "settings.antiAfk", "session.antiAfk")
        toggle(sessionColumns[2], "settings.reconnect", "session.reconnect")
        toggle(sessionColumns[3], "settings.teleport", "session.teleport")
        toggle(automation, "lobby.captcha", "autocaptcha", "lobby/lobbyWorkspaces/utilities/lobby.captcha")
        if app.services.sessionLogs then
            local logs = create:Group({id = "sessionLogs", key = "settings.logs", collapsible = true}).Create
            toggle(logs, "settings.logsEnabled", "settings.sessionLogs")
            logs:Label({key = "settings.logsHint"})
            logs:Button({key = "settings.logsClear", onChanged = function()
                local ok, count = app.services.sessionLogs:ClearOld()
                notify(ok and "settings.logsCleared" or "settings.logsUnavailable", not ok, {count = count})
            end})
        end
        local maintenance = create:Group({id = "sessionMaintenance", key = "lobby.misc", collapsible = true}).Create
        local maintenanceColumns = maintenance:Columns({id = "settingsMaintenance", columns = 2}).Columns
        maintenanceColumns[1]:Button({ key = "settings.forgetKey", onChanged = function()
            if app.ForgetKey then app:ForgetKey()
            else app.keyConfig:Set("key", ""); app.keyConfig:Flush() end
            notify("settings.keyForgotten")
        end })
        maintenanceColumns[2]:Button({ key = "settings.flush", onChanged = function()
            local success = cfg:Flush()
            notify(success and app.storage and "ui.saved" or "settings.unsupported", not success)
        end })
        local serverActions = maintenance:Columns({id = "serverActions", columns = 2}).Columns
        serverActions[1]:Button({ key = "lobby.serverHop", onChanged = function()
            if not app.services.session:ServerHop() then notify("lobby.noServers", true) end
        end })
        serverActions[2]:Button({ key = "lobby.rejoin", onChanged = function() app.services.session:Rejoin() end })
        local sessionActions = maintenance:Columns({id = "sessionActions", columns = 2}).Columns
        sessionActions[1]:Button({key = "home.community", onChanged = copy})
        sessionActions[2]:Button({key = "home.unload", onChanged = function() app:Destroy() end})
        create = settingsPages.pages.data.Create
        create:Section({key = "settings.transfer"})
        local secrets = create:Toggle({key = "settings.includeWebhook", value = false})
        local exchange = create:Input({key = "settings.configJson", multiline = true, height = 170, maxLength = 131072})
        local transferActions = create:Columns({id = "settingsTransfer", columns = 2}).Columns
        transferActions[1]:Button({key = "settings.export", onChanged = function()
            local text = app:ExportConfig(secrets:Get())
            if not text then notify("settings.transferFailed", true); return end
            exchange:Set(text, false)
            notify(app.runtime:Copy(text) and "settings.exportCopied" or "settings.exportReady")
        end})
        transferActions[2]:Button({key = "settings.import", onChanged = function()
            local ok = app:ImportConfig(exchange:Get())
            notify(ok and "settings.imported" or "settings.transferFailed", not ok)
        end})
        create = settingsPages.pages.notifications.Create
        local notificationPages = pages(create, "notificationWorkspaces", {
            {id = "discord", key = "notifications.discord", image = Assets.Icons.Notifications},
            {id = "telegram", key = "telegram.title", image = Assets.Icons.Send}})
        local function channelEvents(parent, channel)
            local prefix = NotificationSettings.prefix(channel)
            local discord = channel == "discord"
            parent:Section({key = "notifications.events"})
            local matchEvents = parent:Columns({id = "matchEvents", columns = 2}).Columns
            toggle(matchEvents[1], "settings.webhookStart", prefix .. "settings.ongamestart",
                discord and "notifications/notificationWorkspaces/events/settingsWebhook/1/settings.webhookStart" or nil)
            toggle(matchEvents[2], "settings.webhookEnd", prefix .. "settings.ongameend",
                discord and "notifications/notificationWorkspaces/events/settingsWebhook/2/settings.webhookEnd" or nil)
            toggle(parent, "notifications.summons", prefix .. "summons.enabled",
                discord and "lobby/lobbyWorkspaces/summon/summonDelivery/1/summon.webhook" or nil)
            local drops = parent:Group({id = "dropSettings", key = "drops.title", collapsible = true}).Create
            drops:Label({key = "drops.notice"})
            toggle(drops, "drops.enabled", prefix .. "drops.enabled",
                discord and "notifications/notificationWorkspaces/drops/drops.enabled" or nil)
            local filters = drops:Columns({id = "rarities", columns = 3}).Columns
            for index, rarity in ipairs({"secret", "mythic", "other"}) do
                toggle(filters[index], "drops." .. rarity, prefix .. "drops.units_" .. rarity,
                    discord and "notifications/notificationWorkspaces/drops/dropFilters/1/drops.units/drops." .. rarity or nil)
            end
        end
        create = notificationPages.pages.discord.Create
        create:Section({ key = "settings.webhooks" })
        input(create, "settings.webhookUrl", "webhook.ds_url", "settings.webhookPlaceholder", function(value)
            if value ~= "" and not Webhook.valid(value) then notify("settings.invalidWebhook", true); return false end
            return true
        end)
        local testButton
        local function delivery(outcome)
            if not testButton.scope.alive then return end
            testButton:SetEnabled(true)
            testButton.options.key = "settings.webhookTest"
            testButton.label.Text = window.i18n:T(testButton.options.key)
            notify("webhook." .. outcome.code, not outcome.ok, {status = outcome.status,
                discord = outcome.discordCode or "—"})
        end
        testButton = create:Button({ key = "settings.webhookTest", onChanged = function()
            testButton:SetEnabled(false)
            testButton.options.key = "webhook.sending"
            testButton.label.Text = window.i18n:T(testButton.options.key)
            local queued, outcome = app.services.webhook:Send("Test notification", nil, delivery)
            if not queued then delivery(outcome) end
        end })
        create:Label({ key = "settings.webhookNotice" })
        channelEvents(create, "discord")
        if app.services.telegram then
            create = notificationPages.pages.telegram.Create
            create:Section({key = "telegram.title"})
            create:Label({key = "telegram.notice"})
            local fields = create:Columns({id = "telegramFields", columns = 2}).Columns
            fields[1]:Input({key = "telegram.token", placeholderKey = "telegram.tokenPlaceholder",
                writeOnly = true, maxLength = 128, onChanged = function(value)
                    if not value:match("^%d+:[%w_-]+$") then notify("telegram.invalid", true); return false end
                    cfg:Set("webhook.tg_token", value)
                end})
            input(fields[2], "telegram.chat", "webhook.tg_chat_id", "telegram.chatPlaceholder", function(value)
                if value == "" then return true end
                local id = tonumber(value)
                if #value <= 17 and value:match("^%-?%d+$") and id ~= 0 and math.abs(id) < 2 ^ 52 then return true end
                notify("telegram.invalid", true)
                return false
            end)
            local actions = create:Columns({id = "telegramActions", columns = 2}).Columns
            local telegramTest
            local function telegramDelivery(outcome)
                if not telegramTest.scope.alive then return end
                telegramTest:SetEnabled(true)
                notify(outcome.ok and "telegram.sent" or "telegram.failed", not outcome.ok,
                    {reason = tostring(outcome.code), status = outcome.status or 0})
            end
            telegramTest = actions[1]:Button({key = "telegram.test", onChanged = function()
                telegramTest:SetEnabled(false)
                local queued, outcome = app.services.telegram:Send("Test notification", nil, telegramDelivery)
                if not queued then telegramDelivery(outcome) end
            end})
            actions[2]:Button({key = "telegram.clear", onChanged = function()
                cfg:Set("webhook.tg_token", "")
                cfg:Set("webhook.tg_chat_id", "")
            end})
            channelEvents(create, "telegram")
        end
        create = settingsPages.pages.appearance.Create
        local visualPages = pages(create, "appearanceWorkspaces", {{id = "general", key = "visual.title"},
            UIAssets.With({id = "traits", key = "visual.unitAppearance"}, UIAssets.GameIcon("traits")),
            UIAssets.With({id = "resources", key = "visual.resources"}, UIAssets.Resource("Gems"))})
        create = visualPages.pages.general.Create
        create:Section({key = "visual.title"})
        toggle(create, "ui.enabled", "visuals.enabled")
        input(create, "visual.nickname", "visuals.nickname", "visual.nicknamePlaceholder", function(value)
            return #value <= 64 and not value:find("%c")
        end)
        create = visualPages.pages.traits.Create
        create:Section({key = "visual.unitAppearance"})
        create:Label({key = "visual.unitAppearanceNotice"})
        local icons = app.adapter.TraitDescriptors and app.adapter:TraitDescriptors() or TraitIcons.read()
        local traitChoices = {{value = "", key = "visual.originalTrait"}}
        for _, name in ipairs(TraitIcons.names()) do
            local icon = icons[name]
            traitChoices[#traitChoices + 1] = {value = name, label = name, image = icon.image,
                imageRectOffset = icon.rectOffset, imageRectSize = icon.rectSize, imageGradient = TraitIcons.gradient(icon)}
        end
        local slots = app.adapter.Hotbar and app.adapter:Hotbar() or {}
        if not next(slots) and app.adapter.Equipped then slots = app.adapter:Equipped() end
        for index = 1, 6 do
            local name = slots[index] and slots[index].name
            local slot = tostring(index)
            local group = create:Group({id = "visualSlot", key = name and name ~= "" and "units.slotNamed" or "units.slot",
                parameters = {index = index, name = name or ""}, collapsible = true}).Create
            local options = group:Columns({id = "visualSlotOptions", columns = 2}).Columns
            dropdown(options[1], "visual.trait", "visuals.traits." .. slot, traitChoices)
            toggle(options[2], "visual.shiny", "visuals.shiny." .. slot, nil, {field = true})
        end
        create = visualPages.pages.resources.Create
        create:Section({key = "visual.resources"})
        toggle(create, "visual.showResourcesOnHome", "visuals.showResourcesOnHome")
        create:Label({key = "visual.resourceOriginalHint"})
        local resourceColumns = create:Columns({id = "visualResources", columns = 2}).Columns
        for index, name in ipairs({"Gems", "Gold", "GemsLegacy", "SummerPearls", "Yen"}) do
            numeric(resourceColumns[(index - 1) % 2 + 1], "visual.resource." .. name, "visuals.resources." .. name, -1, 1e15)
        end
        create:Button({key = "visual.restore", onChanged = function() cfg:Set("visuals.enabled", false) end})
    end })

    window:CreateTab({id = "macros", key = "tab.macros", hidden = true, backTab = "units", build = function(create)
        back(create, "units")
        MacroPage.mount(app, create)
    end})
    window:CreateThemeTab({id = "themes", key = "tab.themes", hidden = true, backTab = "settings"})
    window:CreateKeybindTab({id = "binds", hidden = true, backTab = "settings"})
    if app.settings.SaintTest == true then
        window:CreateTab({id = "testMenu", key = "test.title", icon = Assets.Icons.Settings,
            build = function(create) TestPage.mount(app, create) end})
    end
    if headerSettings then window:SetSettingsTab("settings") end
    window:SetTabOrder({"home", "farm", "units", "lobby", "testMenu", "statistics", "macros", "settings"})
    window:SetBottomTabs({"settings"})
end

return View
end

__modules["game/Adapter"] = function(require)
local Scope = require("core/Scope")
local Util = require("core/Util")
local Catalog = require("game/Catalog")
local Signal = require("core/Signal")
local CodeRedemption = require("game/CodeRedemption")
local TraitIcons = require("game/TraitIcons")
local Adapter = {}
Adapter.__index = Adapter
Adapter.Version = "2.0.0"
local nativeRequire = type(getfenv) == "function" and getfenv(0).require or nil

local resourceFields = {Gems = "gem_amount", Gold = "gold_amount", Yen = "resource"}
local clientEndpoints = {"spawn_unit", "upgrade_unit_ingame", "sell_unit_ingame", "request_join_lobby", "request_lock_level",
    "request_start_game", "request_matchmaking", "buy_from_banner", "redeem_code", "redeem_quest",
    "claim_battlepass_rewards", "claim_daily_reward", "vote_start", "set_game_finished_vote", "teleport_back_to_lobby",
    "dungeon_start", "dungeon_enter_room", "dungeon_continue_shop", "dungeon_continue_death", "dungeon_open_chest",
    "dungeon_shrine_accept", "request_start_infinite_tower", "request_start_infinite_tower_from_game",
    "buy_travelling_merchant_item", "buy_gold_shop_item", "vote_wave_skip", "change_priority", "use_item",
    "party_respond_invite", "equip_unit", "unequip_unit", "unequip_all", "sell_units", "use_portal"}

local function identifier(value)
    return type(value) == "string" and #value > 0 and #value <= 128 and value:match("^[%w_:%-]+$") ~= nil
end

local function text(object)
    if not object or not (object:IsA("TextLabel") or object:IsA("TextButton")) then return "" end
    return Util.trim(object.Text:gsub("<[^>]+>", ""))
end

local function numberValue(object)
    if not object or not (object:IsA("NumberValue") or object:IsA("IntValue")) then return nil end
    return Util.number(object.Value, nil, -math.huge, math.huge)
end

local function placementRadius(records, name)
    local radius = 1.9
    if type(name) ~= "string" or name == "" then return radius end
    for _, record in pairs(type(records) == "table" and records or {}) do
        if type(record) == "table" and record.name == name then
            local current = tonumber(record.override_hitbox_radius)
            if current and current == current and current >= 0.9 and current <= 12 then radius = math.max(radius, current) end
        end
    end
    return radius
end
Adapter.placementRadius = placementRadius

function Adapter.new(player, scope, lobbyId)
    local ids = {}
    local self = setmetatable({
        player = player, scope = scope:Child(), lobbyId = lobbyId,
        storage = game:GetService("ReplicatedStorage"), cache = {}, inFlight = {}, lastCall = {}, unitsIds = ids, UnitsIds = ids,
    }, Adapter)
    self.Succeeded = Signal.new()
    self.scope:Add(self.Succeeded)
    self.Failed = Signal.new()
    self.scope:Add(self.Failed)
    self.BeforeCall = Signal.new()
    self.scope:Add(self.BeforeCall)
    self.Redeemed = Signal.new()
    self.scope:Add(self.Redeemed)
    return self
end

function Adapter:_Failed(name, reason, started)
    if self.Failed then self.Failed:Fire(name, reason, math.max(0, (os.clock() - (started or os.clock())) * 1000)) end
    return false, reason
end

function Adapter:Gui(path)
    return Util.find(self.player:FindFirstChildOfClass("PlayerGui"), path)
end

function Adapter:TraitDescriptors()
    return TraitIcons.read(Util.find(self.storage, "packages.assets.gui.TraitIcons"))
end

function Adapter:TraitGradientSources()
    return TraitIcons.sources(Util.find(self.storage, "packages.assets.gui.RarityGradients"))
end

function Adapter:UnitMetadata(id)
    if not self.unitDataLoaded then
        self.unitDataLoaded = true
        local module = Util.find(self.storage, "src.Data.Units")
        if module and nativeRequire then
            local ok, records = pcall(nativeRequire, module)
            if ok and type(records) == "table" then self.unitData = records end
        end
    end
    return self.unitData and self.unitData[id]
end

function Adapter:RewardDescriptor(value)
    if type(value) ~= "string" or value == "" or #value > 128 then return nil end
    self.rewardDescriptors = self.rewardDescriptors or {}
    if self.rewardDescriptors[value] ~= nil then return self.rewardDescriptors[value] or nil end
    local lowered = value:lower()
    local compact = lowered:gsub("[%s_%-]", "")
    local resources = {gems = "Gems", gold = "Gold", xp = "XP", trophies = "Trophies",
        summerpearls = "SummerPearls", gemslegacy = "GemsLegacy", yen = "Yen"}
    for _, resource in ipairs(self:Resources()) do
        if type(resource.name) == "string" then resources[resource.name:lower():gsub("[%s_%-]", "")] = resource.name end
    end
    if resources[compact] then
        local row = {kind = "resource", id = resources[compact], name = resources[compact]}
        self.rewardDescriptors[value] = row
        return row
    end
    self:ItemMetadata(value)
    for id, metadata in pairs(self.itemData or {}) do
        if identifier(id) and type(metadata) == "table" and (id:lower() == lowered
            or (type(metadata.name) == "string" and metadata.name:lower() == lowered)) then
            local row = {kind = "item", id = id, name = metadata.name or id, rarity = metadata.rarity}
            self.rewardDescriptors[value] = row
            return row
        end
    end
    self:UnitMetadata(value)
    for id, metadata in pairs(self.unitData or {}) do
        if identifier(id) and type(metadata) == "table" and (id:lower() == lowered
            or (type(metadata.name) == "string" and metadata.name:lower() == lowered)) then
            local row = {kind = "unit", id = id, name = metadata.name or id, rarity = metadata.rarity}
            self.rewardDescriptors[value] = row
            return row
        end
    end
end

function Adapter:PlacementRadius(name)
    self:UnitMetadata(name)
    return placementRadius(self.unitData, name)
end

function Adapter:AutoPlaceRule(slot)
    self:UnitMetadata(slot.name)
    local rule
    local count = self:SpawnLimit(slot)
    if not count then return nil end
    for _, unit in pairs(self.unitData or {}) do
        if type(unit) == "table" and unit.name == slot.name and type(unit.cost) == "number" and unit.cost > 0 then
            local id = type(unit.id) == "string" and unit.id or ""
            local back = (tonumber(unit.farm_amount) or 0) > 0 or id:match("^hoshino") ~= nil
            local surface = unit.hill_unit == true and "hill" or "ground"
            local pathPercent = back and 0 or 100
            if rule and (rule.place_type ~= surface or rule.path_percent ~= pathPercent
                or rule.count ~= count) then return nil end
            rule = {place_type = surface, path_percent = pathPercent, count = count,
                cost = tonumber(unit.cost)}
        end
    end
    return rule
end

function Adapter:_NativeService(name)
    self.nativeServices = self.nativeServices or {}
    if self.nativeServices[name] ~= nil then return self.nativeServices[name] or nil end
    local loader = Util.find(self.storage, "src.Loader")
    if not loader or not nativeRequire then self.nativeServices[name] = false; return nil end
    local ok, service = pcall(function() return nativeRequire(loader).load_client_service(loader, name) end)
    self.nativeServices[name] = ok and type(service) == "table" and service or false
    return self.nativeServices[name] or nil
end

function Adapter:SpawnLimit(slot)
    if type(slot) ~= "table" then return nil end
    if slot.unique == true then return 1 end
    self:UnitMetadata(slot.name)
    local limit
    for _, unit in pairs(self.unitData or {}) do
        if type(unit) == "table" and unit.name == slot.name then
            local current = unit.spawn_cap == nil and 5 or tonumber(unit.spawn_cap)
            if not current or current ~= current or current % 1 ~= 0 or current < 1 or current > 20 then return nil end
            if limit and limit ~= current then return nil end
            limit = current
        end
    end
    return limit
end

function Adapter:ResolveSummonTarget(target)
    target = target:lower()
    self:UnitMetadata(target)
    if not self.unitData then return nil end
    local exact, matches
    for id, entry in pairs(self.unitData) do
        if type(id) == "string" and type(entry) == "table" then
            if id:lower() == target then return {[id] = true}, entry.rarity end
            if type(entry.name) == "string" and entry.name:lower() == target then
                exact = exact or {}
                exact[id] = true
                if not matches then matches = entry.rarity
                elseif matches ~= entry.rarity then matches = "Mixed" end
            end
        end
    end
    return exact, matches
end

function Adapter:InLobby()
    return game.PlaceId == self.lobbyId
end

function Adapter:AcquireLobbyAction(owner)
    if type(owner) ~= "table" or not self.scope.alive or not self:InLobby() then return false, "unavailable" end
    if self.lobbyActionOwner and self.lobbyActionOwner ~= owner then return false, "lobby_busy" end
    self.lobbyActionOwner = owner
    return true
end

function Adapter:ReleaseLobbyAction(owner)
    if self.lobbyActionOwner ~= owner then return false end
    self.lobbyActionOwner = nil
    return true
end

function Adapter:LobbyActionBusy()
    return self.lobbyActionOwner ~= nil
end

function Adapter:Endpoint(name, server)
    local key = (server and "s:" or "c:") .. name
    local endpoint = self.cache[key]
    if endpoint and endpoint.Parent then return endpoint end
    endpoint = Util.find(self.storage, "endpoints." .. (server and "server_to_client." or "client_to_server.") .. name)
    self.cache[key] = endpoint
    return endpoint
end

function Adapter:Call(name, ...)
    return self:_Call(name, 0.45, ...)
end

function Adapter:MacroCall(name, ...)
    if name ~= "spawn_unit" and name ~= "upgrade_unit_ingame" and name ~= "sell_unit_ingame"
        and name ~= "use_active_attack" and name ~= "activate_unit_ability" then
        return self:_Failed(name, "unsupported_macro_call")
    end
    -- Macro actions await receipts and timestamps; keep native in-flight
    -- serialization without inserting the auto-farm debounce between steps.
    return self:_Call(name, 0, ...)
end

function Adapter:_Call(name, minimumGap, ...)
    if not self.scope.alive then return self:_Failed(name, "destroyed") end
    local now = os.clock()
    if self.inFlight[name] or now - (self.lastCall[name] or -math.huge) < minimumGap then return self:_Failed(name, "busy", now) end
    local endpoint = self:Endpoint(name)
    if not endpoint or not (endpoint:IsA("RemoteFunction") or endpoint:IsA("RemoteEvent")) then
        return self:_Failed(name, "missing", now)
    end
    self.lastCall[name] = now
    local arguments = table.pack(...)
    self.BeforeCall:Fire(name, arguments)
    if endpoint:IsA("RemoteEvent") then
        local ok, errorCode = pcall(endpoint.FireServer, endpoint, ...)
        if ok then self.Succeeded:Fire(name, arguments, math.max(0, (os.clock() - now) * 1000)); return true, errorCode end
        return self:_Failed(name, errorCode, now)
    end
    local request = self.scope:Child()
    self.inFlight[name] = request
    request:Delay(8, function() request:Destroy() end)
    local done, success, result = false, false, nil
    local inFlight = self.inFlight
    -- InvokeServer is resumed by Roblox when its reply arrives. Cancelling that
    -- coroutine at our timeout/unload can produce "cannot resume dead coroutine".
    -- Own the logical deadline, not the native waiter; it retires itself on reply.
    task.defer(function()
        if not request.alive then
            done = true
            if inFlight[name] == request then inFlight[name] = nil end
            return
        end
        success, result = pcall(endpoint.InvokeServer, endpoint, table.unpack(arguments, 1, arguments.n))
        done = true
        if inFlight[name] == request then inFlight[name] = nil end
        request:Destroy()
    end)
    local deadline = now + 8
    repeat task.wait(minimumGap == 0 and 0.015 or 0.05)
    until done or not request.alive or not self.scope.alive or os.clock() >= deadline
    request:Destroy()
    if not self.scope.alive then return self:_Failed(name, "destroyed", now) end
    -- Keep a timed-out native request quarantined until it really returns. A
    -- retry must not duplicate a spawn/purchase that may already have succeeded.
    if not done then return self:_Failed(name, "timeout", now) end
    if success and result ~= false then
        self.Succeeded:Fire(name, arguments, math.max(0, (os.clock() - now) * 1000))
        return true, result
    end
    self:_Failed(name, success and (result or "rejected") or result, now)
    return false, result
end

function Adapter:Value(path, fallback)
    local object = Util.find(self.player, path)
    return object and object.Value or fallback
end

function Adapter:Resource(name)
    if type(name) ~= "string" then return 0, "missing" end
    local stats = self.player:FindFirstChild("_stats")
    local field = resourceFields[name] or (name:sub(1, 9) == "_resource" and name or "_resource" .. name)
    local value = numberValue(stats and stats:FindFirstChild(field))
    if value == nil then value = numberValue(stats and stats:FindFirstChild(name)) end
    if value == nil then return 0, "missing" end
    return value, "ready"
end

function Adapter:Resources()
    local stats, result = self.player:FindFirstChild("_stats"), {}
    for _, child in ipairs(stats and stats:GetChildren() or {}) do
        local name = child.Name == "gem_amount" and "Gems" or child.Name == "gold_amount" and "Gold" or
            (child.Name:sub(1, 9) == "_resource" and child.Name:sub(10) or nil)
        local value = numberValue(child)
        if name and name ~= "" and value ~= nil then result[#result + 1] = {name = name, field = child.Name, value = value} end
    end
    table.sort(result, function(a, b) return a.name < b.name end)
    return result
end

function Adapter:Capabilities()
    local result = {version = self.Version, inLobby = self:InLobby(), remotes = {}, events = {}}
    for _, name in ipairs(clientEndpoints) do
        local object = self:Endpoint(name)
        result.remotes[name] = object and (object:IsA("RemoteEvent") or object:IsA("RemoteFunction")) or false
    end
    for _, name in ipairs({"normal_item_added", "unique_item_added", "unit_added"}) do
        local object = self:Endpoint(name, true)
        result.events[name] = object and object:IsA("RemoteEvent") or false
    end
    return result -- Availability, not a claim that the server accepts a payload.
end

function Adapter:Events()
    local root, result, seen = Util.find(workspace, "_EVENT_CHALLENGES.Lobbies"), {}, {}
    for _, lobby in ipairs(root and root:GetChildren() or {}) do
        local level = lobby:FindFirstChild("Level")
        local id = level and level:IsA("StringValue") and level.Value
        if identifier(id) and not seen[id] then
            local label = text(Util.find(lobby, "Door.Surface.LevelName"))
            local metadata = self:LevelMetadata(id)
            result[#result + 1] = {value = id, label = label ~= "" and label or id, lobby = lobby.Name,
                map = metadata and metadata.map}
            seen[id] = true
        end
    end
    table.sort(result, function(a, b) return a.value < b.value end)
    return result
end

function Adapter:ResolveEventId(preferred)
    local events = self:Events()
    if preferred and preferred ~= "" then
        for _, event in ipairs(events) do if event.value == preferred then return event.value, "ready" end end
        return nil, "missing"
    end
    if #events == 1 then return events[1].value, "ready" end
    return nil, #events > 1 and "ambiguous" or "missing"
end

function Adapter:EventLobby(id)
    for _, event in ipairs(self:Events()) do
        if event.value == id and identifier(event.lobby) then return event.lobby end
    end
end

function Adapter:MapCatalog(refresh)
    if self.mapCatalog and not refresh then return self.mapCatalog, self.mapDiagnostics end
    if self.loadingMaps then return self.mapCatalog or {story = {}, legend = {}, raids = {}, infinity = {}}, {busy = true} end
    self.loadingMaps = true
    local scope = self.scope:Child()
    scope:Add(function() self.loadingMaps = false end)
    local catalog, diagnostics = Catalog.load(Util.find(self.storage, "src.Data.Worlds"), scope)
    scope:Destroy()
    if self.scope.alive then self.mapCatalog, self.mapDiagnostics = catalog, diagnostics end
    return catalog, diagnostics
end

function Adapter:SelectedLevel(mode, worldId, levelId)
    local catalog = self.mapCatalog
    for _, world in ipairs(catalog and catalog[mode] or {}) do
        if world.value == worldId then
            for _, level in ipairs(world.levels) do if level.value == levelId then return level.value end end
        end
    end
    return nil
end

function Adapter:Lobbies(category)
    local root = Util.find(workspace, "_LOBBIES." .. (category or "Story"))
    local result = {}
    for _, lobby in ipairs(root and root:GetChildren() or {}) do
        local active, owner = lobby:FindFirstChild("Active"), lobby:FindFirstChild("Owner")
        local available = active and active:IsA("BoolValue") and not active.Value and
            (not owner or (owner:IsA("ObjectValue") and owner.Value == nil)) or false
        result[#result + 1] = {value = lobby.Name, label = lobby.Name, available = available}
    end
    table.sort(result, function(a, b) return a.value < b.value end)
    return result
end

function Adapter:GameData()
    local ok, teleport = pcall(function() return game:GetService("TeleportService"):GetLocalPlayerTeleportData() end)
    local data = ok and type(teleport) == "table" and teleport.level_data
    local level = type(data) == "table" and data.levelData or {}
    if type(level) ~= "table" then level = {} end
    local challenge = level._gamemode == "challenge" and level._challenge_uuid ~= nil
        and not level._is_event_challenge and (level._is_daily_challenge and "daily" or "normal") or nil
    return { id = tostring(level.id or ""), mode = tostring(level._gamemode or "unknown"), challenge = challenge,
        location = tostring(level._location_name or "unknown"), name = tostring(level.name or ""),
        difficulty = tostring(level._difficulty or ""), weather = tostring(level._weather or "") }
end

function Adapter:LobbyMembership(lobby)
    if not identifier(lobby) then return false end
    local model = Util.find(workspace, "_EVENT_CHALLENGES.Lobbies." .. lobby)
    if not model then
        local root = Util.find(workspace, "_LOBBIES")
        for _, category in ipairs(root and root:GetChildren() or {}) do
            local candidate = category:FindFirstChild(lobby)
            if candidate then model = candidate; break end
        end
    end
    local players = model and model:FindFirstChild("Players")
    if not players then return false end
    for _, entry in ipairs(players:GetDescendants()) do
        if entry:IsA("ObjectValue") and entry.Value == self.player then return true end
        if entry:IsA("StringValue") and entry.Value == self.player.Name then return true end
    end
    return false
end

function Adapter:LobbyRequiresOwner(lobby)
    if not identifier(lobby) then return nil end
    local model = Util.find(workspace, "_EVENT_CHALLENGES.Lobbies." .. lobby)
    local value = model and model:FindFirstChild("requires_owner")
    if value and value:IsA("BoolValue") then return value.Value end
end

function Adapter:_LoadLevelData()
    if not self.levelDataLoaded then
        self.levelDataLoaded = true
        local module = Util.find(self.storage, "src.Data.Levels")
        local ok, records = false, nil
        if module and nativeRequire then ok, records = pcall(nativeRequire, module) end
        if (not ok or type(records) ~= "table") and nativeRequire then
            local loaderModule = Util.find(self.storage, "src.Loader")
            local loaderOK, loader = false, nil
            if loaderModule then loaderOK, loader = pcall(nativeRequire, loaderModule) end
            if loaderOK and type(loader) == "table" and type(loader.load_data) == "function" then
                ok, records = pcall(loader.load_data, loaderModule, "Levels")
            end
        end
        if ok and type(records) == "table" then self.levelData = records end
    end
    return self.levelData
end

function Adapter:LevelMetadata(levelId)
    if not identifier(levelId) then return nil end
    self:_LoadLevelData()
    local record = self.levelData and self.levelData[levelId]
    if type(record) ~= "table" then return nil end
    return {id = levelId, name = type(record.name) == "string" and record.name or levelId,
        map = identifier(record.map) and record.map or nil,
        resources = type(record.resources_shown_at_start) == "table" and record.resources_shown_at_start or nil,
        boardReward = type(record.map_board_line_reward) == "table" and record.map_board_line_reward or nil}
end

function Adapter:LevelMap(levelId)
    local metadata = self:LevelMetadata(levelId)
    return metadata and metadata.map
end

function Adapter:LevelReward(levelId)
    if not identifier(levelId) then return nil end
    if not self.questDataLoaded then
        self.questDataLoaded = true
        local module = Util.find(self.storage, "src.Data.Quests")
        local ok, records = false, nil
        if module and nativeRequire then ok, records = pcall(nativeRequire, module) end
        if (not ok or type(records) ~= "table") and nativeRequire then
            local loaderModule = Util.find(self.storage, "src.Loader")
            local loaderOK, loader = false, nil
            if loaderModule then loaderOK, loader = pcall(nativeRequire, loaderModule) end
            if loaderOK and type(loader) == "table" and type(loader.load_data) == "function" then
                ok, records = pcall(loader.load_data, loaderModule, "Quests")
            end
        end
        if ok and type(records) == "table" then self.questData = records end
    end
    local metadata = self:LevelMetadata(levelId)
    local lineReward = metadata and metadata.boardReward
    local resources = type(lineReward) == "table" and lineReward.resource_reward
    if type(resources) == "table" then
        for name, amount in pairs(resources) do
            amount = tonumber(amount)
            if identifier(name) and amount and amount == amount and amount > 0 then
                return {resource = name, amount = math.floor(amount)}
            end
        end
    end
    for _, name in ipairs(metadata and metadata.resources or {}) do
        if identifier(name) then return {resource = name} end
    end
    local record = self.levelData and self.levelData[levelId]
    local shown = type(record) == "table" and record._show_rewards
    local firstItem
    for _, row in ipairs(type(shown) == "table" and shown or {}) do
        local params = type(row) == "table" and row.params
        if row.type == "resource" and type(params) == "table" and identifier(params.resource) then
            return {resource = params.resource}
        end
        if not firstItem and row.type == "item" and type(params) == "table" and identifier(params.item_id) then
            firstItem = params.item_id
        end
    end
    if firstItem then return {item = firstItem} end
    local quest = self.questData and self.questData[levelId]
    local reward = type(quest) == "table" and quest.quest_reward
    local gems = type(reward) == "table" and tonumber(reward.gem_reward)
    if gems and gems == gems and gems > 0 then return {resource = "Gems", amount = math.floor(gems)} end
    local override = type(record) == "table" and tonumber(record._override_gem_reward)
    if override and override == override and override > 0 then return {resource = "Gems", amount = math.floor(override)} end
end

function Adapter:LevelLoot(levelId)
    if not identifier(levelId) then return {} end
    self:LevelReward(levelId)
    local record = self.levelData and self.levelData[levelId]
    if type(record) ~= "table" then return {} end
    local found = {}
    local function add(kind, id, amount, source)
        if (kind ~= "resource" and kind ~= "item" and kind ~= "unit") or not identifier(id) then return end
        local key = kind .. ":" .. id
        local row = found[key]
        if not row then
            local metadata = kind == "item" and self:ItemMetadata(id) or kind == "unit" and self:UnitMetadata(id)
            row = {kind = kind, id = id, name = type(metadata) == "table" and metadata.name or id,
                rarity = type(metadata) == "table" and metadata.rarity or nil, amount = 0, sources = {}}
            found[key] = row
        end
        amount = tonumber(amount)
        if amount and amount == amount and amount > 0 then row.amount = math.max(row.amount, amount) end
        row.sources[source] = true
    end
    local function scan(value, source, depth, resourceId)
        if depth > 6 or type(value) ~= "table" then return end
        if resourceId and tonumber(value.reward) and tonumber(value.reward) > 0 then
            add("resource", resourceId, value.reward, source)
        end
        if identifier(value.resource) then add("resource", value.resource, value.amount or value.reward, source) end
        if identifier(value._resource) then add("resource", value._resource, value.amount or value.max_amount, source) end
        if identifier(value.item_id) then add("item", value.item_id, value.amount or value.max_amount or value.min_amount, source) end
        if identifier(value.item) then add("item", value.item, value.amount or value.max_amount or value.min_amount, source) end
        if identifier(value.unit_id) then add("unit", value.unit_id, value.amount or 1, source) end
        if identifier(value.unit) then add("unit", value.unit, value.amount or 1, source) end
        for key, child in pairs(value) do
            if key == "gem_reward" and tonumber(child) and tonumber(child) > 0 then add("resource", "Gems", child, source)
            elseif key == "gold_reward" and tonumber(child) and tonumber(child) > 0 then add("resource", "Gold", child, source)
            elseif key == "trophy_reward" and tonumber(child) and tonumber(child) > 0 then add("resource", "Trophies", child, source)
            elseif key == "resource_reward" and type(child) == "table" then
                for name, amount in pairs(child) do add("resource", name, amount, source) end
            elseif type(child) == "table" then scan(child, source, depth + 1, resourceId) end
        end
    end
    local function scanInfinite(value)
        for name, rows in pairs(type(value) == "table" and value or {}) do
            if identifier(name) and type(rows) == "table" then
                for _, row in pairs(rows) do
                    if type(row) == "table" then scan(row, "infinite", 0, name) end
                end
            end
        end
    end
    local quest = self.questData and self.questData[levelId]
    local questReward = type(quest) == "table" and quest.quest_reward
    if type(questReward) == "table" and tonumber(questReward.gem_reward) and questReward.gem_reward > 0 then
        add("resource", "Gems", questReward.gem_reward, "quest")
    end
    local override = tonumber(record._override_gem_reward)
    if override and override > 0 then add("resource", "Gems", override, "level") end
    scan(record.map_board_line_reward, "board", 0)
    scanInfinite(record.infinite_resource_rewards)
    scan(record._show_rewards, "shown", 0)
    scan(record.rewards, "drop", 0)
    scan(record.clear_rewards, "clear", 0)
    for _, name in ipairs(type(record.resources_shown_at_start) == "table" and record.resources_shown_at_start or {}) do
        add("resource", name, nil, "shown")
    end
    local result = {}
    for _, row in pairs(found) do
        local sources = {}; for source in pairs(row.sources) do sources[#sources + 1] = source end
        table.sort(sources); row.sources = sources
        result[#result + 1] = row
    end
    local rank = {resource = 1, item = 2, unit = 3}
    table.sort(result, function(a, b)
        if rank[a.kind] ~= rank[b.kind] then return rank[a.kind] < rank[b.kind] end
        return a.name < b.name or (a.name == b.name and a.id < b.id)
    end)
    return result
end

function Adapter:LootCatalog()
    local levels = self:_LoadLevelData()
    if type(levels) ~= "table" then return {resources = {}, items = {}, units = {}, levels = 0}, "unavailable" end
    local groups, levelCount = {resource = {}, item = {}, unit = {}}, 0
    for id, record in pairs(levels) do
        if identifier(id) and type(record) == "table" then
            levelCount = levelCount + 1
            if levelCount > 1000 then break end
            for _, row in ipairs(self:LevelLoot(id)) do
                local group = groups[row.kind]
                if group then
                    local saved = group[row.id]
                    if not saved then
                        saved = {id = row.id, name = row.name, levels = 0}
                        group[row.id] = saved
                    end
                    saved.levels = saved.levels + 1
                end
            end
        end
    end
    local function list(source)
        local result = {}; for _, row in pairs(source) do result[#result + 1] = row end
        table.sort(result, function(a, b) return a.name < b.name or (a.name == b.name and a.id < b.id) end)
        return result
    end
    return {resources = list(groups.resource), items = list(groups.item), units = list(groups.unit), levels = levelCount}, "ready"
end

function Adapter:SpecialModeContext(mode)
    if mode == "dungeon" then
        local service = self:_NativeService("DungeonServiceClient")
        local loot = {{kind = "run", id = "treasure", name = "Treasure Chests"}}
        local loaderModule = Util.find(self.storage, "src.Loader")
        if loaderModule and nativeRequire then
            local ok, loader = pcall(nativeRequire, loaderModule)
            local coreOK, core = false, nil
            if ok and type(loader) == "table" and type(loader.load_core_service) == "function" then
                coreOK, core = pcall(loader.load_core_service, loaderModule, "DungeonServiceCore")
            end
            if coreOK and type(core) == "table" and type(core.ITEMS) == "table" then
                local names = {}
                for _, item in pairs(core.ITEMS) do
                    if type(item) == "table" and type(item.name) == "string" and not item.curse_chance
                        and not item.curse_super_chance then names[#names + 1] = item.name end
                end
                table.sort(names)
                if #names > 0 then loot[#loot + 1] = {kind = "run", id = "run_items",
                    name = string.format("%d temporary run items", #names)} end
            end
        end
        return {background = nil, loot = loot, serviceReady = service ~= nil}
    end
    if mode ~= "infinity_castle" then return nil end
    local loaderModule = Util.find(self.storage, "src.Loader")
    if not loaderModule or not nativeRequire then return {loot = {{kind = "resource", id = "Gems", name = "Gems"}}} end
    local ok, loader = pcall(nativeRequire, loaderModule)
    local coreOK, core, guiOK, gui = false, nil, false, nil
    if ok and type(loader) == "table" then
        if type(loader.load_core_service) == "function" then
            coreOK, core = pcall(loader.load_core_service, loaderModule, "InfiniteTowerServiceCore")
        end
        if type(loader.load_client_service) == "function" then
            guiOK, gui = pcall(loader.load_client_service, loaderModule, "GUIService")
        end
    end
    gui = guiOK and type(gui) == "table" and gui.infinite_tower_ui or nil
    if not coreOK or type(core) ~= "table" then return {loot = {{kind = "resource", id = "Gems", name = "Gems"}}} end
    local floor = tonumber(gui and (gui.selected_floor or gui.floor_reached)) or self:InfinityCastleFloor()
    local seed = gui and type(gui.room_seeds) == "table" and gui.room_seeds[floor]
    local map
    if type(seed) == "number" and type(core.get_world_for_floor) == "function" then
        local resolved, value = pcall(core.get_world_for_floor, floor, seed)
        if resolved and identifier(value) then map = value end
    end
    local gems = type(core.calculate_gem_reward) == "function" and tonumber(core.calculate_gem_reward(floor)) or nil
    local loot = {{kind = "resource", id = "Gems", name = "Gems", amount = gems}}
    local special = {}
    if type(core.get_floor_special_rewards) == "function" then
        local rewardsOK, rewards = pcall(core.get_floor_special_rewards)
        for _, milestone in ipairs(rewardsOK and type(rewards) == "table" and rewards or {}) do
            for _, item in ipairs(type(milestone.reward) == "table" and type(milestone.reward.item) == "table"
                and milestone.reward.item or {}) do
                if type(item) == "table" and identifier(item.item_id) then
                    local metadata = self:ItemMetadata(item.item_id)
                    local saved = special[item.item_id]
                    if not saved then
                        saved = {kind = "item", id = item.item_id,
                            name = type(metadata) == "table" and metadata.name or item.item_id,
                            rarity = type(metadata) == "table" and metadata.rarity or nil,
                            milestones = {}}
                        special[item.item_id] = saved
                    end
                    saved.milestones[#saved.milestones + 1] = tonumber(milestone.floor_num)
                end
            end
        end
    end
    for _, item in pairs(special) do table.sort(item.milestones); loot[#loot + 1] = item end
    table.sort(loot, function(a, b)
        if a.kind ~= b.kind then return a.kind == "resource" end
        return a.name < b.name
    end)
    return {map = map, floor = floor, loot = loot}
end

function Adapter:StoryProgress()
    local service = self:_NativeService("ChallengeServiceClient")
    local profile = service and service.session and service.session.profile_data
    local levelData = type(profile) == "table" and profile.level_data
    local completed = type(levelData) == "table" and levelData.completed_story_levels
    if type(completed) ~= "table" then completed = {} end
    local result = {}
    for key, value in pairs(completed) do
        local completedEntry = value == true or (type(value) == "number" and value > 0)
            or (type(value) == "table" and ((tonumber(value.times_completed) or 0) > 0
                or (tonumber(value.furthest_wave) or 0) > 0
                or (type(value.difficulty_completed_data) == "table" and next(value.difficulty_completed_data) ~= nil)))
        if type(key) == "string" and completedEntry then result[key] = true end
        if type(value) == "string" and identifier(value) then result[value] = true end
    end
    return result, tonumber(type(profile) == "table" and profile.level) or 0
end

function Adapter:InventoryUnits()
    local service = self:_NativeService("ChallengeServiceClient")
    local collection = service and service.session and service.session.collection
    local profile = collection and collection.collection_profile_data
    local owned = type(profile) == "table" and profile.owned_units
    local equipped = type(profile) == "table" and profile.equipped_units or {}
    if type(owned) ~= "table" then return {}, "unavailable" end
    local equippedByUuid = {}
    for slot, uuid in pairs(type(equipped) == "table" and equipped or {}) do
        if type(uuid) == "string" then equippedByUuid[uuid] = tonumber(slot) or true end
    end
    local result = {}
    for uuid, unit in pairs(owned) do
        if type(uuid) == "string" and #uuid <= 128 and type(unit) == "table" and unit.uuid == uuid and identifier(unit.unit_id) then
            local metadata = self:UnitMetadata(unit.unit_id)
            local traits = type(unit.traits) == "table" and unit.traits or {}
            local hasTrait = next(traits) ~= nil
            local rarity = type(metadata) == "table" and metadata.rarity or nil
            local level = tonumber(unit.level) or math.max(1, math.floor(1 + math.log((tonumber(unit.xp) or 0) / 1000 + 1) / math.log(1.08)))
            result[#result + 1] = {uuid = uuid, id = unit.unit_id,
                name = type(metadata) == "table" and metadata.name or unit.unit_id,
                rarity = rarity, level = level, shiny = unit.shiny == true, trait = hasTrait,
                -- Native collection treats only `_locked == true` as locked;
                -- an absent field is the canonical unlocked state.
                locked = unit._locked == true, lockKnown = true,
                equipped = unit.equipped_slot or equippedByUuid[uuid],
                metadataKnown = type(metadata) == "table"}
        end
    end
    table.sort(result, function(a, b) return a.uuid < b.uuid end)
    return result, "ready"
end

function Adapter:InventorySlots()
    local service = self:_NativeService("ChallengeServiceClient")
    local collection = service and service.session and service.session.collection
    local profile = collection and collection.collection_profile_data
    local equipped = type(profile) == "table" and profile.equipped_units
    if type(equipped) ~= "table" then return {}, "unavailable" end
    local result = {}
    for index = 1, 6 do
        local uuid = equipped[tostring(index)] or equipped[index]
        if type(uuid) == "string" and uuid ~= "" and #uuid <= 128 and not uuid:find("%c") then
            result[index] = uuid
        end
    end
    return result, "ready"
end

function Adapter:PortalInventory()
    local service = self:_NativeService("ChallengeServiceClient")
    local profile = service and service.session and service.session.profile_data
    local inventory = type(profile) == "table" and profile.inventory
    local unique = type(inventory) == "table" and inventory.unique_items
    if type(unique) ~= "table" then return {}, "unavailable" end
    local grouped, private = {}, {}
    for sourceUuid, item in pairs(unique) do
        if type(item) == "table" and identifier(item.item_id) then
            local metadata = self:ItemMetadata(item.item_id)
            local data = type(item._unique_item_data) == "table" and item._unique_item_data._unique_portal_data
            local portal = type(data) == "table" and identifier(data.level_id)
                and (type(metadata) == "table" and metadata.item_group == "Portals")
            if portal then
                local tier = tonumber(data.portal_depth)
                tier = tier and tier % 1 == 0 and tier >= 0 and tier <= 100 and tier or 0
                local map = identifier(data._override_map) and data._override_map or ""
                local key = item.item_id .. ":" .. data.level_id .. ":" .. tostring(tier) .. ":" .. map
                local row = grouped[key]
                if not row then
                    row = {key = key, id = item.item_id, levelId = data.level_id, tier = tier,
                        name = type(metadata.name) == "string" and metadata.name or item.item_id,
                        map = map ~= "" and map or nil, count = 0, automatic = true}
                    grouped[key] = row
                    private[key] = {}
                end
                row.count = row.count + 1
                local uuid = identifier(item.uuid) and item.uuid or identifier(sourceUuid) and sourceUuid
                if uuid then private[key][#private[key] + 1] = uuid end
            end
        end
    end
    local result = {}; for _, row in pairs(grouped) do result[#result + 1] = row end
    table.sort(result, function(a, b)
        if a.tier ~= b.tier then return a.tier > b.tier end
        return a.name < b.name or (a.name == b.name and a.levelId < b.levelId)
    end)
    for _, uuids in pairs(private) do table.sort(uuids) end
    self.portalUUIDs = private
    return result, "ready"
end

function Adapter:UsePortal(key, friendsOnly)
    if not self:InLobby() then return false, "not_lobby" end
    if not identifier(key) and (type(key) ~= "string" or #key > 520 or not key:match("^[%w_:%-]+$")) then
        return false, "invalid_portal"
    end
    self:PortalInventory()
    local choices = self.portalUUIDs and self.portalUUIDs[key]
    local uuid = type(choices) == "table" and choices[1]
    if not uuid then return false, "missing_portal" end
    local receipt = self:Endpoint("portal_lobby_owner_created", true)
    if not receipt or not receipt:IsA("RemoteEvent") then return false, "missing_receipt" end
    local confirmed = false
    local connection = receipt.OnClientEvent:Connect(function() confirmed = true end)
    local ok, detail
    if friendsOnly == true then ok, detail = self:Call("use_portal", uuid, {friends_only = true})
    else ok, detail = self:Call("use_portal", uuid) end
    local deadline = os.clock() + 8
    while ok and not confirmed and self.scope.alive and os.clock() < deadline do task.wait(0.05) end
    connection:Disconnect()
    if not confirmed then
        if not ok and (detail == "busy" or detail == "missing" or detail == "destroyed") then return false, detail end
        return false, "unconfirmed"
    end
    self.portalUUIDs = nil
    return true, "created"
end

function Adapter:CapsuleInventory()
    local service = self:_NativeService("ChallengeServiceClient")
    local profile = service and service.session and service.session.profile_data
    local inventory = type(profile) == "table" and profile.inventory
    local normal = type(inventory) == "table" and inventory.normal_items
    if type(normal) ~= "table" then return {}, "unavailable" end
    local result = {}
    for id, count in pairs(normal) do
        local metadata = identifier(id) and self:ItemMetadata(id)
        local usage = type(metadata) == "table" and metadata.usage
        count = tonumber(count)
        if type(usage) == "table" and usage.type == "capsule" and metadata.usage_from_inventory == true
            and count and count % 1 == 0 and count > 0 and count <= 1e9 then
            local rewards, seen = {}, {}
            local function add(kind, rewardId)
                if not identifier(rewardId) then return end
                local key = kind .. ":" .. rewardId
                if seen[key] then return end
                seen[key] = true
                local data = kind == "unit" and self:UnitMetadata(rewardId) or kind == "item" and self:ItemMetadata(rewardId)
                rewards[#rewards + 1] = type(data) == "table" and data.name or rewardId
            end
            for _, reward in ipairs(type(usage.guaranteed_rewards) == "table" and usage.guaranteed_rewards or {}) do
                if type(reward) == "table" then add("unit", reward.unit); add("item", reward.item); add("resource", reward._resource) end
            end
            for _, reward in ipairs(type(usage.possible_rewards) == "table" and usage.possible_rewards or {}) do
                if type(reward) == "table" then add("unit", reward.unit); add("item", reward.item); add("resource", reward._resource) end
            end
            table.sort(rewards)
            result[#result + 1] = {id = id, name = metadata.name or id, count = count, rewards = rewards,
                locked = type(usage._locked) == "string" and usage._locked ~= "", automatic = false,
                reason = type(usage._locked) == "string" and usage._locked ~= "" and "locked" or "receipt_required"}
        end
    end
    table.sort(result, function(a, b) return a.name < b.name or (a.name == b.name and a.id < b.id) end)
    return result, "ready"
end

function Adapter:PartyInvites()
    local gui = self:_NativeService("GUIService")
    local party = gui and gui.party_ui
    local source = type(party) == "table" and party.incoming_invites or gui and gui.party_invites_waiting
    local result, seen = {}, {}
    for player in pairs(type(source) == "table" and source or {}) do
        local ok, isPlayer = pcall(function() return player:IsA("Player") end)
        if ok and isPlayer and player.Parent and not seen[player.Name] and #result < 32 then
            seen[player.Name] = true
            result[#result + 1] = {name = player.Name, displayName = player.DisplayName,
                automatic = false, reason = "receipt_required"}
        end
    end
    table.sort(result, function(a, b) return a.name < b.name end)
    return result, type(source) == "table" and "ready" or "unavailable"
end

function Adapter:UseCapsule(id, quantity)
    quantity = tonumber(quantity)
    if not self:InLobby() or not identifier(id) or (quantity ~= 1 and quantity ~= 10) then
        return false, "invalid_capsule"
    end
    for _, capsule in ipairs(self:CapsuleInventory()) do
        if capsule.id == id and not capsule.locked and capsule.count >= quantity then
            return self:Call("use_item", id, {use10 = quantity == 10, use_all = false})
        end
    end
    return false, "missing_capsule"
end

function Adapter:RespondPartyInvite(name, accepted)
    if not self:InLobby() or type(name) ~= "string" or #name < 1 or #name > 20 or type(accepted) ~= "boolean" then
        return false, "invalid_invite"
    end
    local gui = self:_NativeService("GUIService")
    local party = gui and gui.party_ui
    local source = type(party) == "table" and party.incoming_invites or gui and gui.party_invites_waiting
    for player in pairs(type(source) == "table" and source or {}) do
        local ok, isPlayer = pcall(function() return player:IsA("Player") end)
        if ok and isPlayer and player.Parent and player.Name == name then
            return self:Call("party_respond_invite", player, accepted)
        end
    end
    return false, "missing_invite"
end

function Adapter:SmartStoryTarget(refresh)
    return self:SmartTarget("story", refresh)
end

function Adapter:LevelRequirements(levelId)
    local metadata = self:LevelMetadata(levelId)
    local record = metadata and self.levelData and self.levelData[levelId]
    local required = type(record) == "table" and type(record.requirements) == "table"
        and record.requirements.required_levels or {}
    local result = {}
    for _, id in ipairs(type(required) == "table" and required or {}) do
        if identifier(id) then result[#result + 1] = id end
    end
    return result
end

function Adapter:SmartTarget(mode, refresh)
    if mode ~= "story" and mode ~= "legend" and mode ~= "raids" and mode ~= "infinity" then
        return nil, "unsupported_mode"
    end
    local catalog = self:MapCatalog(refresh == true)
    local completed = self:StoryProgress()
    local unlocked = {}
    for _, world in ipairs(catalog[mode] or {}) do
        for _, level in ipairs(world.levels or {}) do
            local available = true
            for _, requirement in ipairs(self:LevelRequirements(level.value)) do
                if not completed[requirement] then available = false; break end
            end
            if available then
                local target = {mode = mode, worldId = world.value, levelId = level.value,
                    world = world.label, act = level.label, map = world.map,
                    why = completed[level.value] and "latest_unlocked" or "first_incomplete"}
                if mode ~= "infinity" and not completed[level.value] then return target end
                unlocked[#unlocked + 1] = target
            end
        end
    end
    if mode == "infinity" and #unlocked > 0 then return unlocked[#unlocked] end
    return nil, mode .. "_complete"
end

function Adapter:Banners()
    local names = {Summer2026 = "Summer Event", EventClover = "Special", Legacy = "Legacy"}
    local root = self:Gui("SummonGUI.BannerFrames")
    local result = {}
    for _, child in ipairs(root and root:GetChildren() or {}) do
        if child:IsA("ImageLabel") then
            result[#result + 1] = {value = child.Name, label = names[child.Name] or child.Name}
        end
    end
    table.sort(result, function(a, b) return a.value < b.value end)
    return result
end

function Adapter:ItemMetadata(id)
    if not self.itemData then
        local module = Util.find(self.storage, "src.Data.Items")
        local ok, records
        if module and nativeRequire then ok, records = pcall(nativeRequire, module) end
        if ok and type(records) == "table" then self.itemData = records end
    end
    return self.itemData and self.itemData[id]
end

function Adapter:SummonBanner(id)
    if not identifier(id) then return nil end
    local frame = self:Gui("SummonGUI.BannerFrames." .. id)
    if not frame or not frame:IsA("ImageLabel") then return nil end
    if not self.bannerData then
        local module = Util.find(self.storage, "src.Data.Banners")
        if not module or not nativeRequire then return nil end
        local ok, records = pcall(nativeRequire, module)
        if not ok or type(records) ~= "table" then return nil end
        self.bannerData = records
    end
    local banner = self.bannerData[id]
    if type(banner) ~= "table" or banner.active ~= true then return nil end
    local resource = banner.resource_cost
    local currency = resource and resource.id or "Gems"
    local cost = tonumber(resource and resource.amount or banner.gem_cost)
    if type(currency) ~= "string" or not cost or cost ~= cost or cost <= 0 or cost > 1000000 then return nil end
    local current, threshold
    if frame.Visible then
        local pity = self:Gui("SummonGUI.Main.TopBar.Pity")
        local count = pity and pity.Visible and text(pity:FindFirstChild("Time"))
        if count then
            current, threshold = count:match("^(%d+)%s*/%s*(%d+)$")
            current, threshold = tonumber(current), tonumber(threshold)
        end
    end
    local pool = {}
    for _, unit in ipairs(self:BannerPool(id)) do pool[unit.value] = true end
    if next(pool) == nil then pool = nil end
    local capsule = type(banner._MOCK_CAPSULE_BANNER) == "table" and banner._MOCK_CAPSULE_BANNER.item_id
    if not identifier(capsule) then capsule = nil end
    -- The current native Summer capsule x10 path reproducibly wedged two fresh
    -- clients before wallet/pity changed. Keep its displayed price for diagnostics,
    -- but publish the capability as unsafe so no SaintHub path invokes it.
    local batchSupported = not (id == "Summer2026" and capsule == "capsule_summer2")
    local batchCost = id == "Summer2026" and cost * 9 or cost * 10
    return {currency = currency, cost = cost, batchCost = batchCost, pity = current, threshold = threshold,
        pool = pool, capsule = capsule, batchSupported = batchSupported}
end

function Adapter:CapsulePity(id)
    if not identifier(id) then return nil end
    local service = self:_NativeService("ChallengeServiceClient")
    local profile = service and service.session and service.session.profile_data
    local records = type(profile) == "table" and profile.capsule_pity_data
    local record = type(records) == "table" and records[id]
    local total = type(record) == "table" and tonumber(record.total_opens)
    if not total or total ~= total or total < 0 or total % 1 ~= 0 then return nil end
    return total
end

function Adapter:BannerPool(id)
    if not identifier(id) then return {} end
    local frame = self:Gui("SummonGUI.BannerFrames." .. id)
    if not frame or not frame:IsA("ImageLabel") then return {} end
    if not self.bannerData then
        local module = Util.find(self.storage, "src.Data.Banners")
        local ok, records = false, nil
        if module and nativeRequire then ok, records = pcall(nativeRequire, module) end
        if ok and type(records) == "table" then self.bannerData = records end
    end
    local banner = self.bannerData and self.bannerData[id]
    if type(banner) ~= "table" or banner.active ~= true then return {} end
    local ids, order = {}, {}
    local rarityRank = {Secret = 1, Exclusive = 2, Mythic = 3, Legendary = 4, Epic = 5, Rare = 6, Common = 7}
    local function add(unitId, featured)
        if type(unitId) ~= "string" or ids[unitId] then return end
        local metadata = self:UnitMetadata(unitId)
        if type(metadata) ~= "table" or type(metadata.name) ~= "string" then return end
        ids[unitId] = true
        order[#order + 1] = {value = unitId,
            label = string.format("%s · %s%s", metadata.name,
                type(metadata.rarity) == "string" and metadata.rarity or "Unknown", featured and " · Featured" or ""),
            rarity = metadata.rarity, featured = featured == true}
    end
    local capsule = banner._MOCK_CAPSULE_BANNER
    if type(capsule) == "table" and type(capsule.item_id) == "string" then
        local item = self:ItemMetadata(capsule.item_id)
        local rewards = item and item.usage and item.usage.possible_rewards
        for _, reward in ipairs(type(rewards) == "table" and rewards or {}) do add(type(reward) == "table" and reward.unit) end
    else
        local rateups = type(banner.rateup_units) == "table" and banner.rateup_units or {}
        local slots = type(banner.rateup_config_show_order) == "table" and banner.rateup_config_show_order or {}
        local summon = self:_NativeService("SummonServiceClient")
        local current = type(summon) == "table" and type(summon.BANNER_UNITS) == "table" and summon.BANNER_UNITS[id]
        local currentRateups = type(current) == "table" and type(current.rateup_units) == "table" and current.rateup_units or {}
        local source = type(summon) == "table" and (id == "Legacy" and summon.LEGACY_UNITS_BY_RARITY
            or summon.RATEUP_UNITS_BY_RARITY)
        for _, slot in ipairs(slots) do add(currentRateups[slot], true) end
        for rarity, units in pairs(type(source) == "table" and source or {}) do
            if type(rarity) == "string" and type(units) == "table" then
                for key, value in pairs(units) do
                    if type(value) == "string" then add(value, false)
                    elseif type(key) == "string" then add(key, false) end
                end
            end
        end
        -- Fallback for a service that has not received get_hatch_setup_data yet.
        local main = frame:FindFirstChild("Main")
        self:UnitMetadata("")
        for _, slot in ipairs(slots) do
            local row = type(slot) == "string" and main and main:FindFirstChild("Featured_" .. slot)
            local label = row and row:FindFirstChild("name")
            local displayed = label and text(label)
            local expected = type(rateups[slot]) == "table" and rateups[slot].rarity
            if displayed then
                for unitId, metadata in pairs(self.unitData or {}) do
                    if type(unitId) == "string" and type(metadata) == "table" and metadata.name == displayed
                        and (type(expected) ~= "string" or metadata.rarity == expected) then add(unitId, true) end
                end
            end
        end
    end
    table.sort(order, function(a, b)
        if a.featured ~= b.featured then return a.featured end
        local ar, br = rarityRank[a.rarity] or 99, rarityRank[b.rarity] or 99
        if ar ~= br then return ar < br end
        return a.label < b.label
    end)
    for _, item in ipairs(order) do item.rarity, item.featured = nil, nil end
    return order
end

function Adapter:BannerRewards(id)
    if not identifier(id) then return {} end
    local frame = self:Gui("SummonGUI.BannerFrames." .. id)
    if not frame or not frame:IsA("ImageLabel") then return {} end
    if not self.bannerData then self:SummonBanner(id) end
    local banner = self.bannerData and self.bannerData[id]
    if type(banner) ~= "table" or banner.active ~= true then return {} end
    local found = {}
    local function add(kind, rewardId, reward, guaranteed)
        if (kind ~= "unit" and kind ~= "item" and kind ~= "resource") or not identifier(rewardId) then return end
        local key = kind .. ":" .. rewardId
        local row = found[key]
        local metadata = kind == "unit" and self:UnitMetadata(rewardId)
            or kind == "item" and self:ItemMetadata(rewardId) or nil
        if not row then
            row = {kind = kind, id = rewardId, name = type(metadata) == "table" and metadata.name or rewardId,
                rarity = type(metadata) == "table" and metadata.rarity or nil, guaranteed = guaranteed == true}
            found[key] = row
        elseif guaranteed then row.guaranteed = true end
        local count = type(reward) == "table" and tonumber(reward.amount or reward.quantity)
        local minimum = type(reward) == "table" and tonumber(reward.min_amount)
        local maximum = type(reward) == "table" and tonumber(reward.max_amount)
        if not count and (kind == "unit" or kind == "item") and not minimum and not maximum then count = 1 end
        if count and count == count and count > 0 then row.amount = math.max(tonumber(row.amount) or 0, count) end
        if minimum and minimum == minimum and minimum > 0 then row.minAmount = minimum end
        if maximum and maximum == maximum and maximum > 0 then row.maxAmount = maximum end
        local chance = type(reward) == "table" and tonumber(reward.chance or reward.rate)
        if chance and chance == chance and chance > 0 then row.chance = chance end
    end
    local capsule = type(banner._MOCK_CAPSULE_BANNER) == "table" and banner._MOCK_CAPSULE_BANNER.item_id
    local metadata = identifier(capsule) and self:ItemMetadata(capsule)
    local usage = type(metadata) == "table" and metadata.usage
    local function scan(rewards, guaranteed)
        for _, reward in ipairs(type(rewards) == "table" and rewards or {}) do
            if type(reward) == "table" then
                add("unit", reward.unit or reward.unit_id, reward, guaranteed)
                add("item", reward.item or reward.item_id, reward, guaranteed)
                add("resource", reward._resource or reward.resource, reward, guaranteed)
            end
        end
    end
    if type(usage) == "table" then
        scan(usage.guaranteed_rewards, true)
        scan(usage.possible_rewards, false)
    else
        for _, unit in ipairs(self:BannerPool(id)) do
            add("unit", unit.value, nil, false)
            local row = found["unit:" .. unit.value]
            if row then row.featured = unit.featured == true end
        end
    end
    local result = {}; for _, row in pairs(found) do result[#result + 1] = row end
    local rank = {resource = 1, item = 2, unit = 3}
    local rarity = {Secret = 1, Exclusive = 2, Mythic = 3, Legendary = 4, Epic = 5, Rare = 6, Common = 7}
    table.sort(result, function(a, b)
        if a.guaranteed ~= b.guaranteed then return a.guaranteed end
        if rank[a.kind] ~= rank[b.kind] then return rank[a.kind] < rank[b.kind] end
        if (rarity[a.rarity] or 99) ~= (rarity[b.rarity] or 99) then
            return (rarity[a.rarity] or 99) < (rarity[b.rarity] or 99)
        end
        return a.name < b.name or (a.name == b.name and a.id < b.id)
    end)
    return result
end

local function shopWhole(value, minimum, maximum)
    return type(value) == "number" and value == value and value % 1 == 0 and value >= minimum and value <= maximum
end

local function itemPolicy(metadata, itemId)
    if type(metadata) ~= "table" then return nil end
    if metadata.item_group == "XP Food" then return "food" end
    if metadata.item_group == "Stars" then return "stars" end
    -- Current Star Fruits are grouped under the broad native "Materials"
    -- category. Match the exact item family instead of buying every material.
    local id, name = itemId or metadata.id, metadata.name
    if metadata.item_group == "Materials" and
        ((type(id) == "string" and id:match("^StarFruit[%w_%-]*$"))
            or (type(name) == "string" and name:match("^Star Fruit[%s%(]"))) then return "stars" end
end

function Adapter:GoldShopOffers()
    if not self:InLobby() then return {}, nil, "not_lobby" end
    local service = self:_NativeService("GoldShopServiceClient")
    local source = service and service.shop_items_for_sale
    local interval = service and tonumber(service.gold_shop_interval)
    local profile = service and service.session and service.session.profile_data
    local bought = type(profile) == "table" and type(profile.gold_shop_data) == "table"
        and profile.gold_shop_data.bought_items or {}
    if type(source) ~= "table" or not shopWhole(interval, -1000000000, 1000000000) then return {}, nil, "unavailable" end
    local result = {}
    for key, row in pairs(source) do
        if identifier(key) and type(row) == "table" and row.id == key and type(row.category) == "string"
            and shopWhole(row.gold_cost, 1, 1000000000) and shopWhole(row.stock, 0, 1000000) then
            local purchased = type(bought) == "table" and tonumber(bought[key]) or 0
            purchased = shopWhole(purchased, 0, 1000000) and purchased or 0
            local metadata = self:ItemMetadata(key)
            local lock = self:Gui("GoldShop.Window.Items.ItemFrames." .. key .. ".Locked")
            result[#result + 1] = {key = key, id = key, name = type(metadata) == "table" and metadata.name or key,
                rarity = type(metadata) == "table" and metadata.rarity or nil, category = row.category, policy = itemPolicy(metadata, key),
                currency = "Gold", price = row.gold_cost, stock = row.stock,
                available = math.max(0, row.stock - purchased), interval = interval,
                locked = lock and lock:IsA("GuiObject") and lock.Visible == true or false}
        end
    end
    table.sort(result, function(a, b) return a.id < b.id end)
    return result, interval, "ready"
end

function Adapter:MerchantOffers()
    if not self:InLobby() then return {}, nil, "not_lobby" end
    local service = self:_NativeService("TravellingMerchantServiceClient")
    if not service or service.opened ~= true or type(service.SELLING_ITEMS) ~= "table" then return {}, nil, "closed" end
    local profile = service.session and service.session.profile_data
    local bought = type(profile) == "table" and profile.bought_items or {}
    local result = {}
    for key, row in pairs(service.SELLING_ITEMS) do
        if identifier(key) and type(row) == "table" and identifier(row.id) and not (type(bought) == "table" and bought[key]) then
            local currency, price
            if shopWhole(row.gem_cost, 1, 1000000000) then currency, price = "Gems", row.gem_cost
            elseif shopWhole(row.gold_cost, 1, 1000000000) then currency, price = "Gold", row.gold_cost end
            if currency then
                local metadata = self:ItemMetadata(row.id)
                local policy = itemPolicy(metadata, row.id)
                if row.id == "summon_ticket" then policy = "tickets" end
                result[#result + 1] = {key = key, id = row.id,
                    name = type(metadata) == "table" and metadata.name or row.id,
                    rarity = type(metadata) == "table" and metadata.rarity or nil,
                    policy = policy, currency = currency,
                    price = price, stock = 1, available = 1}
            end
        end
    end
    table.sort(result, function(a, b) return a.key < b.key end)
    return result, service.SELLING_ITEMS, "ready"
end

function Adapter:BuyMerchantOffer(key)
    if not self:InLobby() or not identifier(key) then return false, "invalid_offer" end
    local offers = self:MerchantOffers()
    for _, offer in ipairs(offers) do
        if offer.key == key then return self:Call("buy_travelling_merchant_item", key, "1") end
    end
    return false, "missing_offer"
end

function Adapter:BuyGoldOffer(id, quantity)
    quantity = tostring(quantity)
    if not self:InLobby() or not identifier(id) or (quantity ~= "1" and quantity ~= "10" and quantity ~= "100") then
        return false, "invalid_offer"
    end
    local offers = self:GoldShopOffers()
    for _, offer in ipairs(offers) do
        if offer.id == id and not offer.locked and offer.available >= tonumber(quantity) then
            return self:Call("buy_gold_shop_item", id, quantity)
        end
    end
    return false, "missing_offer"
end

function Adapter:EnterGoldShop()
    if not self:InLobby() or not self.scope.alive then return nil, "not_lobby" end
    local character = self.player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local area = Util.find(workspace, "_goldshop.area")
    if not character or not root or not area or not area:IsA("BasePart") then return nil, "missing_gold_shop" end
    local original = character:GetPivot()
    character:PivotTo(CFrame.new(area.Position))
    local deadline = os.clock() + 4
    local opened = false
    repeat
        local service = self:_NativeService("GUIService")
        opened = service and service.gold_shop_ui and service.gold_shop_ui.IsOpen == true
        if opened or os.clock() >= deadline or not self.scope.alive or character.Parent == nil then break end
        task.wait(0.05)
    until false
    if not opened then
        if character.Parent and (root.Position - area.Position).Magnitude <= 30 then character:PivotTo(original) end
        return nil, "gold_shop_unavailable"
    end
    local restored = false
    return function()
        if restored then return false end
        restored = true
        if character.Parent and root.Parent and (root.Position - area.Position).Magnitude <= 30 then
            character:PivotTo(original)
            return true
        end
        return false -- Player moved independently; never overwrite that move.
    end, "ready"
end

local function unitName(frame)
    local label = text(frame:FindFirstChild("name"))
    if label ~= "" then return label end
    local view = Util.find(frame, "Main.View.WorldModel")
    local model = view and view:FindFirstChildOfClass("Model")
    return model and not tonumber(model.Name) and model.Name or ""
end

local function parseCost(text)
    text = tostring(text):gsub(",", ""):gsub("%s", "")
    local number, suffix = text:match("(%d+%.?%d*)([kKmM]?)")
    local value = (tonumber(number) or 0) * ((suffix == "k" or suffix == "K") and 1000 or ((suffix == "m" or suffix == "M") and 1000000 or 1))
    return Util.number(value, 0, 0, math.huge)
end
Adapter.parseCost = parseCost

local function frameUUID(frame)
    local uuid = frame:FindFirstChild("_uuid")
    if uuid and uuid:IsA("StringValue") then return uuid.Value end
    local pointer = frame:FindFirstChild("unit")
    if pointer and pointer:IsA("ObjectValue") and pointer.Value then
        uuid = pointer.Value:FindFirstChild("_uuid")
        if uuid and uuid:IsA("StringValue") then return uuid.Value end
    end
    -- Current hotbar frames keep the equipped collection UUID as an
    -- attribute even when their legacy `unit` ObjectValue is nil.
    local ok, attribute = pcall(frame.GetAttribute, frame, "_equipped_frame_unit_uuid")
    if ok and type(attribute) == "string" and attribute ~= "" and #attribute <= 128 then return attribute end
    return ""
end

local function hasUniqueTrait(frame)
    local traits = frame:FindFirstChild("TraitIcons", true)
    local unique = traits and traits:FindFirstChild("unique")
    return unique ~= nil and unique:IsA("ImageLabel")
end

function Adapter:Hotbar()
    local root = self:Gui("spawn_units.Lives.Frame.Units")
    local slots = {}
    for _, frame in ipairs(root and root:GetChildren() or {}) do
        local index = tonumber(frame.Name)
        if index and index >= 1 and index <= 6 and frame:IsA("GuiObject") then
            local cost = Util.find(frame, "Cost.text")
            slots[index] = {name = unitName(frame), uuid = frameUUID(frame), cost = cost and parseCost(cost.Text) or 0,
                unique = hasUniqueTrait(frame), viewport = Util.find(frame, "Main.View")}
        end
    end
    return slots
end

-- The current client no longer replicates `_stats.upgrade_cost`, but keeps an
-- always-current UnitOverview card keyed by the placed unit UUID. Reading that
-- card prevents unaffordable upgrade requests (and their error-message spam)
-- without opening or clicking the upgrade window.
function Adapter:UpgradeCost(unit)
    local owned, reason = self:_ValidateOwnedUnit(unit)
    if not owned then return nil, reason end
    local stats = owned:FindFirstChild("_stats")
    local uuid = stats and stats:FindFirstChild("uuid")
    uuid = uuid and uuid:IsA("StringValue") and uuid.Value or nil
    if type(uuid) ~= "string" or uuid == "" then return nil, "missing_uuid" end
    local list = self:Gui("UnitOverview.OuterOuter.Outer.ScrollingFrame")
    local card = list and list:FindFirstChild(uuid)
    local label = card and Util.find(card, "Outer.buttons.Upgrade.Main.Text")
    if not label or not (label:IsA("TextLabel") or label:IsA("TextButton")) then return nil, "missing_cost" end
    local raw = text(label)
    local price = parseCost(raw)
    if price <= 0 or not raw:match("%d") then return nil, "missing_cost" end
    return price, "ready"
end

function Adapter:Equipped()
    local root = self:Gui("collection.grid.List.Outer.UnitFrames")
    local hotbar, slots, blocked, seen, ambiguous = self:Hotbar(), {}, {}, {}, false
    for _, frame in ipairs(root and root:GetChildren() or {}) do
        if frame:IsA("ImageButton") then
            local equipped = Util.find(frame, "EquippedList.Equipped")
            local uuid = frame:FindFirstChild("_uuid")
            local index = frame.LayoutOrder
            if equipped and equipped.Visible and uuid and uuid:IsA("StringValue") and uuid.Value ~= "" and index >= 1 and index <= 6 and index % 1 == 0 then
                if blocked[index] or slots[index] or seen[uuid.Value] then
                    ambiguous = true
                    slots[index], blocked[index] = nil, true
                    local previous = seen[uuid.Value]
                    if previous then slots[previous], blocked[previous] = nil, true end
                else
                    local name = unitName(frame)
                    local current = hotbar[index]
                    if current and current.uuid ~= uuid.Value then current = nil end
                    slots[index] = {uuid = uuid.Value, name = name ~= "" and name or (current and current.name or ""),
                        cost = current and current.cost or 0, unique = hasUniqueTrait(frame) or (current and current.unique) == true}
                    seen[uuid.Value] = index
                end
            end
        end
    end
    return slots, ambiguous and "ambiguous" or (next(slots) and "ready" or "empty")
end

function Adapter:RefreshEquipped()
    if self.refreshing then return {}, "busy" end
    local slots, status = self:Equipped()
    if next(slots) or status == "ambiguous" then return slots, status end
    -- The old game populates this UI on opening collection. Never blindly toggle twice.
    local collection = self:Gui("collection")
    local wasVisible = collection and ((collection:IsA("ScreenGui") and collection.Enabled) or (collection:IsA("GuiObject") and collection.Visible))
    if not collection or wasVisible then return slots, status end
    self.refreshing = true
    local input
    local function toggle()
        input = input or game:GetService("VirtualInputManager")
        input:SendKeyEvent(true, Enum.KeyCode.K, false, game)
        input:SendKeyEvent(false, Enum.KeyCode.K, false, game)
    end
    local function visible()
        return (collection:IsA("ScreenGui") and collection.Enabled) or (collection:IsA("GuiObject") and collection.Visible)
    end
    local ok = pcall(function()
        if game:GetService("UserInputService"):GetFocusedTextBox() then status = "input_focused"; return end
        toggle()
        local deadline = os.clock() + 1.2
        repeat
            task.wait(0.1)
            if not self.scope.alive then status = "destroyed"; break end
            slots, status = self:Equipped()
        until next(slots) or status == "ambiguous" or os.clock() >= deadline
    end)
    if visible() then pcall(toggle) end
    self.refreshing = false
    return slots, ok and status or "input_unavailable"
end

function Adapter:LoadUnitsIds(open)
    local slots, status
    if open then slots, status = self:RefreshEquipped() else slots, status = self:Equipped() end
    self.unitsIds = {}
    for index, unit in pairs(slots) do self.unitsIds[index] = unit.uuid end
    self.UnitsIds = self.unitsIds
    return slots, status
end

function Adapter:JoinLobby(lobby)
    if not self:InLobby() then return false, "not_lobby" end
    if not identifier(lobby) then return false, "invalid_lobby" end
    local success, detail = self:Call("request_join_lobby", lobby)
    if success then return true, detail end
    -- Event rooms can return false after already adding the player and starting
    -- their countdown. Trust only the exact replicated room/player membership,
    -- never the existence of a room or a running timer by itself.
    local deadline = os.clock() + 2
    repeat
        if self:LobbyMembership(lobby) then return true, "joined_receipt" end
        if not self.scope.alive then return false, "destroyed" end
        task.wait(0.05)
    until os.clock() >= deadline
    return false, detail
end

function Adapter:LockLevel(lobby, level, difficulty, friendsOnly)
    if not self:InLobby() then return false, "not_lobby" end
    if not identifier(lobby) or not identifier(level) or (difficulty ~= "Normal" and difficulty ~= "Hard")
        or (friendsOnly ~= nil and type(friendsOnly) ~= "boolean") then return false, "invalid_level" end
    return self:Call("request_lock_level", lobby, level, friendsOnly == true, difficulty)
end

function Adapter:StartLobby(lobby)
    if not self:InLobby() then return false, "not_lobby" end
    if not identifier(lobby) then return false, "invalid_lobby" end
    return self:Call("request_start_game", lobby)
end

function Adapter:StartEvent(preferred)
    if not self:InLobby() then return false, "not_lobby" end
    local id, status = self:ResolveEventId(preferred)
    if not id then return false, status end
    return self:Call("request_matchmaking", id)
end

local challengeKinds = {
    daily = {endpoint = "get_daily_challenge", completed = "last_completed_daily_challenge_uuid",
        folder = "DailyChallenge", queue = "__DAILY_CHALLENGE", levelField = "current_level"},
    normal = {endpoint = "get_normal_challenge", completed = "last_completed_challenge_uuid",
        folder = "Challenges", queue = "__NORMAL_CHALLENGE", levelField = "current_level_id"},
}

function Adapter:CurrentChallenge(kind)
    local spec = challengeKinds[kind]
    if not spec or not self:InLobby() or not nativeRequire then return end
    if not self.challengeService then
        local loaderModule = Util.find(self.storage, "src.Loader")
        if not loaderModule then return end
        local ok, service = pcall(function()
            return nativeRequire(loaderModule).load_client_service(loaderModule, "ChallengeServiceClient")
        end)
        if ok and type(service) == "table" then self.challengeService = service end
    end
    local session = self.challengeService and self.challengeService.session
    local profile = session and session.profile_data
    if type(profile) ~= "table" then return end
    local ok, data = self:Call(spec.endpoint)
    if not ok or type(data) ~= "table" then return end
    local id, uuid, modifier = data[spec.levelField], data.current_uuid, data.current_challenge
    if type(id) == "table" then id = id.id end
    if not identifier(id) or not identifier(modifier) or (type(uuid) ~= "number" and not identifier(uuid))
        or tostring(uuid) == tostring(profile[spec.completed]) then return end
    return {kind = kind, levelId = id, uuid = uuid, modifier = modifier}
end

function Adapter:StartChallenge(challenge, playMode)
    local spec = challengeKinds[challenge.kind]
    if not spec or not self:InLobby() then return false, "missing_challenge" end
    if self:Value("AlreadyInLobby", false) then return false, "already_in_lobby" end
    if playMode == "matchmaking" then return self:Call("request_matchmaking", spec.queue) end

    local root = Util.find(workspace, "_CHALLENGES." .. spec.folder)
    for _, lobby in ipairs(root and root:GetChildren() or {}) do
        local level, modifier = lobby:FindFirstChild("Level"), lobby:FindFirstChild("Challenge")
        local owner, active = lobby:FindFirstChild("Owner"), lobby:FindFirstChild("Active")
        local locked, teleporting = lobby:FindFirstChild("Locked"), lobby:FindFirstChild("Teleporting")
        if level and level.Value == challenge.levelId and modifier and modifier.Value == challenge.modifier
            and owner and owner.Value == nil and active and not active.Value
            and locked and not locked.Value and teleporting and not teleporting.Value then
            -- Challenge lobbies already have a level and start on their lobby timer.
            return self:JoinLobby(lobby.Name)
        end
    end
    return false, "missing_challenge_lobby"
end

function Adapter:BuyBanner(banner, payment, owner)
    if not self:InLobby() then return false, "not_lobby" end
    if self.autoSummonOwner and self.autoSummonOwner ~= owner then return false, "busy" end
    if payment ~= "gems" and payment ~= "gems10" then return false, "invalid_payment" end
    local found = false
    for _, item in ipairs(self:Banners()) do if item.value == banner then found = true; break end end
    if not found then return false, "missing_banner" end
    if payment == "gems10" then
        local info = self:SummonBanner(banner)
        if info and info.batchSupported == false then return false, "unsafe_batch" end
    end
    return self:Call("buy_from_banner", banner, payment)
end

function Adapter:RedeemCode(code, owner)
    if not self:InLobby() then return false, "not_lobby" end
    if type(code) ~= "string" then return false, "invalid_code" end
    code = Util.trim(code)
    if code == "" or #code > 128 then return false, "invalid_code" end
    local ok, response, state, confirmed = CodeRedemption.run(self, code, owner)
    if self.scope.alive then self.Redeemed:Fire(code, state, confirmed) end
    return ok, response
end

function Adapter:SpawnUnitId(uuid, position)
    if self:InLobby() then return false, "lobby" end
    if type(uuid) ~= "string" or uuid == "" or #uuid > 128 then return false, "missing_unit" end
    local kind = typeof(position)
    if kind ~= "Vector3" and kind ~= "CFrame" then return false, "invalid_position" end
    return self:Call("spawn_unit", uuid, kind == "Vector3" and CFrame.new(position) or position)
end

function Adapter:SpawnUnitIndex(index, position)
    if self:InLobby() then return false, "lobby" end
    if type(index) ~= "number" or index % 1 ~= 0 or index < 1 or index > 6 then return false, "missing_unit" end
    local uuid = self.unitsIds and self.unitsIds[index]
    if not uuid then return false, "missing_unit" end
    return self:SpawnUnitId(uuid, position)
end

function Adapter:OwnedUnits()
    local result = {}
    local root = workspace:FindFirstChild("_UNITS")
    for _, unit in ipairs(root and root:GetChildren() or {}) do
        local stats = unit:FindFirstChild("_stats")
        local owner = stats and stats:FindFirstChild("player")
        if owner and owner:IsA("ObjectValue") and owner.Value == self.player then
            local function value(name)
                local object = stats:FindFirstChild(name)
                return object and object:IsA("ValueBase") and object.Value or nil
            end
            result[#result + 1] = {unit = unit, uuid = tostring(value("uuid") or ""), id = tostring(value("id") or unit.Name),
                upgrade = tonumber(value("upgrade")) or 0, maxUpgrade = tonumber(value("max_upgrade")) or 0,
                totalSpent = tonumber(value("total_spent")) or 0}
        end
    end
    return result
end

function Adapter:_ValidateOwnedUnit(unit)
    if self:InLobby() then return nil, "lobby" end
    if typeof(unit) ~= "Instance" or not unit:IsA("Model") then return nil, "invalid_unit" end
    local root = workspace:FindFirstChild("_UNITS")
    local stats = root and unit.Parent == root and unit:FindFirstChild("_stats")
    local owner = stats and stats:FindFirstChild("player")
    if not owner or not owner:IsA("ObjectValue") or owner.Value ~= self.player then return nil, "not_owned" end
    return unit
end

function Adapter:UpgradeUnit(unit)
    local owned, reason = self:_ValidateOwnedUnit(unit)
    if not owned then return false, reason end
    return self:Call("upgrade_unit_ingame", owned)
end

function Adapter:SellUnit(unit)
    local owned, reason = self:_ValidateOwnedUnit(unit)
    if not owned then return false, reason end
    return self:Call("sell_unit_ingame", owned)
end

function Adapter:EventChallenges()
    if not self:InLobby() then return {} end
    local service = self:_NativeService("ChallengeServiceClient")
    local source = service and service._CURRENT_EVENT_CHALLENGES
    local result = {}
    for key, row in pairs(type(source) == "table" and source or {}) do
        local level = type(row) == "table" and row.current_level_data
        local id = type(level) == "table" and level.id or key
        if identifier(id) and type(level) == "table" then
            result[#result + 1] = {levelId = id, name = type(level.name) == "string" and level.name or id,
                map = identifier(level.map) and level.map or nil,
                modifier = type(row.current_challenge) == "string" and row.current_challenge or "",
                weather = type(row.current_weather) == "string" and row.current_weather or "",
                seed = tonumber(row.current_lane_seed), automatic = false, reason = "missing_completion_receipt"}
        end
    end
    table.sort(result, function(a, b) return a.levelId < b.levelId end)
    return result
end

function Adapter:ChangePriority(unit, priority)
    local allowed = {first = true, last = true, strongest = true, weakest = true, air = true}
    local owned, reason = self:_ValidateOwnedUnit(unit)
    if not owned then return false, reason end
    if not allowed[priority] then return false, "invalid_priority" end
    return self:Call("change_priority", owned, priority)
end

function Adapter:SetAutoAbility(unit, enabled)
    if type(enabled) ~= "boolean" then return false, "invalid_auto_ability" end
    local owned, reason = self:_ValidateOwnedUnit(unit)
    if not owned then return false, reason end
    if enabled then
        local stats = owned:FindFirstChild("_stats")
        local active = stats and stats:FindFirstChild("active_attack")
        if not active or type(active.Value) ~= "string" or active.Value == "" or active.Value == "nil" then
            return false, "missing_ability"
        end
    end
    local ui = self.unitUpgradeUI
    if not ui or type(ui.auto_active_table) ~= "table" then
        local loader = Util.find(self.storage, "src.Loader")
        if loader and nativeRequire then
            local ok, service = pcall(function() return nativeRequire(loader).load_client_service(loader, "GUIService") end)
            if ok and type(service) == "table" then ui = service.unit_upgrade_ui end
        end
        self.unitUpgradeUI = ui
    end
    if type(ui) ~= "table" or type(ui.auto_active_table) ~= "table" then return false, "missing_auto_ability" end
    owned, reason = self:_ValidateOwnedUnit(unit) -- module lookup may yield
    if not owned then return false, reason end
    -- Native Auto button state, NOT SaintHub's per-slot autoplace configuration.
    -- The game's existing loop services this table and removes dead units.
    if enabled then
        ui.auto_active_table[owned] = ui.auto_active_table[owned] or {_last_request = -999}
    else ui.auto_active_table[owned] = nil end
    owned:SetAttribute("_auto_active", enabled)
    return owned:GetAttribute("_auto_active") == enabled, "ready"
end

function Adapter:ClaimableRewards()
    if not self:InLobby() then return {quests = {}, battlepass = 0, daily = false, code = "not_lobby"} end
    local result = {quests = {}, battlepass = 0, daily = false, code = "ready"}
    local root = self:Gui("QuestsUI.Main.Main.Main.Content")
    for _, category in ipairs(root and root:GetChildren() or {}) do
        local scroll = category:FindFirstChild("Scroll")
        for _, quest in ipairs(scroll and scroll:GetChildren() or {}) do
            local claim = quest:FindFirstChild("ClaimQuest")
            if claim and claim:IsA("GuiObject") and claim.Visible and identifier(quest.Name) and #result.quests < 128 then
                result.quests[#result.quests + 1] = quest.Name
            end
        end
    end
    table.sort(result.quests)
    local pages = self:Gui("BattlePass.Main.Main.Rewards.Frame.Pages")
    for _, tier in ipairs(pages and pages:GetChildren() or {}) do
        local frame = tier:FindFirstChild("Frame")
        for _, name in ipairs({"Normal", "Premium"}) do
            local reward = frame and frame:FindFirstChild(name)
            local marker = reward and reward:FindFirstChild("Claimable")
            if marker and marker:IsA("GuiObject") and marker.Visible then result.battlepass = result.battlepass + 1 end
        end
    end
    local screen = self:Gui("DailyRewards")
    local claim = screen and screen:FindFirstChild("Claim", true)
    result.daily = screen ~= nil and screen.Enabled == true and claim ~= nil
        and claim:IsA("GuiObject") and claim.Visible == true
    result.account = {}
    local playerGui = self.player:FindFirstChildOfClass("PlayerGui")
    local families = {
        player_level = {"playerlevel", "levelreward"}, tournament = {"tournament"},
        first_clear = {"firstclear"}, bracket = {"bracket"},
    }
    local function normalized(value) return tostring(value or ""):lower():gsub("[^%w]", "") end
    for family, tokens in pairs(families) do
        local found, claimable = false, false
        for _, object in ipairs(playerGui and playerGui:GetDescendants() or {}) do
            local name = normalized(object.Name)
            local matched = false
            for _, token in ipairs(tokens) do if name:find(token, 1, true) then matched = true; break end end
            if matched then
                found = true
                for _, marker in ipairs(object:GetDescendants()) do
                    if marker:IsA("GuiObject") and marker.Visible then
                        local label = (marker:IsA("TextLabel") or marker:IsA("TextButton")) and normalized(marker.Text) or ""
                        if normalized(marker.Name) == "claimable" or label == "claim" then claimable = true; break end
                    end
                end
            end
            if claimable then break end
        end
        result.account[family] = claimable and "claimable" or found and "unverified" or "unavailable"
    end
    if not root and not pages and not screen then result.code = "missing_ui" end
    return result
end

function Adapter:ClaimQuests()
    if not self:InLobby() then return 0, 0, "not_lobby" end
    local snapshot = self:ClaimableRewards()
    self.questClaimAttempts = self.questClaimAttempts or {}
    local accepted, attempted, now = 0, 0, os.clock()
    for _, questId in ipairs(snapshot.quests) do
        local last = self.questClaimAttempts[questId] or -math.huge
        if now - last >= 600 then
            self.questClaimAttempts[questId] = now
            attempted = attempted + 1
            local ok = self:Call("redeem_quest", questId)
            if ok then accepted = accepted + 1 end
            task.wait(0.45)
        end
        if not self.scope.alive then return accepted, attempted, "destroyed" end
    end
    return accepted, attempted, attempted > 0 and "attempted" or snapshot.code == "missing_ui" and "missing_ui" or "not_ready"
end

function Adapter:ClaimBattlepassRewards()
    if not self:InLobby() then return false, "not_lobby" end
    local snapshot = self:ClaimableRewards()
    if snapshot.battlepass == 0 then return false, snapshot.code == "missing_ui" and "missing_ui" or "not_ready" end
    return self:Call("claim_battlepass_rewards")
end

function Adapter:ClaimDailyReward()
    if not self:InLobby() then return false, "not_lobby" end
    local snapshot = self:ClaimableRewards()
    if not snapshot.daily then return false, snapshot.code == "missing_ui" and "missing_ui" or "not_ready" end
    if os.clock() < (self.dailyClaimRetryAt or 0) then return false, "pending" end
    self.dailyClaimRetryAt = os.clock() + 300
    return self:Call("claim_daily_reward")
end

function Adapter:InfinityCastleFloor()
    local value = self:Gui("InfiniteTowerUI.InfiniteLeaderboard.Ranking.Wrapper.Frame.FurthestRoom.V")
    local floor = value and tonumber(value.Text)
    return floor and floor % 1 == 0 and floor >= 1 and floor <= 10000 and floor or 1
end

function Adapter:StartInfinityCastle(floor, difficulty)
    if not self:InLobby() then return false, "not_lobby" end
    floor = tonumber(floor)
    if not floor or floor == 0 then floor = self:InfinityCastleFloor() end
    if floor % 1 ~= 0 or floor < 1 or floor > 10000 then return false, "invalid_floor" end
    if difficulty ~= "Normal" and difficulty ~= "Hard" then return false, "invalid_difficulty" end
    return self:Call("request_start_infinite_tower", floor, difficulty)
end

function Adapter:DungeonStep(options)
    options = type(options) == "table" and options or {}
    local screen = self:Gui("DungeonUI")
    local outer = self:Gui("DungeonUI.Main.Main.Outer")
    local start, holder = outer and outer:FindFirstChild("StartHolder"), outer and outer:FindFirstChild("MainHolder")
    local states = holder and holder:FindFirstChild("Outer")
    if not screen or not outer or not states then return false, "missing_ui" end
    local action, argument
    local function visible(name)
        local object = states:FindFirstChild(name)
        return object and object:IsA("GuiObject") and object.Visible
    end
    if start and start:IsA("GuiObject") and start.Visible then
        action = "dungeon_start"
    elseif visible("YouDied") then
        action = "dungeon_continue_death"
    elseif visible("ShrineRoom") then
        action = options.shrine == true and "dungeon_shrine_accept" or "dungeon_continue_shop"
    elseif visible("ShopSelection") then
        action = "dungeon_continue_shop"
    elseif visible("OpenTreasure") then
        if options.chest ~= "none" and not self.dungeonChestOpened then
            self.dungeonChestOpened = true
            action, argument = "dungeon_open_chest", options.chest == "rare" and true or nil
        else
            action = "dungeon_continue_shop"
        end
    elseif visible("LevelSelection") then
        self.dungeonChestOpened = false
        local preferred = math.floor(Util.number(options.room_choice, 1, 1, 3))
        local selection = states:FindFirstChild("LevelSelection")
        local inset = selection and selection:FindFirstChild("Inset")
        local row = inset and inset:FindFirstChild("MainRow")
        local choices = {}
        for _, frame in ipairs(row and row:GetChildren() or {}) do
            local main = frame:FindFirstChild("Main")
            if frame:IsA("GuiObject") and frame.Name ~= "Configuration" and main and main:FindFirstChild("Unavailable") then
                choices[#choices + 1] = frame
            end
        end
        local selected, firstAvailable
        for index, frame in ipairs(choices) do
            local lives, unavailable = frame.Main:FindFirstChild("Lives"), frame.Main:FindFirstChild("Unavailable")
            if lives and lives.Visible then selected = index; break end
            if not firstAvailable and unavailable and not unavailable.Visible then firstAvailable = index end
        end
        if choices[preferred] and choices[preferred].Main.Unavailable.Visible then preferred = firstAvailable or preferred end
        action, argument = "dungeon_enter_room", tostring(selected or preferred)
    else
        self.dungeonChestOpened = false
        return true, "waiting"
    end
    local token = action .. ":" .. tostring(argument)
    if self.dungeonPending == token and os.clock() < (self.dungeonPendingUntil or 0) then return true, "pending" end
    self.dungeonPending, self.dungeonPendingUntil = token, os.clock() + 12
    if argument == nil then return self:Call(action) end
    return self:Call(action, argument)
end

function Adapter:Destroy()
    self.scope:Destroy()
    self.cache, self.inFlight = {}, {}
end

return Adapter
end

__modules["game/AutoCodes"] = function(require)
local Signal = require("core/Signal")
local CodeRedemption = require("game/CodeRedemption")
local AutoCodes = {}
AutoCodes.__index = AutoCodes
AutoCodes.URL = "https://beebom.com/anime-adventures-codes/"
local function timestamp() return type(os.time) == "function" and os.time() or math.floor(os.clock()) end

local function plain(text)
    text = text:gsub("<[^>]+>", ""):gsub("&amp;", "&"):gsub("&nbsp;", " ")
    text = text:gsub("&#x(%x+);", function(value) local n = tonumber(value, 16); return n and n >= 32 and n <= 126 and string.char(n) or "" end)
    text = text:gsub("&#(%d+);", function(value) local n = tonumber(value); return n and n >= 32 and n <= 126 and string.char(n) or "" end)
    return text:match("^%s*(.-)%s*$")
end
local function code(value)
    return type(value) == "string" and #value >= 2 and #value <= 64 and value:match("^[%w_!%-]+$") and value ~= "NEW"
end

function AutoCodes.parse(html)
    if type(html) ~= "string" or #html > 2 * 1024 * 1024 then return nil, "page_too_large" end
    html = html:gsub("<script[^>]*>.-</script>", ""):gsub("<style[^>]*>.-</style>", "")
    local lower, start = html:lower(), nil
    for first, body, last in lower:gmatch("()<h[23][^>]*>(.-)</h[23]>()") do
        local heading = plain(body):gsub("%s+", " ")
        if heading:find("working anime adventures codes", 1, true) or heading:find("active anime adventures codes", 1, true) then start = last; break end
    end
    if not start then return nil, "working_section_missing" end
    local boundary = lower:find("<h[23][%s>]", start) or (#html + 1)
    local block = html:sub(start, boundary - 1)
    local list = block:match("<ul[^>]*>(.-)</ul>") or block:match("<table[^>]*>(.-)</table>")
    if not list then return nil, "working_section_missing" end
    local result, seen = {}, {}
    local function item(body)
        local s, _, strong = body:find("<strong[^>]*>(.-)</strong>")
        local c, _, literal = body:find("<code[^>]*>(.-)</code>")
        local value = c and (not s or c < s) and literal or strong
        if not value then value = plain(body):match("^([^:]+):") end
        value = value and plain(value)
        if code(value) and not seen[value] and #result < 100 then seen[value] = true; result[#result + 1] = value end
    end
    for body in list:gmatch("<li[^>]*>(.-)</li>") do item(body) end
    if #result == 0 then for body in list:gmatch("<tr[^>]*>(.-)</tr>") do item(body) end end
    return result
end

AutoCodes.outcome = CodeRedemption.outcome

function AutoCodes.new(context)
    local self = setmetatable({scope = context.scope:Child(), runtime = context.runtime, adapter = context.adapter,
        config = context.config, storage = context.storage, codec = context.codec, path = context.path,
        entries = {}, Changed = Signal.new(), busy = false, lastRun = -math.huge}, AutoCodes)
    self.scope:Add(self.Changed)
    if self.storage then
        local ok, document = pcall(function()
            if not self.storage.exists(self.path) then return nil end
            local text = self.storage.read(self.path)
            assert(type(text) == "string" and #text <= 128 * 1024)
            return self.codec.decode(text)
        end)
        if ok and type(document) == "table" and document.version == 1 and type(document.entries) == "table" then
            local count = 0
            for value, entry in pairs(document.entries) do
                count = count + 1
                if count <= 1000 and code(value) and type(entry) == "table" and ({used = true, already_used = true, submitted = true})[entry.state] then
                    self.entries[value] = {state = entry.state, at = tonumber(entry.at) or 0}
                end
            end
        end
    end
    if self.adapter.Redeemed then
        self.scope:Connect(self.adapter.Redeemed, function(value, state, confirmed)
            if self.currentCode == value or not code(value) then return end
            if state == "failed" and confirmed and self.entries[value] and self.entries[value].state == "submitted" then
                self.entries[value] = nil
                self:_Save()
                return
            end
            if state ~= "used" and state ~= "already_used" then return end
            -- Manual checks can confirm old submitted entries without retrying
            -- uncertain history automatically or turning a timeout into success.
            self.entries[value] = {state = state, at = timestamp()}
            self:_Save()
        end)
    end
    self.scope:Connect(self.config.Changed, function(path)
        if path == "autocodes" then
            if self.config:Get("autocodes") then self:Run()
            elseif self.run then self.run:Destroy() end
        end
    end)
    if self.config:Get("autocodes") and self.adapter:InLobby() then self:Run() end
    return self
end

function AutoCodes:_Save()
    if not self.storage then return false, "unsupported" end
    local ok = pcall(function() self.storage.write(self.path, self.codec.encode({version = 1, entries = self.entries})) end)
    return ok, not ok and "write_failed" or nil
end

function AutoCodes:Run()
    if not self.scope.alive or not self.config:Get("autocodes") or not self.adapter:InLobby() then return false, "not_lobby" end
    if self.busy or os.clock() - self.lastRun < 5 then return false, "busy" end
    self.busy, self.lastRun = true, os.clock()
    local run = self.scope:Child()
    self.run = run
    run:Add(function() if self.run == run then self.run, self.busy, self.currentCode = nil, false, nil end end)
    local finished = false
    local function finish(state)
        if finished or not run.alive then return end
        finished = true
        self.lastResult = state
        run:Destroy()
        self.Changed:Fire(state)
    end
    run:Delay(90, function() finish({code = "timeout"}) end)
    run:Spawn(function()
        local ok, status, html = pcall(self.runtime.HTTP, self.runtime, AutoCodes.URL)
        if not run.alive then return end
        if not ok or status ~= 200 then finish({code = "fetch_failed"}); return end
        local codes, errorCode = AutoCodes.parse(html)
        if not codes then finish({code = errorCode}); return end
        if self.adapter.AcquireLobbyAction then
            local deadline, acquired = os.clock() + 30, false
            repeat
                acquired = self.adapter:AcquireLobbyAction(run) == true
                if not acquired then task.wait(0.5) end
            until acquired or not run.alive or not self.config:Get("autocodes")
                or not self.adapter:InLobby() or os.clock() >= deadline
            if not run.alive then return end
            if not acquired then finish({code = "lobby_busy"}); return end
            run:Add(function() self.adapter:ReleaseLobbyAction(run) end)
        end
        local result = {code = "done", found = #codes, used = 0, submitted = 0, skipped = 0, failed = 0}
        for _, value in ipairs(codes) do
            if not run.alive or not self.config:Get("autocodes") or not self.adapter:InLobby() then return end
            if self.entries[value] then result.skipped = result.skipped + 1
            else
                -- Persist the pending attempt before sending; ambiguous requests are never retried automatically.
                self.entries[value] = {state = "submitted", at = timestamp()}
                local _, storageError = self:_Save()
                result.storage = storageError
                self.currentCode = value
                local called, accepted, response = pcall(self.adapter.RedeemCode, self.adapter, value, run)
                if not run.alive then return end
                self.currentCode = nil
                local state = called and AutoCodes.outcome(accepted == true, response) or "submitted"
                if state == "failed" then self.entries[value] = nil; result.failed = result.failed + 1
                else self.entries[value].state = state; result[state == "submitted" and "submitted" or "used"] = result[state == "submitted" and "submitted" or "used"] + 1 end
                self:_Save()
                task.wait(0.6)
            end
        end
        finish(result)
    end)
    return true
end
function AutoCodes:Destroy() self.scope:Destroy() end
return AutoCodes
end

__modules["game/AutoSummon"] = function(require)
local Signal = require("core/Signal")
local Util = require("core/Util")
local NotificationSettings = require("game/NotificationSettings")

local AutoSummon = {}
AutoSummon.__index = AutoSummon
local RECEIPT_TIMEOUT = 8
local paymentCost, nextPayment

local function whole(value, min, max)
    return type(value) == "number" and value % 1 == 0 and value >= min and value <= max
end

function AutoSummon.new(context)
    local self = setmetatable({scope = context.scope:Child(), config = context.config, api = context.adapter,
        webhook = context.webhook, telegram = context.telegram, logs = context.sessionLogs, Changed = Signal.new(),
        state = {active = false, code = "idle", rolls = 0, acquired = 0}}, AutoSummon)
    self.scope:Add(self.Changed)
    if self.config.Changed then
        self.scope:Connect(self.config.Changed, function(path, value)
            if path == "autosummon.lobby_enabled" then
                self.lobbyComplete, self.lobbyRetries = value ~= true, 0
                if value == true then self:_QueueLobby(0)
                elseif self.run and self.run.automatic then self:Stop("stopped") end
            end
        end)
    end
    self.lobbyComplete = self.config:Get("autosummon.lobby_enabled") ~= true
    if not self.lobbyComplete then self:_QueueLobby(1) end
    return self
end

function AutoSummon:State()
    local state = self.state
    return {active = state.active, code = state.code, rolls = state.rolls, acquired = state.acquired or 0,
        banner = state.banner, target = state.target, automatic = state.automatic == true,
        pending = self.config:Get("autosummon.lobby_enabled") == true and not self.lobbyComplete}
end

function AutoSummon:Preflight(options)
    options = options or {}
    local automatic = options.automatic == true
    local settings = automatic and {banner = "Summer2026", target = "", mode = "luck", limit = 100000,
        reserve = 0, batch = "gems10"} or {
            banner = self.config:Get("autosummon.banner"), target = Util.trim(self.config:Get("autosummon.target")),
            mode = self.config:Get("autosummon.mode"), limit = self.config:Get("autosummon.limit"),
            reserve = self.config:Get("autosummon.reserve"), batch = self.config:Get("autosummon.batch"),
        }
    local result = {ok = false, code = "invalid", automatic = automatic, settings = settings}
    if not self.scope.alive then result.code = "stopped"; return result end
    if self.run or (self.api.inFlight and self.api.inFlight.buy_from_banner) then result.code = "running"; return result end
    if not self.api:InLobby() then result.code = "lobby"; return result end
    if type(settings.banner) ~= "string" or settings.banner == "" or #settings.target > 128
        or not whole(settings.limit, 1, 100000) or not whole(settings.reserve, 0, 1000000000)
        or (settings.mode ~= "luck" and settings.mode ~= "pity")
        or (settings.batch ~= "gems" and settings.batch ~= "gems10") then return result end
    local banner = self.api:SummonBanner(settings.banner)
    result.banner = banner
    local added = self.api:Endpoint("unit_added", true)
    local hatched = self.api:Endpoint("units_hatched_through_banner", true)
    local rewards = self.api:Endpoint("show_unit_and_item_rewards", true)
    result.events = {unitAdded = added and added:IsA("RemoteEvent") or false,
        hatched = hatched and hatched:IsA("RemoteEvent") or false,
        rewards = rewards and rewards:IsA("RemoteEvent") or false}
    local capsuleReady = banner and banner.capsule and type(self.api.CapsulePity) == "function"
        and self.api:CapsulePity(banner.capsule) ~= nil and result.events.rewards and result.events.unitAdded
    if not banner or (not banner.capsule and (not result.events.unitAdded or not result.events.hatched))
        or (banner.capsule and not capsuleReady) then result.code = "unavailable"; return result end
    if settings.target ~= "" then
        local rarity
        result.target, rarity = self.api:ResolveSummonTarget(settings.target)
        if not result.target then result.code = "unknownTarget"; return result end
        if banner.pool and rarity ~= "Secret" and rarity ~= "Mixed" then
            local matches = {}
            for id in pairs(result.target) do if banner.pool[id] then matches[id] = true end end
            if next(matches) == nil then result.code = "targetUnavailable"; return result end
            result.target = matches
        end
    end
    result.balance = self.api:Resource(banner.currency)
    result.payment, result.count = nextPayment(settings, banner, 0, result.balance)
    if not result.payment then result.code = result.count; return result end
    result.required = settings.reserve + paymentCost(banner, result.count)
    if result.balance < result.required then result.code = "budget"; return result end
    result.ok, result.code = true, "ready"
    return result
end

function AutoSummon:_Publish(code)
    self.state.code = code
    self.state.active = self.run ~= nil
    self.Changed:Fire(self:State())
end

function AutoSummon:Stop(code)
    local run = self.run
    if not run then return false end
    local automatic, rewards, acquired = run.automatic, run.rewards, run.acquired
    self.run = nil
    run:Destroy()
    self:_Publish(code or "stopped")
    if acquired and acquired > 0 then self:_Notify(rewards, code or "stopped") end
    if automatic then
        local complete = code == "budget" or code == "limit" or code == "target" or code == "stopped"
        if complete then
            self.lobbyComplete = true
        else
            self.lobbyRetries = (self.lobbyRetries or 0) + 1
            if self.lobbyRetries >= 3 then self.lobbyComplete = true else self:_QueueLobby(4) end
        end
        self:_Publish(code or "stopped")
    end
    return true
end

function AutoSummon:_Notify(rewards, reason)
    if not next(rewards or {}) then return end
    for channel, service in pairs({discord = self.webhook, telegram = self.telegram}) do
        if NotificationSettings.enabled(self.config, channel, "summons.enabled") then
            local attempts = 0
            local function deliver()
                if not self.scope.alive or not NotificationSettings.enabled(self.config, channel, "summons.enabled") then return end
                attempts = attempts + 1
                local queued, detail = service:Send("Summon results · " .. tostring(reason or "finished"), rewards)
                if not queued and type(detail) == "table" and detail.code == "busy" and attempts < 15 then
                    self.scope:Delay(2, deliver)
                elseif self.logs then
                    if queued then self.logs:Info("summon_notification_queued", {channel = channel, units = self.state.acquired or 0})
                    else self.logs:Error("summon_notification_rejected", detail, {channel = channel, units = self.state.acquired or 0}) end
                end
            end
            self.scope:Delay(0.2, deliver)
        end
    end
end

function AutoSummon:_QueueLobby(delay)
    if self.lobbyQueued or self.lobbyComplete or self.config:Get("autosummon.lobby_enabled") ~= true then return end
    self.lobbyQueued = true
    self.scope:Delay(delay or 0, function()
        self.lobbyQueued = false
        if self.lobbyComplete or self.config:Get("autosummon.lobby_enabled") ~= true then return end
        local ok, reason = self:Start({automatic = true})
        if ok then return end
        if reason == "lobbyBusy" or reason == "running" then
            self.state.code = reason
            self:_Publish(reason)
            self:_QueueLobby(2)
            return
        end
        if reason == "budget" or reason == "limit" then
            self.lobbyComplete = true
            self.state.code = reason
            self:_Publish(reason)
            return
        end
        self.lobbyRetries = (self.lobbyRetries or 0) + 1
        self.state.code = reason or "unavailable"
        self:_Publish(self.state.code)
        if self.lobbyRetries >= 3 then self.lobbyComplete = true; self:_Publish(self.state.code)
        else self:_QueueLobby(4) end
    end)
end

function AutoSummon:StartLobbyRun()
    if self.config:Get("autosummon.lobby_enabled") ~= true then return false, "disabled" end
    self.lobbyComplete, self.lobbyRetries = false, 0
    self:_QueueLobby(0)
    return true
end

function AutoSummon:BlocksFarm()
    if self.config:Get("autosummon.lobby_enabled") ~= true or not self.api:InLobby() or self.lobbyComplete then return false end
    if not self.run and not self.lobbyQueued then self:_QueueLobby(0) end
    return true
end

paymentCost = function(banner, count)
    return count == 10 and (tonumber(banner.batchCost) or banner.cost * 10) or banner.cost * count
end

nextPayment = function(settings, banner, rolls, balance)
    if rolls >= settings.limit then return nil, "limit" end
    if settings.mode == "pity" then
        if rolls > 0 then return nil, "limit" end
        if not whole(banner.threshold, 1, 100000)
            or not whole(banner.pity, 0, banner.threshold)
            or banner.pity < banner.threshold - 1 then return nil, "pity" end
        return "gems", 1
    end
    if settings.batch == "gems10" and banner.batchSupported ~= false and settings.limit - rolls >= 10
        and (balance == nil or balance >= settings.reserve + paymentCost(banner, 10)) then return "gems10", 10 end
    return "gems", 1
end

function AutoSummon:Start(options)
    options = options or {}
    local preflight = self:Preflight(options)
    if not preflight.ok then return false, preflight.code end
    local automatic, settings, banner = preflight.automatic, preflight.settings, preflight.banner
    local added = self.api:Endpoint("unit_added", true)
    local hatched = self.api:Endpoint("units_hatched_through_banner", true)
    local rewards = self.api:Endpoint("show_unit_and_item_rewards", true)
    local target = preflight.target

    local run = self.scope:Child()
    if self.api.AcquireLobbyAction then
        local acquired = self.api:AcquireLobbyAction(run)
        if not acquired then run:Destroy(); return false, "lobbyBusy" end
        run:Add(function() self.api:ReleaseLobbyAction(run) end)
    end
    run.automatic, run.rewards, run.reported, run.acquired = automatic, {}, {}, 0
    self.run = run
    self.api.autoSummonOwner = run
    run:Add(function()
        if self.api.autoSummonOwner == run then self.api.autoSummonOwner = nil end
    end)
    self.state = {rolls = 0, acquired = 0, banner = settings.banner, target = settings.target, automatic = automatic}
    local pending
    run:Connect(added.OnClientEvent, function(unit)
        if not pending or type(unit) ~= "table" or type(unit.uuid) ~= "string" or type(unit.unit_id) ~= "string" then return end
        pending.units[unit.uuid] = unit.unit_id
    end)
    local function registerHatches(uuids)
        if not pending or type(uuids) ~= "table" then return end
        for _, uuid in ipairs(uuids) do
            if type(uuid) == "string" then pending.hatched[uuid] = true end
        end
    end
    if hatched and hatched:IsA("RemoteEvent") then run:Connect(hatched.OnClientEvent, registerHatches) end
    if rewards and rewards:IsA("RemoteEvent") then
        run:Connect(rewards.OnClientEvent, function(items, uuids, _, _, source, options)
            if pending and type(options) == "table" and options._hatched_through_banner == true then
                registerHatches(uuids)
            end
            if pending and banner.capsule and source == "capsule" and type(options) == "table"
                and options.capsule_id == banner.capsule then
                pending.capsule = true
                if type(items) == "table" then
                    for _, item in pairs(items) do
                        local id = type(item) == "table" and item.item_id
                        local count = type(item) == "table" and (item.uuid and 1 or tonumber(item.amount))
                        if type(id) == "string" and id ~= "" and count and count > 0 and count % 1 == 0 then
                            pending.items[id] = (pending.items[id] or 0) + count
                        end
                    end
                end
                if type(uuids) == "table" then
                    for _, uuid in pairs(uuids) do if type(uuid) == "string" then pending.rewardUnits[uuid] = true end end
                end
            end
        end)
    end

    local function checkReceipt(receipt)
        local confirmed, expected, hit = 0, 0, false
        local source = next(receipt.hatched) and receipt.hatched or receipt.units
        for uuid in pairs(source) do
            expected = expected + 1
            local id = receipt.units[uuid]
            if id then
                confirmed = confirmed + 1
                if target and target[id] then hit = true end
            end
        end
        return confirmed, hit, expected
    end

    local function recordUnit(receipt, uuid, id)
        if id and not run.reported[uuid] then
            run.reported[uuid] = true
            local metadata = self.api.UnitMetadata and self.api:UnitMetadata(id)
            local name = type(metadata) == "table" and type(metadata.name) == "string" and metadata.name or id
            local rarity = type(metadata) == "table" and type(metadata.rarity) == "string" and metadata.rarity or "Unknown"
            local label = string.format("%s [%s]", name, rarity)
            run.rewards[label] = (run.rewards[label] or 0) + 1
            run.acquired = run.acquired + 1
        end
    end

    local function recordReceipt(receipt, capsule)
        local source = capsule and receipt.rewardUnits or (next(receipt.hatched) and receipt.hatched or receipt.units)
        for uuid in pairs(source) do
            local id = receipt.units[uuid]
            if id then recordUnit(receipt, uuid, id) end
        end
        for id, count in pairs(receipt.items) do
            local metadata = self.api.ItemMetadata and self.api:ItemMetadata(id)
            local name = type(metadata) == "table" and type(metadata.name) == "string" and metadata.name or id
            local rarity = type(metadata) == "table" and type(metadata.rarity) == "string" and metadata.rarity or "Unknown"
            local label = string.format("%s [%s]", name, rarity)
            run.rewards[label] = (run.rewards[label] or 0) + count
            run.acquired = run.acquired + count
        end
        self.state.acquired = run.acquired
    end

    self:_Publish("running")
    run:Spawn(function()
        local ok = pcall(function()
            while run.alive do
                if not self.api:InLobby() then self:Stop("lobby"); return end
                local current = self.api:SummonBanner(settings.banner)
                if not current or current.currency ~= banner.currency or current.cost ~= banner.cost
                    or paymentCost(current, 10) ~= paymentCost(banner, 10) then
                    self:Stop("unavailable"); return
                end
                local before = self.api:Resource(current.currency)
                local method, requested = nextPayment(settings, current, self.state.rolls, before)
                if not method then self:Stop(requested); return end
                if before < settings.reserve + paymentCost(current, requested) then self:Stop("budget"); return end
                local receipt = {units = {}, hatched = {}, items = {}, rewardUnits = {}}
                local pityBefore = current.capsule and self.api:CapsulePity(current.capsule) or nil
                pending = receipt
                local accepted = self.api:BuyBanner(settings.banner, method, run)
                if not run.alive then return end
                if not accepted then self:Stop("rejected"); return end
                local deadline = os.clock() + RECEIPT_TIMEOUT
                repeat
                    local confirmed, hit, expected = checkReceipt(receipt)
                    local spent = self.api:Resource(current.currency) < before
                    local capsuleCount = 0
                    local capsuleHit = false
                    for _, count in pairs(receipt.items) do capsuleCount = capsuleCount + count end
                    for uuid in pairs(receipt.rewardUnits) do
                        -- Unit outcomes are authoritative only when the UUID in
                        -- the capsule reward payload also arrived via unit_added.
                        local id = receipt.units[uuid]
                        if id then
                            capsuleCount = capsuleCount + 1
                            if target and target[id] then capsuleHit = true end
                        end
                    end
                    local pityAfter = current.capsule and self.api:CapsulePity(current.capsule) or nil
                    local capsuleConfirmed = current.capsule and spent and receipt.capsule
                        and type(pityBefore) == "number" and type(pityAfter) == "number"
                        and pityAfter - pityBefore == requested and capsuleCount == requested
                    -- Some lobby servers omit units_hatched_through_banner, but unit_added still
                    -- carries each acquired UUID. Use the correlated hatch set when present and
                    -- otherwise the post-purchase additions; an empty capsule snapshot confirms nothing.
                    if capsuleConfirmed or (not current.capsule and spent and confirmed >= requested and expected >= requested) then
                        recordReceipt(receipt, current.capsule ~= nil)
                        self.state.rolls = self.state.rolls + requested
                        pending = nil
                        if (current.capsule and capsuleHit) or (not current.capsule and hit) then self:Stop("target"); return end
                        self:_Publish("running")
                        break
                    end
                    if os.clock() >= deadline then self:Stop("unconfirmed"); return end
                    task.wait(0.1)
                until not run.alive
                task.wait(0.75)
            end
        end)
        if not ok and self.run == run then self:Stop("unavailable") end
    end)
    return true
end

function AutoSummon:Destroy()
    self:Stop()
    self.scope:Destroy()
end

return AutoSummon
end

__modules["game/Catalog"] = function(require)
local Util = require("core/Util")
local Catalog = {}
-- The bundle's require resolves internal module names, not Roblox ModuleScripts.
local nativeRequire = type(getfenv) == "function" and getfenv(0).require or nil

local function id(value)
    return type(value) == "string" and #value > 0 and #value <= 128 and value:match("^[%w_:%-]+$") ~= nil
end

local function orderMap(values)
    local result = {}
    for index, value in ipairs(type(values) == "table" and values or {}) do
        if id(value) and result[value] == nil then result[value] = index end
    end
    return result
end

local function validWorld(world)
    if type(world) ~= "table" or type(world.name) ~= "string" or world.name == "" then return false end
    if type(world.infinite) == "table" and id(world.infinite.id) then return true end
    for _, level in pairs(type(world.levels) == "table" and world.levels or {}) do
        if type(level) == "table" and id(level.id) then return true end
    end
    return false
end

-- Pure normalization of the game's Worlds records; never guesses level IDs.
function Catalog.normalize(worlds, ordering)
    local result = {story = {}, legend = {}, raids = {}, infinity = {}}
    local orders = {
        story = orderMap(ordering and ordering.WORLD_ORDER),
        legend = orderMap(ordering and ordering.LEGEND_WORLD_ORDER),
        raids = orderMap(ordering and ordering.RAID_WORLD_ORDER),
    }
    for worldId, world in pairs(worlds or {}) do
        if id(worldId) and validWorld(world) then
            local mode = world.raid_world == true and "raids" or (world.legend_stage == true and "legend" or "story")
            local levels = {}
            for index, level in pairs(type(world.levels) == "table" and world.levels or {}) do
                if type(level) == "table" and id(level.id) then
                    levels[#levels + 1] = {value = level.id, label = tostring(index), order = tonumber(index) or 999}
                end
            end
            table.sort(levels, function(a, b) return a.order < b.order or (a.order == b.order and a.value < b.value) end)
            local function entry(items)
                return {value = worldId, label = world.name, map = tostring(world.map or worldId),
                    recommendedLevel = tonumber(world.recommended_level) or 0, levels = items,
                    order = (orders[mode] and orders[mode][worldId]) or math.huge}
            end
            if #levels > 0 then result[mode][#result[mode] + 1] = entry(levels) end
            if type(world.infinite) == "table" and id(world.infinite.id) then
                result.infinity[#result.infinity + 1] = entry({{value = world.infinite.id, label = world.name, order = 1}})
            end
        end
    end
    for _, items in pairs(result) do
        table.sort(items, function(a, b)
            if a.order ~= b.order then return a.order < b.order end
            return a.label < b.label or (a.label == b.label and a.value < b.value)
        end)
    end
    return result
end

-- Load direct leaf modules only. The aggregator can block on unrelated children.
function Catalog.load(root, scope, reader)
    local worlds, ordering = {}, nil
    local diagnostics = {loaded = 0, failed = 0, timedOut = 0, orderLoaded = false}
    if not root then return Catalog.normalize(worlds), diagnostics end
    reader = reader or nativeRequire
    local function read(module)
        local job, done, ok, data = scope:Child(), false, false, nil
        job:Spawn(function() ok, data = pcall(reader, module); done = true end)
        local deadline = os.clock() + 0.8
        repeat task.wait(0.03) until done or not scope.alive or os.clock() >= deadline
        job:Destroy()
        if not done then return nil, "timeout" end
        if not ok or type(data) ~= "table" then return nil, "failed" end
        return data
    end

    local orderModule = root.Parent and root.Parent:FindFirstChild("WorldLevelOrder")
    if orderModule and orderModule:IsA("ModuleScript") then
        local data, reason = read(orderModule)
        if data then ordering, diagnostics.orderLoaded = data, true
        elseif reason == "timeout" then diagnostics.timedOut = diagnostics.timedOut + 1
        else diagnostics.failed = diagnostics.failed + 1 end
    end
    local modules = root:GetChildren()
    table.sort(modules, function(a, b) return a.Name < b.Name end)
    for _, module in ipairs(modules) do
        if not scope.alive then break end
        if module:IsA("ModuleScript") then
            local data, reason = read(module)
            if data then
                for key, record in pairs(data) do
                    -- Stable module order gives deterministic precedence, while
                    -- malformed duplicates cannot erase an earlier valid world.
                    if id(key) and validWorld(record) then worlds[key] = record end
                end
                diagnostics.loaded = diagnostics.loaded + 1
            elseif reason == "timeout" then diagnostics.timedOut = diagnostics.timedOut + 1
            else diagnostics.failed = diagnostics.failed + 1 end
        end
    end
    return Catalog.normalize(worlds, ordering), diagnostics
end

return Catalog
end

__modules["game/CodeRedemption"] = function(require)
-- Anime Adventures reports redeem failures through show_message, but is silent
-- after a successful RemoteFunction invocation. Silence is usable only when
-- that invocation completed AND its error-notification observer is available.
local Redemption = {ObserveSeconds = 1}

local function normalized(value)
    return value:lower():gsub("<[^>]*>", ""):gsub("[_%-]", " "):gsub("%s+", " ")
end

function Redemption.outcome(ok, response)
    if type(response) == "table" then
        if response.already_redeemed == true or response.already_used == true then return "already_used" end
        if response.ok == true or response.success == true then return "used" end
        response = response.code or response.message or response.error
    end
    if response == true then return "used" end
    if type(response) == "string" then
        local value = normalized(response)
        if value == "timeout" or value == "transport" or value == "request failed" or value == "cancelled" then return "submitted" end
        if value == "needs social" then return "failed" end
        if value:find("already", 1, true) and (value:find("redeem", 1, true) or value:find("claim", 1, true) or value:find("used", 1, true)) then return "already_used" end
        if value:find("invalid", 1, true) or value:find("unknown code", 1, true) or value:find("expired", 1, true) or value:find("level", 1, true) then return "failed" end
        if value == "success" or value == "redeemed" or value == "ok" then return "used" end
    end
    return ok and "submitted" or "failed"
end

function Redemption.message(text, kind)
    if type(text) ~= "string" or #text > 4096 or type(kind) ~= "string" or kind:lower() ~= "error" then return nil end
    local value = normalized(text)
    -- Ignore unrelated quest/summon/match errors; they share this notification.
    if not value:find("code", 1, true) and not value:find("redeem", 1, true) then return nil end
    if value:find("already", 1, true) and value:find("redeem", 1, true) then return "already_redeemed" end
    if value:find("unknown code", 1, true) or value:find("invalid code", 1, true) then return "invalid_code" end
    if value:find("expired", 1, true) then return "expired" end
    if value:find("level", 1, true) then return "level_required" end
    if value:find("failed to redeem", 1, true) or value:find("cannot redeem", 1, true) or value:find("cannot be redeemed", 1, true) then return "code_rejected" end
    return "unconfirmed" -- A new code-related error must never become silent success.
end

local function endpoints(adapter)
    if type(adapter.Endpoint) ~= "function" then return end
    local ok, redeem, message = pcall(function()
        return adapter:Endpoint("redeem_code"), adapter:Endpoint("show_message", true)
    end)
    if not ok then return end
    local compatible, supported = pcall(function()
        return redeem and redeem:IsA("RemoteFunction") and message and message:IsA("RemoteEvent")
    end)
    if compatible and supported then return message end
end

function Redemption.run(adapter, code, owner)
    if adapter.redeeming and adapter.redeeming.alive then return false, "busy", "failed" end
    if not adapter.scope.alive or (owner and not owner.alive) then return false, "cancelled", "submitted" end
    local scope = adapter.scope:Child()
    adapter.redeeming = scope
    scope:Add(function() if adapter.redeeming == scope then adapter.redeeming = nil end end)
    if owner then
        local _, id = owner:Add(function() scope:Destroy() end)
        scope:Add(function() owner:Remove(id) end)
    end
    local timedOut = false
    scope:Delay(10, function() timedOut = true; scope:Destroy() end)
    local observed, notification = false, nil
    local message = endpoints(adapter)
    if message then
        observed = pcall(function()
            scope:Connect(message.OnClientEvent, function(text, kind)
                local result = Redemption.message(text, kind)
                if result then notification = notification or result end
            end)
        end)
    end
    local function finish(ok, response, confirmed)
        local state = Redemption.outcome(ok, response)
        scope:Destroy()
        return ok, response, state, confirmed == true
    end
    local called, accepted, response = pcall(adapter.Call, adapter, "redeem_code", code)
    if not called then return finish(false, "transport") end
    if not scope.alive then return finish(false, timedOut and "timeout" or "cancelled") end
    if not accepted and response ~= false and response ~= "busy" and response ~= "missing" and response ~= "destroyed"
        and response ~= "timeout" and response ~= "cancelled" and not notification then
        response = "transport" -- Adapter.Call may already have caught InvokeServer's exception.
    end
    -- A timeout/transport failure is still ambiguous, even without an error toast.
    if accepted and observed and response == nil then
        local deadline = os.clock() + Redemption.ObserveSeconds
        repeat task.wait(0.05) until not scope.alive or os.clock() >= deadline
        if not scope.alive then return finish(false, timedOut and "timeout" or "cancelled") end
    end
    if notification then
        if notification == "unconfirmed" then return finish(true, {code = "unconfirmed"}) end
        return finish(false, {code = notification, already_redeemed = notification == "already_redeemed", notified = true}, true)
    end
    if accepted and observed and response == nil then
        return finish(true, {success = true, confirmation = "silent_response"}, true)
    end
    local state = Redemption.outcome(accepted, response)
    if accepted and (state == "failed" or state == "already_used") then return finish(false, response, true) end
    return finish(accepted, response, state == "used" or state == "already_used" or response == false)
end

return Redemption
end

__modules["game/CombatAutomation"] = function(require)
local Scheduler = require("core/Scheduler")
local Util = require("core/Util")

local Combat = {}
Combat.__index = Combat

function Combat.new(context)
    local self = setmetatable({scope = context.scope:Child(), config = context.config, api = context.adapter,
        lastSkip = -math.huge, priorities = {}}, Combat)
    self.scheduler = Scheduler.new(self.scope:Child())
    local startVote = self.api:Endpoint("start_vote_wave_skip", true)
    if startVote and startVote:IsA("RemoteEvent") then
        self.scope:Connect(startVote.OnClientEvent, function() self.skipPending = true; self:Tick() end)
    end
    local closeVotes = self.api:Endpoint("close_vote_prompts", true)
    if closeVotes and closeVotes:IsA("RemoteEvent") then
        self.scope:Connect(closeVotes.OnClientEvent, function() self.skipPending = false end)
    end
    if self.config.Changed then self.scope:Connect(self.config.Changed, function(path)
        if path:match("^combat%.") or path:match("^autoplace%.unit%d+%.target_priority$") then
            self.priorities = {}
            self:_Sync()
        end
    end) end
    self:_Sync()
    return self
end

function Combat:_Sync()
    self.scheduler:Remove("combat")
    local cfg = self.config.data.combat
    local targeting = false
    for index = 1, 6 do
        local unit = self.config.data.autoplace["unit" .. index]
        if unit and unit.target_priority and unit.target_priority ~= "original" then targeting = true; break end
    end
    if not self.api:InLobby() and (cfg.wave_skip.enabled or targeting) then
        self.scheduler:Set("combat", 1, function() self:Tick() end, true)
    end
end

function Combat:_PriorityByUUID()
    local result = {}
    if type(self.api.Hotbar) ~= "function" then return result end
    local hotbar = self.api:Hotbar()
    for index = 1, 6 do
        local slot = hotbar[index]
        local cfg = self.config.data.autoplace["unit" .. index]
        local priority = cfg and cfg.target_priority or "original"
        if slot and type(slot.uuid) == "string" and slot.uuid ~= "" and priority ~= "original" then
            result[slot.uuid] = priority
        end
    end
    return result
end

function Combat:Tick()
    if not self.scope.alive or self.api:InLobby() then return end
    local finished = Util.find(workspace, "_DATA.GameFinished")
    if finished and finished.Value then return end
    local cfg, wave = self.config.data.combat, workspace:FindFirstChild("_wave_num")
    wave = wave and tonumber(wave.Value) or 0
    if cfg.wave_skip.enabled and (cfg.wave_skip.stop_wave == 0 or wave < cfg.wave_skip.stop_wave)
        and os.clock() - self.lastSkip >= 1.5 then
        local prompt = Util.find(workspace, "_DATA.VoteWaveSkip")
        if self.skipPending or prompt or self.api:Gui("VoteWaveUI") then
            self.lastSkip = os.clock()
            if self.api:Call("vote_wave_skip") then self.skipPending = false end
        end
    end
    local priorities = self:_PriorityByUUID()
    if next(priorities) then
        for _, record in ipairs(self.api:OwnedUnits()) do
            local requested = priorities[record.uuid]
            local stats = record.unit:FindFirstChild("_stats")
            local priority = stats and stats:FindFirstChild("priority")
            if requested and priority and priority:IsA("StringValue") and priority.Value ~= requested
                and self.priorities[record.unit] ~= requested then
                self.priorities[record.unit] = requested
                local ok = self.api:ChangePriority(record.unit, requested)
                if ok then
                    local deadline = os.clock() + 2
                    repeat task.wait(0.05) until priority.Value == requested or os.clock() >= deadline or not self.scope.alive
                end
                self.priorities[record.unit] = nil
                return
            end
        end
    end
end

function Combat:Destroy() self.scope:Destroy() end
return Combat
end

__modules["game/DropNotifications"] = function(require)
local Util = require("core/Util")
local NotificationSettings = require("game/NotificationSettings")
local DropNotifications = {}
DropNotifications.__index = DropNotifications

local nativeRequire = type(getfenv) == "function" and getfenv(0).require or nil
local events = {unit_added = "units"}

local function catalog(storage, name)
    local module = Util.find(storage, "src.Data." .. name)
    if not module or not nativeRequire then return {} end
    local ok, data = pcall(nativeRequire, module)
    return ok and type(data) == "table" and data or {}
end

local function rarityFilter(rarity)
    local value = string.lower(rarity)
    if value == "secret" then return "secret" end
    if value == "mythic" or value == "mythical" then return "mythic" end
    return "other"
end

function DropNotifications.new(context)
    local self = setmetatable({scope = context.scope:Child(), config = context.config, api = context.adapter,
        deliveries = {}, endpoints = {}, catalogs = {}}, DropNotifications)
    for channel, service in pairs({discord = context.webhook, telegram = context.telegram}) do
        self.deliveries[#self.deliveries + 1] = {channel = channel, service = service, rewards = {}, filters = {}, size = 0}
    end
    self:_Attach()
    local root = Util.find(self.api.storage, "endpoints.server_to_client")
    if root then
        self.scope:Connect(root.ChildAdded, function() self:_Attach() end)
    end
    return self
end

function DropNotifications:_Attach()
    for event, category in pairs(events) do
        local remote = self.api:Endpoint(event, true)
        local previous = self.endpoints[event]
        if remote and remote:IsA("RemoteEvent") and (not previous or previous.remote ~= remote) then
            if previous then self.scope:Remove(previous.id, true) end
            local _, id = self.scope:Connect(remote.OnClientEvent, function(payload, count)
                self:_Drop(category, payload, count)
            end)
            self.endpoints[event] = {remote = remote, id = id}
        end
    end
end

function DropNotifications:_Drop(category, payload, count)
    if category ~= "units" then return end
    local enabled = false
    for _, delivery in ipairs(self.deliveries) do
        if NotificationSettings.enabled(self.config, delivery.channel, "drops.enabled") then enabled = true; break end
    end
    if not enabled then return end
    local id = payload
    if type(payload) == "table" then
        local field = category == "units" and "unit_id" or "item_id"
        id = payload[field]
    end
    if type(id) ~= "string" or #id > 128 then return end

    local name = category == "units" and "Units" or "Items"
    if not self.catalogs[name] then self.catalogs[name] = catalog(self.api.storage, name) end
    local data = self.catalogs[name][id]
    if type(data) ~= "table" or type(data.name) ~= "string" or type(data.rarity) ~= "string" then return end
    local filter = "drops." .. category .. "_" .. rarityFilter(data.rarity)

    count = tonumber(count) or 1
    if count < 1 or count % 1 ~= 0 or count > 10000 then return end
    local label = string.format("%s [%s %s]", data.name, data.rarity, "unit")
    for _, delivery in ipairs(self.deliveries) do
        if NotificationSettings.enabled(self.config, delivery.channel, "drops.enabled")
            and NotificationSettings.enabled(self.config, delivery.channel, filter) then
            local current = delivery.rewards[label]
            if current or delivery.size < 32 then
                if not current then delivery.size = delivery.size + 1 end
                delivery.rewards[label] = (current or 0) + count
                delivery.filters[label] = filter
            end
            if not delivery.pending then
                delivery.pending = self.scope:Delay(0.5, function() self:_Flush(delivery, 0) end)
            end
        end
    end
end

function DropNotifications:_Flush(delivery, retries)
    delivery.pending = nil
    if delivery.size > 0 and NotificationSettings.enabled(self.config, delivery.channel, "drops.enabled") then
        local rewards = {}
        for label, count in pairs(delivery.rewards) do
            if NotificationSettings.enabled(self.config, delivery.channel, delivery.filters[label]) then rewards[label] = count end
        end
        if next(rewards) then
            local queued, detail = delivery.service:Send("Drops acquired", rewards)
            if not queued and type(detail) == "table" and detail.code == "busy" and retries < 15 then
                delivery.pending = self.scope:Delay(2, function() self:_Flush(delivery, retries + 1) end)
                return
            end
        end
    end
    delivery.rewards, delivery.filters, delivery.size = {}, {}, 0
end

function DropNotifications:Destroy()
    self.scope:Destroy()
end

return DropNotifications
end

__modules["game/GameService"] = function(require)
local Scheduler = require("core/Scheduler")
local Util = require("core/Util")
local NotificationSettings = require("game/NotificationSettings")
local MatchReport = require("game/MatchReport")
local GameService = {}
GameService.__index = GameService

function GameService.new(context)
    local self = setmetatable({
        scope = context.scope:Child(), adapter = context.adapter, config = context.config,
        webhook = context.webhook, telegram = context.telegram, settings = context.settings, rewards = {}, startResources = {},
        matchToken = 1, startSent = false, endSent = false, matchmakingBusy = false,
        onStart = context.onStart, logs = context.sessionLogs, challengeMethod = context.challengeMethod,
        autoSummon = context.autoSummon,
        lobbyUtilities = context.lobbyUtilities,
        matchStats = context.matchStats,
        portalFarm = context.portalFarm,
    }, GameService)
    self.scheduler = Scheduler.new(self.scope:Child())
    self.scope:Add(self.config.Changed:Connect(function(path)
        if path:match("^game%.") or path:match("^smartfarm%.") or path:match("^portals%.")
            or path:match("^autoclaim%.") or path == "autocaptcha" then self:_Sync() end
    end))
    self:_Sync()
    -- Retry attachment for a bounded time; game objects may arrive after authorization.
    local attempts = 0
    self.scheduler:Set("attach", 1, function()
        attempts = attempts + 1
        if self:_Attach() or attempts >= 20 then self.scheduler:Remove("attach") end
    end, true)
    return self
end

function GameService:_Sync()
    if self.adapter:InLobby() then
        local enabled = self.config.data.autoclaim
        if enabled.quests or enabled.battlepass or enabled.dailylogin then
            if not self.scheduler.jobs.claims then self.scheduler:Set("claims", 30, function() self:ClaimRewards() end, true) end
        else self.scheduler:Remove("claims") end
        if self.config:Get("game.enabled") and not self.config:Get("smartfarm.enabled") then
            local mode = self.config:Get("game.type")
            if not self.scheduler.jobs.matchmaking or self.matchmakingMode ~= mode then
                self.matchmakingMode = mode
                self.scheduler:Set("matchmaking", (mode == "dungeon" or mode == "portals") and 3 or 15, function()
                    self.scope:Spawn(function() self:StartGame() end)
                end, true)
            end
        else self.matchmakingMode = nil; self.scheduler:Remove("matchmaking") end
    else
        if self.config:Get("game.enabled") and self.config:Get("game.type") == "dungeon" then
            if not self.scheduler.jobs.dungeon then
                self.scheduler:Set("dungeon", 3, function() self.adapter:DungeonStep(self.config.data.game.dungeon) end, true)
            end
        else self.scheduler:Remove("dungeon") end
        if self.config:Get("game.player_simulate") then
            if not self.scheduler.jobs.movement then self.scheduler:Set("movement", 40, function() self:_Move() end) end
        else self.scheduler:Remove("movement") end
        if self.config:Get("game.vote_start") then
            if not self.scheduler.jobs.vote then self.scheduler:Set("vote", 5, function() self:_Vote() end, true) end
        else self.scheduler:Remove("vote") end
    end
end

function GameService:ClaimRewards()
    if not self.adapter:InLobby() then return end
    local owner = {}
    if self.adapter.AcquireLobbyAction and not self.adapter:AcquireLobbyAction(owner) then return false, "lobby_busy" end
    local ok, reason = pcall(function()
        if self.config:Get("autoclaim.quests") then self.adapter:ClaimQuests() end
        if self.scope.alive and self.config:Get("autoclaim.battlepass") then self.adapter:ClaimBattlepassRewards() end
        if self.scope.alive and self.config:Get("autoclaim.dailylogin") then self.adapter:ClaimDailyReward() end
    end)
    if self.adapter.ReleaseLobbyAction then self.adapter:ReleaseLobbyAction(owner) end
    if not ok then
        if self.logs then self.logs:Error("reward_claim_failed", reason) end
        return false, "claim_failed"
    end
    return true
end

function GameService:StartGame()
    if not self.adapter:InLobby() or not self.config:Get("game.enabled") or self.matchmakingBusy then return false end
    if self.autoSummon and self.autoSummon.BlocksFarm and self.autoSummon:BlocksFarm() then return false, "summoning" end
    return self:StartSelected(true)
end

function GameService:_StartPriorityChallenge(cfg)
    if not (cfg.events.priorityDaily or cfg.events.priorityNormal) or not self.challengeMethod then return end
    if os.clock() < (self.challengePendingUntil or 0) then return false, "challenge_pending" end
    for _, kind in ipairs({"daily", "normal"}) do
        local key = kind == "daily" and "priorityDaily" or "priorityNormal"
        if cfg.events[key] then
            local challenge = self.adapter:CurrentChallenge(kind)
            if not self.scope.alive or self.config.data.game ~= cfg or not cfg.enabled or cfg.type ~= "event" then
                return false, "cancelled"
            end
            if cfg.events[key] and challenge and self.challengeMethod(challenge.levelId, kind) then
                local success, detail = self.adapter:StartChallenge(challenge, cfg.play_mode)
                if success then self.challengePendingUntil = os.clock() + 45 end
                if detail ~= "missing_challenge_lobby" then return success, detail end
            end
        end
    end
end

function GameService:_StartSolo(mode, id, difficulty)
    local lobby
    if mode == "event" and self.adapter.EventLobby then lobby = self.adapter:EventLobby(id) end
    if not lobby then
        local categories = ({story = {"Story"}, raids = {"Raids", "Raid"}, legend = {"Legend", "Story"},
            infinity = {"Infinite", "Infinity"}, event = {"Event"}})[mode] or {}
        for _, category in ipairs(categories) do
            for _, item in ipairs(self.adapter:Lobbies(category)) do
                if item.available then lobby = item.value; break end
            end
            if lobby then break end
        end
    end
    if not lobby then return false, "missing_lobby" end
    local joined, joinError = self.adapter:JoinLobby(lobby)
    if not joined then return false, joinError end
    -- Shared event rooms with `requires_owner = false` own their countdown and
    -- teleport lifecycle. Joining is the complete request; attempting to lock
    -- or start somebody else's room returns false after a valid join.
    if mode == "event" and self.adapter.LobbyRequiresOwner
        and self.adapter:LobbyRequiresOwner(lobby) == false then
        return true, "joined_countdown"
    end
    local locked, lockError = self.adapter:LockLevel(lobby, id, difficulty or "Normal", self.config:Get("game.friends_only"))
    if not locked then return false, lockError end
    return self.adapter:StartLobby(lobby)
end

-- Explicit button action; auto-play being disabled must not prevent a manual start.
function GameService:StartSelected(automatic)
    if self.autoSummon and self.autoSummon.BlocksFarm and self.autoSummon:BlocksFarm() then
        if self.logs then self.logs:Info("game_start_waiting", {code = "summoning"}) end
        return false, "summoning"
    end
    if self.lobbyUtilities and self.lobbyUtilities.BlocksFarm and self.lobbyUtilities:BlocksFarm() then
        if self.logs then self.logs:Info("game_start_waiting", {code = "capsules"}) end
        return false, "capsules"
    end
    if self.adapter.LobbyActionBusy and self.adapter:LobbyActionBusy() then
        if self.logs then self.logs:Info("game_start_waiting", {code = "lobby_action"}) end
        return false, "lobby_action"
    end
    if not self.adapter:InLobby() or self.matchmakingBusy then
        if self.logs then self.logs:Warn("game_start_rejected", {code = self.matchmakingBusy and "busy" or "not_lobby"}) end
        return false
    end
    local cfg = self.config.data.game
    self.matchmakingBusy = true
    local ok, success, detail = pcall(function()
        if cfg.type == "portals" then
            if not self.portalFarm then return false, "portals_unavailable" end
            return self.portalFarm:StartSelected()
        end
        if cfg.type == "dungeon" then return self.adapter:DungeonStep(cfg.dungeon) end
        if cfg.type == "infinity_castle" then
            return self.adapter:StartInfinityCastle(cfg.infinity_castle.floor, cfg.infinity_castle.difficulty)
        end
        if cfg.type == "event" then
            if automatic then
                local started, detail = self:_StartPriorityChallenge(cfg)
                if started ~= nil then return started, detail end
            end
            local id = self.adapter:ResolveEventId(cfg.events.event_id)
            if not id then return false, "missing_event" end
            self.config:Set("game.events.event_id", id)
            if cfg.play_mode == "matchmaking" then return self.adapter:StartEvent(id) end
            return self:_StartSolo("event", id, "Normal")
        end
        local fields = {story = "storymode", legend = "legend", raids = "raids", infinity = "infinity"}
        local options = cfg[fields[cfg.type]]
        if not options then return false, "missing_mode" end
        if not self.adapter.mapCatalog and self.adapter.MapCatalog then self.adapter:MapCatalog(false) end
        local id = self.adapter:SelectedLevel(cfg.type, options.world_id, options.level_id)
        if not id then return false, "missing_level" end
        if cfg.play_mode == "matchmaking" then return self.adapter:Call("request_matchmaking", id) end
        return self:_StartSolo(cfg.type, id, cfg.type == "story" and options.difficulty or "Normal")
    end)
    self.matchmakingBusy = false
    if not ok then
        if self.logs then self.logs:Error("game_start_failed", success, {stage = "request"}) end
        return false, "request_failed"
    end
    if self.logs then
        local fields = {automatic = automatic == true, game_type = cfg.type, play_mode = cfg.play_mode}
        if success then self.logs:Info("game_start_requested", fields)
        else self.logs:Error("game_start_failed", detail, fields) end
    end
    return success, detail
end

function GameService:_Vote()
    if not self.config:Get("game.vote_start") or self.startSent then return end
    local started = Util.find(workspace, "_DATA.GameStarted")
    if started and started.Value then self.scheduler:Remove("vote"); return end
    local vote = Util.find(workspace, "_DATA.VoteStart.StartTime")
    if vote then self.adapter:Call("vote_start") end
end

function GameService:_Move()
    if not self.config:Get("game.player_simulate") then return end
    local finished = Util.find(workspace, "_DATA.GameFinished")
    if finished and finished.Value then return end
    local character = self.adapter.player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local spawn = workspace:FindFirstChild("initial_spawn")
    if humanoid and spawn and spawn:IsA("BasePart") then
        humanoid:MoveTo(spawn.Position + Vector3.new(math.random(-20, 20), 0, math.random(-20, 20)))
    end
end

function GameService:_Attach()
    if self.adapter:InLobby() then
        local popups = self.adapter:Gui("NotificationWindows.Popups")
        if not popups then return false end
        local function fill(child)
            if not self.config:Get("autocaptcha") or child.Name ~= "CaptchaWindow" then return end
            self.scope:Spawn(function()
                local input = child:WaitForChild("TypeBox", 3)
                local text = child:WaitForChild("Captcha", 3)
                if self.scope.alive and input and text and input:IsA("TextBox") and text:IsA("TextLabel") then input.Text = text.Text end
            end)
        end
        self.scope:Connect(popups.ChildAdded, fill)
        for _, child in ipairs(popups:GetChildren()) do fill(child) end
        return true
    end
    local started = Util.find(workspace, "_DATA.GameStarted")
    local finished = Util.find(workspace, "_DATA.GameFinished")
    if not started or not finished then return false end
    local data = self.adapter:GameData()
    if data.id ~= "" then
        if data.mode == "infinite" then self.config:Set("game.infinity.last_id", data.id)
        elseif data.mode == "raid" then self.config:Set("game.raids.last_id", data.id) end
    end
    for _, name in ipairs({"normal_item_added", "unique_item_added", "unit_added"}) do
        local endpoint = self.adapter:Endpoint(name, true)
        if endpoint and endpoint:IsA("RemoteEvent") then
            self.scope:Connect(endpoint.OnClientEvent, function(payload, count)
                self:_CollectReward(name, payload, count)
            end)
        end
    end
    local function reset() self:_ResetMatch() end
    for _, name in ipairs({"replay_started", "match_rematch_started"}) do
        local endpoint = self.adapter:Endpoint(name, true)
        if endpoint and endpoint:IsA("RemoteEvent") then self.scope:Connect(endpoint.OnClientEvent, reset) end
    end
    local gameFinished = self.adapter:Endpoint("game_finished", true)
    if gameFinished and gameFinished:IsA("RemoteEvent") then
        self.scope:Connect(gameFinished.OnClientEvent, function(settings) self:_OnGameFinished(settings) end)
    end
    self.scope:Connect(started.Changed, function(value)
        if value then
            if self.endSent then self:_ResetMatch() end
            self:_OnStart(true)
        end
    end)
    self.scope:Connect(finished.Changed, function(value)
        if value then self:_OnEnd()
        elseif self.endSent then self:_ResetMatch() end
    end)
    if started.Value then self:_OnStart(false) end
    if finished.Value then self:_OnEnd() end
    return true
end

function GameService:_ResetMatch()
    -- replay_started and match_rematch_started can both describe the same reset.
    if not self.startSent and not self.endSent then return false end
    self.matchToken = (self.matchToken or 1) + 1
    self.startSent, self.endSent = false, false
    self.rewards, self.startResources = {}, {}
    self.finishedSettings, self.finishedReport, self.endFinalized = nil, nil, false
    self.matchStartedAt = nil
    self.challengePendingUntil = nil
    self:_Sync()
    return true
end

function GameService:_OnGameFinished(settings)
    if type(settings) ~= "table" then return false end
    self.finishedSettings = Util.copy(settings)
    if not self.endFinalized then self.finishedReport = nil end
    if not self.endSent then self:_OnEnd() end
    return true
end

function GameService:_Report()
    if self.finishedReport then return self.finishedReport end
    local identity = self.adapter.GameData and self.adapter:GameData() or {}
    local duration
    if self.matchStartedAt then duration = math.max(0, os.clock() - self.matchStartedAt) end
    self.finishedReport = MatchReport.normalize(self.finishedSettings or {}, identity,
        {observedStart = self.matchStartedAt ~= nil, duration = duration}, self.rewards)
    return self.finishedReport
end

function GameService:_SnapshotStartResources()
    self.startResources = {}
    if type(self.adapter.Resources) ~= "function" then return end
    for _, resource in ipairs(self.adapter:Resources()) do
        if resource.name ~= "Yen" and resource.name ~= "HolidayStars" then
            self.startResources[resource.name] = resource.value
        end
    end
end

function GameService:_CollectReward(event, payload, count)
    local unit = event == "unit_added"
    local id = payload
    if type(payload) == "table" then id = payload[unit and "unit_id" or "item_id"] end
    if type(id) ~= "string" or id == "" or id:lower():gsub("%s+", "") == "holidaystars" then return end
    count = event == "normal_item_added" and (tonumber(count) or 1) or 1
    if count < 1 or count > 1e12 or count % 1 ~= 0 then return end
    local metadata = unit and self.adapter.UnitMetadata or not unit and self.adapter.ItemMetadata
    local item = metadata and metadata(self.adapter, id)
    local name = type(item) == "table" and type(item.name) == "string" and item.name ~= "" and item.name or id
    self.rewards[name] = (self.rewards[name] or 0) + count
    if self.logs then self.logs:Info("reward_collected", {source = event, item = name, count = count}) end
end

function GameService:_Notify(event, rewards, setting)
    local function send(channel, service)
        if not service then return end
        if setting and not NotificationSettings.enabled(self.config, channel, setting) then return end
        local queued, immediate = service:Send(event, rewards, function(result)
            if not self.logs then return end
            local fields = {channel = channel, notification = event, status = result.status, attempts = result.attempts,
                provider_code = result.discordCode}
            if result.ok then self.logs:Info("notification_sent", fields)
            else self.logs:Error("notification_failed", result, fields) end
        end)
        if not self.logs then return end
        if queued then self.logs:Debug("notification_queued", {channel = channel, notification = event})
        else self.logs:Error("notification_rejected", immediate, {channel = channel, notification = event}) end
    end
    send("discord", self.webhook)
    send("telegram", self.telegram)
end

function GameService:_OnStart(observedTransition)
    if self.startSent then return end
    self.matchToken = self.matchToken or 1
    self.startSent = true
    if observedTransition ~= false then self.matchStartedAt = os.clock() end
    self:_SnapshotStartResources()
    self.scheduler:Remove("vote")
    if self.onStart then self.onStart() end
    self:_Notify("Match started", nil, "settings.ongamestart")
end

function GameService:_OnEnd()
    if self.endSent then return end
    self.endSent = true
    self.endFinalized = false
    local token = self.matchToken or 1
    self.matchToken = token
    if self.logs then
        local wave = workspace:FindFirstChild("_wave_num")
        local rewardTypes, rewardTotal = 0, 0
        for _, count in pairs(self.rewards) do rewardTypes, rewardTotal = rewardTypes + 1, rewardTotal + (tonumber(count) or 0) end
        self.logs:Info("match_finished", {wave = wave and wave.Value, reward_types = rewardTypes, reward_total = rewardTotal})
    end
    self.scheduler:Remove("movement")
    self.scheduler:Remove("vote")
    local function finalize(attempt)
        self.scope:Delay(attempt == 1 and 3 or 0.5, function()
        if token ~= self.matchToken or not self.endSent then return end
        -- GameFinished is only a lifecycle trigger. The authoritative
        -- game_finished payload can arrive several frames later (and did so
        -- after the old 3-second settle in live acceptance). Wait a bounded
        -- window before classifying the result as unknown.
        if not self.finishedSettings and attempt < 19 then finalize(attempt + 1); return end
        if self.endFinalized then return end
        self.endFinalized = true
        for name, initial in pairs(self.startResources) do
            local gained = self.adapter:Resource(name) - initial
            if gained > 0 then self.rewards[name] = gained end
        end
        local smartActive = self.config:Get("smartfarm.enabled") == true
        local report = self:_Report()
        local normalized = {}
        for name, amount in pairs(report.rewards) do
            local metadata = type(self.adapter.ItemMetadata) == "function" and self.adapter:ItemMetadata(name)
                or type(self.adapter.UnitMetadata) == "function" and self.adapter:UnitMetadata(name)
            local label = type(metadata) == "table" and type(metadata.name) == "string" and metadata.name or name
            normalized[label] = (normalized[label] or 0) + amount
        end
        report.rewards = normalized
        if self.matchStats then self.matchStats:Accept(report); report.stats = self.matchStats:Snapshot() end
        local portalActive = self.portalFarm and self.portalFarm.OwnsMatch and self.portalFarm:OwnsMatch(report)
        if portalActive then self.portalFarm:NoteMatchEnd(report) end
        if self.smartFarm and self.smartFarm.NoteMatchEnd then self.smartFarm:NoteMatchEnd(report) end
        local function sendReport(channel, service)
            if not service or not NotificationSettings.enabled(self.config, channel, "settings.ongameend") then return end
            if type(service.SendReport) == "function" then service:SendReport(report)
            else service:Send("Match finished", self.rewards) end
        end
        sendReport("discord", self.webhook); sendReport("telegram", self.telegram)
        if smartActive then
            if self.config:Get("smartfarm.enabled") then self.adapter:Call("teleport_back_to_lobby") end
            return
        end
        if portalActive or (self.config:Get("game.enabled") and self.config:Get("game.type") == "portals") then
            self.adapter:Call("teleport_back_to_lobby")
            return
        end
        if not self.config:Get("game.enabled") then return end
        local cfg = self.config.data.game
        local match = self.adapter.GameData and self.adapter:GameData()
        if (match and match.challenge) or (cfg.type == "event" and (cfg.events.priorityDaily or cfg.events.priorityNormal)) then
            self.adapter:Call("teleport_back_to_lobby")
            return
        end
        if cfg.type == "infinity_castle" then
            if cfg.infinity_castle.advance then self.adapter:Call("request_start_infinite_tower_from_game")
            elseif cfg.infinity_castle.replay then self.adapter:Call("set_game_finished_vote", "replay") end
            return
        end
        if cfg.type == "dungeon" then return end -- DungeonStep owns room/treasure/shop progression.
        local fields = {event = "events", legend = "legend", holiday = "holidayhunt", contracts = "contracts", raids = "raids", story = "storymode", infinity = "infinity"}
        local mode = cfg[fields[cfg.type]]
        if not mode then return end
        if cfg.type == "story" and mode.next then self.adapter:Call("set_game_finished_vote", "next_story")
        elseif mode.replay then self.adapter:Call("set_game_finished_vote", "replay")
        elseif cfg.endless and cfg.play_mode == "matchmaking" then self.adapter:Call("teleport_back_to_lobby")
        elseif cfg.endless then self.adapter:Call("set_game_finished_vote", "replay") end
        end)
    end
    finalize(1)
end

function GameService:Destroy() self.scope:Destroy() end

return GameService
end

__modules["game/InventoryAutomation"] = function(require)
local Inventory = {}
Inventory.__index = Inventory

local weights = {Common = 1, Rare = 2, Epic = 3, Legendary = 4, Exclusive = 5, Mythic = 6, Secret = 7}
local protectedRarity = {Mythic = true, Secret = true, Exclusive = true}

local function score(unit, strategy)
    strategy = strategy or "balanced"
    local rarity = (weights[unit.rarity] or 0) * 100000
    local level = (tonumber(unit.level) or 0) * (strategy == "level" and 1000 or 100)
    local shiny = unit.shiny and (strategy == "rarity" and 10 or 5000) or 0
    local trait = unit.trait and (strategy == "rarity" and 5 or 3000) or 0
    return rarity + level + shiny + trait,
        {rarity = rarity, level = level, shiny = shiny, trait = trait, strategy = strategy}
end

function Inventory.new(context)
    return setmetatable({scope = context.scope:Child(), config = context.config, api = context.adapter,
        logs = context.sessionLogs, busy = false}, Inventory)
end

local function copySlots(source)
    local result = {}
    for index = 1, 6 do result[index] = source[index] end
    return result
end

local function exactSlots(current, expected, limit)
    for index = 1, limit do
        if current[index] ~= expected[index] then return false, index end
    end
    return true
end

local function locate(slots, uuid, limit)
    for index = 1, limit do if slots[index] == uuid then return index end end
end

function Inventory:BestTeam(limit, strategy)
    local units = self.api:InventoryUnits()
    local result = {}
    for _, unit in ipairs(units) do
        if unit.metadataKnown and unit.rarity then
            local copy = {}; for key, value in pairs(unit) do copy[key] = value end
            result[#result + 1] = copy
        end
    end
    table.sort(result, function(a, b)
        local sa = score(a, strategy)
        local sb = score(b, strategy)
        return sa == sb and a.uuid < b.uuid or sa > sb
    end)
    while #result > (limit or 6) do table.remove(result) end
    for _, unit in ipairs(result) do unit.score, unit.scoreBreakdown = score(unit, strategy) end
    return result
end

function Inventory:EquipPlan(limit)
    local strategy = self.config.data.inventory.team_strategy or "balanced"
    local best = self:BestTeam(limit or 6, strategy)
    local changes, unchanged = {}, 0
    for slot, unit in ipairs(best) do
        local current = tonumber(unit.equipped)
        if current == slot then unchanged = unchanged + 1
        else changes[#changes + 1] = {slot = slot, unit = unit, fromSlot = current} end
    end
    return {team = best, changes = changes, unchanged = unchanged, automatic = false,
        reason = "live_acceptance_required"}
end

function Inventory:_Slots(limit)
    if not self.api.InventorySlots then return nil, "slots_unavailable" end
    local slots, status = self.api:InventorySlots()
    if status ~= "ready" or type(slots) ~= "table" then return nil, status or "slots_unavailable" end
    local result = copySlots(slots)
    for index = 1, limit do
        local uuid = result[index]
        if uuid ~= nil and (type(uuid) ~= "string" or uuid == "" or #uuid > 128 or uuid:find("%c")) then
            return nil, "invalid_slot"
        end
    end
    return result
end

function Inventory:_WaitReceipt(check)
    local deadline = os.clock() + 5
    repeat
        if not self.scope.alive then return false, "destroyed" end
        local slots, reason = self:_Slots(6)
        if not slots then return false, reason end
        if check(slots) then return true end
        task.wait(0.05)
    until os.clock() >= deadline
    return false, "receipt_timeout"
end

function Inventory:_Call(name, ...)
    local arguments = table.pack(...)
    for _ = 1, 5 do
        local ok, reason = self.api:Call(name, table.unpack(arguments, 1, arguments.n))
        if ok then return true end
        if reason ~= "busy" then return false, reason or "rejected" end
        task.wait(0.5)
    end
    return false, "busy"
end

function Inventory:_Unequip(uuid)
    local ok, reason = self:_Call("unequip_unit", uuid)
    if not ok then return false, reason end
    return self:_WaitReceipt(function(slots) return locate(slots, uuid, 6) == nil end)
end

function Inventory:_Equip(uuid, slot, automatic)
    local ok, reason
    if automatic then ok, reason = self:_Call("equip_unit", uuid)
    else ok, reason = self:_Call("equip_unit", uuid, tostring(slot)) end
    if not ok then return false, reason end
    local confirmed, receipt = self:_WaitReceipt(function(slots) return slots[slot] == uuid end)
    if confirmed then task.wait(0.5) end -- Respect Adapter's per-endpoint debounce before the next slot.
    return confirmed, receipt
end

function Inventory:_ApplyExact(expected, limit)
    local current, reason = self:_Slots(limit)
    if not current then return false, reason, 0 end
    local desired = {}
    for slot = 1, limit do
        local uuid = expected[slot]
        if type(uuid) ~= "string" or uuid == "" then return false, "incomplete_team", 0 end
        if desired[uuid] then return false, "duplicate_unit", 0 end
        desired[uuid] = slot
    end
    local receipts = 0

    -- A unit already equipped in another slot cannot be moved by equip_unit;
    -- native UI returns success without changing profile state. Unequip only
    -- those conflicts first, then refill the resulting holes in slot order.
    for slot = 1, limit do
        local uuid = current[slot]
        if uuid and desired[uuid] and desired[uuid] ~= slot then
            local ok
            ok, reason = self:_Unequip(uuid)
            if not ok then return false, "unequip_" .. tostring(reason), receipts end
            receipts = receipts + 1
            current, reason = self:_Slots(limit)
            if not current then return false, reason, receipts end
        end
    end

    -- When the loadout is not full the native contract accepts no slot and
    -- fills the first free slot. Ascending holes make that deterministic.
    for slot = 1, limit do
        current, reason = self:_Slots(limit)
        if not current then return false, reason, receipts end
        if current[slot] == nil then
            local uuid = expected[slot]
            if locate(current, uuid, limit) then return false, "unit_still_equipped", receipts end
            local ok
            ok, reason = self:_Equip(uuid, slot, true)
            if not ok then return false, "equip_" .. tostring(reason), receipts end
            receipts = receipts + 1
        end
    end

    -- The team is full now, so explicit string slot keys perform native
    -- replacement for remaining non-target units.
    for slot = 1, limit do
        current, reason = self:_Slots(limit)
        if not current then return false, reason, receipts end
        if current[slot] ~= expected[slot] then
            if locate(current, expected[slot], limit) then return false, "unit_still_equipped", receipts end
            local ok
            ok, reason = self:_Equip(expected[slot], slot, false)
            if not ok then return false, "equip_" .. tostring(reason), receipts end
            receipts = receipts + 1
        end
    end
    current, reason = self:_Slots(limit)
    local exact, slot = current and exactSlots(current, expected, limit)
    return exact == true, exact and nil or (reason or "slot_" .. tostring(slot) .. "_mismatch"), receipts
end

function Inventory:EquipBest(limit)
    limit = math.max(1, math.min(6, math.floor(tonumber(limit) or 6)))
    if self.busy then return false, {code = "busy", restored = true} end
    if not self.scope.alive then return false, {code = "destroyed", restored = false} end
    if not self.api.InLobby or not self.api:InLobby() then return false, {code = "lobby_only", restored = true} end
    local owner = {}
    if self.api.AcquireLobbyAction and not self.api:AcquireLobbyAction(owner) then
        return false, {code = "lobby_busy", restored = true}
    end
    self.busy = true
    local ok, success, report = pcall(function()
        local original, reason = self:_Slots(limit)
        if not original then return false, {code = reason, restored = true} end
        for index = 1, limit do
            if not original[index] then return false, {code = "incomplete_current_team", restored = true} end
        end
        local plan = self:EquipPlan(limit)
        if #plan.team ~= limit then return false, {code = "incomplete_best_team", restored = true} end
        local target = {}
        for index, unit in ipairs(plan.team) do target[index] = unit.uuid end
        local exact = exactSlots(original, target, limit)
        if exact then return true, {code = "already_best", receipts = 0, changes = 0, restored = true} end
        local applyOk, applied, code, receipts = pcall(self._ApplyExact, self, target, limit)
        if not applyOk then
            code, receipts = "runtime_error", 0
            if self.logs then self.logs:Error("inventory_equip_apply_failed", applied) end
            applied = false
        end
        if applied then
            return true, {code = "equipped", receipts = receipts, changes = #plan.changes, restored = true}
        end
        local restoreOk, restored, restoreCode, restoreReceipts = pcall(self._ApplyExact, self, original, limit)
        if not restoreOk then restored, restoreCode, restoreReceipts = false, "runtime_error", 0 end
        return false, {code = code or "unconfirmed", receipts = receipts, changes = #plan.changes,
            restored = restored == true, restoreCode = restoreCode, restoreReceipts = restoreReceipts or 0}
    end)
    self.busy = false
    if self.api.ReleaseLobbyAction then self.api:ReleaseLobbyAction(owner) end
    if not ok then
        if self.logs then self.logs:Error("inventory_equip_failed", success) end
        return false, {code = "runtime_error", restored = false}
    end
    if self.logs then
        if success then self.logs:Info("inventory_equip_confirmed", {changes = report.changes, receipts = report.receipts})
        else self.logs:Error("inventory_equip_failed", report.code, {restored = report.restored}) end
    end
    return success, report
end

function Inventory:SellPreview()
    local units = self.api:InventoryUnits()
    local settings = self.config.data.inventory.sell_preview
    local eligible, protected = {}, 0
    for _, unit in ipairs(units) do
        local rarityKey = type(unit.rarity) == "string" and unit.rarity:lower() or ""
        local safe = unit.metadataKnown and unit.lockKnown and not unit.locked and not unit.equipped
            and not unit.shiny and not unit.trait and not protectedRarity[unit.rarity]
            and settings[rarityKey] == true
        if safe then eligible[#eligible + 1] = unit else protected = protected + 1 end
    end
    table.sort(eligible, function(a, b)
        local sa = score(a, "balanced")
        local sb = score(b, "balanced")
        return sa == sb and a.uuid < b.uuid or sa < sb
    end)
    local result, maximum = {}, math.max(0, #units - 6)
    for index = 1, math.min(maximum, #eligible) do result[index] = eligible[index] end
    protected = #units - #result
    return result, protected
end

function Inventory:SellPlan()
    local units, protected = self:SellPreview()
    local batches = {}
    for index, unit in ipairs(units) do
        local batchIndex = math.floor((index - 1) / 20) + 1
        batches[batchIndex] = batches[batchIndex] or {}
        batches[batchIndex][#batches[batchIndex] + 1] = unit
    end
    return {units = units, batches = batches, protected = protected, automatic = false,
        receipt = "unit_removed", reason = "live_acceptance_required"}
end

function Inventory:Destroy() self.scope:Destroy() end
return Inventory
end

__modules["game/LobbyShops"] = function(require)
local Scheduler = require("core/Scheduler")
local Signal = require("core/Signal")

local Shops = {}
Shops.__index = Shops

local function identifier(value)
    return type(value) == "string" and #value > 0 and #value <= 128 and value:match("^[%w_:%-]+$") ~= nil
end

local function selection(value)
    local result = {}
    for id in tostring(value or ""):gmatch("[^,]+") do
        if identifier(id) then result[id] = true end
    end
    return result
end

local function encodeSelection(items)
    local result = {}
    for id, selected in pairs(items or {}) do
        if selected == true and identifier(id) then result[#result + 1] = id end
    end
    table.sort(result)
    return table.concat(result, ",")
end

local function legacyEnabled(settings, offer)
    return offer.policy and settings[offer.policy] == true
end

local function enabled(settings, offer)
    if settings.use_selection == true then return selection(settings.selected_items)[offer.id] == true end
    return legacyEnabled(settings, offer)
end

Shops.DecodeSelection = selection
Shops.EncodeSelection = encodeSelection

local function reserve(settings, currency)
    return tonumber(settings[currency == "Gems" and "gem_reserve" or "gold_reserve"]) or 0
end

local function affordable(api, settings, offer, quantity, spent)
    local price = offer.price * quantity
    local wallet = api:Resource(offer.currency)
    local limit = tonumber(settings.max_spend) or 0
    return wallet - price >= reserve(settings, offer.currency)
        and (limit == 0 or spent + price <= limit), price
end

local function quantity(settings, offer, api, spent)
    if offer.locked then return nil end
    local requested = tonumber(settings.quantity) or 1
    for _, candidate in ipairs({100, 10, 1}) do
        if candidate <= requested and candidate <= offer.available and affordable(api, settings, offer, candidate, spent) then
            return candidate
        end
    end
end

function Shops.new(context)
    local self = setmetatable({scope = context.scope:Child(), config = context.config, api = context.adapter,
        logs = context.sessionLogs, attempted = {}, spent = {}, Changed = Signal.new()}, Shops)
    self.scope:Add(self.Changed)
    self.scheduler = Scheduler.new(self.scope:Child())
    if self.config.Changed then
        self.scope:Connect(self.config.Changed, function(path) if path:match("^lobby%.shops") then self:_Sync() end end)
    end
    self:_Sync()
    return self
end

function Shops:_Sync()
    self.scheduler:Remove("shops")
    local cfg = self.config.data.lobby.shops
    if self.api:InLobby() and (cfg.merchant.enabled or cfg.gold.enabled) then
        self.scheduler:Set("shops", 5, function() self:Tick() end, true)
    end
end

function Shops:_SetGoldInterval(interval)
    if interval == nil or self.goldInterval == interval then return end
    self.goldInterval, self.spent = interval, {}
    for key in pairs(self.attempted) do if key:sub(1, 5) == "gold:" then self.attempted[key] = nil end end
end

function Shops:_Offers(kind)
    if kind == "merchant" then return self.api:MerchantOffers() end
    if kind == "gold" then return self.api:GoldShopOffers() end
    return {}
end

function Shops:SetItemEnabled(kind, id, value)
    if (kind ~= "merchant" and kind ~= "gold") or not identifier(id) or type(value) ~= "boolean" then return false end
    local settings = self.config.data.lobby.shops[kind]
    if type(settings) ~= "table" then return false end
    local selected = selection(settings.selected_items)
    if settings.use_selection ~= true then
        for _, offer in ipairs(self:_Offers(kind)) do
            if legacyEnabled(settings, offer) then selected[offer.id] = true end
        end
        self.config:Set("lobby.shops." .. kind .. ".use_selection", true)
    end
    selected[id] = value and true or nil
    self.config:Set("lobby.shops." .. kind .. ".selected_items", encodeSelection(selected))
    return true
end

function Shops:Preview()
    local merchant, _, merchantStatus = self.api:MerchantOffers()
    local gold, interval, goldStatus = self.api:GoldShopOffers()
    self:_SetGoldInterval(interval)
    local cfg = self.config.data.lobby.shops
    local function plan(kind, offers, settings, currentInterval)
        local rows, spent = {}, currentInterval and (self.spent[currentInterval] or 0) or 0
        for _, offer in ipairs(offers) do
            local key = kind == "merchant" and "merchant:" .. offer.key
                or "gold:" .. tostring(currentInterval) .. ":" .. offer.id
            local count
            if kind == "merchant" then
                local canBuy = affordable(self.api, settings, offer, 1, 0)
                count = canBuy and 1 or nil
            else count = quantity(settings, offer, self.api, spent) end
            local allowed = enabled(settings, offer)
            local status = offer.locked and "locked" or not allowed and "disabled" or self.attempted[key] and "attempted"
                or offer.available < 1 and "sold_out" or not count and "budget" or "ready"
            local price = count and offer.price * count or 0
            rows[#rows + 1] = {id = offer.id, currency = offer.currency, available = offer.available,
                quantity = count or 0, cost = price, status = status, policy = offer.policy, selected = allowed}
        end
        return rows
    end
    return {merchant = merchant, merchantPlan = plan("merchant", merchant, cfg.merchant), merchantStatus = merchantStatus,
        gold = gold, goldPlan = plan("gold", gold, cfg.gold, interval), goldInterval = interval,
        goldSpent = interval and (self.spent[interval] or 0) or 0, goldStatus = goldStatus,
        contracts = {merchant = "buy_travelling_merchant_item → offer removed",
            gold = "buy_gold_shop_item → stock decreased"}}
end

function Shops:_Receipt(kind, offer, interval)
    local deadline = os.clock() + 3
    repeat
        local offers = kind == "merchant" and self.api:MerchantOffers() or self.api:GoldShopOffers()
        local found
        for _, current in ipairs(offers) do
            if current.key == offer.key and (kind ~= "gold" or current.interval == interval) then found = current; break end
        end
        if not found or found.available < offer.available then return true end
        task.wait(0.1)
    until not self.scope.alive or os.clock() >= deadline
    return false
end

function Shops:_BuyMerchant(settings)
    local offers = self.api:MerchantOffers()
    for _, offer in ipairs(offers) do
        local key = "merchant:" .. offer.key
        if enabled(settings, offer) and not self.attempted[key] and affordable(self.api, settings, offer, 1, 0) then
            self.attempted[key] = true
            local ok, reason = self.api:BuyMerchantOffer(offer.key)
            local confirmed = ok and self:_Receipt("merchant", offer)
            self.Changed:Fire({shop = "merchant", id = offer.id, confirmed = confirmed, reason = reason})
            return true
        end
    end
end

function Shops:_BuyGold(settings)
    local offers, interval = self.api:GoldShopOffers()
    if interval == nil then return end
    self:_SetGoldInterval(interval)
    local spent = self.spent[interval] or 0
    for _, offer in ipairs(offers) do
        local key = "gold:" .. tostring(interval) .. ":" .. offer.id
        local count = not offer.locked and enabled(settings, offer) and not self.attempted[key]
            and quantity(settings, offer, self.api, spent)
        if count then
            self.attempted[key] = true
            local ok, reason = self.api:BuyGoldOffer(offer.id, tostring(count))
            local confirmed = ok and self:_Receipt("gold", offer, interval)
            if confirmed then self.spent[interval] = spent + offer.price * count end
            self.Changed:Fire({shop = "gold", id = offer.id, quantity = count, confirmed = confirmed, reason = reason})
            return true
        end
    end
end

function Shops:Tick()
    if self.busy or not self.scope.alive or not self.api:InLobby() then return false end
    local owner = {}
    if self.api.AcquireLobbyAction and not self.api:AcquireLobbyAction(owner) then return false end
    self.busy = true
    local cfg = self.config.data.lobby.shops
    local restoreGoldShop
    local ok, acted = pcall(function()
        if cfg.merchant.enabled and self:_BuyMerchant(cfg.merchant) then return true end
        if cfg.gold.enabled then
            if type(self.api.EnterGoldShop) == "function" then
                restoreGoldShop = self.api:EnterGoldShop()
                if not restoreGoldShop then return false end
            end
            if self:_BuyGold(cfg.gold) then return true end
        end
        return false
    end)
    if restoreGoldShop then pcall(restoreGoldShop) end
    self.busy = false
    if self.api.ReleaseLobbyAction then self.api:ReleaseLobbyAction(owner) end
    if not ok and self.logs then self.logs:Error("shop_automation_failed", acted) end
    return ok and acted == true
end

function Shops:Destroy() self.scope:Destroy() end

return Shops
end

__modules["game/LobbyUtilities"] = function(require)
local Scheduler = require("core/Scheduler")
local Signal = require("core/Signal")

local Utilities = {}
Utilities.__index = Utilities

function Utilities.new(context)
    local self = setmetatable({scope = context.scope:Child(), config = context.config, api = context.adapter,
        attemptedCapsules = {}, attemptedInvites = {}, Changed = Signal.new()}, Utilities)
    self.scope:Add(self.Changed)
    self.scheduler = Scheduler.new(self.scope:Child())
    local rewards = self.api:Endpoint("show_unit_and_item_rewards", true)
    if rewards and rewards:IsA("RemoteEvent") then
        self.scope:Connect(rewards.OnClientEvent, function() self.rewardReceipt = (self.rewardReceipt or 0) + 1 end)
    end
    if self.config.Changed then
        self.scope:Connect(self.config.Changed, function(path)
            if path:match("^lobby%.utilities") then self:_Sync() end
        end)
    end
    self:_Sync()
    return self
end

function Utilities:Preview()
    local capsules, capsuleStatus = self.api:CapsuleInventory()
    local invites, inviteStatus = self.api:PartyInvites()
    return {capsules = capsules, capsuleStatus = capsuleStatus, invites = invites,
        inviteStatus = inviteStatus, lastAction = self.lastAction,
        contracts = {capsule = "use_item → normal_item_removed + show_unit_and_item_rewards",
            party = "party_respond_invite → party_invite_cleared"}}
end

function Utilities:_Sync()
    self.scheduler:Remove("utilities")
    local cfg = self.config.data.lobby.utilities
    if self.api:InLobby() and (cfg.capsules.enabled or cfg.party.auto_accept) then
        self.scheduler:Set("utilities", 4, function() self:Tick() end, true)
    end
end

function Utilities:_CapsuleReceipt(id, before, quantity, receiptBefore)
    local deadline = os.clock() + 5
    repeat
        local rows = self.api:CapsuleInventory()
        local current = 0
        for _, row in ipairs(rows) do if row.id == id then current = row.count; break end end
        if current <= before - quantity and (self.rewardReceipt or 0) > receiptBefore then return true end
        task.wait(0.1)
    until not self.scope.alive or os.clock() >= deadline
    return false
end

function Utilities:_InviteReceipt(name)
    local deadline = os.clock() + 3
    repeat
        local rows = self.api:PartyInvites()
        local found = false
        for _, row in ipairs(rows) do if row.name == name then found = true; break end end
        if not found then return true end
        task.wait(0.1)
    until not self.scope.alive or os.clock() >= deadline
    return false
end

function Utilities:_AcceptParty()
    if not self.config:Get("lobby.utilities.party.auto_accept") then return false end
    local invites = self.api:PartyInvites()
    for _, invite in ipairs(invites) do
        if not self.attemptedInvites[invite.name] then
            self.attemptedInvites[invite.name] = true
            local ok, reason = self.api:RespondPartyInvite(invite.name, true)
            local confirmed = ok and self:_InviteReceipt(invite.name)
            if confirmed then self.attemptedInvites[invite.name] = nil end
            self.lastAction = {kind = "party", name = invite.name, confirmed = confirmed, reason = reason}
            self.Changed:Fire(self.lastAction)
            return true
        end
    end
    return false
end

function Utilities:_OpenCapsule()
    local cfg = self.config.data.lobby.utilities.capsules
    if not cfg.enabled then return false end
    local capsules = self.api:CapsuleInventory()
    for _, capsule in ipairs(capsules) do
        if not capsule.locked and not self.attemptedCapsules[capsule.id] then
            local quantity = cfg.batch == 10 and capsule.count >= 10 and 10 or 1
            self.attemptedCapsules[capsule.id] = true
            local receiptBefore, countBefore = self.rewardReceipt or 0, capsule.count
            local ok, reason = self.api:UseCapsule(capsule.id, quantity)
            local confirmed = ok and self:_CapsuleReceipt(capsule.id, countBefore, quantity, receiptBefore)
            if confirmed then self.attemptedCapsules[capsule.id] = nil end
            self.lastAction = {kind = "capsule", id = capsule.id, quantity = quantity,
                confirmed = confirmed, reason = reason}
            self.Changed:Fire(self.lastAction)
            return true
        end
    end
    return false
end

function Utilities:BlocksFarm()
    if not self.api:InLobby() or not self.config:Get("lobby.utilities.capsules.enabled") then return false end
    if self.busy then return true end
    for _, capsule in ipairs(self.api:CapsuleInventory()) do
        if not capsule.locked and not self.attemptedCapsules[capsule.id] then return true end
    end
    return false
end

function Utilities:Tick()
    if self.busy or not self.scope.alive or not self.api:InLobby() then return false end
    local owner = {}
    if self.api.AcquireLobbyAction and not self.api:AcquireLobbyAction(owner) then return false end
    self.busy = true
    local ok, acted = pcall(function()
        if self:_AcceptParty() then return true end
        return self:_OpenCapsule()
    end)
    self.busy = false
    if self.api.ReleaseLobbyAction then self.api:ReleaseLobbyAction(owner) end
    return ok and acted == true
end

function Utilities:Destroy() self.scope:Destroy() end
return Utilities
end

__modules["game/MacroCapture"] = function(require)
local SaleCapture = require("game/SaleCapture")
local Capture = {}
Capture.__index = Capture

function Capture.new(context)
    local self = setmetatable({scope = context.scope:Child(), api = context.adapter, macros = context.macros,
        saved = context.unitsConfig, watch = nil}, Capture)
    self.pendingActions = setmetatable({}, {__mode = "k"})
    self.pendingTimes = setmetatable({}, {__mode = "k"})
    self.spawnTimes, self.apiHookPending = {}, {}
    local function endpoint(name) return self.api.Endpoint and self.api:Endpoint(name) end
    local routes = {}
    local function route(name, kind)
        local remote = endpoint(name)
        if remote then routes[remote] = {name = name, kind = kind} end
    end
    route("sell_unit_ingame", "sell")
    self.abilityEndpoints = {}
    for _, name in ipairs({"use_active_attack", "activate_unit_ability"}) do
        if endpoint(name) then
            self.abilityEndpoints[name] = true
            route(name, "ability")
        end
    end
    route("upgrade_unit_ingame", "upgrade")
    route("change_priority", "priority")
    route("spawn_unit", "spawn")
    self.nativeSpawnSteps = setmetatable({}, {__mode = "k"})
    self.observer = next(routes) and SaleCapture.new({scope = self.scope, api = self.api,
        environment = context.runtime and context.runtime.env,
        matchEndpoint = function(remote) return routes[remote] end,
        beforeSale = function(unit, argument, routeInfo)
            local kind = routeInfo.kind
            local apiPending = self.apiHookPending[routeInfo.name]
            if apiPending and apiPending.unit == unit and apiPending.tape == self.macros.tape then
                apiPending.hookSeen = true
                return nil -- Adapter BeforeCall/Succeeded owns this exact request.
            end
            if kind == "spawn" then
                local pending = self:_SpawnRequest(unit)
                if pending then self.nativeSpawnSteps[pending] = true end
                return pending
            end
            local step = self:_RequestStep(unit, kind)
            if step and kind == "priority" then
                if type(argument) ~= "string" then return nil end
                step.priority = argument
            end
            return step
        end,
        afterCall = function(step, accepted)
            if self.nativeSpawnSteps[step] and not accepted then step.rejected = true end
        end,
        record = function(step)
            if self.nativeSpawnSteps[step] then return false end -- replication records a spawn
            if self.scope.alive and self.macros.recording then return self.macros:Record(step) end
            return false
        end}) or nil
    -- One exact-endpoint router owns one namecall hook for the whole recording.
    self.scope:Add(function() self:_StopHooks() end)
    self.scope:Connect(self.macros.Changed, function(state) self:_Sync(state.recording) end)
    if self.api.BeforeCall then self.scope:Connect(self.api.BeforeCall, function(name, args)
        if not self.macros.recording or type(args) ~= "table" then return end
        self.apiHookPending[name] = {unit = args[1], argument = args[2], args = args, tape = self.macros.tape}
        if name == "spawn_unit" then
            local pending = self:_SpawnRequest(args[1])
            self.pendingActions[args], self.apiSpawnPending = pending, pending
            return
        end
        local kind = name == "sell_unit_ingame" and "sell" or name == "upgrade_unit_ingame" and "upgrade"
            or name == "change_priority" and "priority"
            or self.abilityEndpoints[name] and "ability"
        if kind then
            local step = self:_RequestStep(args[1], kind)
            if step and kind == "priority" and type(args[2]) == "string" then step.priority = args[2] end
            self.pendingActions[args] = step
        end
    end) end
    if self.api.Succeeded then self.scope:Connect(self.api.Succeeded, function(name, args)
        if type(args) ~= "table" then return end
        local hookPending = self.apiHookPending[name]
        if hookPending and hookPending.args == args then self.apiHookPending[name] = nil end
        local step = self.pendingActions[args]
        self.pendingActions[args] = nil
        if name == "spawn_unit" and self.apiSpawnPending == step then self.apiSpawnPending = nil end
        if step and (name == "sell_unit_ingame" or name == "change_priority" or self.abilityEndpoints[name])
            and self.macros.recording then
            self.macros:Record(step)
        end
    end) end
    if self.api.Failed then self.scope:Connect(self.api.Failed, function(name, reason)
        self.apiHookPending[name] = nil
        local pending = self.apiSpawnPending
        if name == "spawn_unit" and reason ~= "timeout" and reason ~= "busy" and pending
            and pending.tape == self.macros.tape then pending.rejected = true; self.apiSpawnPending = nil end
    end) end
    return self
end

function Capture:_StopHooks()
    if self.observer then self.observer:Stop() end
    self.hookReady = false
end

function Capture:_RequestStep(unit, kind)
    if kind == "ability" and self:_IsAuto(unit) then return nil end
    local step = self:_TypedStep(unit, kind)
    if not step then return nil end
    if kind == "ability" or kind == "upgrade" then
        local stats = unit:FindFirstChild("_stats")
        local value = stats and stats:FindFirstChild(kind == "ability" and "last_active_cast" or "upgrade")
        if value then
            local pending = self.pendingTimes[unit] or {}
            self.pendingTimes[unit] = pending
            pending[kind] = {step = step, before = tonumber(value.Value), expires = os.clock() + 8, tape = self.macros.tape}
            return nil -- the stat change confirms it, without response-time drift
        end
    end
    return step
end

function Capture:_IsAuto(unit)
    local ok, enabled = pcall(function() return unit:GetAttribute("_auto_active") end)
    return ok and enabled == true
end

function Capture:_ConfirmedStep(unit, kind, current)
    local times = self.pendingTimes[unit]
    local pending = times and times[kind]
    if times then times[kind] = nil end
    if pending and not pending.rejected and pending.tape == self.macros.tape and pending.expires >= os.clock()
        and (not pending.before or current > pending.before) then return pending.step end
    return self:_TypedStep(unit, kind)
end

function Capture:_SpawnRequest(uuid)
    if not self.scope.alive or not self.macros.recording or type(uuid) ~= "string" or not self:_Slot(uuid) then return nil end
    local queue, retained = self.spawnTimes[uuid] or {}, {}
    for _, pending in ipairs(queue) do
        if not pending.rejected and pending.tape == self.macros.tape and pending.expires >= os.clock() then
            retained[#retained + 1] = pending
        end
    end
    if #retained >= 1000 then return nil end
    local pending = {wave = self.macros:CurrentWave(), at = self.macros:RecordTime(),
        tape = self.macros.tape, expires = os.clock() + 8}
    retained[#retained + 1] = pending
    self.spawnTimes[uuid] = retained
    return pending
end

function Capture:_SpawnTime(uuid)
    local queue = self.spawnTimes[uuid]
    while queue and #queue > 0 do
        local pending = table.remove(queue, 1)
        if #queue == 0 then self.spawnTimes[uuid] = nil end
        if not pending.rejected and pending.tape == self.macros.tape and pending.expires >= os.clock() then return pending end
    end
end

function Capture:_TypedStep(unit, kind, wave)
    if not self.scope.alive or not self.macros.recording or not unit or not unit:IsA("Model") then return nil end
    local stats = unit:FindFirstChild("_stats")
    local owner, uuid = stats and stats:FindFirstChild("player"), stats and stats:FindFirstChild("uuid")
    if not owner or owner.Value ~= self.api.player or not uuid then return nil end
    local slot = self:_Slot(tostring(uuid.Value))
    if not slot then return nil end
    local ordinal, folder = 0, workspace:FindFirstChild("_UNITS")
    for _, candidate in ipairs(folder and folder:GetChildren() or {}) do
        local data = candidate:FindFirstChild("_stats")
        local player, id = data and data:FindFirstChild("player"), data and data:FindFirstChild("uuid")
        if player and player.Value == self.api.player and id and id.Value == uuid.Value then ordinal = ordinal + 1 end
        if candidate == unit then
            if ordinal < 1 then return nil end
            return {type = kind, slot = slot, ordinal = ordinal, wave = wave == nil and self.macros:CurrentWave() or wave,
                at = self.macros:RecordTime()}
        end
    end
end

function Capture:_SaleStep(unit) return self:_TypedStep(unit, "sell") end

function Capture:_Slot(uuid)
    if uuid == "" then return nil end
    local hotbar = self.api.Hotbar and self.api:Hotbar() or {}
    for index = 1, 6 do
        local current = hotbar[index] and hotbar[index].uuid
        if type(current) ~= "string" or current == "" then current = self.api.unitsIds and self.api.unitsIds[index] end
        if type(current) ~= "string" or current == "" then current = self.saved:Get("unit" .. index .. ".uuid") end
        if current == uuid then return index end
    end
end

local function spawnPosition(hitbox)
    local center = hitbox.Position
    -- The placement cylinder's local X axis is vertical. Its bottom is near
    -- the requested surface, while the animated model pivot moves independently.
    local floor = center.Y - hitbox.Size.X / 2
    local terrain = workspace:FindFirstChild("_terrain")
    if terrain then
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Include
        local nearest = math.huge
        local estimatedFloor = floor
        local origin = Vector3.new(center.X, floor + 1, center.Z)
        for _, surface in ipairs({"ground", "hill"}) do
            local root = terrain:FindFirstChild(surface)
            if root then
                params.FilterDescendantsInstances = {root}
                local hit = workspace:Raycast(origin, Vector3.new(0, -2, 0), params)
                local distance = hit and math.abs(hit.Position.Y - estimatedFloor)
                if distance and distance < nearest then nearest, floor = distance, hit.Position.Y end
            end
        end
    end
    return {x = center.X, y = floor, z = center.Z}
end

function Capture:_Unit(unit, spawned)
    if not self.watch or not self.watch.alive or not unit:IsA("Model") or self.tracked[unit] then return end
    self.tracked[unit] = true
    local watch, wave, at = self.watch, self.macros:CurrentWave(), self.macros:RecordTime()
    local scope = self.folderWatch:Child()
    local ready, pendingAuto = false, {}
    local function recordAuto(event)
        local step = self:_TypedStep(unit, "auto_ability", event.wave)
        if step then step.enabled, step.at = event.enabled, event.at; self.macros:Record(step) end
    end
    local previousAuto = self:_IsAuto(unit)
    local initialAuto = previousAuto and {enabled = true, wave = wave, at = at} or nil
    local ok, autoChanged = pcall(function() return unit:GetAttributeChangedSignal("_auto_active") end)
    if ok and autoChanged then scope:Connect(autoChanged, function()
        local enabled = self:_IsAuto(unit)
        if enabled == previousAuto then return end
        previousAuto = enabled
        if not self.macros.recording or self.watch ~= watch then return end
        local event = {enabled = enabled, wave = self.macros:CurrentWave(), at = self.macros:RecordTime()}
        if ready then recordAuto(event)
        elseif #pendingAuto < 1000 then pendingAuto[#pendingAuto + 1] = event end
    end) end
    scope:Spawn(function()
        local stats = unit:WaitForChild("_stats", 2)
        local owner = stats and stats:WaitForChild("player", 2)
        local uuid = stats and stats:WaitForChild("uuid", 2)
        if not scope.alive or self.watch ~= watch or not unit.Parent or not owner or owner.Value ~= self.api.player or not uuid then
            scope:Destroy(); return
        end
        if not self:_Slot(tostring(uuid.Value)) then scope:Destroy(); return end
        if spawned and self.macros.recording then
            local requestTime = self:_SpawnTime(tostring(uuid.Value))
            if requestTime then wave, at = requestTime.wave, requestTime.at end
            local hitbox = unit:WaitForChild("_hitbox", 2)
            if not scope.alive or self.watch ~= watch or not unit.Parent then scope:Destroy(); return end
            if hitbox and hitbox:IsA("BasePart") then
                local step = self:_TypedStep(unit, "spawn", wave)
                if step then
                    step.position, step.at = spawnPosition(hitbox), at
                    self.macros:Record(step)
                end
            end
        end
        if not scope.alive or self.watch ~= watch then return end
        ready = true
        if spawned and initialAuto then recordAuto(initialAuto) end
        for _, event in ipairs(pendingAuto) do recordAuto(event) end
        pendingAuto = {}
        local lastCast = stats:FindFirstChild("last_active_cast")
        if lastCast then
            local previous = tonumber(lastCast.Value)
            local pending = self.pendingTimes[unit] and self.pendingTimes[unit].ability
            if pending and pending.tape == self.macros.tape and pending.expires >= os.clock()
                and previous and pending.before and previous > pending.before and not self:_IsAuto(unit) then
                local step = self:_ConfirmedStep(unit, "ability", previous)
                if step then self.macros:Record(step) end
            end
            scope:Connect(lastCast.Changed, function(value)
                local current = tonumber(value)
                if previous and current and current > previous and self.macros.recording then
                    if not self:_IsAuto(unit) then
                        local step = self:_ConfirmedStep(unit, "ability", current)
                        if step then self.macros:Record(step) end
                    elseif self.pendingTimes[unit] then self.pendingTimes[unit].ability = nil end
                end
                previous = current
            end)
        end
        local upgrade = stats:FindFirstChild("upgrade")
        if upgrade then
            local previous = tonumber(upgrade.Value) or 0
            local pending = self.pendingTimes[unit] and self.pendingTimes[unit].upgrade
            if pending and pending.tape == self.macros.tape and pending.expires >= os.clock()
                and pending.before and previous > pending.before then
                local step = self:_ConfirmedStep(unit, "upgrade", previous)
                if step then for _ = 1, math.min(100, previous - pending.before) do self.macros:Record(step) end end
            end
            scope:Connect(upgrade.Changed, function(value)
                local current = tonumber(value) or previous
                if current > previous and self.macros.recording then
                    local step = self:_ConfirmedStep(unit, "upgrade", current)
                    if step then
                        for _ = 1, math.min(100, current - previous) do self.macros:Record(step) end
                    end
                end
                previous = current
            end)
        end
        scope:Connect(unit.Destroying, function() scope:Destroy() end)
    end)
end

function Capture:_BindFolder(folder)
    if self.captureFolder == folder then return end
    if self.folderWatch then self.folderWatch:Destroy() end
    self.captureFolder, self.tracked = folder, setmetatable({}, {__mode = "k"})
    self.folderWatch = self.watch:Child()
    self.folderWatch:Connect(folder.ChildAdded, function(unit) self:_Unit(unit, true) end)
    for _, unit in ipairs(folder:GetChildren()) do self:_Unit(unit, false) end
end

function Capture:_Sync(recording)
    if self.watchingRecording == recording then return end
    self.watchingRecording = recording
    if self.watch then self.watch:Destroy(); self.watch = nil end
    self.folderWatch, self.captureFolder = nil, nil
    self.pendingActions = setmetatable({}, {__mode = "k"})
    self.pendingTimes, self.spawnTimes = setmetatable({}, {__mode = "k"}), {}
    self.apiHookPending = {}
    self.nativeSpawnSteps = setmetatable({}, {__mode = "k"})
    self.apiSpawnPending = nil
    self.ready, self.error = false, nil
    -- Keep the one verified router installed but inert between recordings.
    -- Replacing/restoring a DataModel metamethod on every button press is both
    -- unnecessary and unsafe on executors that use a stable hook trampoline.
    if not recording then return end
    local function start(observer)
        if not observer then return true end
        local ok, reason = observer:Start()
        if not ok then self.error = reason or "capture_hook_failed" end
        return ok
    end
    local ok = self.observer ~= nil and (self.hookReady or start(self.observer))
    if not self.observer then self.error = "missing_capture_endpoints" end
    if not ok then self:_StopHooks(); return end
    self.hookReady = true
    self.watch = self.scope:Child()
    local folder = workspace:FindFirstChild("_UNITS")
    if folder then self:_BindFolder(folder) end
    if workspace.ChildAdded then self.watch:Connect(workspace.ChildAdded, function(child)
        if child.Name == "_UNITS" then self:_BindFolder(child) end
    end) end
    self.ready = true
end

function Capture:Status()
    return self.ready == true and self.watchingRecording == true, self.error
end

function Capture:Destroy() self.scope:Destroy() end
return Capture
end

__modules["game/MacroPosition"] = function(require)
local MacroPosition = {}

local function bounded(value, limit)
    return type(value) == "number" and math.abs(value) <= limit
end

function MacroPosition.validate(position, rotationY)
    if position == nil then return rotationY == nil end
    if type(position) ~= "table" or getmetatable(position) ~= nil then return false end
    for key in next, position do
        if key ~= "x" and key ~= "y" and key ~= "z" then return false end
    end
    return bounded(position.x, 1000000) and bounded(position.y, 1000000) and
        bounded(position.z, 1000000) and (rotationY == nil or bounded(rotationY, 2 * math.pi))
end

return MacroPosition
end

__modules["game/MacroRouter"] = function(require)
local Router = {}
Router.__index = Router
local aliases = {infinite = "infinity", raid = "raids", storymode = "story", legend_stage = "legend",
    challenge = "event", portal = "portals"}

function Router.mode(value, levelId)
    if levelId == "summer2_event" then return "event" end
    return aliases[value] or value
end
function Router.matches(library, levelId, mode)
    local names = {}
    mode = Router.mode(mode, levelId)
    for name, enabled in pairs(library.autoEnabled or {}) do
        if enabled and library.items[name] and library.mapBindings[name] == levelId and library.modeBindings[name] == mode then names[#names + 1] = name end
    end
    table.sort(names)
    return names
end

function Router.new(context)
    return setmetatable({scope = context.scope:Child(), library = context.library, engine = context.engine,
        play = context.play, run = nil}, Router)
end
function Router:Start(levelId, mode)
    if self.run then return false, "busy" end
    local names = Router.matches(self.library, levelId, mode)
    if #names == 0 then return false, "no_matching_macro" end
    if #names > 1 then return false, "binding_conflict" end
    local run = self.scope:Child()
    self.run = run
    run:Add(function()
        self.engine:Stop()
        if self.run == run then self.run = nil end
    end)
    run:Spawn(function()
        for _, name in ipairs(names) do
            if not run.alive then return end
            local ok = self.play(name)
            if not ok then break end
            repeat task.wait(0.05) until not self.engine.playing or not run.alive
            if not run.alive or self.engine.error then break end
        end
        run:Destroy()
    end)
    return true
end
function Router:Stop() if self.run then self.run:Destroy(); return true end; return false end
function Router:Destroy() self.scope:Destroy() end
return Router
end

__modules["game/Macros"] = function(require)
local Signal = require("core/Signal")
local MacroPosition = require("game/MacroPosition")
local Macros = {}
Macros.__index = Macros

-- Only spawn steps may carry a placement position and rotation.
local MAX_STEPS, STEP_TIMEOUT, MAX_MAP_TIME = 1000, 120, 86400
local actions = {spawn = true, upgrade = true, ability = true, auto_ability = true, priority = true, sell = true}
local stepFields = {type = true, slot = true, ordinal = true, wave = true, at = true, waveAt = true}
local spawnFields = {type = true, slot = true, ordinal = true, wave = true, position = true, rotationY = true, at = true, waveAt = true}
local autoAbilityFields = {type = true, slot = true, ordinal = true, wave = true, at = true, waveAt = true, enabled = true}
local priorityFields = {type = true, slot = true, ordinal = true, wave = true, at = true, waveAt = true, priority = true}
local priorities = {first = true, last = true, strongest = true, weakest = true, air = true}
local function fields(kind)
    return kind == "spawn" and spawnFields or (kind == "auto_ability" and autoAbilityFields
        or (kind == "priority" and priorityFields or stepFields))
end
local legacyFields = {
    spawn = spawnFields,
    wait = {type = true, seconds = true}, vote_start = {type = true},
    event_start = {type = true, id = true}, lobby_join = {type = true, lobby = true},
    lobby_lock = {type = true, lobby = true, level = true, difficulty = true},
    lobby_start = {type = true, lobby = true},
}
local abilityAliases = {active = true, use_active_attack = true, activate_unit_ability = true}

local function integer(value, minimum, maximum)
    return type(value) == "number" and value == value and value >= minimum and value <= maximum and value % 1 == 0
end

local function validName(value)
    return type(value) == "string" and #value > 0 and #value <= 64 and
        value:find("%S") ~= nil and value:find("[%z\1-\31\127]") == nil
end

local function knownKeys(value, allowed)
    if type(value) ~= "table" or getmetatable(value) ~= nil then return false end
    for key in next, value do if not allowed[key] then return false end end
    return true
end

-- Even discarded legacy fields must be inert; never traverse a metatable or
-- accept executable/cyclic data merely because migration will drop it.
local function inert(value, seen, budget, depth)
    local kind = type(value)
    if kind ~= "table" then return kind == "nil" or kind == "boolean" or kind == "string" or
        (kind == "number" and value == value and value > -math.huge and value < math.huge) end
    if getmetatable(value) ~= nil or seen[value] or depth > 8 then return false end
    seen[value] = true
    for key, child in next, value do
        budget[1] = budget[1] - 1
        if budget[1] < 0 or (type(key) ~= "string" and type(key) ~= "number") or
            not inert(child, seen, budget, depth + 1) then return false end
    end
    seen[value] = nil
    return true
end

local function normalizeStep(step)
    if type(step) ~= "table" or getmetatable(step) ~= nil then return nil, "invalid_step" end
    if type(step.type) ~= "string" or not actions[step.type] then return nil, "unsupported_step" end
    if not knownKeys(step, fields(step.type)) then return nil, "invalid_step_keys" end
    if not integer(step.slot, 1, 6) then return nil, "invalid_slot" end
    if not MacroPosition.validate(step.position, step.rotationY) then return nil, "invalid_position" end
    local result = {type = step.type, slot = step.slot}
    if step.type == "auto_ability" then
        if type(step.enabled) ~= "boolean" then return nil, "invalid_auto_ability" end
        result.enabled = step.enabled
    end
    if step.type == "priority" then
        if type(step.priority) ~= "string" or not priorities[step.priority] then return nil, "invalid_priority" end
        result.priority = step.priority
    end
    if step.position then
        result.position = {x = step.position.x, y = step.position.y, z = step.position.z}
        result.rotationY = step.rotationY
    end
    if step.ordinal ~= nil then
        if not integer(step.ordinal, 1, 100) then return nil, "invalid_ordinal" end
        result.ordinal = step.ordinal
    end
    if step.wave ~= nil then
        if not integer(step.wave, 0, 100000) then return nil, "invalid_wave" end
        if step.wave > 0 then result.wave = step.wave end
    end
    if step.at ~= nil then
        if type(step.at) ~= "number" or not (step.at >= 0 and step.at <= MAX_MAP_TIME) then
            return nil, "invalid_map_time"
        end
        result.at = step.at
    end
    if step.waveAt ~= nil then
        if not result.wave or type(step.waveAt) ~= "number" or not (step.waveAt >= 0 and step.waveAt <= MAX_MAP_TIME) then
            return nil, "invalid_map_time"
        end
        result.waveAt = step.waveAt
    end
    return result
end

function Macros:Validate(macro)
    if not knownKeys(macro, {version = true, name = true, steps = true, clock = true}) then return nil, "invalid_macro" end
    if macro.version ~= 1 and macro.version ~= 2 then return nil, "invalid_version" end
    if not validName(macro.name) then return nil, "invalid_name" end
    if macro.clock ~= nil and macro.clock ~= "battle" and macro.clock ~= "wave" and macro.clock ~= "playback" then
        return nil, "invalid_clock"
    end
    local steps = macro.steps
    if type(steps) ~= "table" or getmetatable(steps) ~= nil then return nil, "invalid_steps" end
    local count = 0
    for key in next, steps do
        count = count + 1
        if count > MAX_STEPS then return nil, "step_limit" end
        if not integer(key, 1, MAX_STEPS) then return nil, "invalid_steps" end
    end
    local result = {version = 2, name = macro.name, steps = {}, clock = macro.clock}
    local migration = macro.version == 1 and {fromVersion = 1, droppedSteps = 0, strippedPositions = 0, mappedAbilities = 0} or nil
    for index = 1, count do
        local raw = steps[index]
        if raw == nil then return nil, "invalid_steps" end
        local step, message
        if migration then
            if type(raw) ~= "table" or getmetatable(raw) ~= nil then return nil, "invalid_step" end
            local kind = raw.type
            if type(kind) ~= "string" then return nil, "unsupported_step" end
            local allowed = legacyFields[kind] or ((actions[kind] or abilityAliases[kind]) and fields(kind))
            if not allowed then return nil, "unsupported_step" end
            if not knownKeys(raw, allowed) then return nil, "invalid_step_keys" end
            if not inert(raw, {}, {256}, 0) then return nil, "invalid_step" end
            if kind ~= "spawn" and legacyFields[kind] then
                migration.droppedSteps = migration.droppedSteps + 1
            else
                if abilityAliases[kind] then kind = "ability"; migration.mappedAbilities = migration.mappedAbilities + 1 end
                step, message = normalizeStep({type = kind, slot = raw.slot, ordinal = raw.ordinal, wave = raw.wave,
                    position = raw.position, rotationY = raw.rotationY, at = raw.at, waveAt = raw.waveAt,
                    enabled = raw.enabled, priority = raw.priority})
                if not step then return nil, message end
            end
        else
            step, message = normalizeStep(raw)
            if not step then return nil, message end
        end
        if step then result.steps[#result.steps + 1] = step end
    end
    return result, nil, migration
end

function Macros.new(context)
    assert(context and context.scope and context.adapter, "Macros requires scope and adapter")
    local self = setmetatable({scope = context.scope:Child(), adapter = context.adapter,
        config = context.config, settings = context.settings, executeStep = context.executeStep,
        clockSource = context.clockSource,
        Changed = Signal.new(), recording = false, playing = false, name = "", index = 0, error = nil}, Macros)
    self.scope:Add(self.Changed)
    self.scope:Add(function()
        self.destroyed = true
        self.recording, self.playing, self.tape, self.playScope = false, false, nil, nil
        self.name, self.index, self.error = "", 0, nil
        self:_Changed()
    end)
    if workspace and not self.clockSource then
        self:_BindBattleRoot(workspace:FindFirstChild("_DATA"))
        self:_BindWaveClock(workspace:FindFirstChild("_wave_num"))
        if workspace.ChildAdded then self.scope:Connect(workspace.ChildAdded, function(child)
            if child.Name == "_wave_num" then self:_BindWaveClock(child) end
            if child.Name == "_DATA" then self:_BindBattleRoot(child) end
        end) end
        if workspace.ChildRemoved then self.scope:Connect(workspace.ChildRemoved, function(child)
            if child == self.clockWave then self:_BindWaveClock(workspace:FindFirstChild("_wave_num")) end
            if child == self.battleRoot then self:_BindBattleRoot(workspace:FindFirstChild("_DATA")) end
        end) end
    end
    return self
end

function Macros:State()
    return {recording = self.recording, playing = self.playing, name = self.name, index = self.index, error = self.error}
end

function Macros:_Changed() self.Changed:Fire(self:State()) end

function Macros:_BindWaveClock(wave)
    if self.clockScope then self.clockScope:Destroy(); self.clockScope = nil end
    self.clockWave, self.firstWaveAt = wave, nil
    if not wave then return end
    local previous = wave.Value
    self.clockScope = self.scope:Child()
    self.clockScope:Connect(wave.Changed, function(value)
        if type(value) ~= "number" or value < 1 then
            self.firstWaveAt = nil
        elseif value == 1 and type(previous) == "number" and previous < 1 then
            self.firstWaveAt = os.clock()
        end
        previous = value
    end)
end

function Macros:_BindBattleStarted(started)
    if self.clockStarted == started then return end
    if self.battleScope then self.battleScope:Destroy(); self.battleScope = nil end
    self.clockStarted, self.battleStartedAt = started, nil
    if not started then return end
    local previous = started.Value
    self.battleScope = self.scope:Child()
    self.battleScope:Connect(started.Changed, function(value)
        if value ~= true then self.battleStartedAt = nil
        elseif previous ~= true then self.battleStartedAt = os.clock() end
        previous = value
    end)
    -- A true flag seen on late attachment is not an epoch. Never fabricate a
    -- time origin by treating script load or macro launch as battle start.
end

function Macros:_BindBattleRoot(root)
    if self.battleRoot == root then return end
    if self.battleRootScope then self.battleRootScope:Destroy(); self.battleRootScope = nil end
    self.battleRoot = root
    self:_BindBattleStarted(root and root:FindFirstChild("GameStarted"))
    if not root then return end
    local scope = self.scope:Child()
    self.battleRootScope = scope
    if root.ChildAdded then scope:Connect(root.ChildAdded, function(child)
        if child.Name == "GameStarted" then self:_BindBattleStarted(child) end
    end) end
    if root.ChildRemoved then scope:Connect(root.ChildRemoved, function(child)
        if child == self.clockStarted then self:_BindBattleStarted(root:FindFirstChild("GameStarted")) end
    end) end
end

function Macros:WaveTime()
    if self.firstWaveAt then return math.max(0, os.clock() - self.firstWaveAt) end
end

function Macros:MapTime(clock)
    if self.clockSource then
        if not self.clockSource.scope.alive then return nil end
        return self.clockSource:MapTime(clock)
    end
    if clock == "wave" or not self.clockStarted then return self:WaveTime() end
    if self.battleStartedAt then return math.max(0, os.clock() - self.battleStartedAt) end
end

function Macros:RecordTime()
    if self.tape and self.tape.clock == "playback" then
        return self.recordingStartedAt and math.max(0, os.clock() - self.recordingStartedAt) or nil
    end
    return self:MapTime(self.tape and self.tape.clock or "battle")
end

function Macros:CurrentWave()
    local wave = workspace and workspace:FindFirstChild("_wave_num")
    local value = wave and wave.Value
    return integer(value, 1, 100000) and value or 0
end

function Macros:StartRecording(name)
    if not self.scope.alive then return false, "destroyed" end
    if self.playing or self.recording then return false, "busy" end
    if not validName(name) then return false, "invalid_name" end
    local clock = self.clockSource or self
    local active = (clock.clockStarted and clock.clockStarted.Value == true)
        or (not clock.clockStarted and self:CurrentWave() > 0)
    local clockKind = active and not self:MapTime("battle") and "playback" or "battle"
    self.recordingStartedAt = clockKind == "playback" and os.clock() or nil
    self.tape = {version = 2, name = name, steps = {}, clock = clockKind}
    self.recording, self.name, self.index, self.error = true, name, 0, nil
    self:_Changed()
    return true
end

function Macros:Record(action, arguments)
    if not self.scope.alive then return false, "destroyed" end
    if not self.recording then return false, "not_recording" end
    local raw = action
    if type(action) == "string" then
        if not actions[action] then return false, "unsupported_step" end
        if arguments ~= nil and not knownKeys(arguments, fields(action)) then return false, "invalid_step_keys" end
        if arguments and arguments.type ~= nil and arguments.type ~= action then return false, "invalid_step" end
        raw = {type = action}
        for key, value in next, arguments or {} do raw[key] = value end
    elseif arguments ~= nil then return false, "invalid_step" end
    local step, message = normalizeStep(raw)
    if not step then return false, message end
    -- Capture may snapshot wave=0 before asynchronous unit stats become ready.
    -- It is deliberately omitted from the resulting document, not re-read late.
    if raw.wave == nil then
        local wave = self:CurrentWave()
        if wave > 0 then step.wave = wave end
    end
    if step.at == nil and raw.wave ~= 0 then
        local elapsed = self:RecordTime()
        if elapsed then step.at = math.min(elapsed, MAX_MAP_TIME) end
    end
    local steps = self.tape.steps
    if #steps >= MAX_STEPS then self.error = "step_limit"; self:_Changed(); return false, "step_limit" end
    local index = #steps + 1
    local time = step.at or -1
    while index > 1 and (steps[index - 1].at or -1) > time do index = index - 1 end
    table.insert(steps, index, step)
    self.index = #steps
    self:_Changed()
    return true
end

function Macros:StopRecording()
    if not self.scope.alive then return nil, "destroyed" end
    if not self.recording then return nil, "not_recording" end
    local macro, message = self:Validate(self.tape)
    self.recording, self.tape, self.recordingStartedAt, self.error = false, nil, nil, message
    self:_Changed()
    return macro, message
end

function Macros:CancelRecording(reason)
    if not self.recording then return false end
    self.recording, self.tape, self.recordingStartedAt, self.error = false, nil, nil, reason or "cancelled"
    self:_Changed()
    return true
end

function Macros:_Guard()
    if self.adapter.scope and not self.adapter.scope.alive then return false, "destroyed" end
    if type(self.adapter.InLobby) ~= "function" then return false, "missing_api" end
    local inLobby = self.adapter:InLobby()
    if type(inLobby) ~= "boolean" then return false, "missing_api" end
    if inLobby then return false, "lobby" end
    if type(self.executeStep) ~= "function" then return false, "missing_executor" end
    return true
end

local function failureCode(message)
    if type(message) == "string" and #message <= 64 and message:match("^[%w_%-]+$") then return message end
    return "step_failed"
end

function Macros:Play(macro, options)
    if not self.scope.alive then return false, "destroyed" end
    if self.playing or self.recording then return false, "busy" end
    if options ~= nil and not knownKeys(options, {}) then return false, "invalid_options" end
    local normalized, message = self:Validate(macro)
    if not normalized then return false, message end
    if #normalized.steps == 0 then return false, "empty_macro" end
    local ok, allowed, status = pcall(self._Guard, self)
    if not ok then return false, "step_error" end
    if not allowed then return false, status end
    local playback = self.scope:Child()
    self.playScope, self.playing, self.name, self.index, self.error = playback, true, normalized.name, 0, nil
    playback:Add(function()
        if self.playScope == playback then self.playScope, self.playing = nil, false; self:_Changed() end
    end)
    playback:Spawn(function()
        local playbackStartedAt = os.clock()
        local function run()
            for index, step in ipairs(normalized.steps) do
                if not playback.alive then return end
                self.index = index
                self:_Changed()
                if not playback.alive then return end -- Changed listeners may Stop()
                local ready, code = self:_Guard()
                if not ready then self.error = code; return end
                local action = normalizeStep(step)
                if action.at ~= nil then
                    while playback.alive do
                        -- No marker means an existing wave-one recording.
                        local clock = normalized.clock or "wave"
                        local clockOwner = self.clockSource or self
                        local elapsed = clock == "playback" and math.max(0, os.clock() - playbackStartedAt)
                            or self:MapTime(clock)
                        if elapsed and elapsed >= action.at then break end
                        if not elapsed and ((clock == "battle" and clockOwner.clockStarted and clockOwner.clockStarted.Value == true)
                            or ((clock == "wave" or not clockOwner.clockStarted) and self:CurrentWave() > 0)) then
                            self.error = "map_clock_unavailable"; return
                        end
                        task.wait(elapsed and math.min(action.at - elapsed, 0.03) or 0.03)
                        if not playback.alive then return end
                        ready, code = self:_Guard()
                        if not ready then self.error = code; return end
                    end
                    action.wave = nil
                end
                action.at, action.waveAt = nil, nil
                local deadline = playback:Child()
                deadline:Delay(STEP_TIMEOUT, function()
                    if playback.alive then self.error = "timeout"; playback:Destroy() end
                end)
                -- No direct remote fallback: all actions share Units' owned
                -- unit lookup, placement and resource/cooldown readiness path.
                local success, result = self.executeStep(action)
                deadline:Destroy()
                if not playback.alive then return end
                if success ~= true then self.error = failureCode(result); return end
            end
        end
        local success = pcall(run)
        if not playback.alive then return end
        if not success then self.error = "step_error" end
        playback:Destroy()
    end)
    self:_Changed()
    return true -- queued once; not a server acceptance claim
end

function Macros:Stop()
    if self.playScope then self.playScope:Destroy(); return true end
    return false
end

function Macros:Destroy() self.scope:Destroy() end
return Macros
end

__modules["game/MatchReport"] = function(require)
local Util = require("core/Util")

local Report = {}

local function finite(value, minimum, maximum)
    value = tonumber(value)
    if not value or value ~= value or value == math.huge or value == -math.huge then return nil end
    return math.max(minimum, math.min(maximum, value))
end

local function text(value, limit)
    if type(value) ~= "string" then return "" end
    value = value:gsub("%z", "")
    return #value <= limit and value or value:sub(1, limit)
end

local function plainTable(value)
    return type(value) == "table" and getmetatable(value) == nil and value or {}
end

function Report.normalize(settings, identity, timing, observedRewards)
    settings, identity, timing = plainTable(settings), plainTable(identity), plainTable(timing)
    local stats = plainTable(settings.stats)
    local victory = settings.victory
    if type(victory) ~= "boolean" then victory = stats.victory end
    local result = type(victory) == "boolean" and (victory and "victory" or "defeat") or "unknown"
    local rewards, rewardCount = {}, 0
    local function add(name, value)
        value = finite(value, 0, 1e18)
        name = text(name, 128)
        if name ~= "" and value and value > 0 and (rewards[name] ~= nil or rewardCount < 64) then
            if rewards[name] == nil then rewardCount = rewardCount + 1 end
            rewards[name] = value
        end
    end
    add("Gold", settings.gold_reward)
    add("Gems", settings.gem_reward)
    add("Trophies", settings.trophy_reward)
    add("XP", settings.xp_reward)
    for name, value in pairs(plainTable(settings.resource_reward)) do add(name, value) end
    local function drops(value, field)
        for _, row in pairs(plainTable(value)) do
            if type(row) == "table" then
                local id = row[field]
                if type(id) == "string" then add(id, tonumber(row.amount or row.count) or 1) end
            end
        end
    end
    drops(settings.new_items, "item_id")
    drops(settings.new_units, "unit_id")
    for name, value in pairs(plainTable(observedRewards)) do if rewards[name] == nil then add(name, value) end end
    local duration = timing.observedStart == true and finite(stats.time_taken or timing.duration, 0, 86400) or nil
    return {
        version = 1,
        identity = {levelId = text(identity.id or identity.levelId, 128), mode = text(identity.mode, 64),
            location = text(identity.location, 256), name = text(settings.title or identity.name, 256),
            difficulty = text(identity.difficulty, 64), weather = text(identity.weather, 64)},
        result = result,
        timing = {duration = duration, observedStart = timing.observedStart == true},
        progress = {wave = finite(stats.waves_completed, 0, 100000), maxWave = finite(stats.num_waves, 0, 100000)},
        performance = {kills = finite(stats.kills, 0, 1e12), damage = finite(stats.damage_dealt, 0, 1e18)},
        rewards = rewards,
    }
end

return Report
end

__modules["game/MatchStats"] = function(require)
local Signal = require("core/Signal")
local Util = require("core/Util")

local Stats = {}
Stats.__index = Stats

local MAX_MAPS, MAX_HISTORY, MAX_REWARDS = 200, 100, 32
local numericFields = {"matches", "wins", "losses", "unknown", "current_streak", "best_streak",
    "duration_seconds", "timed_matches", "kills", "damage", "kill_matches", "damage_matches"}

local function now()
    return type(os.time) == "function" and os.time() or math.floor(os.clock())
end

local function finite(value, maximum)
    return type(value) == "number" and value == value and value >= 0 and value <= (maximum or 1e18)
end

local function blank()
    return {matches = 0, wins = 0, losses = 0, unknown = 0, current_streak = 0, best_streak = 0,
        duration_seconds = 0, timed_matches = 0, kills = 0, damage = 0, kill_matches = 0,
        damage_matches = 0, rewards = {}}
end

local function validRewards(value)
    if type(value) ~= "table" or getmetatable(value) ~= nil then return false end
    local count = 0
    for name, amount in pairs(value) do
        count = count + 1
        if count > MAX_REWARDS or type(name) ~= "string" or name == "" or #name > 128
            or not finite(amount) then return false end
    end
    return true
end

local function validBucket(value, legacy)
    if type(value) ~= "table" or getmetatable(value) ~= nil then return false end
    local fields = legacy and {"matches", "wins", "losses", "unknown", "current_streak", "best_streak",
        "duration_seconds", "timed_matches"} or numericFields
    for _, key in ipairs(fields) do if not finite(value[key]) then return false end end
    return legacy or validRewards(value.rewards)
end

local function upgradeBucket(value)
    local result = blank()
    for _, key in ipairs(numericFields) do
        if finite(value and value[key]) then result[key] = value[key] end
    end
    if validRewards(value and value.rewards) then result.rewards = Util.copy(value.rewards) end
    if type(value) == "table" then
        if type(value.name) == "string" and #value.name <= 256 then result.name = value.name end
        if finite(value.last_played) then result.last_played = value.last_played end
    end
    return result
end

local function addReward(bucket, name, amount)
    if type(name) ~= "string" or name == "" or #name > 128 or not finite(amount) or amount <= 0 then return end
    if bucket.rewards[name] ~= nil then bucket.rewards[name] = math.min(1e18, bucket.rewards[name] + amount); return end
    local count = 0; for _ in pairs(bucket.rewards) do count = count + 1 end
    if count < MAX_REWARDS then bucket.rewards[name] = amount end
end

local function apply(bucket, report)
    bucket.matches = bucket.matches + 1
    if report.timing.duration then
        bucket.duration_seconds = bucket.duration_seconds + report.timing.duration
        bucket.timed_matches = bucket.timed_matches + 1
    end
    if report.performance.kills then
        bucket.kills, bucket.kill_matches = bucket.kills + report.performance.kills, bucket.kill_matches + 1
    end
    if report.performance.damage then
        bucket.damage, bucket.damage_matches = bucket.damage + report.performance.damage, bucket.damage_matches + 1
    end
    for name, amount in pairs(report.rewards or {}) do addReward(bucket, name, amount) end
    if report.result == "victory" then
        bucket.wins, bucket.current_streak = bucket.wins + 1, bucket.current_streak + 1
        bucket.best_streak = math.max(bucket.best_streak, bucket.current_streak)
    elseif report.result == "defeat" then
        bucket.losses, bucket.current_streak = bucket.losses + 1, 0
    else bucket.unknown = bucket.unknown + 1 end
end

local function mapKey(report)
    local id = report.identity
    return table.concat({id.mode ~= "" and id.mode or "unknown", id.levelId ~= "" and id.levelId or "unknown",
        id.difficulty ~= "" and id.difficulty or "normal"}, "|")
end

local function historyRecord(report, timestamp, serial)
    local rewards, count = {}, 0
    for name, amount in pairs(report.rewards or {}) do
        if count < MAX_REWARDS and validRewards({[name] = amount}) then
            rewards[name] = amount
            count = count + 1
        end
    end
    return {id = tostring(timestamp) .. "-" .. tostring(serial), at = timestamp,
        identity = Util.copy(report.identity), result = report.result,
        duration = report.timing.duration, wave = report.progress.wave, maxWave = report.progress.maxWave,
        kills = report.performance.kills, damage = report.performance.damage, rewards = rewards}
end

local function loadDocument(document)
    if type(document) ~= "table" or type(document.maps) ~= "table" or getmetatable(document.maps) ~= nil then return nil end
    local legacy = document.version == 1
    if not legacy and document.version ~= 2 then return nil end
    if not validBucket(document.totals, legacy) then return nil end
    local result = {version = 2, totals = upgradeBucket(document.totals), maps = {}, history = {}}
    local count = 0
    for key, bucket in pairs(document.maps) do
        count = count + 1
        if type(key) ~= "string" or #key > 384 or count > MAX_MAPS or not validBucket(bucket, legacy) then return nil end
        result.maps[key] = upgradeBucket(bucket)
    end
    if not legacy then
        if type(document.history) ~= "table" or getmetatable(document.history) ~= nil or #document.history > MAX_HISTORY then return nil end
        for index, row in ipairs(document.history) do
            local id = type(row) == "table" and row.identity
            if type(row) ~= "table" or getmetatable(row) ~= nil or type(row.id) ~= "string" or #row.id > 64
                or not finite(row.at, 1e12) or type(id) ~= "table" or getmetatable(id) ~= nil
                or (row.result ~= "victory" and row.result ~= "defeat" and row.result ~= "unknown")
                or not validRewards(row.rewards) then return nil end
            for _, key in ipairs({"levelId", "mode", "location", "name", "difficulty", "weather"}) do
                if type(id[key]) ~= "string" or #id[key] > 256 then return nil end
            end
            for _, key in ipairs({"duration", "wave", "maxWave", "kills", "damage"}) do
                if row[key] ~= nil and not finite(row[key]) then return nil end
            end
            result.history[index] = Util.copy(row)
        end
    end
    return result
end

function Stats.new(options)
    local self = setmetatable({storage = options.storage, codec = options.codec, path = options.path,
        data = {version = 2, totals = blank(), maps = {}, history = {}}, session = blank(),
        sessionHistory = {}, sessionStartedAt = now(), serial = 0, Changed = Signal.new()}, Stats)
    if self.storage then
        local ok, document = pcall(function()
            if not self.storage.exists(self.path) then return nil end
            local raw = self.storage.read(self.path)
            assert(type(raw) == "string" and #raw <= 256 * 1024)
            return self.codec.decode(raw)
        end)
        if ok and document ~= nil then
            local loaded = loadDocument(document)
            if loaded then self.data, self.serial = loaded, #loaded.history else self.loadError = "invalid_stats" end
        elseif not ok then self.loadError = "read_failed" end
    end
    return self
end

function Stats:Accept(report)
    if type(report) ~= "table" or report.version ~= 1 then return false, "invalid_report" end
    local key = mapKey(report)
    if not self.data.maps[key] then
        local count = 0; for _ in pairs(self.data.maps) do count = count + 1 end
        if count >= MAX_MAPS then return false, "map_limit" end
    end
    local nextData = Util.copy(self.data)
    nextData.maps[key] = nextData.maps[key] or blank()
    apply(nextData.totals, report); apply(nextData.maps[key], report); apply(self.session, report)
    nextData.maps[key].name = report.identity.location ~= "" and report.identity.location or report.identity.name
    local timestamp = now()
    nextData.maps[key].last_played = timestamp
    self.serial = self.serial + 1
    local row = historyRecord(report, timestamp, self.serial)
    local used = {}; for _, saved in ipairs(nextData.history) do used[saved.id] = true end
    while used[row.id] do
        self.serial = self.serial + 1
        row.id = tostring(timestamp) .. "-" .. tostring(self.serial)
    end
    nextData.history[#nextData.history + 1] = row
    while #nextData.history > MAX_HISTORY do table.remove(nextData.history, 1) end
    self.sessionHistory[#self.sessionHistory + 1] = Util.copy(row)
    while #self.sessionHistory > MAX_HISTORY do table.remove(self.sessionHistory, 1) end
    self.data, self.dirty = nextData, true
    self:Flush()
    self.Changed:Fire(self:Snapshot())
    return true
end

function Stats:Snapshot()
    return {persistent = self.storage ~= nil and self.loadError == nil, totals = Util.copy(self.data.totals),
        maps = Util.copy(self.data.maps), history = Util.copy(self.data.history), session = Util.copy(self.session),
        sessionHistory = Util.copy(self.sessionHistory), sessionStartedAt = self.sessionStartedAt,
        sessionElapsed = math.max(0, now() - self.sessionStartedAt), error = self.loadError}
end

function Stats:Flush()
    if not self.dirty then return true end
    if self.loadError == "invalid_stats" then return false, "invalid_stats" end
    if not self.storage then return false, "unsupported" end
    local ok = pcall(function()
        local document = Util.copy(self.data)
        local raw = self.codec.encode(document)
        assert(type(raw) == "string")
        while #raw > 256 * 1024 and #document.history > 1 do
            table.remove(document.history, 1)
            raw = self.codec.encode(document)
            assert(type(raw) == "string")
        end
        if #raw > 256 * 1024 then
            local keys = {}
            for key, bucket in pairs(document.maps) do keys[#keys + 1] = {key = key, at = bucket.last_played or 0} end
            table.sort(keys, function(a, b) return a.at < b.at or (a.at == b.at and a.key < b.key) end)
            for _, item in ipairs(keys) do
                document.maps[item.key].rewards = {}
                raw = self.codec.encode(document)
                assert(type(raw) == "string")
                if #raw <= 256 * 1024 then break end
            end
        end
        assert(#raw <= 256 * 1024)
        assert(self.storage.write(self.path, raw) ~= false)
        self.data = document
    end)
    if ok then self.dirty = false else self.lastError = "write_failed" end
    return ok, self.lastError
end

function Stats:Reset()
    self.data, self.session, self.sessionHistory, self.sessionStartedAt, self.loadError, self.dirty =
        {version = 2, totals = blank(), maps = {}, history = {}}, blank(), {}, now(), nil, true
    local ok, reason = self:Flush(); self.Changed:Fire(self:Snapshot()); return ok, reason
end

function Stats:Destroy() self:Flush(); self.Changed:Destroy() end

return Stats
end

__modules["game/NotificationSettings"] = function(require)
local Settings = {}

function Settings.prefix(channel)
    assert(channel == "discord" or channel == "telegram", "Unknown notification channel")
    return channel == "telegram" and "webhook.telegram." or "webhook."
end

function Settings.enabled(config, channel, event)
    local value = config:Get(Settings.prefix(channel) .. event)
    -- Hosts with an older config adapter keep the original shared match/drop flags.
    -- Summon summaries were previously Discord-only.
    if value == nil and channel == "telegram" and not event:match("^summons%.") then
        value = config:Get("webhook." .. event)
    end
    return value == true
end

return Settings
end

__modules["game/Placement"] = function(require)
local Util = require("core/Util")
local Placement = {}
Placement.__index = Placement
local PLACEMENT_POINT_RADIUS = 0.35

function Placement.new()
    return setmetatable({ lanes = {}, surfaces = {}, candidates = {}, supports = {}, cursors = {}, expansions = {}, failures = {}, reservations = {} }, Placement)
end

local function order(part)
    if part.Name == "spawn" then return -math.huge end
    if part.Name == "final" then return math.huge end
    return tonumber(part.Name) or 0
end

local function flatDistance(a, b)
    if not a or not b then return math.huge end
    local dx, dz = a.X - b.X, a.Z - b.Z
    return math.sqrt(dx * dx + dz * dz)
end

local function partPosition(object)
    return object and object:IsA("BasePart") and object.Position or nil
end

local function markerPosition(paths)
    for _, path in ipairs(paths) do
        local found = Util.find(workspace, path)
        local position = partPosition(found)
        if position then return position end
    end
end

function Placement:_Lane(index)
    local root = Util.find(workspace, "_BASES.player.LANES." .. tostring(index))
    if not root then return nil end
    local cached = self.lanes[index]
    if cached and cached.root == root and cached.count == #root:GetChildren() then return cached end
    local points = {}
    for _, part in ipairs(root:GetChildren()) do if part:IsA("BasePart") then points[#points + 1] = part end end
    table.sort(points, function(a, b) return order(a) < order(b) end)
    if #points < 2 then return nil end
    local lengths, total = {}, 0
    for i = 1, #points - 1 do
        lengths[i] = (points[i + 1].Position - points[i].Position).Magnitude
        total = total + lengths[i]
    end
    -- Lane numbering is not consistent across maps. Orient the polyline so
    -- distance 0 is the enemy spawn and distance total is the player base.
    local playerBase = markerPosition({"_BASES.player.base", "_BASES.player.Base", "_BASES.pve.base", "_BASES.pve.Base", "base"})
    local enemySpawn = markerPosition({"_BASES.enemy", "_BASES.enemy_spawn", "initial_spawn", "enemy_spawn"})
    local first, last = points[1].Position, points[#points].Position
    local reverse
    if points[1].Name == "spawn" or points[#points].Name == "final" then
        reverse = true
    elseif points[1].Name == "final" or points[#points].Name == "spawn" then
        reverse = false
    elseif playerBase then
        reverse = flatDistance(first, playerBase) < flatDistance(last, playerBase)
    elseif enemySpawn then
        reverse = flatDistance(last, enemySpawn) < flatDistance(first, enemySpawn)
    else
        reverse = false
    end
    if reverse then
        local reversed = {}
        for i = #points, 1, -1 do reversed[#reversed + 1] = points[i] end
        points, lengths, total = reversed, {}, 0
        for i = 1, #points - 1 do
            lengths[i] = (points[i + 1].Position - points[i].Position).Magnitude
            total = total + lengths[i]
        end
    end
    cached = { root = root, count = #root:GetChildren(), points = points, lengths = lengths, total = total,
        reversed = reverse == true, orientation = playerBase and "player_base" or (enemySpawn and "enemy_spawn" or "names") }
    self.lanes[index] = cached
    return cached
end

function Placement:_AtDistance(lane, distance)
    local remaining = math.max(0, math.min(lane.total, distance))
    for index, length in ipairs(lane.lengths) do
        if remaining <= length then
            local start, finish = lane.points[index].Position, lane.points[index + 1].Position
            local direction = finish - start
            return start:Lerp(finish, length > 0 and remaining / length or 0), direction.Magnitude > 0 and direction.Unit or Vector3.new(0, 0, 1)
        end
        remaining = remaining - length
    end
    return lane.points[#lane.points].Position, Vector3.new(0, 0, 1)
end

function Placement:_Anchor(lane, percent)
    local legacy = type(percent) == "string" and (percent == "spawn" and 100 or (percent == "end" and 0 or 50))
    local ratio = math.max(0, math.min(100, tonumber(percent) or legacy or 50)) / 100
    return self:_AtDistance(lane, lane.total * ratio)
end

local function key(position)
    return string.format("%.1f:%.1f:%.1f", position.X, position.Y, position.Z)
end

local function distanceToPath(lane, point)
    local minimum = math.huge
    for index = 1, #lane.points - 1 do
        local start = lane.points[index].Position
        local finish = lane.points[index + 1].Position
        local segment = Vector3.new(finish.X - start.X, 0, finish.Z - start.Z)
        local offset = Vector3.new(point.X - start.X, 0, point.Z - start.Z)
        local lengthSquared = segment:Dot(segment)
        local ratio = lengthSquared > 0 and math.max(0, math.min(1, offset:Dot(segment) / lengthSquared)) or 0
        minimum = math.min(minimum, (offset - segment * ratio).Magnitude)
    end
    return minimum
end

local footprintDirections = {
    {1, 0}, {-1, 0}, {0, 1}, {0, -1},
}

local function supportedSurface(hit, params, radius)
    -- Placement is accepted for a horizontal circular footprint, including on
    -- sloped meshes. Compare every perimeter ray with the plane at the centre;
    -- comparing raw Y values rejected valid slopes as the unit radius grew.
    if hit.Normal.Y < 0.55 then return false end
    local normal = hit.Normal
    local footprint = math.max(0.25, radius - 0.1) -- avoid rejecting a tangent edge on floating point noise
    local height = math.max(8, radius * 2 + 5)
    local tolerance = math.max(0.65, radius * 0.14)
    for _, direction in ipairs(footprintDirections) do
        local offsetX, offsetZ = direction[1] * footprint, direction[2] * footprint
        local expectedY = hit.Position.Y - (normal.X * offsetX + normal.Z * offsetZ) / normal.Y
        local origin = Vector3.new(hit.Position.X + offsetX, math.max(hit.Position.Y, expectedY) + height,
            hit.Position.Z + offsetZ)
        local support = workspace:Raycast(origin, Vector3.new(0, -height * 2, 0), params)
        if not support or support.Normal.Y < 0.5 or math.abs(support.Position.Y - expectedY) > tolerance then
            return false
        end
    end
    return true
end

local function samples(half, step)
    local result, seen = {0}, {[0] = true}
    if half <= 0 then return result end
    for value = -half + math.min(step / 2, half), half, step do
        local id = math.floor(value * 1000 + 0.5)
        if not seen[id] then seen[id] = true; result[#result + 1] = value end
    end
    return result
end

function Placement:_Bounds()
    local source = Util.find(workspace, "ignore._bounds") or workspace:FindFirstChild("_bounds")
    if not source then
        local storage = game:GetService("ReplicatedStorage")
        source = storage and storage:FindFirstChild("_bounds")
    end
    if not source then return nil end
    if self.bounds and self.bounds.Parent and self.boundsSource == source then return self.bounds end
    if self.bounds then self.bounds:Destroy() end
    local folder = Instance.new("Folder")
    folder.Name = "__SaintHubPlacementBounds"
    for _, part in ipairs(source:GetDescendants()) do
        if part:IsA("BasePart") then
            local ok, clone = pcall(part.Clone, part)
            if ok and clone then
                clone:ClearAllChildren()
                clone.Anchored, clone.Transparency = true, 1
                clone.CanCollide, clone.CanTouch, clone.CanQuery = false, false, true
                clone.Parent = folder
            end
        end
    end
    folder.Parent = workspace
    self.boundsSource, self.bounds = source, folder
    return folder
end

function Placement:_Probe(radius)
    if self.probe and self.probe.Parent then return self.probe end
    local probe = Instance.new("Part")
    probe.Name = "__SaintHubPlacementProbe"
    probe.Shape = Enum.PartType.Cylinder
    probe.Size = Vector3.new(3, radius * 2, radius * 2)
    probe.Orientation = Vector3.new(0, 0, 90)
    probe.Anchored, probe.Transparency = true, 1
    probe.CanCollide, probe.CanTouch, probe.CanQuery = false, false, true
    probe.Parent = workspace
    self.probe = probe
    return probe
end

function Placement:_SurfaceSamples(surface, terrain, params, footprint)
    local cacheKey = surface .. ":" .. string.format("%.2f", footprint)
    local cached = self.surfaces[cacheKey]
    if cached and cached.terrain == terrain then return cached.list end
    local list, seen = {}, {}
    -- v1 was reliable largely because it used a regular grid. Sample in each
    -- part's local frame (with its centre always included) so rotated and narrow
    -- placement surfaces cannot fall between an axis-aligned world grid.
    local step = surface == "hill" and math.min(2.5, math.max(1.9, footprint))
        or math.min(4, math.max(2.5, footprint))
    local function add(origin, height)
        local hit = workspace:Raycast(origin, Vector3.new(0, -height, 0), params)
        if hit and hit.Normal.Y >= 0.5 then
            local id = key(hit.Position)
            if not seen[id] then seen[id] = true; list[#list + 1] = hit.Position end
        end
    end
    for _, part in ipairs(terrain:GetDescendants()) do
        if part:IsA("BasePart") then
            local half, frame = part.Size / 2, part.CFrame
            local extentY = math.abs(frame.RightVector.Y) * half.X + math.abs(frame.UpVector.Y) * half.Y
                + math.abs(frame.LookVector.Y) * half.Z
            local height = math.max(16, extentY * 2 + footprint * 2 + 8)
            local top = part.Position.Y + extentY + height / 2
            local xs, zs = samples(half.X, step), samples(half.Z, step)
            for _, x in ipairs(xs) do
                for _, z in ipairs(zs) do
                    local projected = frame:PointToWorldSpace(Vector3.new(x, 0, z))
                    add(Vector3.new(projected.X, top, projected.Z), height)
                end
            end
        end
    end
    self.surfaces[cacheKey] = {terrain = terrain, list = list}
    return list
end

function Placement:_Candidates(index, percent, surface, footprint, expansion)
    local terrain = Util.find(workspace, "_terrain." .. surface)
    local lane = self:_Lane(index)
    if not terrain or not lane then return nil end
    expansion = surface == "ground" and math.max(0, math.min(3, tonumber(expansion) or 0)) or 0
    local legacy = type(percent) == "string" and (percent == "spawn" and 100 or (percent == "end" and 0 or 50))
    percent = math.max(0, math.min(100, tonumber(percent) or legacy or 50))
    local id = tostring(index) .. ":" .. tostring(percent) .. ":" .. surface .. ":" .. string.format("%.2f", footprint)
        .. ":" .. tostring(expansion)
    local cached = self.candidates[id]
    if cached and cached.terrain == terrain and cached.lane == lane then return cached.list end
    local anchor, tangent = self:_Anchor(lane, percent)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances = { terrain }
    local list, seen = {}, {}
    local allowedDrift = (percent <= 5 or percent >= 95) and 25 or 45
    local function add(origin)
        local hit = workspace:Raycast(origin + Vector3.new(0, 120, 0), Vector3.new(0, -260, 0), params)
        if hit and hit.Normal.Y >= 0.5 and distanceToPath(lane, hit.Position) >= footprint + 0.4 then
            local along = 0
            local nearest, travelled = math.huge, 0
            for segment = 1, #lane.points - 1 do
                local start = lane.points[segment].Position
                local finish = lane.points[segment + 1].Position
                local vector = Vector3.new(finish.X - start.X, 0, finish.Z - start.Z)
                local offset = Vector3.new(hit.Position.X - start.X, 0, hit.Position.Z - start.Z)
                local length = vector.Magnitude
                local ratio = length > 0 and math.max(0, math.min(1, offset:Dot(vector) / (length * length))) or 0
                local distance = (offset - vector * ratio).Magnitude
                if distance < nearest then nearest, along = distance, travelled + length * ratio end
                travelled = travelled + length
            end
            local actualPercent = lane.total > 0 and along / lane.total * 100 or percent
            if math.abs(actualPercent - percent) > allowedDrift then return end
            local idKey = key(hit.Position)
            if not seen[idKey] then seen[idKey] = true; list[#list + 1] = hit.Position end
        end
    end
    if surface == "ground" then
        -- Follow the lane itself instead of growing a circle around one anchor.
        -- Each expansion extends the corridor forward and backward; every road
        -- sample probes both sides, so curved paths remain covered.
        local ratio = percent / 100
        local centreDistance = lane.total * ratio
        local longitudinalReach = 22 + expansion * 26
        local alongStep = math.max(3, math.min(4.5, footprint))
        local lateralStart = footprint + 0.6
        local lateralReach = math.max(22, footprint * 2 + 8)
        local lateralStep = math.max(2.5, math.min(4, footprint))
        for along = -longitudinalReach, longitudinalReach, alongStep do
            local centre, roadTangent = self:_AtDistance(lane, centreDistance + along)
            local roadSide = Vector3.new(-roadTangent.Z, 0, roadTangent.X)
            if roadSide.Magnitude < 0.001 then roadSide = Vector3.new(1, 0, 0) else roadSide = roadSide.Unit end
            for lateral = lateralStart, lateralReach, lateralStep do
                add(centre + roadSide * lateral)
                add(centre - roadSide * lateral)
            end
        end
    else
        local side = Vector3.new(-tangent.Z, 0, tangent.X)
        if side.Magnitude < 0.001 then side = Vector3.new(1, 0, 0) else side = side.Unit end
        for ring = 1, 18 do
            for sample = 0, 15 do
                local angle = sample * math.pi / 8
                local offset = side * (math.cos(angle) * ring * 1.9) + tangent * (math.sin(angle) * ring * 1.9)
                add(anchor + offset)
            end
        end
    end
    if surface == "hill" then
        for _, candidate in ipairs(self:_SurfaceSamples(surface, terrain, params, footprint)) do
            local minimumPathDistance = footprint + 0.4
            local idKey = key(candidate)
            if not seen[idKey] and distanceToPath(lane, candidate) >= minimumPathDistance then
                seen[idKey] = true
                list[#list + 1] = candidate
            end
        end
    end
    table.sort(list, function(a, b) return (a - anchor).Magnitude < (b - anchor).Magnitude end)
    self.candidates[id] = { terrain = terrain, lane = lane, list = list }
    return list
end

function Placement:Find(index, percent, surface, radius)
    -- The unit has no replicated hitbox before spawn. Treat the requested
    -- position as a point; actual hitboxes matter only after units exist.
    radius = PLACEMENT_POINT_RADIUS
    local legacy = type(percent) == "string" and (percent == "spawn" and 100 or (percent == "end" and 0 or 50))
    percent = math.max(0, math.min(100, tonumber(percent) or legacy or 50))
    local baseKey = tostring(index) .. ":" .. tostring(percent) .. ":" .. surface
    local expansion = surface == "ground" and (self.expansions[baseKey] or 0) or 0
    local candidates = self:_Candidates(index, percent, surface, radius, expansion)
    if not candidates then return nil end
    local function widen()
        if surface == "ground" and expansion < 3 then self.expansions[baseKey] = expansion + 1 end
    end
    local terrain = Util.find(workspace, "_terrain." .. surface)
    local supportParams = RaycastParams.new()
    supportParams.FilterType = Enum.RaycastFilterType.Include
    supportParams.FilterDescendantsInstances = {terrain}
    local units = workspace:FindFirstChild("_UNITS")
    local bounds = self:_Bounds()
    local probe = self:_Probe(radius)
    probe.Size = Vector3.new(3, radius * 2, radius * 2)
    local filter, occupied = {}, {}
    for _, unit in ipairs(units and units:GetChildren() or {}) do
        local hitbox = unit:FindFirstChild("_hitbox")
        if hitbox and hitbox:IsA("BasePart") then
            occupied[#occupied + 1] = { position = hitbox.Position,
                radius = math.max(hitbox.Size.Y, hitbox.Size.Z) / 2 }
        end
    end
    if bounds then filter[#filter + 1] = bounds end
    local params = OverlapParams.new()
    params.FilterType = Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances = filter
    params.MaxParts = 1
    local now = os.clock()
    for id, expires in pairs(self.failures) do if expires <= now then self.failures[id] = nil end end
    for id, expires in pairs(self.reservations) do if expires <= now then self.reservations[id] = nil end end
    local queries = 0
    -- Busy multiplayer maps can have dozens of occupied/blocked candidates.
    -- The old limits frequently returned nil before reaching a free part of the
    -- exact same highlighted surface.
    local maxQueries = surface == "hill" and 320 or 192
    local supportQueries, maxSupportQueries = 0, surface == "hill" and 160 or 96
    local cacheKey = baseKey .. ":" .. tostring(expansion)
    local start = self.cursors[cacheKey] or 1
    for offset = 0, #candidates - 1 do
        local candidateIndex = (start + offset - 1) % #candidates + 1
        local candidate = candidates[candidateIndex]
        local id = key(candidate)
        if not self.failures[id] and not self.reservations[id] then
            local supportKey = cacheKey .. ":" .. id
            local supported = self.supports[supportKey]
            if supported == nil then
                supportQueries = supportQueries + 1
                local height = math.max(8, radius * 2 + 5)
                local hit = workspace:Raycast(candidate + Vector3.new(0, height, 0), Vector3.new(0, -height * 2, 0), supportParams)
                supported = hit ~= nil and supportedSurface(hit, supportParams, radius)
                self.supports[supportKey] = supported
            end
            if supported then
                local blocked = false
                for _, unit in ipairs(occupied) do
                    local unitOffset = candidate - unit.position
                    local separation = unit.radius + 0.05
                    if math.abs(unitOffset.Y) < 4 and unitOffset.X * unitOffset.X + unitOffset.Z * unitOffset.Z < separation * separation then
                        blocked = true
                        break
                    end
                end
                if not blocked and #filter > 0 then
                    queries = queries + 1
                    probe.CFrame = CFrame.new(candidate + Vector3.new(0, 1.5, 0)) * CFrame.Angles(0, 0, math.pi / 2)
                    blocked = #workspace:GetPartsInPart(probe, params) > 0
                end
                if not blocked then
                    self.cursors[cacheKey] = candidateIndex % #candidates + 1
                    self.reservations[id] = now + 5
                    return candidate
                end
                self.failures[id] = now + 2
            end
            if queries >= maxQueries or supportQueries >= maxSupportQueries then
                self.cursors[cacheKey] = candidateIndex % #candidates + 1
                widen()
                return nil
            end
        end
    end
    widen()
    return nil
end

function Placement:Result(position, success)
    self.reservations[key(position)] = nil
    if not success then self.failures[key(position)] = os.clock() + 10 end
end

function Placement:Destroy()
    if self.bounds then self.bounds:Destroy() end
    if self.probe then self.probe:Destroy() end
    self.bounds, self.boundsSource, self.probe = nil, nil, nil
    self.lanes, self.surfaces, self.candidates, self.supports, self.cursors, self.expansions, self.failures, self.reservations = {}, {}, {}, {}, {}, {}, {}, {}
end

return Placement
end

__modules["game/PortalFarm"] = function(require)
local Signal = require("core/Signal")

local PortalFarm = {}
PortalFarm.__index = PortalFarm

local function now()
    return type(os.time) == "function" and os.time() or math.floor(os.clock())
end

local function split(value)
    local result, seen = {}, {}
    for key in tostring(value or ""):gmatch("[^,]+") do
        if #key <= 520 and key:match("^[%w_:%-]+$") and not seen[key] then
            seen[key] = true
            result[#result + 1] = key
        end
    end
    return result, seen
end

local function join(items)
    return table.concat(items, ",")
end

local function validActive(value)
    return type(value) == "table" and type(value.key) == "string" and #value.key <= 520
        and value.key:match("^[%w_:%-]+$") and type(value.levelId) == "string"
        and #value.levelId <= 128 and value.levelId:match("^[%w_:%-]+$")
        and type(value.startedAt) == "number"
end

function PortalFarm.new(context)
    local self = setmetatable({scope = context.scope:Child(), config = context.config, api = context.adapter,
        storage = context.storage, codec = context.codec, path = context.path, Changed = Signal.new(),
        run = {version = 1, retries = {}, lastCode = ""}}, PortalFarm)
    self.scope:Add(self.Changed)
    if self.storage then
        local ok, saved = pcall(function()
            if not self.storage.exists(self.path) then return end
            local raw = self.storage.read(self.path)
            assert(type(raw) == "string" and #raw <= 4096)
            local data = self.codec.decode(raw)
            assert(type(data) == "table" and data.version == 1)
            local retries, count = {}, 0
            for key, attempts in pairs(type(data.retries) == "table" and data.retries or {}) do
                count = count + 1
                assert(count <= 200 and type(key) == "string" and #key <= 520
                    and key:match("^[%w_:%-]+$") and attempts == 1)
                retries[key] = 1
            end
            saved = {version = 1, retries = retries,
                lastCode = type(data.lastCode) == "string" and #data.lastCode <= 64 and data.lastCode or ""}
            if data.active ~= nil then assert(validActive(data.active)); saved.active = {
                key = data.active.key, levelId = data.active.levelId, startedAt = data.active.startedAt}
            end
            return saved
        end)
        if ok and saved then self.run = saved end
    end
    if self.config.Changed then
        self.scope:Connect(self.config.Changed, function(path)
            if path:match("^portals%.") or path == "game.type" or path == "game.enabled" then
                self:_Changed()
            end
        end)
    end
    return self
end

function PortalFarm:_Changed()
    if self.changeQueued or not self.scope.alive then return end
    self.changeQueued = true
    self.scope:Delay(0, function()
        self.changeQueued = false
        if self.scope.alive then self.Changed:Fire(self:Status()) end
    end)
end

function PortalFarm:Flush()
    if not self.storage then return false, "unsupported" end
    local ok = pcall(function()
        local raw = self.codec.encode(self.run)
        assert(type(raw) == "string" and #raw <= 4096)
        assert(self.storage.write(self.path, raw) ~= false)
    end)
    return ok, not ok and "write_failed" or nil
end

function PortalFarm:Inventory()
    local rows, status = self.api:PortalInventory()
    rows = type(rows) == "table" and rows or {}
    local order, ordered = split(self.config:Get("portals.order"))
    local _, selected = split(self.config:Get("portals.selected"))
    local rank = {}
    for index, key in ipairs(order) do rank[key] = index end
    for _, row in ipairs(rows) do
        row.selected = selected[row.key] == true
        row.position = rank[row.key]
        row.eligible = row.selected and row.tier >= self.config:Get("portals.minimum_tier")
    end
    table.sort(rows, function(a, b)
        if a.tier ~= b.tier then return a.tier > b.tier end
        return a.name < b.name or (a.name == b.name and a.key < b.key)
    end)
    return rows, status
end

function PortalFarm:Preview()
    local rows, status = self:Inventory()
    local target
    for _, row in ipairs(rows) do
        if row.eligible and row.count > 0 and (not target
            or (row.position or math.huge) < (target.position or math.huge)) then
            target = row
        end
    end
    if target then return target, status end
    return nil, status == "ready" and "no_selected_portal" or status
end

-- Presentation is intentionally independent from launch eligibility. The
-- banner should still show a real portal when the queue is empty or its first
-- item is below the minimum farming tier.
function PortalFarm:Featured()
    local rows, status = self:Inventory()
    local target
    for _, row in ipairs(rows) do
        if row.selected and (not target
            or (row.position or math.huge) < (target.position or math.huge)) then
            target = row
        end
    end
    return target or rows[1], status
end

function PortalFarm:SetSelected(key, enabled)
    local rows = self:Inventory()
    local exists = false
    for _, row in ipairs(rows) do if row.key == key then exists = true; break end end
    if not exists then return false, "missing_portal" end
    local selected, selectedSet = split(self.config:Get("portals.selected"))
    local order, orderSet = split(self.config:Get("portals.order"))
    if enabled == true and not selectedSet[key] then selected[#selected + 1] = key end
    if enabled == true and not orderSet[key] then order[#order + 1] = key end
    if enabled ~= true then
        for index = #selected, 1, -1 do if selected[index] == key then table.remove(selected, index) end end
        for index = #order, 1, -1 do if order[index] == key then table.remove(order, index) end end
    end
    table.sort(selected)
    self.config:Set("portals.selected", join(selected))
    self.config:Set("portals.order", join(order))
    self:_Changed()
    return true
end

function PortalFarm:Move(key, delta)
    delta = delta < 0 and -1 or delta > 0 and 1 or 0
    if delta == 0 then return false, "invalid_direction" end
    local order = split(self.config:Get("portals.order"))
    local index
    for current, value in ipairs(order) do if value == key then index = current; break end end
    if not index then return false, "missing_portal" end
    local target = math.max(1, math.min(#order, index + delta))
    if target == index then return false, "edge" end
    order[index], order[target] = order[target], order[index]
    self.config:Set("portals.order", join(order))
    self:_Changed()
    return true
end

function PortalFarm:Status()
    return {active = self.run.active ~= nil, activeKey = self.run.active and self.run.active.key or "",
        lastCode = self.run.lastCode or "", retries = self.run.retries or {}}
end

function PortalFarm:StartSelected()
    if not self.scope.alive or not self.api:InLobby() then return false, "not_lobby" end
    if self.starting then return false, "busy" end
    if self.run.active then
        if now() - self.run.active.startedAt >= 120 then
            self.run.lastCode = "stale_pending"
            self.config:Set("game.enabled", false)
            self:Flush()
            self:_Changed()
            return false, "stale_pending"
        end
        return false, "start_pending"
    end
    local target, reason = self:Preview()
    if not target then return false, reason end
    local owner = {}
    if self.api.AcquireLobbyAction then
        local acquired, acquireReason = self.api:AcquireLobbyAction(owner)
        if not acquired then return false, acquireReason end
    end
    self.run.active = {key = target.key, levelId = target.levelId, startedAt = now()}
    self.run.lastCode = "starting"
    self:Flush()
    self.starting = true
    local ok, success, detail = pcall(self.api.UsePortal, self.api, target.key, self.config:Get("portals.friends_only"))
    self.starting = false
    if self.api.ReleaseLobbyAction then self.api:ReleaseLobbyAction(owner) end
    if not ok or success ~= true then
        self.run.active = nil
        self.run.lastCode = ok and tostring(detail or "start_failed") or "start_failed"
        if not ok or self.run.lastCode == "unconfirmed" or self.run.lastCode == "timeout"
            or self.run.lastCode == "missing_receipt" then
            self.config:Set("game.enabled", false)
        end
        self:Flush()
        self:_Changed()
        return false, ok and detail or "start_failed"
    end
    self.run.lastCode = "room_created"
    self:Flush()
    self:_Changed()
    return true, target
end

function PortalFarm:OwnsMatch(report)
    return self.run.active ~= nil
end

function PortalFarm:NoteMatchEnd(report)
    local active = self.run.active
    if not active then return false, "inactive" end
    local levelId = type(report) == "table" and report.identity and report.identity.levelId
    local result = type(report) == "table" and report.result
    self.run.active = nil
    if type(levelId) == "string" and levelId ~= "" and levelId ~= active.levelId then
        self.run.lastCode = "target_mismatch"
        self.config:Set("game.enabled", false)
    elseif result == "victory" then
        self.run.retries[active.key] = nil
        self.run.lastCode = "victory"
        if self.config:Get("portals.after_victory") == "stop" then self.config:Set("game.enabled", false) end
    elseif result == "defeat" then
        local policy = self.config:Get("portals.after_defeat")
        if policy == "retry_once" and not self.run.retries[active.key] then
            self.run.retries[active.key] = 1
            self.run.lastCode = "retry"
        else
            self.run.retries[active.key] = nil
            self.run.lastCode = policy == "stop" and "defeat_stop" or "skipped"
            if policy == "stop" then self.config:Set("game.enabled", false) end
        end
    else
        self.run.lastCode = "unknown_result"
        self.config:Set("game.enabled", false)
    end
    self:Flush()
    self:_Changed()
    return true, self.run.lastCode
end

function PortalFarm:Destroy()
    self:Flush()
    self.scope:Destroy()
end

return PortalFarm
end

__modules["game/SaleCapture"] = function(require)
-- Passive, exact-endpoint observation. The parent owns recording/ownership guards,
-- detached typed-step normalization and playback; unit removal is never evidence.
-- beforeSale(unit) and record(step) are protected, synchronous callbacks. Neither
-- should yield (native Lua 5.1 does not support yielding through their pcall).
local SaleCapture = {}
SaleCapture.__index = SaleCapture
local unpackValues = table.unpack or unpack
local function pack(...) return {n = select("#", ...), ...} end

-- Defined outside new/Start so no closure can accidentally capture the service.
local function wrapperFor(reference, tag, link, getMethod)
    return function(receiver, ...)
        link.calls = (link.calls or 0) + 1
        -- Capture this before callbacks can make any other Roblox namecall.
        local methodOK, method = pcall(getMethod)
        local step, token
        do
            local capture = reference[1]
            local route
            if capture and type(capture.matchEndpoint) == "function" then
                local matched, value = pcall(capture.matchEndpoint, receiver)
                if matched then route = value end
            elseif capture and rawequal(receiver, capture.endpoint) then route = true end
            if methodOK and (method == "InvokeServer" or method == "FireServer") and capture
                and capture.active and capture.tag == tag and capture.scope.alive and route then
                local unit, argument = ...
                local generation = capture.token
                local ok, snapshot = pcall(capture.beforeSale, unit, argument, route)
                if ok and type(snapshot) == "table" and capture.active and capture.tag == tag
                    and capture.token == generation and capture.scope.alive then
                    step, token = snapshot, generation
                end
            end
        end
        if not step then return link.previous(receiver, ...) end

        -- No pcall/newcclosure around the original: preserve its error object and
        -- permit yielding where the host's namecall boundary itself permits it.
        -- No strong service reference is held across this potentially long call.
        local results = pack(link.previous(receiver, ...))
        do
            local capture = reference[1]
            if capture and capture.active and capture.tag == tag
                and capture.token == token and capture.scope.alive then
                if type(capture.afterCall) == "function" then pcall(capture.afterCall, step, results[1] ~= false) end
                if results[1] ~= false then pcall(capture.record, step) end
            end
        end
        return unpackValues(results, 1, results.n)
    end
end

-- hookmetamethod implementations may patch a stable C closure in place, so
-- reading __namecall back and comparing function identities is not portable.
-- A benign DataModel namecall proves whether this exact wrapper is routed.
local function routed(self, link)
    local before = link.calls or 0
    local ok
    if type(self.environment.namecallProbe) == "function" then
        ok = pcall(self.environment.namecallProbe, self.game)
    else ok = pcall(function() return self.game:IsLoaded() end) end
    if not ok then return nil end
    return (link.calls or 0) > before
end

function SaleCapture.new(context)
    local environment = context.environment
    if environment == nil then
        environment = {hookmetamethod = hookmetamethod, getrawmetatable = getrawmetatable,
            getnamecallmethod = getnamecallmethod, isnewcclosure = isnewcclosure, iscclosure = iscclosure}
    end
    local self = setmetatable({scope = context.scope:Child(), game = context.game or game,
        endpoint = context.endpoint, api = context.api, beforeSale = context.beforeSale,
        matchEndpoint = context.matchEndpoint, record = context.record, afterCall = context.afterCall,
        environment = environment, active = false, destroyed = false}, SaleCapture)
    self.reference = setmetatable({self}, {__mode = "v"})
    self.scope:Add(function() self:Destroy() end)
    return self
end

-- Availability/status, not a guarantee that an executor supports yieldable hooks
-- or that the server accepts sales. Neither construction nor this probe hooks.
function SaleCapture:Supported()
    if self.destroyed then return false, "destroyed" end
    if not self.scope.alive then return false, "scope_destroyed" end
    for _, name in ipairs({"hookmetamethod", "getrawmetatable", "getnamecallmethod"}) do
        if type(self.environment[name]) ~= "function" then return false, "missing_" .. name end
    end
    if self.game == nil then return false, "missing_game" end
    if self.endpoint == nil and type(self.matchEndpoint) ~= "function" then return false, "missing_endpoint" end
    if type(self.beforeSale) ~= "function" then return false, "missing_before_sale" end
    if type(self.record) ~= "function" then return false, "missing_record" end
    if self.startError then return false, self.startError end
    return true
end

local function current(self)
    local ok, metatable = pcall(self.environment.getrawmetatable, self.game)
    if not ok or type(metatable) ~= "table" then return nil, "metatable_unavailable" end
    local value = rawget(metatable, "__namecall")
    if type(value) ~= "function" then return nil, "invalid_namecall" end
    return value
end

function SaleCapture:Start()
    if self.active then return true end
    self.startError = nil -- Allow an explicit retry after a failed installation.
    local supported, reason = self:Supported()
    if not supported then return false, reason end
    if self.hook then
        local stopped, stopReason = self:Stop()
        if not stopped then return false, stopReason end
    end
    local previous, inspectReason = current(self)
    if not previous then self.startError = inspectReason; return false, inspectReason end
    local tag, link = {}, {previous = previous}
    local wrapper = wrapperFor(self.reference, tag, link, self.environment.getnamecallmethod)
    local hook = {wrapper = wrapper, link = link}
    self.hook = hook
    local ok, displaced = pcall(self.environment.hookmetamethod, self.game, "__namecall", wrapper)
    -- Preserve the actual displaced hook if it differed from the inspected one.
    if ok and type(displaced) == "function" and displaced ~= wrapper then link.previous = displaced end
    local installed = current(self)
    hook.installed = installed
    -- Some executors expose the installed Lua hook through a generated C
    -- closure. Accept that only when their own predicate identifies it; an
    -- arbitrary Lua wrapper remains unverifiable and is rolled back.
    local wrapped = installed ~= wrapper and installed ~= previous and installed ~= displaced
    local wrappedOK = false
    if wrapped and type(self.environment.isnewcclosure) == "function" then
        local checked, value = pcall(self.environment.isnewcclosure, installed)
        wrappedOK = checked and value == true
    end
    if wrapped and not wrappedOK and type(self.environment.iscclosure) == "function" then
        local checked, value = pcall(self.environment.iscclosure, installed)
        wrappedOK = checked and value == true
    end
    local routeOK = installed ~= wrapper and routed(self, link) or nil
    hook.inPlace = installed ~= wrapper and routeOK == true
    if not ok or type(displaced) ~= "function" or displaced == wrapper
        or (installed ~= wrapper and routeOK ~= true and not wrappedOK) then
        local failure = not ok and "hook_install_failed" or
            ((type(displaced) ~= "function" or displaced == wrapper) and "invalid_hook_result" or "hook_verification_failed")
        if installed == previous then
            -- The installer failed before changing the metatable. There is
            -- nothing to restore, and retry must not depend on the failed API.
            self.hook = nil
        else self:Stop() end -- Rolls back only if the current hook is exactly ours.
        self.startError = failure
        return false, failure
    end
    self.tag, self.token, self.active = tag, {}, true
    return true
end

function SaleCapture:Stop()
    self.active, self.tag, self.token = false, nil, nil
    local hook = self.hook
    if not hook then return true end
    local installed, reason = current(self)
    if not installed then return false, reason end
    if installed ~= hook.installed then
        -- Another hook may contain ours. Leave that chain intact; ours is inert.
        self.hook = nil
        return true
    end
    if hook.inPlace and routed(self, hook.link) ~= true then
        -- The stable executor trampoline is still present, but no longer routes
        -- our callback. Treat it as externally restored instead of replacing it.
        self.hook = nil
        return true
    end
    local ok = pcall(self.environment.hookmetamethod, self.game, "__namecall", hook.link.previous)
    if not ok then return false, "hook_restore_failed" end
    local restored, inspectReason = current(self)
    if not restored then return false, inspectReason end
    local stillRouted = routed(self, hook.link)
    if restored == hook.wrapper or stillRouted == true or (hook.inPlace and stillRouted ~= false)
        or (not hook.inPlace and stillRouted == nil and restored == hook.installed) then
        return false, "hook_restore_failed"
    end
    self.hook = nil
    return true
end

function SaleCapture:Destroy()
    if self.destroyed then return true end
    self.destroyed = true
    local ok, reason = self:Stop()
    self.reference[1] = nil
    self.scope:Destroy()
    return ok, reason
end

-- Intentionally no newcclosure fallback: C wrappers may prohibit InvokeServer
-- yields. Executors requiring one are reported as unsupported on Start failure.
-- Only colon/namecall calls are observable; explicit endpoint.InvokeServer calls
-- and Adapter success signals belong to the parent's separate capture path.
return SaleCapture
end

__modules["game/Session"] = function(require)
return require("sainthub-core/Session")
end

__modules["game/SmartFarm"] = function(require)
local Scheduler = require("core/Scheduler")
local Signal = require("core/Signal")

local SmartFarm = {}
SmartFarm.__index = SmartFarm
local function now() return type(os.time) == "function" and os.time() or math.floor(os.clock()) end
local function targetKey(target)
    if type(target) ~= "table" or type(target.levelId) ~= "string" or target.levelId == "" then return nil end
    if target.mode == "challenge" then
        local uuid = target.challenge and target.challenge.uuid
        if type(uuid) ~= "number" and type(uuid) ~= "string" then return nil end
        return "challenge:" .. tostring(target.challengeKind or "unknown") .. ":" .. tostring(uuid) .. ":" .. target.levelId
    end
    return tostring(target.mode or "unknown") .. ":" .. target.levelId
end

local function validKey(value)
    return type(value) == "string" and #value > 0 and #value <= 320 and value:match("^[%w_:%-]+$") ~= nil
end

function SmartFarm.new(context)
    local self = setmetatable({scope = context.scope:Child(), config = context.config, api = context.adapter,
        startSelected = context.startSelected, challengeMethod = context.challengeMethod,
        storage = context.storage, codec = context.codec, path = context.path,
        Changed = Signal.new(), run = {version = 1, startedAt = now(), matches = 0, retries = {}, lastCode = ""}}, SmartFarm)
    self.scope:Add(self.Changed)
    self.scheduler = Scheduler.new(self.scope:Child())
    if self.storage then pcall(function()
        if not self.storage.exists(self.path) then return end
        local raw = self.storage.read(self.path); assert(type(raw) == "string" and #raw <= 4096)
        local data = self.codec.decode(raw)
        assert(type(data) == "table" and data.version == 1 and type(data.startedAt) == "number"
            and type(data.matches) == "number" and data.matches >= 0 and data.matches <= 100000)
        local retries, count = {}, 0
        for key, value in pairs(type(data.retries) == "table" and data.retries or {}) do
            count = count + 1
            assert(count <= 16 and validKey(key) and type(value) == "number" and value % 1 == 0 and value >= 0 and value <= 2)
            retries[key] = value
        end
        local active
        if data.active ~= nil then
            assert(type(data.active) == "table" and validKey(data.active.key)
                and type(data.active.levelId) == "string" and #data.active.levelId <= 128)
            active = {key = data.active.key, levelId = data.active.levelId}
        end
        self.run = {version = 1, startedAt = data.startedAt, matches = math.floor(data.matches),
            retries = retries, active = active,
            lastCode = type(data.lastCode) == "string" and #data.lastCode <= 64 and data.lastCode or ""}
    end) end
    if self.config.Changed then self.scope:Connect(self.config.Changed, function(path, value)
        if path == "smartfarm.enabled" and value == true then
            self.config:Set("game.enabled", false)
            self.run = {version = 1, startedAt = now(), matches = 0, retries = {}, lastCode = ""}
            self:Flush()
        end
        if path:match("^smartfarm%.") then self:_Sync() end
    end) end
    self:_Sync()
    return self
end

function SmartFarm:Flush()
    if not self.storage then return false end
    local ok = pcall(function()
        local raw = self.codec.encode(self.run); assert(type(raw) == "string" and #raw <= 4096)
        assert(self.storage.write(self.path, raw) ~= false)
    end)
    return ok
end

function SmartFarm:Preview(refresh)
    local retries = self.run and self.run.retries or {}
    for _, kind in ipairs({"daily", "normal"}) do
        local key = kind == "daily" and "game.events.priorityDaily" or "game.events.priorityNormal"
        if self.config:Get(key) then
            local challenge = self.api:CurrentChallenge(kind)
            if challenge and (not self.challengeMethod or self.challengeMethod(challenge.levelId, kind)) then
                local target = {mode = "challenge", challengeKind = kind, levelId = challenge.levelId,
                    world = kind == "daily" and "Daily Challenge" or "Challenge", act = challenge.modifier,
                    why = "priority_challenge", challenge = challenge}
                target.retryCount = retries[targetKey(target)] or 0
                return target
            end
        end
    end
    local target, reason = self.api:SmartTarget(self.config:Get("smartfarm.strategy"), refresh)
    if target then target.retryCount = retries[targetKey(target)] or 0 end
    return target, reason
end

function SmartFarm:Status()
    return {matches = self.run.matches, retryCount = self.run.active and ((self.run.retries or {})[self.run.active.key] or 0) or 0,
        lastCode = self.run.lastCode or "", activeLevel = self.run.active and self.run.active.levelId or ""}
end

function SmartFarm:GoalReached()
    local cfg = self.config.data.smartfarm
    return (cfg.goal_matches > 0 and self.run.matches >= cfg.goal_matches)
        or (cfg.goal_minutes > 0 and now() - self.run.startedAt >= cfg.goal_minutes * 60)
end

function SmartFarm:_Sync()
    self.scheduler:Remove("smartfarm")
    if self.config:Get("smartfarm.enabled") and self.api:InLobby() then
        self.scheduler:Set("smartfarm", 10, function() self:Tick() end, true)
    end
end

function SmartFarm:Tick()
    if not self.scope.alive or not self.config:Get("smartfarm.enabled") or not self.api:InLobby() then return false end
    if self.starting then return false, "busy" end
    -- A successful start remains active until the destination match reports its
    -- result. Lobby schedulers may tick again before Roblox begins teleporting;
    -- never start a second room or overwrite the persisted active target.
    if self.run.active then return false, "start_pending" end
    if self:GoalReached() then self.config:Set("smartfarm.enabled", false); return false, "goal" end
    local target, reason = self:Preview(false)
    if not target then return false, reason end
    local key = targetKey(target)
    if not key then return false, "invalid_target" end
    self.run.retries = self.run.retries or {}
    self.run.active = {key = key, levelId = target.levelId}
    self.run.lastCode = "starting"
    self:Flush()
    self.starting = true
    local success, detail
    if target.mode == "challenge" then
        self.Changed:Fire(target)
        success, detail = self.api:StartChallenge(target.challenge, self.config:Get("game.play_mode"))
    else
        local field = target.mode == "story" and "storymode" or target.mode
        self.config:Set("game.type", target.mode)
        self.config:Set("game." .. field .. ".world_id", target.worldId)
        self.config:Set("game." .. field .. ".level_id", target.levelId)
        self.Changed:Fire(target)
        success, detail = self.startSelected and self.startSelected(true) or false, target
    end
    self.starting = false
    if success ~= true then
        self.run.active, self.run.lastCode = nil, "start_failed"
        self:Flush()
    end
    return success, detail
end

function SmartFarm:NoteMatchEnd(report)
    self.run.retries = self.run.retries or {}
    self.run.matches = self.run.matches + 1
    local active = self.run.active
    if active and type(report) == "table" then
        local result = report.result
        local levelId = report.identity and report.identity.levelId
        if type(levelId) == "string" and levelId ~= "" and levelId ~= active.levelId then
            self.run.lastCode, self.run.active = "target_mismatch", nil
            self.config:Set("smartfarm.enabled", false)
        elseif result == "victory" then
            self.run.retries[active.key], self.run.active, self.run.lastCode = nil, nil, "victory"
        elseif result == "defeat" then
            local attempts = (self.run.retries[active.key] or 0) + 1
            self.run.retries[active.key], self.run.active = attempts, nil
            if attempts >= 2 then
                self.run.lastCode = "retry_exhausted"
                self.config:Set("smartfarm.enabled", false)
            else self.run.lastCode = "retry" end
        else
            self.run.lastCode, self.run.active = "unknown_result", nil
            self.config:Set("smartfarm.enabled", false)
        end
    elseif active then
        self.run.lastCode, self.run.active = "unknown_result", nil
        self.config:Set("smartfarm.enabled", false)
    end
    self:Flush()
    if self:GoalReached() then
        self.config:Set("smartfarm.enabled", false)
        if self.config.Flush then self.config:Flush() end
    end
    if self.Changed then self.Changed:Fire(self:Status()) end
end

function SmartFarm:Destroy() self:Flush(); self.scope:Destroy() end
return SmartFarm
end

__modules["game/Telegram"] = function(require)
local Util = require("core/Util")
local Webhook = require("game/Webhook")
local Telegram = {}
Telegram.__index = Telegram

local function destination(config)
    local token = Util.trim(config:Get("webhook.tg_token"))
    local chat = Util.trim(config:Get("webhook.tg_chat_id"))
    if #token > 128 or not token:match("^%d+:[%w_%-]+$") then return nil end
    if #chat > 17 or not chat:match("^%-?%d+$") then return nil end
    local chatId = tonumber(chat)
    if chatId == 0 or math.abs(chatId) >= 2 ^ 52 then return nil end
    return token, chatId
end

local function outcome(code, status)
    return {ok = code == "sent", code = code, status = status or 0}
end

function Telegram.new(context)
    local self = setmetatable({
        runtime = context.runtime, config = context.config, adapter = context.adapter,
        scope = context.scope:Child(), queue = {}, pending = nil,
        timeout = Util.number(context.webhookTimeout, 20, 0.01, 30),
    }, Telegram)
    self.scope:Add(function() self.pending, self.queue = nil, {} end)
    return self
end

function Telegram:_Next()
    if self.pending or not self.scope.alive or #self.queue == 0 then return end
    local item = table.remove(self.queue, 1)
    local request = self.scope:Child()
    self.pending = request
    local function finish(result)
        if not request.alive then return end
        request:Destroy()
        self.pending = nil
        self.lastResult = result
        if item.callback and self.scope.alive then pcall(item.callback, result) end
        self:_Next()
    end

    request:Delay(self.timeout, function() finish(outcome("timeout")) end)
    request:Spawn(function()
        local token, chatId = destination(self.config)
        if not token or token ~= item.token or chatId ~= item.chatId then
            finish(outcome("cancelled")); return
        end
        local encoded, body = pcall(function()
            return self.runtime:Codec().encode({chat_id = chatId, text = item.text})
        end)
        if not encoded then finish(outcome("payload")); return end
        local ok, status, response = pcall(self.runtime.HTTP, self.runtime,
            "https://api.telegram.org/bot" .. token .. "/sendMessage", "POST", body)
        if not request.alive then return end
        if not ok then finish(outcome("transport")); return end
        if type(status) ~= "number" or status % 1 ~= 0 or status < 100 or status > 599 then
            finish(outcome("response")); return
        end
        if status == 429 then finish(outcome("rateLimited", status)); return end
        if status < 200 or status >= 300 then finish(outcome("http", status)); return end
        local decoded, data = pcall(function()
            if type(response) == "string" and #response <= 65536 then
                return self.runtime:Codec().decode(response)
            end
        end)
        local accepted = decoded and type(data) == "table" and data.ok == true
        finish(outcome(accepted and "sent" or "response", status))
    end)
end

function Telegram:SendText(message, callback)
    if not self.scope.alive then return false, outcome("cancelled") end
    local token, chatId = destination(self.config)
    if not token then return false, outcome("invalidTelegram") end
    if type(self.runtime.request) ~= "function" then return false, outcome("unsupported") end
    if type(message) ~= "string" or message == "" then return false, outcome("payload") end
    if #self.queue >= 16 then return false, outcome("busy") end
    self.queue[#self.queue + 1] = {text = Webhook.text(message, 4096), token = token, chatId = chatId, callback = callback}
    self:_Next()
    return true
end

function Telegram:Send(event, rewards, callback)
    local data = self.adapter:GameData()
    local lines = {string.format("Saint Hub | %s", tostring(event)),
        "Player: " .. self.adapter.player.Name, "Mode: " .. tostring(data.mode), "Map: " .. tostring(data.location)}
    local balances = Webhook.resourceLines(self.adapter)
    if #balances > 0 then
        lines[#lines + 1] = "Resources:"
        for _, line in ipairs(balances) do lines[#lines + 1] = line end
    end
    local drops = {}
    for name, count in pairs(rewards or {}) do
        drops[#drops + 1] = string.format("+%s %s", Webhook.text(count, 32), Webhook.text(name, 100))
        if #drops >= 100 then break end
    end
    table.sort(drops)
    if #drops > 0 then lines[#lines + 1] = "Rewards:" end
    for _, line in ipairs(drops) do lines[#lines + 1] = line end
    return self:SendText(table.concat(lines, "\n"), callback)
end

function Telegram:SendReport(report, callback)
    local id, lines = report.identity or {}, {}
    lines[#lines + 1] = (report.result == "victory" and "Victory" or report.result == "defeat" and "Defeat" or "Match finished")
    lines[#lines + 1] = (id.location ~= "" and id.location or id.name or "Unknown map") .. " · " .. (id.mode or "unknown")
    if id.difficulty and id.difficulty ~= "" then lines[#lines + 1] = "Difficulty: " .. id.difficulty end
    if id.weather and id.weather ~= "" then lines[#lines + 1] = "Weather: " .. id.weather end
    if report.progress and report.progress.wave then
        lines[#lines + 1] = "Wave: " .. tostring(report.progress.wave) .. (report.progress.maxWave and "/" .. tostring(report.progress.maxWave) or "")
    end
    if report.timing and report.timing.duration then lines[#lines + 1] = "Time: " .. tostring(math.floor(report.timing.duration)) .. "s" end
    if report.performance and report.performance.kills then lines[#lines + 1] = "Kills: " .. tostring(report.performance.kills) end
    if report.performance and report.performance.damage then lines[#lines + 1] = "Damage: " .. string.format("%.0f", report.performance.damage) end
    local rewards = {}; for name, value in pairs(report.rewards or {}) do rewards[#rewards + 1] = "+" .. tostring(value) .. " " .. name end
    table.sort(rewards); if #rewards > 0 then lines[#lines + 1] = "Rewards:" end
    for index = 1, math.min(8, #rewards) do lines[#lines + 1] = rewards[index] end
    if #rewards > 8 then lines[#lines + 1] = "+" .. tostring(#rewards - 8) .. " more" end
    local stats = report.stats and report.stats.totals
    if stats and stats.matches > 0 then
        lines[#lines + 1] = string.format("All time: %d matches · %dW/%dL · %.1f%% · best streak %d",
            stats.matches, stats.wins, stats.losses, stats.wins / stats.matches * 100, stats.best_streak)
    end
    local session = report.stats and report.stats.session
    if session and session.matches > 0 then
        lines[#lines + 1] = string.format("Session: %d matches · %dW/%dL · %.1f%%",
            session.matches, session.wins, session.losses, session.wins / session.matches * 100)
    end
    return self:SendText(table.concat(lines, "\n"), callback)
end

function Telegram:Destroy()
    self.scope:Destroy()
end

return Telegram
end

__modules["game/TraitIcons"] = function(require)
-- Read-only image catalogue. IDs below were verified against the live game's
-- ReplicatedStorage.packages.assets.gui.TraitIcons on 2026-11-03. Templates
-- override these fallbacks, including atlas rectangles; no game modules run.
local TraitIcons = {}
local entries = {
    {"Unique", "unique", "106165041836099"},
    {"Divine", "divine", "136020763726956"},
    {"Celestial", "ethereal", "122779785958409"},
    {"Adept", "neuroplasticity", "125205199635059"},
    {"Reaper", "reaper", "84105257755991"},
    {"Golden", "golden", "110727118151060"},
    {"Range", "range", "97808620409723"},
    {"Nimble", "nimble", "120317842461491"},
    {"Superior", "superior", "74642913422297"},
    {"Godspeed", "godspeed", "70454784426851"},
    {"Culling", "culling", "81776003135260"},
    {"Sniper", "sniper", "87780515075226"},
}
local rare = {{0, 0, 89, 255}, {1, 21, 173, 255}}
local legendary = {{0, 255, 170, 0}, {1, 255, 242, 58}}
local mythic = {{0, 255, 51, 210}, {0.2, 255, 51, 63}, {0.4, 255, 186, 51},
    {0.6, 177, 255, 51}, {0.8, 51, 255, 72}, {1, 51, 255, 219}}
local colors = {Unique = mythic, Divine = mythic, Celestial = mythic, Reaper = mythic, Golden = mythic,
    Adept = legendary, Godspeed = legendary, Culling = legendary, Sniper = legendary,
    Range = rare, Nimble = rare, Superior = rare}

function TraitIcons.mythic(name)
    return colors[name] == mythic
end

-- Exact native GUIGradientService.gradient_fx rainbow branch (speed_mul = 1).
-- One palette is shared by all our mythic icons per frame.
function TraitIcons.rainbow(now)
    if not Color3 or not Color3.fromHSV or not ColorSequence or not ColorSequenceKeypoint then return nil end
    local points, phase = {}, (now * 0.1 / (2 / 3)) % 1
    for index = 0, 10 do
        local position = index / 10
        points[#points + 1] = ColorSequenceKeypoint.new(position, Color3.fromHSV((phase + position * 0.4) % 1, 0.8, 1))
    end
    return ColorSequence.new(points)
end

-- Read-only native border properties. These are templates, NOT animation sources;
-- the native service animates clones using the rainbow formula above.
function TraitIcons.sources(root)
    local result = {}
    if not root then return result end
    for name, palette in pairs(colors) do
        local rarity = palette == mythic and "Mythic" or (palette == legendary and "Legendary" or "Rare")
        local ok, border = pcall(function()
            local folder = root:FindFirstChild(rarity)
            local source = folder and folder:FindFirstChild("Border")
            return source and source:IsA("UIGradient") and source or nil
        end)
        if ok then result[name] = border end
    end
    return result
end

function TraitIcons.gradient(descriptor)
    local palette = colors[descriptor.name]
    if not palette or not ColorSequence or not ColorSequenceKeypoint or not Color3 then return nil end
    local points = {}
    for _, point in ipairs(palette) do
        points[#points + 1] = ColorSequenceKeypoint.new(point[1], Color3.fromRGB(point[2], point[3], point[4]))
    end
    return ColorSequence.new(points)
end

function TraitIcons.names()
    local result = {}
    for index, entry in ipairs(entries) do result[index] = entry[1] end
    return result
end

local function fallback(entry)
    return {name = entry[1], image = "rbxassetid://" .. entry[3], rectOffset = {0, 0}, rectSize = {0, 0}}
end

function TraitIcons.default(name)
    if type(name) ~= "string" then return end
    for _, entry in ipairs(entries) do
        if name:lower() == entry[1]:lower() or name:lower() == entry[2] then return fallback(entry) end
    end
end

function TraitIcons.read(root)
    local result = {}
    for _, entry in ipairs(entries) do
        local descriptor = fallback(entry)
        if root then
            local ok, current = pcall(function()
                local icon = root:FindFirstChild(entry[2])
                if not icon or not icon:IsA("ImageLabel") then return end
                if type(icon.Image) ~= "string" or not icon.Image:match("^rbxassetid://[1-9]%d*$") then return end
                local offset, size = icon.ImageRectOffset, icon.ImageRectSize
                for _, value in ipairs({offset.X, offset.Y, size.X, size.Y}) do
                    if type(value) ~= "number" or value < 0 or value > 1e6 or value ~= math.floor(value) then return end
                end
                return {name = entry[1], image = icon.Image, rectOffset = {offset.X, offset.Y}, rectSize = {size.X, size.Y}}
            end)
            if ok and current then descriptor = current end
        end
        result[entry[1]] = descriptor
    end
    return result
end

return TraitIcons
end

__modules["game/Units"] = function(require)
local Scheduler = require("core/Scheduler")
local Util = require("core/Util")
local Placement = require("game/Placement")
local MacroPosition = require("game/MacroPosition")
local Units = {}
Units.__index = Units
local MACRO_TIMEOUT, POLL, MAX_SPAWN_ATTEMPTS = 90, 0.05, 8
local macroActions = {spawn = true, upgrade = true, ability = true, auto_ability = true, priority = true, sell = true}

local function positive(value)
    return type(value) == "number" and value == value and value > 0 and value < math.huge
end

local function uuidValue(value)
    return type(value) == "string" and #value > 0 and #value <= 128 and value or nil
end

local function stat(record, name)
    local object = record.stats:FindFirstChild(name)
    return object and object.Value
end

local function findPosition(placement, lane, percent, surface, radius)
    lane = math.max(1, math.floor(tonumber(lane) or 1))
    if percent == nil then percent = 50 end
    for current = lane, 1, -1 do
        local position = placement:Find(current, percent, surface, radius)
        if position then return position, current end
    end
end

function Units.new(context)
    local self = setmetatable({
        scope = context.scope:Child(), adapter = context.adapter, config = context.config, saved = context.unitsConfig,
        records = {}, unitScopes = {}, placement = context.placement or Placement.new(), folder = nil, macros = context.macros,
        useChallengeUnits = context.useChallengeUnits, logs = context.sessionLogs, spawnAttempts = {},
        positionFactory = context.positionFactory or function(position, rotationY)
            local frame = CFrame.new(position)
            return rotationY and frame * CFrame.Angles(0, rotationY, 0) or frame
        end,
    }, Units)
    self.scheduler = Scheduler.new(self.scope:Child())
    self.scope:Add(self.placement)
    self.scope:Add(self.config.Changed:Connect(function(path)
        if path:match("^autoplace%.") then
            self:_Sync()
            if path == "autoplace.enabled" and self.config:Get(path) then self.scope:Spawn(function() self:Refresh() end) end
        end
    end))
    self:_Sync()
    return self
end

function Units:_BindFolder()
    local folder = workspace:FindFirstChild("_UNITS")
    if folder == self.folder then return end
    if self.folderScope then self.folderScope:Destroy() end
    self.records, self.unitScopes, self.spawnAttempts = {}, {}, {}
    self.folder = folder
    if not folder then return end
    self.folderScope = self.scope:Child()
    self.folderScope:Connect(folder.ChildAdded, function(unit) self:_Track(unit) end)
    self.folderScope:Connect(folder.ChildRemoved, function(unit)
        local scope = self.unitScopes[unit]
        if scope then scope:Destroy() end
        self.unitScopes[unit], self.records[unit] = nil, nil
    end)
    for _, unit in ipairs(folder:GetChildren()) do self:_Track(unit) end
end

function Units:_Track(unit)
    if self.unitScopes[unit] or unit.Parent ~= self.folder then return end
    local scope = self.folderScope:Child()
    self.unitScopes[unit] = scope
    local statsScope, valuesScope

    local function bindStats()
        if statsScope then statsScope:Destroy() end
        local stats = unit:FindFirstChild("_stats")
        statsScope = scope:Child()

        local function bindValues()
            if valuesScope then valuesScope:Destroy() end
            valuesScope = statsScope:Child()
            local owner = stats and stats:FindFirstChild("player")
            local uuid = stats and stats:FindFirstChild("uuid")

            local function update()
                if unit.Parent ~= self.folder or not owner or not owner:IsA("ObjectValue")
                    or owner.Value ~= self.adapter.player then
                    self.records[unit] = nil
                    return
                end

                local record = self.records[unit]
                if not record then
                    record = {unit = unit, nextUpgrade = 0, upgradeFailures = 0}
                    self.records[unit] = record
                end
                record.stats, record.name = stats, unit.Name
                record.uuid = uuid and uuid:IsA("StringValue") and uuidValue(uuid.Value) or ""
            end

            if owner and owner:IsA("ObjectValue") then valuesScope:Connect(owner.Changed, update) end
            if uuid and uuid:IsA("StringValue") then valuesScope:Connect(uuid.Changed, update) end
            update()
        end

        if stats then
            local function onStatChanged(child)
                if child.Name == "player" or child.Name == "uuid" then bindValues() end
            end
            statsScope:Connect(stats.ChildAdded, onStatChanged)
            statsScope:Connect(stats.ChildRemoved, onStatChanged)
        end
        bindValues()
    end

    local function onChildChanged(child)
        if child.Name == "_stats" then bindStats() end
    end
    scope:Connect(unit.ChildAdded, onChildChanged)
    scope:Connect(unit.ChildRemoved, onChildChanged)
    bindStats()
end

function Units:Refresh()
    if not self.scope.alive then return 0, "destroyed" end
    if self.refreshing then return 0, "busy" end
    self.refreshing = true
    local api, ids = self.adapter, self.adapter.unitsIds or {}
    -- RefreshEquipped owns the guarded K toggle. LoadUnitsIds replaces the ID
    -- table, so retain existing aliases even when using an older adapter double.
    local ok, slots, status = pcall(function()
        if api.RefreshEquipped then return api:RefreshEquipped() end
        if api.LoadUnitsIds then return api:LoadUnitsIds(true) end
        return {}, "missing_api"
    end)
    api.unitsIds, api.UnitsIds = ids, ids
    self.refreshing = false
    if not ok then return 0, "refresh_failed" end
    if not self.scope.alive then return 0, "destroyed" end
    if type(slots) ~= "table" then return 0, "missing_unit" end
    return self:_RememberEquipped(slots), status, slots
end

function Units:_RememberEquipped(slots)
    local ids, count = self.adapter.unitsIds or {}, 0
    self.adapter.unitsIds, self.adapter.UnitsIds = ids, ids
    for index, data in pairs(slots) do
        if type(index) == "number" and index % 1 == 0 and index >= 1 and index <= 6 and
            type(data) == "table" and uuidValue(data.uuid) then
            ids[index] = data.uuid
            local prefix = "unit" .. index
            self.saved:Set(prefix .. ".uuid", data.uuid)
            if type(data.name) == "string" and data.name ~= "" then self.saved:Set(prefix .. ".name", data.name) end
            if positive(data.cost) then self.saved:Set(prefix .. ".cost", data.cost) end
            count = count + 1
        end
    end
    return count
end

function Units:AutoFill()
    if not self.scope.alive or self.refreshing then return 0, 0 end
    local api = self.adapter
    if api:InLobby() then return 0, 0, "lobby" end
    local slots = api:Hotbar()
    local equipped = api:Equipped()
    for index, slot in pairs(equipped) do
        local hotbar = slots[index]
        if not hotbar or not uuidValue(hotbar.uuid) or hotbar.uuid == slot.uuid then slots[index] = slot end
    end
    local found = false
    for _, slot in pairs(slots) do
        if uuidValue(slot.uuid) then found = true; break end
    end
    if not found then
        local _, _, refreshed = self:Refresh()
        slots = refreshed or slots
    end
    local count, skipped = 0, 0
    local nextConfig = Util.copy(self.config.data)
    local resolved = {}
    for index = 1, 6 do
        local slot = slots[index]
        if slot and uuidValue(slot.uuid) then
            local rule = api:AutoPlaceRule(slot)
            if rule then
                local config = nextConfig.autoplace["unit" .. index]
                config.place_type, config.path_percent, config.count = rule.place_type, rule.path_percent, rule.count
                config.place_pos = nil
                if positive(rule.cost) then slot.cost = rule.cost end
                resolved[index] = slot
                count = count + 1
            else
                skipped = skipped + 1
            end
        end
    end
    if count > 0 then
        self:_RememberEquipped(resolved)
        self.config:Apply(nextConfig)
    end
    return count, skipped
end

function Units:_MacroGuard(execution)
    if not self.scope.alive or (self.adapter.scope and not self.adapter.scope.alive) then return false, "destroyed" end
    if not execution.scope.alive then return false, "cancelled" end
    if os.clock() >= execution.deadline then return false, "timeout" end
    if self.adapter:InLobby() then return false, "lobby" end
    local finished = Util.find(workspace, "_DATA.GameFinished")
    if finished and finished.Value then return false, "game_finished" end
    return true
end

function Units:_MacroSlot(slot, execution)
    local api = self.adapter
    local hotbar = api.Hotbar and api:Hotbar() or {}
    local current = hotbar[slot] or {}
    if not uuidValue(current.uuid) and not uuidValue(api.unitsIds and api.unitsIds[slot]) and not execution.refreshed then
        execution.refreshed = true
        self:Refresh()
        hotbar = api.Hotbar and api:Hotbar() or {}
        current = hotbar[slot] or {}
    end
    local data = self.saved.data["unit" .. slot] or {}
    local uuid = uuidValue(current.uuid) or uuidValue(api.unitsIds and api.unitsIds[slot]) or uuidValue(data.uuid)
    local cost = positive(current.cost) and current.cost or (positive(data.cost) and data.cost or nil)
    local name = type(current.name) == "string" and current.name ~= "" and current.name or data.name
    return uuid, cost, name
end

function Units:_MacroMoney(cost)
    local yen = self.adapter:Resource("Yen") -- numeric player resource, never UI text
    return type(yen) == "number" and yen == yen and yen < math.huge and yen >= cost
end

function Units:_MacroOwned(uuid, ordinal)
    -- Folder order is the same ordinal convention used by passive capture.
    local count = 0
    for _, unit in ipairs(self.folder and self.folder:GetChildren() or {}) do
        local record = self.records[unit]
        if record and unit.Parent and record.uuid == uuid and stat(record, "player") == self.adapter.player then
            count = count + 1
            if count == (ordinal or 1) then return record end
        end
    end
end

function Units:_MacroOwnedCount(uuid)
    local count = 0
    for unit, record in pairs(self.records) do
        if unit.Parent and record.uuid == uuid and stat(record, "player") == self.adapter.player then count = count + 1 end
    end
    return count
end

local function retryable(code)
    return code == "busy" or code == "not_enough_money" or code == "cooldown" or code == "not_ready" or code == "timeout"
end

function Units:_MacroCall(name, ...)
    if type(self.adapter.MacroCall) == "function" then return self.adapter:MacroCall(name, ...) end
    return self.adapter:Call(name, ...)
end

function Units:_SpawnMacro(step, execution)
    local slot, recorded = step.slot, step.position
    local exact = recorded and Vector3.new(recorded.x, recorded.y, recorded.z)
    local attempts, waitReason = 0, "not_ready"
    while self:_MacroGuard(execution) do
        self:_BindFolder() -- auto Tick is paused while a macro plays
        local uuid, cost, name = self:_MacroSlot(slot, execution)
        local alive, reason = self:_MacroGuard(execution)
        if not alive then return false, reason end
        if not uuid then return false, "missing_unit" end
        if not self.folder or not cost then
            waitReason = "not_ready"
        elseif not self:_MacroMoney(cost) then
            waitReason = "not_enough_money"
        else
            waitReason = "no_position"
            local cfg = self.config.data.autoplace["unit" .. slot] or {}
            -- Deliberately do not gate by cfg.count or autoplace.enabled.
            local lane = cfg.lane or self.config:Get("autoplace.lane") or 1
            local radius = type(self.adapter.PlacementRadius) == "function" and self.adapter:PlacementRadius(name) or nil
            local percent = cfg.path_percent ~= nil and cfg.path_percent or cfg.place_pos
            local position = exact or findPosition(self.placement, lane, percent, cfg.place_type, radius)
            if position then
                if not exact then execution.position = position end
                local before = {}
                for unit, record in pairs(self.records) do if record.uuid == uuid then before[unit] = true end end
                local frame = self.positionFactory(position, step.rotationY)
                if not frame then
                    if not exact then self.placement:Result(position, false); execution.position = nil end
                    return false, "invalid_position"
                end
                alive, reason = self:_MacroGuard(execution)
                if not alive then return false, reason end
                local success, code = self:_MacroCall("spawn_unit", uuid, frame)
                alive, reason = self:_MacroGuard(execution)
                if not alive then return false, reason end
                local confirmed, deadline = false, math.min(execution.deadline, os.clock() + 3)
                if success == true or code == "timeout" then
                    repeat
                        self:_BindFolder()
                        for unit, record in pairs(self.records) do
                            if not before[unit] and record.uuid == uuid and unit.Parent and stat(record, "player") == self.adapter.player then
                                confirmed = true; break
                            end
                        end
                        if confirmed or os.clock() >= deadline then break end
                        task.wait(POLL)
                        alive, reason = self:_MacroGuard(execution)
                        if not alive then return false, reason end
                    until false
                end
                if not exact then self.placement:Result(position, confirmed) end
                execution.position = nil
                if confirmed then return true end
                if exact and (success == true or code == "timeout") then return false, "spawn_unconfirmed" end
                if exact and (code == nil or code == false or code == "invalid_position" or code == "no_position") then
                    return false, "invalid_position"
                end
                waitReason = type(code) == "string" and code or "spawn_unconfirmed"
                if not retryable(code) then
                    attempts = attempts + 1
                    if success ~= true and code ~= nil and code ~= false and code ~= "invalid_position" and code ~= "no_position" then
                        return false, type(code) == "string" and code or "spawn_failed"
                    end
                    if attempts >= MAX_SPAWN_ATTEMPTS then return false, success == true and "spawn_unconfirmed" or "invalid_position" end
                end
            end
        end
        task.wait(POLL) -- readiness polling exists only during active playback
    end
    local _, reason = self:_MacroGuard(execution)
    return false, reason == "timeout" and waitReason or reason
end

function Units:_MacroAction(step, execution)
    if step.type == "priority" then
        while self:_MacroGuard(execution) do
            self:_BindFolder()
            local uuid = self:_MacroSlot(step.slot, execution)
            local alive, reason = self:_MacroGuard(execution)
            if not alive then return false, reason end
            if not uuid then return false, "missing_unit" end
            local record = self:_MacroOwned(uuid, step.ordinal)
            if record then
                local success, code = self.adapter:ChangePriority(record.unit, step.priority)
                if success ~= true then return false, type(code) == "string" and code or "priority_failed" end
                local deadline = math.min(execution.deadline, os.clock() + 3)
                repeat
                    local value = record.stats and record.stats:FindFirstChild("priority")
                    if value and value.Value == step.priority then return true end
                    if os.clock() >= deadline then return false, "priority_unconfirmed" end
                    task.wait(POLL)
                    alive, reason = self:_MacroGuard(execution)
                    if not alive then return false, reason end
                until false
            end
            task.wait(POLL)
        end
        local _, reason = self:_MacroGuard(execution)
        return false, reason
    end
    local endpoint = step.type == "upgrade" and "upgrade_unit_ingame" or "sell_unit_ingame"
    if step.type == "ability" then
        endpoint = self:_AbilityEndpoint()
        if not endpoint then return false, "missing_ability" end
    end
    while self:_MacroGuard(execution) do
        self:_BindFolder()
        local uuid = self:_MacroSlot(step.slot, execution)
        local alive, reason = self:_MacroGuard(execution)
        if not alive then return false, reason end
        if not uuid then return false, "missing_unit" end
        local record = self:_MacroOwned(uuid, step.ordinal)
        if record then
            local ready = true
            local before = stat(record, "upgrade")
            local ownedBefore = step.type == "sell" and self:_MacroOwnedCount(uuid) or nil
            if step.type == "upgrade" then
                local maximum, cost = stat(record, "max_upgrade"), self:_UpgradeCost(record)
                if type(before) == "number" and positive(maximum) and before >= maximum then return false, "max_upgrade" end
                ready = type(before) == "number" and
                    (cost == nil or (type(cost) == "number" and cost >= 0 and cost < math.huge and self:_MacroMoney(cost)))
            elseif step.type == "ability" then
                ready = self:_AbilityReady(record)
            end
            if ready then
                local castBefore = step.type == "ability" and stat(record, "last_active_cast")
                local success, code = self:_MacroCall(endpoint, record.unit)
                alive, reason = self:_MacroGuard(execution)
                if not alive then return false, reason end
                if success == true then
                    if step.type == "ability" then
                        if type(castBefore) ~= "number" then return true end
                        local deadline = math.min(execution.deadline, os.clock() + 8)
                        repeat
                            local cast = stat(record, "last_active_cast")
                            if type(cast) == "number" and cast > castBefore then return true end
                            if os.clock() >= deadline or not record.unit.Parent then break end
                            task.wait(POLL)
                            alive, reason = self:_MacroGuard(execution)
                            if not alive then return false, reason end
                        until false
                        return false, "ability_unconfirmed"
                    end
                    local deadline = math.min(execution.deadline, os.clock() + (step.type == "sell" and 8 or 3))
                    repeat
                        if step.type == "sell" and not record.unit.Parent then return true end
                        if step.type == "sell" then
                            self:_BindFolder()
                            if self:_MacroOwnedCount(uuid) < ownedBefore then return true end
                        end
                        if step.type == "upgrade" and (tonumber(stat(record, "upgrade")) or before) > before then
                            return true
                        end
                        if os.clock() >= deadline then break end
                        task.wait(POLL)
                        alive, reason = self:_MacroGuard(execution)
                        if not alive then return false, reason end
                    until false
                    -- Never repeat a sale against a shifted ordinal or a delayed
                    -- upgrade: a successful request with no observable effect is
                    -- ambiguous, not evidence to issue another destructive action.
                    return false, step.type == "sell" and "sell_unconfirmed" or "upgrade_unconfirmed"
                end
                if not retryable(code) then return false, type(code) == "string" and code or "step_failed" end
            end
        end
        task.wait(POLL)
    end
    local _, reason = self:_MacroGuard(execution)
    return false, reason
end

function Units:_MacroAutoAbility(step, execution)
    if type(self.adapter.SetAutoAbility) ~= "function" then return false, "missing_auto_ability" end
    while self:_MacroGuard(execution) do
        self:_BindFolder()
        local uuid = self:_MacroSlot(step.slot, execution)
        local alive, reason = self:_MacroGuard(execution)
        if not alive then return false, reason end
        if not uuid then return false, "missing_unit" end
        local record = self:_MacroOwned(uuid, step.ordinal)
        if record then
            local success, code = self.adapter:SetAutoAbility(record.unit, step.enabled)
            alive, reason = self:_MacroGuard(execution)
            if not alive then return false, reason end
            if success == true then return true end
            if not retryable(code) and code ~= "missing_auto_ability" and code ~= "missing_ability" then
                return false, type(code) == "string" and code or "auto_ability_failed"
            end
        end
        task.wait(POLL)
    end
    local _, reason = self:_MacroGuard(execution)
    return false, reason
end

function Units:ExecuteMacroStep(step)
    if type(step) ~= "table" or getmetatable(step) ~= nil then return false, "invalid_step" end
    for key in next, step do
        if key ~= "type" and key ~= "slot" and key ~= "ordinal" and key ~= "wave" and
            not (step.type == "auto_ability" and key == "enabled") and
            not (step.type == "priority" and key == "priority") and
            not (step.type == "spawn" and (key == "position" or key == "rotationY")) then
            return false, "invalid_step_keys"
        end
    end
    if type(step.type) ~= "string" or not macroActions[step.type] then return false, "unsupported_step" end
    if step.type == "auto_ability" and type(step.enabled) ~= "boolean" then return false, "invalid_auto_ability" end
    if step.type == "priority" and type(step.priority) ~= "string" then return false, "invalid_priority" end
    if type(step.slot) ~= "number" or step.slot % 1 ~= 0 or step.slot < 1 or step.slot > 6 then return false, "invalid_slot" end
    if step.ordinal ~= nil and (type(step.ordinal) ~= "number" or step.ordinal % 1 ~= 0 or step.ordinal < 1 or step.ordinal > 100) then return false, "invalid_ordinal" end
    if step.wave ~= nil and (type(step.wave) ~= "number" or step.wave % 1 ~= 0 or step.wave < 0 or step.wave > 100000) then return false, "invalid_wave" end
    if not MacroPosition.validate(step.position, step.rotationY) then return false, "invalid_position" end
    local parent = self.macros and self.macros.playing and self.macros.playScope or self.scope
    local execution = {scope = parent:Child(), deadline = os.clock() + MACRO_TIMEOUT}
    execution.scope:Add(function()
        if execution.position then self.placement:Result(execution.position, false); execution.position = nil end
    end)
    local ok, success, code = pcall(function()
        while self:_MacroGuard(execution) do
            local wave = workspace:FindFirstChild("_wave_num")
            if not step.wave or step.wave == 0 or (wave and tonumber(wave.Value) and tonumber(wave.Value) >= step.wave) then break end
            task.wait(POLL)
        end
        local alive, reason = self:_MacroGuard(execution)
        if not alive then return false, reason == "timeout" and "wave_not_reached" or reason end
        if step.type == "spawn" then return self:_SpawnMacro(step, execution) end
        if step.type == "auto_ability" then return self:_MacroAutoAbility(step, execution) end
        return self:_MacroAction(step, execution)
    end)
    execution.scope:Destroy()
    if not ok then return false, "step_error" end
    return success, code
end

function Units:SpawnBySlot(slot)
    return self:ExecuteMacroStep({type = "spawn", slot = slot})
end

function Units:_Sync()
    self.scheduler:Remove("units")
    if self.adapter:InLobby() or not self.config:Get("autoplace.enabled") then return end
    self.scheduler:Set("units", 1, function() self:_Tick() end, true)
end

function Units:_Count(data)
    local count = 0
    for _, record in pairs(self.records) do
        if record.uuid == data.uuid or (record.uuid == "" and record.name == data.name) then count = count + 1 end
    end
    return count
end

function Units:_Rules(priority, upgrading, hotbar)
    local result = {}
    for index = 1, 6 do
        local data = self.saved.data["unit" .. index] or {}
        -- Presets describe slots, not old inventory UUIDs. A verified current
        -- hotbar identity wins at runtime without rewriting saved player data.
        local current = hotbar and hotbar[index]
        if current and uuidValue(current.uuid) then
            data = {uuid = current.uuid, name = current.name or data.name,
                cost = positive(current.cost) and current.cost or data.cost, unique = current.unique}
        end
        local cfg = self.config.data.autoplace["unit" .. index] or {}
        if (tonumber(cfg.count) or 0) > 0 and uuidValue(data.uuid) and (not upgrading or cfg.auto_upgrade ~= false) then
            result[#result + 1] = {index = index, data = data, cfg = cfg}
        end
    end
    table.sort(result, function(a, b)
        local first, second = tonumber(a.cfg[priority]) or a.index, tonumber(b.cfg[priority]) or b.index
        return first == second and a.index < b.index or first < second
    end)
    return result
end

function Units:_Matches(record, data)
    return record.uuid == data.uuid or (record.uuid == "" and record.name == data.name)
end

function Units:_TargetCount(rule, slot)
    local count = math.max(0, tonumber(rule.cfg.count) or 0)
    if type(self.adapter.SpawnLimit) == "function" then
        local ok, limit = pcall(self.adapter.SpawnLimit, self.adapter, slot or rule.data)
        if ok and type(limit) == "number" and limit == limit and limit >= 1 and limit <= 20 and limit % 1 == 0 then
            count = math.min(count, limit)
        end
    end
    return count
end

function Units:_SpawnState(uuid)
    self.spawnAttempts = self.spawnAttempts or {}
    local state = self.spawnAttempts[uuid]
    if not state then state = {failures = 0, nextAttempt = 0}; self.spawnAttempts[uuid] = state end
    return state
end

function Units:_SpawnResult(rule, state, confirmed, code)
    state.failures = confirmed and 0 or math.min(state.failures + 1, 5)
    state.code = confirmed and "confirmed" or (type(code) == "string" and code or "spawn_unconfirmed")
    state.nextAttempt = os.clock() + (confirmed and 0.5 or math.min(30, 2 * 2 ^ (state.failures - 1)))
    if self.logs then
        local fields = {slot = rule.index, unit_name = rule.data.name, code = state.code,
            failures = state.failures, retry_seconds = math.max(0, state.nextAttempt - os.clock())}
        if confirmed then self.logs:Info("unit_spawn_confirmed", fields)
        else self.logs:Warn("unit_spawn_deferred", fields) end
    end
end

function Units:_UpgradeCost(record)
    local replicated = record.stats:FindFirstChild("upgrade_cost")
    local price = replicated and tonumber(replicated.Value)
    if type(price) == "number" and price == price and price >= 0 and price < math.huge then return price end
    if type(self.adapter.UpgradeCost) == "function" then
        local ok, current = pcall(self.adapter.UpgradeCost, self.adapter, record.unit)
        if ok and type(current) == "number" and current == current and current > 0 and current < math.huge then return current end
    end
end

function Units:_Upgradeable(record)
    local upgrade = record.stats:FindFirstChild("upgrade")
    local maximum = record.stats:FindFirstChild("max_upgrade")
    local current, limit = upgrade and tonumber(upgrade.Value), maximum and tonumber(maximum.Value)
    local price = self:_UpgradeCost(record)
    return record.unit.Parent and current ~= nil and (limit == nil or limit <= 0 or current < limit) and
        (record.nextUpgrade or 0) <= os.clock() and (price == nil or price <= self.adapter:Resource("Yen"))
end

function Units:_AutoUpgrade(hotbar)
    local strict = self.config:Get("autoplace.upgrade_mode") == "strict"
    local pendingPriority
    for _, rule in ipairs(self:_Rules("upgrade_priority", true, hotbar)) do
        local priority = tonumber(rule.cfg.upgrade_priority) or rule.index
        if pendingPriority and priority > pendingPriority then return end
        local count = 0
        for _, record in pairs(self.records) do
            if self:_Matches(record, rule.data) and record.unit.Parent then
                count = count + 1
                local complete = false
                if strict then
                    local current, limit = tonumber(stat(record, "upgrade")), tonumber(stat(record, "max_upgrade"))
                    complete = current ~= nil and limit ~= nil and limit >= 0 and current >= limit
                    if not complete then pendingPriority = priority end
                end
                if not complete and self:_Upgradeable(record) then
                    self:_Upgrade(record)
                    return
                end
            end
        end
        if strict and count < self:_TargetCount(rule, hotbar and hotbar[rule.index]) then pendingPriority = priority end
    end
end

function Units:_Upgrade(record)
    local upgrade = record.stats:FindFirstChild("upgrade")
    local before = upgrade and tonumber(upgrade.Value)
    local success = self.adapter:Call("upgrade_unit_ingame", record.unit)
    local deadline = os.clock() + 1
    while success and self.scope.alive and record.unit.Parent and upgrade and tonumber(upgrade.Value) == before and os.clock() < deadline do
        task.wait(0.1)
    end
    local confirmed = before ~= nil and upgrade and tonumber(upgrade.Value) and tonumber(upgrade.Value) > before
    -- Only replicated level growth confirms an upgrade. Unknown/rejected
    -- attempts use exponential backoff, so a missing future UI field cannot
    -- bring back the old "Not enough money" flood.
    record.upgradeFailures = confirmed and 0 or math.min((record.upgradeFailures or 0) + 1, 4)
    record.nextUpgrade = os.clock() + (confirmed and 1.5 or math.min(30, 5 * 2 ^ (record.upgradeFailures - 1)))
    return confirmed == true
end

function Units:_AbilityEndpoint()
    if not self.adapter.Endpoint then return nil end
    for _, name in ipairs({"use_active_attack", "activate_unit_ability"}) do
        if self.adapter:Endpoint(name) then return name end
    end
end

function Units:_AbilityReady(record)
    if not record.unit.Parent or (record.nextAbility or 0) > os.clock() then return false end
    local active = stat(record, "active_attack")
    if type(active) == "string" and (active == "" or active:lower() == "nil") then return false end
    if stat(record, "active_queued_or_using") == true then return false end
    local cooldown = stat(record, "active_attack_cooldown")
    local lastCast = stat(record, "last_active_cast")
    if type(cooldown) == "number" and cooldown > 0 then
        if type(lastCast) ~= "number" or tick() - lastCast < cooldown then return false end
    end
    local remaining = stat(record, "ability_cooldown")
    if type(remaining) == "number" and remaining > 0 then return false end
    for _, name in ipairs({"active_attack_ready", "ability_ready"}) do
        if stat(record, name) == false then return false end
    end
    return true
end

function Units:_UseAbility(record, endpoint)
    local success = self.adapter:Call(endpoint, record.unit)
    record.nextAbility = os.clock() + (success and 1.5 or 5)
    return success
end

function Units:_Tick()
    if not self.config:Get("autoplace.enabled") or not self.scope.alive or (self.macros and self.macros.playing)
        or (self.config:Get("farm.method") == "macro" and not self.useChallengeUnits) then return end
    local finished = Util.find(workspace, "_DATA.GameFinished")
    if finished and finished.Value then return end
    self:_BindFolder()
    if not self.folder then return end
    local hotbar = self.adapter:Hotbar()
    local placementRules = self:_Rules("place_priority", false, hotbar)

    -- Abilities remain responsive while the placement queue is waiting for
    -- money. At most one cast per tick, but a cast/rejection must not consume
    -- the placement/upgrade pass (several ready copies used to starve it forever).
    local abilityEndpoint = self:_AbilityEndpoint()
    if abilityEndpoint then
        local attempted = false
        for _, rule in ipairs(placementRules) do
            if rule.cfg.auto_ability and not attempted then
                for _, record in pairs(self.records) do
                    if self:_Matches(record, rule.data) and self:_AbilityReady(record) then
                        self:_UseAbility(record, abilityEndpoint)
                        attempted = true
                        break
                    end
                end
            end
        end
    end
    if not self.scope.alive or not self.config:Get("autoplace.enabled") then return end

    -- Prefer lower priority numbers, but do not let one large unit with no valid
    -- point block every later slot. Missing money still preserves strict order;
    -- missing geometry skips only that rule for the current tick.
    for _, rule in ipairs(placementRules) do
        local slot = hotbar[rule.index]
        local equipped = slot and (slot.uuid == rule.data.uuid or (slot.uuid == "" and slot.name == rule.data.name))
        local state = self:_SpawnState(rule.data.uuid)
        local spawnPending = self.adapter.inFlight and self.adapter.inFlight.spawn_unit ~= nil
        if equipped and not spawnPending and state.nextAttempt <= os.clock()
            and self:_Count(rule.data) < self:_TargetCount(rule, slot) then
            local cost = slot.cost > 0 and slot.cost or rule.data.cost
            if cost <= 0 or self.adapter:Resource("Yen") >= cost then
                local lane = rule.cfg.lane or self.config:Get("autoplace.lane") or 1
                local radius = type(self.adapter.PlacementRadius) == "function" and self.adapter:PlacementRadius(slot.name) or nil
                local percent = rule.cfg.path_percent ~= nil and rule.cfg.path_percent or rule.cfg.place_pos
                local position, actualLane = findPosition(self.placement, lane, percent, rule.cfg.place_type, radius)
                if position then
                    local before = self:_Count(rule.data)
                    local frame = self.positionFactory and self.positionFactory(position) or CFrame.new(position)
                    local success, code = self.adapter:Call("spawn_unit", rule.data.uuid, frame)
                    local deadline = os.clock() + 2
                    -- Even a transport timeout can have spawned a replicated
                    -- unit. Observe that receipt before deciding to retry.
                    while (success or code == "timeout") and self.scope.alive
                        and self:_Count(rule.data) <= before and os.clock() < deadline do task.wait(0.1) end
                    local confirmed = self:_Count(rule.data) > before
                    self.placement:Result(position, confirmed)
                    self:_SpawnResult(rule, state, confirmed, code)
                    state.requestedLane, state.actualLane = lane, actualLane
                    if confirmed or not self.scope.alive then return end
                    -- Rejected/unconfirmed Fishi (or any other slot) must not
                    -- monopolize the tick and starve all existing-unit upgrades.
                end
            else
                return -- Preserve placement priority while only money is missing.
            end
            -- No valid point: try the next placement rule before upgrades.
        end
    end

    self:_AutoUpgrade(hotbar)
end

function Units:Destroy()
    self.scope:Destroy()
    self.records, self.unitScopes, self.spawnAttempts = {}, {}, {}
end

return Units
end

__modules["game/Visuals"] = function(require)
-- Passive, reversible PlayerGui presentation. No stats, attributes, remotes or hooks.
local TraitIcons = require("game/TraitIcons")
local Visuals = {}
Visuals.__index = Visuals

local LIMIT = 1600
local MAX_NUMBER = 1e15
local DEFAULT_RESOURCES = {"Gems", "Gold", "Yen", "Diamonds", "Coins", "Cash", "Tokens", "Credits",
    "Crystals", "Jewels", "Rerolls", "TraitRerolls", "Emeralds", "Rubies", "Pearls"}
-- `Resource` is the shared HUD container, not the battle Yen counter.
local RESOURCE_FIELDS = {Gems = "gem_amount", Gold = "gold_amount", Yen = "yen_amount"}
local RESOURCE_ALIASES = {Gems = {"gem"}, Gold = {"gold"}, Yen = {"yen", "money"},
    GemsLegacy = {"legacygems", "legacygem", "gemslegacy"}, SummerPearls = {"summerpearls", "summerpearl"}}
local BLOCKED = {"trade", "purchase", "transaction", "checkout", "shop", "store"}

local function get(object, key)
    local ok, value = pcall(function() return object[key] end)
    if ok then return value end
end

local function isA(object, class)
    local ok, result = pcall(function() return object:IsA(class) end)
    return ok and result == true
end

local function find(object, name)
    local ok, child = pcall(function() return object:FindFirstChild(name) end)
    if ok then return child end
end

local function findClass(object, class)
    local ok, child = pcall(function() return object:FindFirstChildOfClass(class) end)
    if ok then return child end
end

local function children(object)
    local ok, result = pcall(function() return object:GetChildren() end)
    return ok and type(result) == "table" and result or {}
end

local function normalize(value)
    return type(value) == "string" and value:lower():gsub("[^%w]", "") or ""
end

-- Bounded batches, not a permanent 1600-node blind spot. Never walk unit preview
-- models: their parts previously consumed the budget before the HUD was reached.
local function walker(root)
    return {queue = {root}, cursor = 1, index = 1}
end
local function batch(state, limit)
    local result, examined = {}, 0
    while state.cursor <= #state.queue and examined < (limit or LIMIT) do
        state.children = state.children or children(state.queue[state.cursor])
        local child = state.children[state.index]
        if not child then
            state.queue[state.cursor] = false
            state.cursor, state.index, state.children = state.cursor + 1, 1, nil
        else
            state.index, examined = state.index + 1, examined + 1
            local kind, name = get(child, "ClassName"), normalize(get(child, "Name"))
            if kind ~= "WorldModel" and kind ~= "Model" and kind ~= "ViewportFrame" and not name:find("sainthub", 1, true) then
                result[#result + 1] = child
                state.queue[#state.queue + 1] = child
            end
        end
    end
    return result, state.cursor > #state.queue
end
local function descendants(root)
    local nodes = batch(walker(root))
    return nodes
end

local function finite(value, maximum)
    return type(value) == "number" and value == value and value >= 0 and value <= maximum
end

local function validName(name)
    return type(name) == "string" and #name > 0 and #name <= 64 and not name:find("%c")
        and name:match("%S") ~= nil
end


local function trim(value)
    return type(value) == "string" and (value:match("^%s*(.-)%s*$")) or value
end

local function wordByte(value)
    return value ~= "" and value:match("[%w_]") ~= nil
end

local function replaceSegment(text, aliases, nickname)
    local result, cursor = {}, 1
    while cursor <= #text do
        local first, last
        for _, alias in ipairs(aliases) do
            local search = cursor
            while true do
                local startAt, endAt = text:find(alias, search, true)
                if not startAt then break end
                local before = startAt > 1 and text:sub(startAt - 1, startAt - 1) or ""
                local after = endAt < #text and text:sub(endAt + 1, endAt + 1) or ""
                if not wordByte(before) and not wordByte(after) then
                    if not first or startAt < first or (startAt == first and endAt > last) then first, last = startAt, endAt end
                    break
                end
                search = startAt + 1
            end
        end
        if not first then result[#result + 1] = text:sub(cursor); break end
        result[#result + 1], result[#result + 2] = text:sub(cursor, first - 1), nickname
        cursor = last + 1
    end
    return table.concat(result)
end

-- Preserve RichText tags and only replace visible text segments.
local function replaceVisibleText(text, aliases, nickname)
    local result, cursor = {}, 1
    while cursor <= #text do
        local openAt, closeAt = text:find("<[^>]*>", cursor)
        if not openAt then result[#result + 1] = replaceSegment(text:sub(cursor), aliases, nickname); break end
        result[#result + 1] = replaceSegment(text:sub(cursor, openAt - 1), aliases, nickname)
        result[#result + 1] = text:sub(openAt, closeAt)
        cursor = closeAt + 1
    end
    return table.concat(result)
end

local function asset(value)
    if type(value) == "number" then
        if not finite(value, MAX_NUMBER) or value < 1 or value ~= math.floor(value) then return nil end
        value = string.format("%.0f", value)
    end
    if type(value) ~= "string" then return nil end
    local id = value:match("^rbxassetid://([1-9]%d*)$") or value:match("^([1-9]%d*)$")
    if not id or #id > 18 then return nil end
    return "rbxassetid://" .. id
end

-- Apply accepts data, not executable objects. Inspect unknown fields too so callbacks,
-- metatables and cycles cannot hide in a preset; next/raw access never invokes hooks.
local function dataOnly(value)
    local ancestors, entries = {}, 0
    local function visit(item, depth)
        local kind = type(item)
        if kind == "nil" or kind == "boolean" then return true end
        if kind == "string" then return #item <= 1024 end
        if kind == "number" then return item == item and item > -math.huge and item < math.huge end
        if kind == "userdata" and typeof and typeof(item) == "Vector2" then return true end
        if kind ~= "table" or getmetatable(item) ~= nil or ancestors[item] or depth > 16 then return false end
        ancestors[item] = true
        for key, child in next, item do
            entries = entries + 1
            if entries > LIMIT or (type(key) ~= "string" and type(key) ~= "number")
                or not visit(key, depth + 1) or not visit(child, depth + 1) then return false end
        end
        ancestors[item] = nil
        return true
    end
    return visit(value, 1)
end

local function field(data, first, second, third)
    local value = rawget(data, first)
    if value == nil and second then value = rawget(data, second) end
    if value == nil and third then value = rawget(data, third) end
    return value
end

local function mapped(data, name)
    if data == nil then return nil, true end
    if type(data) ~= "table" or getmetatable(data) ~= nil then return nil, false end
    return rawget(data, name), true
end

local function vector(value)
    local x, y
    if value == nil then x, y = 0, 0
    else
        x, y = get(value, "X"), get(value, "Y")
        if x == nil then x = get(value, 1) end
        if y == nil then y = get(value, 2) end
    end
    if not finite(x, 1e6) or not finite(y, 1e6) or x ~= math.floor(x) or y ~= math.floor(y) then return nil end
    if Vector2 and Vector2.new then return Vector2.new(x, y) end
    return {X = x, Y = y} -- Native-free mock tests.
end

local function setting(config, key)
    if not config then return nil end
    if type(get(config, "Get")) == "function" then
        local ok, value = pcall(function() return config:Get(key) end)
        if ok and value ~= nil then return value end
    end
    local data = get(config, "data") or config
    local visuals = get(data, "visuals")
    return get(visuals, key) or get(data, key)
end

local function addAllowed(result, list)
    if type(list) ~= "table" then return end
    for key, value in pairs(list) do
        local name = type(key) == "number" and value or (value == true and key or nil)
        if validName(name) and name:match("^[%a][%w_]*$") then result[name] = true end
    end
end

function Visuals.new(context)
    assert(type(context) == "table" and context.scope and context.player, "Visuals requires scope and player")
    local self = setmetatable({scope = context.scope:Child(), player = context.player, config = context.config,
        resourceTargets = context.resourceTargets, traitTargets = context.traitTargets,
        traitImages = context.traitImages, traitDescriptors = context.traitDescriptors,
        traitGradientSources = context.traitGradientSources or {},
        runService = context.runService, clock = context.clock or tick or os.clock, animated = {},
        resourceFields = context.resourceFields or {}, factory = context.factory,
        allowedResources = {}, bindings = {}, decorations = {}, enabled = false, destroyed = false}, Visuals)
    addAllowed(self.allowedResources, DEFAULT_RESOURCES)
    addAllowed(self.allowedResources, context.allowedResources or context.resourceAllowlist)
    self.resourceAliases = {}
    for name in pairs(self.allowedResources) do
        self.resourceAliases[normalize(name)] = name
        local mappedField = normalize(self.resourceFields[name] or RESOURCE_FIELDS[name] or ("_resource" .. name))
        if mappedField ~= "resource" then self.resourceAliases[mappedField] = name end
        for _, alias in ipairs(RESOURCE_ALIASES[name] or {}) do self.resourceAliases[alias] = name end
    end
    self.scope:Add(function()
        self.destroyed = true
        self:_Stop()
    end)
    return self
end

function Visuals:_PlayerGui()
    return find(self.player, "PlayerGui") or get(self.player, "PlayerGui")
end

function Visuals:_Safe(object)
    local root = self:_PlayerGui()
    if not root or not object then return false end
    local node = object
    for _ = 1, 128 do
        if not node then return false end
        local name = normalize(get(node, "Name"))
        local kind = get(node, "ClassName")
        if kind == "Model" or kind == "WorldModel" or kind == "ViewportFrame" then return false end
        if name:find("sainthub", 1, true) then return false end
        for _, blocked in ipairs(BLOCKED) do
            if name:find(blocked, 1, true) then return false end
        end
        if node == root then return true end
        node = get(node, "Parent")
    end
    return false
end


function Visuals:_Character()
    return get(self.player, "Character")
end

function Visuals:_SafeCharacter(object)
    local character = self:_Character()
    local node = object
    for _ = 1, 64 do
        if not node then return false end
        if node == character then return character ~= nil end
        node = get(node, "Parent")
    end
    return false
end

function Visuals:_SafeTarget(object, kind)
    if kind == "nicknameHumanoid" then return isA(object, "Humanoid") and self:_SafeCharacter(object) end
    if kind == "nicknameText" then
        return (isA(object, "TextLabel") or isA(object, "TextButton")) and (self:_Safe(object) or self:_SafeCharacter(object))
    end
    return self:_Safe(object)
end

function Visuals:_NicknameAliases()
    local aliases, seen = {}, {}
    for _, value in ipairs({get(self.player, "DisplayName"), get(self.player, "Name")}) do
        if validName(value) and not seen[value] then aliases[#aliases + 1], seen[value] = value, true end
    end
    table.sort(aliases, function(a, b) return #a > #b end)
    return aliases
end

function Visuals:_NicknameText(object, nickname, aliases)
    local record = self.bindings[object]
    local text = record and record.kind == "nicknameText" and record.baseline.Text or get(object, "Text")
    if type(text) ~= "string" or text == "" then return nil end
    local replaced = replaceVisibleText(text, aliases, nickname)
    return replaced ~= text and replaced or nil
end

function Visuals:_Descriptor(value)
    local name, descriptor
    if type(value) == "string" then
        if not validName(value) then return nil, "trait name must be 1..64 printable characters" end
        name = value
        local descriptors = self.traitDescriptors or setting(self.config, "traitDescriptors")
        local images = self.traitImages or setting(self.config, "traitImages")
        local valid
        descriptor, valid = mapped(descriptors, name)
        if not valid then return nil, "trait mappings must be plain tables" end
        if descriptor == nil then
            descriptor, valid = mapped(images, name)
            if not valid then return nil, "trait mappings must be plain tables" end
        end
        if descriptor == nil then descriptor = TraitIcons.default(name) end
        if descriptor == nil then return nil, "trait icon unavailable" end
        if type(descriptor) ~= "table" then descriptor = {image = descriptor} end
    elseif type(value) == "table" then
        if not dataOnly(value) then return nil, "trait descriptor must be bounded plain data" end
        descriptor, name = value, rawget(value, "name")
        if name ~= nil and not validName(name) then return nil, "invalid trait name" end
    else return nil, "trait must be a name or image descriptor" end
    if not dataOnly(descriptor) then return nil, "trait descriptor must be bounded plain data" end
    local image = asset(field(descriptor, "image", "Image", "assetId"))
    if not image then return nil, "trait image must be a positive Roblox asset ID" end
    local offset = vector(field(descriptor, "rectOffset", "ImageRectOffset"))
    local size = vector(field(descriptor, "rectSize", "ImageRectSize"))
    if not offset or not size then return nil, "invalid trait image rectangle" end
    local canonical = TraitIcons.default(name or rawget(descriptor, "name"))
    name = canonical and canonical.name or name
    return {name = name, image = image, ImageRectOffset = offset, ImageRectSize = size,
        gradient = TraitIcons.gradient({name = name})}
end

function Visuals:_Validate(spec)
    if not dataOnly(spec) then return nil, "spec must be bounded plain data without cycles or executable values" end
    if type(spec) ~= "table" or type(spec.enabled) ~= "boolean" then return nil, "enabled must be a boolean" end
    if spec.resources ~= nil and type(spec.resources) ~= "table" then return nil, "resources must be a table" end
    if spec.traits ~= nil and type(spec.traits) ~= "table" then return nil, "traits must be a table" end
    if spec.shiny ~= nil and type(spec.shiny) ~= "table" then return nil, "shiny must be a table" end
    local nickname = spec.nickname
    if nickname == nil then nickname = "" end
    nickname = trim(nickname)
    if type(nickname) ~= "string" or #nickname > 64 or nickname:find("%c") then
        return nil, "nickname must be at most 64 printable bytes"
    end
    local snapshot = {enabled = spec.enabled, nickname = nickname, resources = {}, traits = {}, shiny = {}}
    for name, value in pairs(spec.resources or {}) do
        if not self.allowedResources[name] then return nil, "unrecognized resource key" end
        if value ~= -1 then
            if not finite(value, MAX_NUMBER) then return nil, "resource number must be -1 or finite and in 0..1e15" end
            snapshot.resources[name] = string.format("%.0f", math.floor(value))
        end
    end
    for key, value in pairs(spec.traits or {}) do
        local slot = type(key) == "number" and key or (type(key) == "string" and tonumber(key))
        if not slot or slot < 1 or slot > 6 or slot ~= math.floor(slot)
            or (type(key) == "string" and key ~= tostring(slot)) then return nil, "trait slots must be 1..6" end
        if snapshot.traits[slot] then return nil, "duplicate trait slot" end
        local descriptor, message = self:_Descriptor(value)
        if not descriptor then return nil, message end
        snapshot.traits[slot] = descriptor
    end
    for key, value in pairs(spec.shiny or {}) do
        local slot = type(key) == "number" and key or (type(key) == "string" and tonumber(key))
        if not slot or slot < 1 or slot > 6 or slot ~= math.floor(slot)
            or (type(key) == "string" and key ~= tostring(slot)) or type(value) ~= "boolean" then
            return nil, "shiny slots must be booleans indexed 1..6"
        end
        if snapshot.shiny[slot] ~= nil then return nil, "duplicate shiny slot" end
        snapshot.shiny[slot] = value
    end
    return snapshot
end

function Visuals:_ResourceName(object, selected)
    if not (isA(object, "TextLabel") or isA(object, "TextButton")) then return nil end
    -- Recognize unselected currencies too: never climb out of Gold into an
    -- ancestor that happens to match a different selected resource.
    local aliases = self.resourceAliases
    -- Numeric counters only: a Gems frame's title and purchase buttons are not balances.
    local value = get(object, "Text")
    if type(value) ~= "string" or not value:gsub("<[^>]*>", ""):find("%d") then return nil end
    local node = object
    for depth = 1, 8 do
        if not node or node == self:_PlayerGui() then break end
        local semantic = normalize(get(node, "Name"))
        local exact = aliases[semantic]
        if exact then return selected[exact] and exact or nil end
        -- Only the text element itself may use these conventional counter suffixes.
        if depth <= 2 then
            for _, suffix in ipairs({"amount", "balance", "counter", "count", "value", "label", "text"}) do
                if semantic:sub(-#suffix) == suffix then
                    local matched = aliases[semantic:sub(1, #semantic - #suffix)]
                    if matched then return selected[matched] and matched or nil end
                end
            end
            for _, prefix in ipairs({"amount", "balance", "counter", "count", "value", "label", "text"}) do
                if semantic:sub(1, #prefix) == prefix then
                    local matched = aliases[semantic:sub(#prefix + 1)]
                    if matched then return selected[matched] and matched or nil end
                end
            end
        end
        node = get(node, "Parent")
    end
end

function Visuals:_Cards(nodes, localOnly)
    local cards, seen = {}, {}
    for slot = 1, 6 do cards[slot] = {} end
    local function add(card, slot)
        if not card or not cards[slot] or seen[card] then return end
        seen[card] = true
        cards[slot][#cards[slot] + 1] = card
    end
    local root = self:_PlayerGui()
    if not localOnly then
        local hotbar = find(find(find(find(root, "spawn_units"), "Lives"), "Frame"), "Units")
        for slot = 1, 6 do add(find(hotbar, tostring(slot)), slot) end
        local collection = root
        for _, name in ipairs({"collection", "grid", "List", "Outer", "UnitFrames"}) do
            collection = find(collection, name)
            if not collection then break end
        end
        -- One collection read per discovery batch, not six per descendant.
        for _, card in ipairs(collection and children(collection) or {}) do
            local list = find(card, "EquippedList")
            local marker = list and find(list, "Equipped")
            if isA(card, "ImageButton") and marker and get(marker, "Visible") == true then
                add(card, get(card, "LayoutOrder"))
            end
        end
    end
    for _, object in ipairs(nodes) do
        local semantic = normalize(get(object, "Name"))
        if semantic == "traiticons" or isA(object, "ImageButton") or semantic == "equipped"
            or (isA(object, "ImageLabel") and normalize(get(get(object, "Parent"), "Name")) == "traiticons") then
            local node = object
            for _ = 1, 24 do
                if not node or node == root then break end
                local parent = get(node, "Parent")
                local parentName = normalize(get(parent, "Name"))
                if parentName == "units" then add(node, tonumber(get(node, "Name"))); break end
                if parentName == "unitframes" or parentName == "unitsframes" then
                    local marker = find(find(node, "EquippedList"), "Equipped")
                    if isA(node, "ImageButton") and (not marker or get(marker, "Visible") == true) then
                        add(node, get(node, "LayoutOrder"))
                    end
                    break
                end
                node = parent
            end
        end
    end
    return cards
end

function Visuals:_DefaultTraits(slot, nodes, cards)
    local targets, seen = {}, {}
    for _, card in ipairs(cards[slot]) do
        local target = find(find(card, "Main"), "TraitIcons") or find(card, "TraitIcons")
        if target then targets[#targets + 1], seen[target] = target, true end
    end
    return targets
end

function Visuals:_BuildDesired(snapshot, suppliedNodes, localOnly)
    local desired = {}
    local root = self:_PlayerGui()
    if not root then return desired end
    local nodes = suppliedNodes or ((not self.resourceTargets or not self.traitTargets) and descendants(root) or {})
    local hasCards = next(snapshot.traits) ~= nil or next(snapshot.shiny) ~= nil
    local cards = hasCards and self:_Cards(nodes, localOnly) or nil
    local function put(object, kind, properties, text)
        if not desired[object] and not self.decorations[object] and self:_SafeTarget(object, kind) then
            desired[object] = {kind = kind, properties = properties, text = text}
        end
    end
    if snapshot.nickname ~= "" then
        local aliases = self:_NicknameAliases()
        for _, object in ipairs(nodes) do
            if isA(object, "TextLabel") or isA(object, "TextButton") then
                local text = self:_NicknameText(object, snapshot.nickname, aliases)
                if text then put(object, "nicknameText", {Text = text}, {nickname = snapshot.nickname, aliases = aliases}) end
            end
        end
        local character = self:_Character()
        if character and not localOnly then
            local humanoid = findClass(character, "Humanoid")
            if humanoid then put(humanoid, "nicknameHumanoid", {DisplayName = snapshot.nickname}) end
            for _, object in ipairs(descendants(character)) do
                if isA(object, "TextLabel") or isA(object, "TextButton") then
                    local text = self:_NicknameText(object, snapshot.nickname, aliases)
                    if text then put(object, "nicknameText", {Text = text}, {nickname = snapshot.nickname, aliases = aliases}) end
                end
            end
        elseif character then
            for _, object in ipairs(nodes) do
                if isA(object, "Humanoid") then put(object, "nicknameHumanoid", {DisplayName = snapshot.nickname}) end
            end
        end
    end
    if self.resourceTargets then
        local names = {}
        for name in pairs(snapshot.resources) do names[#names + 1] = name end
        table.sort(names)
        for _, name in ipairs(names) do
            local ok, targets = pcall(self.resourceTargets, name)
            if not ok or type(targets) ~= "table" then return nil, "resourceTargets must return an array" end
            for index, object in ipairs(targets) do
                if index > LIMIT then break end
                if isA(object, "TextLabel") or isA(object, "TextButton") then
                    put(object, "resource", {Text = snapshot.resources[name]})
                end
            end
        end
    else
        for _, object in ipairs(nodes) do
            local name = self:_ResourceName(object, snapshot.resources)
            if name then put(object, "resource", {Text = snapshot.resources[name]}) end
        end
    end
    for slot = 1, 6 do
        if snapshot.shiny[slot] then
            for _, card in ipairs(cards[slot]) do
                if isA(card, "GuiObject") then
                    put(card, "shinyBadge", {}, {image = "rbxassetid://125052305077571"})
                end
            end
        end
        local descriptor = snapshot.traits[slot]
        if descriptor then
            local targets
            if self.traitTargets then
                local ok
                ok, targets = pcall(self.traitTargets, slot)
                if not ok or type(targets) ~= "table" then return nil, "traitTargets must return an array" end
            else targets = self:_DefaultTraits(slot, nodes, cards) end
            for index, target in ipairs(targets) do
                if index > LIMIT then break end
                if self:_Safe(target) then
                    local container, images, textObjects = target, {}, {}
                    if isA(target, "ImageLabel") and normalize(get(target, "Name")) ~= "traiticons" then
                        images[1] = target
                        container = get(target, "Parent")
                        if normalize(get(container, "Name")) ~= "traiticons" then container = nil end
                    elseif isA(target, "GuiObject") then
                        if isA(target, "ImageLabel") then images[#images + 1] = target end
                        if isA(target, "TextLabel") or isA(target, "TextButton") then textObjects[#textObjects + 1] = target end
                        for _, object in ipairs(descendants(target)) do
                            if isA(object, "ImageLabel") and not self.decorations[object] then images[#images + 1] = object end
                            if isA(object, "TextLabel") or isA(object, "TextButton") then textObjects[#textObjects + 1] = object end
                        end
                    else container = nil end
                    for _, object in ipairs(textObjects) do
                        if object ~= container then put(object, "traitText", {Visible = false}) end
                    end
                    if #images > 0 then
                        for index, image in ipairs(images) do
                            if index == 1 then
                                put(image, "traitImage", {Image = descriptor.image, ImageRectOffset = descriptor.ImageRectOffset,
                                    ImageRectSize = descriptor.ImageRectSize, Visible = true}, descriptor)
                                if descriptor.gradient then
                                    for _, gradient in ipairs(children(image)) do
                                        if isA(gradient, "UIGradient") and not self.decorations[gradient] then
                                            -- The game owns Color/Rotation and animates them.
                                            -- Hide it behind our reversible copy, never fight it.
                                            put(gradient, "traitGradient", {Enabled = false})
                                        end
                                    end
                                end
                            else put(image, "traitHidden", {Visible = false}) end
                        end
                        if container then
                            local properties = {Visible = true}
                            if isA(container, "TextLabel") or isA(container, "TextButton") then properties.Text = "" end
                            put(container, "traitContainer", properties)
                        end
                    elseif container and isA(container, "GuiObject") then
                        local properties = {Visible = true}
                        if isA(container, "TextLabel") or isA(container, "TextButton") then properties.Text = "" end
                        put(container, "traitIcon", properties, descriptor)
                    end
                end
            end
        end
    end
    return desired
end

function Visuals:_Write(record, property, value)
    if get(record.object, property) == value then return true end
    record.guard[property] = true
    local ok = pcall(function() record.object[property] = value end)
    record.guard[property] = nil
    return ok
end

function Visuals:_Release(object)
    local record = self.bindings[object]
    if record then record.scope:Destroy() end
end

function Visuals:_Animate(gradient, enabled)
    self.animated[gradient] = enabled and true or nil
    if enabled then
        local color = TraitIcons.rainbow(self.clock())
        if color then gradient.Color = color end
    end
    if not next(self.animated) then
        if self.animationScope then self.animationScope:Destroy() end
        return
    end
    if self.animationScope or not self.activeScope then return end
    local runService = self.runService
    if not runService and game then
        local ok, service = pcall(function() return game:GetService("RunService") end)
        if ok then runService = service end
    end
    local signal = get(runService, "RenderStepped")
    if not signal then return end
    local scope = self.activeScope:Child()
    self.animationScope = scope
    scope:Add(function() if self.animationScope == scope then self.animationScope = nil end end)
    scope:Connect(signal, function()
        if not self.enabled then return end
        local color = TraitIcons.rainbow(self.clock())
        if not color then return end
        for current in pairs(self.animated) do
            if get(current, "Parent") and get(current, "Enabled") then
                pcall(function() current.Color = color end)
            end
        end
    end)
end

function Visuals:_Gradient(record, icon, descriptor)
    local color = descriptor.gradient
    local gradient = record.gradient
    if gradient and gradient.Parent ~= icon then
        self:_Animate(gradient, false)
        if record.gradientScope then record.gradientScope:Destroy(); record.gradientScope = nil end
        record.gradientSource, record.gradientName = nil, nil
        self.decorations[gradient], record.gradient = nil, nil
        gradient:Destroy()
        gradient = nil
    end
    if color and not gradient then
        local ok, created = pcall(function()
            return self.factory and self.factory("UIGradient") or Instance.new("UIGradient")
        end)
        if not ok or not isA(created, "UIGradient") then return end
        gradient = created
        self.decorations[gradient], record.gradient = true, gradient
        gradient.Name = "SaintHubTraitGradient"
        gradient.Parent = icon
    end
    if gradient then
        gradient.Enabled = color ~= nil
        local source = color and self.traitGradientSources[descriptor.name] or nil
        if record.gradientSource ~= source or record.gradientName ~= descriptor.name then
            if record.gradientScope then record.gradientScope:Destroy(); record.gradientScope = nil end
            record.gradientSource, record.gradientName = source, descriptor.name
            if source then
                local scope = record.scope:Child()
                record.gradientScope = scope
                for _, property in ipairs({"Color", "Offset", "Transparency"}) do
                    local function sync()
                        if get(gradient, "Parent") == icon then
                            pcall(function() gradient[property] = source[property] end)
                        end
                    end
                    sync()
                    local ok, changed = pcall(function() return source:GetPropertyChangedSignal(property) end)
                    if ok and changed and (property ~= "Color" or not TraitIcons.mythic(descriptor.name)) then
                        scope:Connect(changed, sync)
                    end
                end
            end
        end
        if color then
            if not source then gradient.Color = color end
            -- Native make_trait_icon: Mythic borders always face 45 degrees.
            gradient.Rotation = TraitIcons.mythic(descriptor.name) and 45 or (source and get(source, "Rotation") or 0)
        end
        self:_Animate(gradient, color ~= nil and TraitIcons.mythic(descriptor.name))
    end
end

function Visuals:_Decoration(record, descriptor)
    if record.decoration and get(record.decoration, "Parent") ~= record.object then
        local previous = record.decoration
        self.decorations[previous], record.decoration = nil, nil
        pcall(function() previous:Destroy() end)
    end
    if record.decoration then
        pcall(function()
            record.decoration.Image = descriptor.image
            if record.kind ~= "shinyBadge" then
                record.decoration.ImageRectOffset = descriptor.ImageRectOffset
                record.decoration.ImageRectSize = descriptor.ImageRectSize
            end
        end)
        self:_Gradient(record, record.decoration, descriptor)
        return
    end
    local ok, icon = pcall(function()
        if self.factory then return self.factory("ImageLabel") end
        if Instance and Instance.new then return Instance.new("ImageLabel") end
    end)
    if not ok or not icon or not isA(icon, "ImageLabel") then return end
    self.decorations[icon], record.decoration = true, icon
    local configured = pcall(function()
        local shiny = record.kind == "shinyBadge"
        icon.Name = shiny and "SaintHubShinyBadge" or "SaintHubTraitIcon"
        icon.Image = descriptor.image
        if not shiny then
            icon.ImageRectOffset = descriptor.ImageRectOffset
            icon.ImageRectSize = descriptor.ImageRectSize
        end
        icon.BackgroundTransparency = 1
        icon.BorderSizePixel = 0
        icon.ImageTransparency = 0
        icon.Visible = true
        icon.ZIndex = (get(record.object, "ZIndex") or 1) + 1
        local automatic = get(record.object, "AutomaticSize")
        local autoSized = Enum and (automatic == Enum.AutomaticSize.X or automatic == Enum.AutomaticSize.Y or automatic == Enum.AutomaticSize.XY)
        if UDim2 then
            if shiny then
                icon.AnchorPoint = Vector2.new(1, 0)
                icon.Position = UDim2.new(1, -3, 0, 3)
                icon.Size = UDim2.fromOffset(17, 17)
            else
                icon.Size = autoSized and UDim2.fromOffset(18, 18) or UDim2.fromScale(1, 1)
            end
        end
        if Color3 and Color3.new then icon.ImageColor3 = Color3.new(1, 1, 1) end
        local aspect
        if self.factory then aspect = self.factory("UIAspectRatioConstraint")
        elseif Instance and Instance.new then aspect = Instance.new("UIAspectRatioConstraint") end
        if aspect and isA(aspect, "UIAspectRatioConstraint") then aspect.AspectRatio = 1; aspect.Parent = icon end
        icon.Parent = record.object
    end)
    if not configured then
        self.decorations[icon], record.decoration = nil, nil
        pcall(function() icon:Destroy() end)
    else
        self:_Gradient(record, icon, descriptor)
    end
end

function Visuals:_Bind(object, desired)
    local record = self.bindings[object]
    if record and record.kind ~= desired.kind then self:_Release(object); record = nil end
    if not record then
        record = {object = object, kind = desired.kind, scope = self.activeScope:Child(), baseline = {},
            guard = {}, properties = {}}
        self.bindings[object] = record
        -- Added first: Scope disconnects listeners before restoring properties.
        record.scope:Add(function()
            if self.bindings[object] == record then self.bindings[object] = nil end
            for property, value in pairs(record.baseline) do self:_Write(record, property, value) end
            if record.gradient then
                self:_Animate(record.gradient, false)
                self.decorations[record.gradient] = nil
                record.gradient:Destroy()
            end
            if record.decoration then
                self.decorations[record.decoration] = nil
                pcall(function() record.decoration:Destroy() end)
                record.decoration = nil
            end
        end)
        local ancestry = get(object, "AncestryChanged")
        if ancestry then record.scope:Connect(ancestry, function()
            if not self:_SafeTarget(object, record.kind) then self:_Release(object) end
        end) end
        local destroying = get(object, "Destroying")
        if destroying then record.scope:Connect(destroying, function() self:_Release(object) end) end
        local removed = (desired.kind == "traitIcon" or desired.kind == "traitContainer" or desired.kind == "shinyBadge")
            and get(object, "ChildRemoved")
        if removed then record.scope:Connect(removed, function(child)
            if not self.enabled or self.bindings[object] ~= record or not isA(child, "ImageLabel") then return end
            if child == record.decoration then
                self.decorations[child], record.decoration = nil, nil
                -- Don't destroy recursively inside the game's Parent/Destroy
                -- notification. Own the orphan until the deferred cleanup.
                local cleanup = record.scope:Child()
                cleanup:Add(child)
                cleanup:Delay(0, function() cleanup:Destroy() end)
            end
            if record.refreshQueued then return end
            record.refreshQueued = true
            record.scope:Delay(0, function()
                record.refreshQueued = nil
                if not self.enabled or self.bindings[object] ~= record or not self:_SafeTarget(object, record.kind) then return end
                local nodes = descendants(object)
                nodes[#nodes + 1] = object
                local replacement = self:_BuildDesired(self.snapshot, nodes, true)
                if replacement then for target, value in pairs(replacement) do self:_Bind(target, value) end end
            end)
        end) end
    end
    record.properties, record.text = desired.properties, desired.text
    for property, value in pairs(desired.properties) do
        if record.baseline[property] == nil then
            record.baseline[property] = get(object, property)
            local ok, signal = pcall(function() return object:GetPropertyChangedSignal(property) end)
            if ok and signal then record.scope:Connect(signal, function()
                if record.guard[property] or self.bindings[object] ~= record then return end
                if not self.enabled or not self:_SafeTarget(object, record.kind) then self:_Release(object); return end
                record.baseline[property] = get(object, property)
                if record.kind == "nicknameText" and property == "Text" then
                    local details = record.text
                    local replacement = self:_NicknameText(object, details.nickname, details.aliases)
                    if not replacement then self:_Release(object); return end
                    record.properties.Text = replacement
                end
                self:_Write(record, property, record.properties[property])
            end) end
        end
        self:_Write(record, property, value)
    end
    if desired.kind == "traitIcon" or desired.kind == "shinyBadge" then self:_Decoration(record, desired.text) end
    if desired.kind == "traitImage" then self:_Gradient(record, object, desired.text) end
end

function Visuals:_Reconcile(desired)
    if self.reconciling then return end
    self.reconciling = true
    local stale = {}
    for object in pairs(self.bindings) do if not desired[object] then stale[#stale + 1] = object end end
    for _, object in ipairs(stale) do self:_Release(object) end
    for object, target in pairs(desired) do self:_Bind(object, target) end
    self.reconciling = false
end

-- Coalesce a burst of clone/parent notifications, then visit each branch once
-- in small yielding batches. Preview parts and our own decorations never enter it.
function Visuals:_QueueBranch(object)
    self.pendingBranches = self.pendingBranches or {}
    self.pendingBranches[object] = true
    if self.eventScope then return end
    local scope = self.activeScope:Child()
    self.eventScope = scope
    scope:Add(function() if self.eventScope == scope then self.eventScope = nil end end)
    scope:Spawn(function()
        -- task.spawn starts immediately in Roblox (unlike the local mock).
        -- Yield before reading pending so one native clone burst is coalesced.
        task.wait()
        local processed, buffered = 0, {}
        local function flush()
            if #buffered == 0 or not scope.alive or not self.enabled then return end
            local desired = self:_BuildDesired(self.snapshot, buffered, true)
            buffered = {}
            if desired then for target, value in pairs(desired) do self:_Bind(target, value) end end
        end
        while scope.alive and self.enabled and next(self.pendingBranches) do
            local pending = self.pendingBranches
            self.pendingBranches = {}
            for branch in pairs(pending) do
                if not scope.alive or not self.enabled then return end
                processed = processed + 1
                local node, covered = get(branch, "Parent"), false
                for _ = 1, 128 do
                    if not node then break end
                    if pending[node] then covered = true; break end
                    node = get(node, "Parent")
                end
                if not covered and (self:_Safe(branch) or self:_SafeCharacter(branch)) then
                    local state, complete = walker(branch), false
                    while scope.alive and self.enabled and not complete do
                        local nodes
                        nodes, complete = batch(state, 200)
                        if state.includeRoot ~= true then nodes[#nodes + 1] = branch; state.includeRoot = true end
                        for _, node in ipairs(nodes) do buffered[#buffered + 1] = node end
                        processed = processed + #nodes
                        if #buffered >= 200 then flush() end
                        if not complete or processed >= 200 then flush(); task.wait(); processed = 0 end
                    end
                end
                if processed >= 200 then flush(); task.wait(); processed = 0 end
            end
            flush()
        end
        scope:Destroy()
    end)
end

function Visuals:_Watch()
    local signal = get(self.player, "DescendantAdded") or get(self:_PlayerGui(), "DescendantAdded")
    if signal then self.activeScope:Connect(signal, function(object)
        if not self.enabled or self.reconciling or self.decorations[object] then return end
        if isA(object, "UIGradient") then
            local parent = get(object, "Parent")
            local record = self.bindings[parent]
            if record and record.kind == "traitImage" then self:_QueueBranch(parent) end
            return
        end
        if not (isA(object, "GuiObject") or isA(object, "ScreenGui") or isA(object, "PlayerGui")) then return end
        if object ~= self:_PlayerGui() and not self:_Safe(object) then return end
        if isA(object, "TextLabel") or isA(object, "TextButton") then
            -- Counters remain immediate, without discovering unrelated unit cards.
            local desired = self:_BuildDesired(self.snapshot, {object}, true)
            if desired then for target, value in pairs(desired) do self:_Bind(target, value) end end
        end
        self:_QueueBranch(object)
    end) end
    local function bindCharacter(character)
        if self.characterScope then self.characterScope:Destroy() end
        if not character or not self.activeScope then return end
        local scope = self.activeScope:Child()
        self.characterScope = scope
        scope:Add(function() if self.characterScope == scope then self.characterScope = nil end end)
        local added = get(character, "DescendantAdded")
        if added then scope:Connect(added, function(object)
            if not self.enabled or self.reconciling or self.snapshot.nickname == "" then return end
            if not (isA(object, "TextLabel") or isA(object, "TextButton") or isA(object, "Humanoid")) then return end
            local desired = self:_BuildDesired(self.snapshot, {object}, true)
            if desired then for target, value in pairs(desired) do self:_Bind(target, value) end end
        end) end
        local stale = {}
        for object, record in pairs(self.bindings) do
            if (record.kind == "nicknameHumanoid" or record.kind == "nicknameText") and not self:_SafeTarget(object, record.kind) then
                stale[#stale + 1] = object
            end
        end
        for _, object in ipairs(stale) do self:_Release(object) end
        local desired = self:_BuildDesired(self.snapshot, {}, true)
        if desired then for target, value in pairs(desired) do self:_Bind(target, value) end end
        if self.snapshot.nickname ~= "" then
            local humanoid = findClass(character, "Humanoid")
            if humanoid then self:_Bind(humanoid, {kind = "nicknameHumanoid", properties = {DisplayName = self.snapshot.nickname}}) end
            self:_QueueBranch(character)
        end
    end
    local characterAdded = get(self.player, "CharacterAdded")
    if characterAdded then self.activeScope:Connect(characterAdded, bindCharacter) end
    bindCharacter(self:_Character())
end

function Visuals:_ContinueScan(state, snapshot)
    if self.scanScope then self.scanScope:Destroy() end
    local scope = self.activeScope:Child()
    self.scanScope = scope
    scope:Add(function() if self.scanScope == scope then self.scanScope = nil end end)
    scope:Spawn(function()
        local complete = false
        while scope.alive and self.enabled and self.snapshot == snapshot and not complete do
            task.wait() -- yield between batches; no idle polling after discovery ends
            if not scope.alive then return end
            local nodes
            nodes, complete = batch(state)
            local desired = self:_BuildDesired(snapshot, nodes, true)
            if desired then for object, target in pairs(desired) do self:_Bind(object, target) end end
        end
        scope:Destroy()
    end)
end

function Visuals:_Stop()
    self.enabled, self.snapshot = false, nil
    local scope = self.activeScope
    self.activeScope = nil
    if scope then scope:Destroy() end
    self.pendingBranches = nil
end

-- Full replacement snapshot; omitted resources/slots restore their latest real presentation.
-- Apply() reads an optional config's visuals table, but never subscribes to config or enables itself.
function Visuals:Apply(spec)
    if self.destroyed or not self.scope.alive then return false, "destroyed" end
    if spec == nil then
        local config = self.config
        local data = get(config, "data") or config
        spec = setting(config, "visuals") or get(data, "visuals") or data
    end
    local snapshot, message = self:_Validate(spec)
    if not snapshot then return false, message end
    if not snapshot.enabled then return self:Disable() end
    if self.scanScope then self.scanScope:Destroy() end
    local state, nodes, complete
    if not self.resourceTargets or not self.traitTargets then
        local root = self:_PlayerGui()
        if root then state = walker(root); nodes, complete = batch(state) end
    end
    if nodes then
        -- Keep already-discovered late targets stable during a new batched scan.
        for object in pairs(self.bindings) do nodes[#nodes + 1] = object end
    end
    local desired
    desired, message = self:_BuildDesired(snapshot, nodes)
    if not desired then return false, message end
    self.snapshot, self.enabled = snapshot, true
    if not self.activeScope then
        self.activeScope = self.scope:Child()
        self:_Watch()
    end
    self:_Reconcile(desired)
    if state and not complete then self:_ContinueScan(state, snapshot) end
    return true, nil
end

function Visuals:Disable()
    self:_Stop()
    return true, nil
end

function Visuals:State()
    local count = 0
    for _ in pairs(self.bindings) do count = count + 1 end
    return {enabled = self.enabled, bindings = count}
end

function Visuals:Destroy()
    self.scope:Destroy()
    return true, nil
end

return Visuals
end

__modules["game/Webhook"] = function(require)
local Util = require("core/Util")
local Webhook = {}
Webhook.__index = Webhook

-- Never forward credentials to a proxy or follow an arbitrary supplied destination.
function Webhook.normalize(url)
    if type(url) ~= "string" or #url > 2048 then return nil end
    local host, path = Util.trim(url):match("^https://([%w%.%-]+)(/[^#%s]+)$")
    if not host then return nil end
    host = host:lower()
    if host ~= "discord.com" and host ~= "discordapp.com" and host ~= "canary.discord.com" and host ~= "ptb.discord.com" then return nil end
    local route, query = path:match("^([^?]+)%?(.*)$")
    route = (route or path):gsub("/$", "")
    local id, token = route:match("^/api/webhooks/(%d+)/([%w_-]+)$")
    if not id then id, token = route:match("^/api/v%d+/webhooks/(%d+)/([%w_-]+)$") end
    if not id then return nil end
    local thread, seen = nil, {}
    if query then
        if query == "" or query:sub(-1) == "&" then return nil end
        for entry in query:gmatch("[^&]+") do
            local name, value = entry:match("^([%w_]+)=([%w_]+)$")
            if not name or seen[name] then return nil end
            seen[name] = true
            if name == "wait" and (value == "true" or value == "false") then
                -- Always wait for Discord to validate and acknowledge the message.
            elseif name == "thread_id" and value:match("^%d+$") then thread = value
            else return nil end
        end
        if query:find("&&", 1, true) or query:sub(1, 1) == "&" then return nil end
    end
    return "https://discord.com/api/webhooks/" .. id .. "/" .. token .. "?wait=true" .. (thread and "&thread_id=" .. thread or "")
end

function Webhook.valid(url) return Webhook.normalize(url) ~= nil end

-- Discord counts UTF-16 units. Never cut a multibyte character in half.
function Webhook.text(value, limit)
    local text = tostring(value or ""):gsub("%z", "")
    local ok, length = pcall(utf8.len, text)
    if not ok or not length then text = text:gsub("[\128-\255]", "?") end
    local units, finish = 0, 0
    for offset, codepoint in utf8.codes(text) do
        local width = codepoint > 65535 and 2 or 1
        if units + width > limit then break end
        units = units + width
        finish = (utf8.offset(text, 2, offset) or (#text + 1)) - 1
    end
    return text:sub(1, finish)
end

function Webhook.new(context)
    return setmetatable({ runtime = context.runtime, config = context.config, adapter = context.adapter,
        scope = context.scope:Child(), settings = context.settings, busy = false, lastSent = -math.huge,
        timeout = Util.number(context.webhookTimeout, 20, 0.01, 30) }, Webhook)
end

function Webhook.resourceLines(adapter)
    local lines = {}
    local resources = adapter.Resources and adapter:Resources() or {}
    for _, resource in ipairs(resources) do
        local name = resource.name
        if type(name) == "string" and name:lower():gsub("%s+", "") ~= "holidaystars" then
            lines[#lines + 1] = string.format("%s: %s", Webhook.text(name, 100), Webhook.text(resource.value, 32))
            if #lines >= 32 then break end
        end
    end
    return lines
end

function Webhook:_Payload(event, rewards)
    local data = self.adapter:GameData()
    local description = string.format("**Player:** %s\n**Mode:** %s\n**Map:** %s",
        Webhook.text(self.adapter.player.Name, 100), Webhook.text(data.mode, 300), Webhook.text(data.location, 500))
    local lines = {}
    for name, count in pairs(rewards or {}) do
        lines[#lines + 1] = string.format("+%s %s", Webhook.text(count, 32), Webhook.text(name, 100))
        if #lines >= 100 then break end
    end
    table.sort(lines)
    local balances = Webhook.resourceLines(self.adapter)
    local fields = {{name = "Resources", value = #balances > 0 and Webhook.text(table.concat(balances, "\n"), 1024) or "—"}}
    if #lines > 0 then fields[#fields + 1] = {name = "Rewards", value = Webhook.text(table.concat(lines, "\n"), 1024)} end
    local wave = workspace:FindFirstChild("_wave_num")
    if wave then fields[#fields + 1] = {name = "Wave", value = Webhook.text(wave.Value, 64)} end
    return self.runtime:Codec().encode({ username = "Saint Hub", allowed_mentions = {parse = {}},
        embeds = {{title = Webhook.text("Saint Hub | " .. tostring(event), 256), description = description,
            color = 2236962, fields = fields}} })
end

local function duration(value)
    value = math.floor(tonumber(value) or 0)
    return string.format("%dm %02ds", math.floor(value / 60), value % 60)
end

local function rate(bucket)
    return bucket and bucket.matches > 0 and bucket.wins / bucket.matches * 100 or 0
end

local function rewardText(rewards, limit)
    local rows = {}; for name, value in pairs(rewards or {}) do rows[#rows + 1] = string.format("+%s %s", value, name) end
    table.sort(rows)
    local shown = {}; for index = 1, math.min(limit or 8, #rows) do shown[index] = rows[index] end
    if #rows > #shown then shown[#shown + 1] = string.format("+%d more", #rows - #shown) end
    return table.concat(shown, "\n")
end

function Webhook:_ReportPayload(report)
    local identity, progress, performance = report.identity or {}, report.progress or {}, report.performance or {}
    local title = (report.result == "victory" and "Victory" or (report.result == "defeat" and "Defeat" or "Match finished"))
        .. " · " .. (identity.location ~= "" and identity.location or identity.name ~= "" and identity.name or "Unknown map")
    local fields = {}
    local match = {identity.mode ~= "" and identity.mode or "unknown"}
    if identity.difficulty and identity.difficulty ~= "" then match[#match + 1] = identity.difficulty end
    if identity.weather and identity.weather ~= "" then match[#match + 1] = identity.weather end
    if progress.wave then match[#match + 1] = "Wave " .. tostring(math.floor(progress.wave))
        .. (progress.maxWave and "/" .. tostring(math.floor(progress.maxWave)) or "") end
    fields[#fields + 1] = {name = "Match", value = Webhook.text(table.concat(match, " · "), 1024)}
    if report.timing and report.timing.duration then fields[#fields + 1] = {name = "Time", value = duration(report.timing.duration)} end
    local rewards = rewardText(report.rewards, 8)
    if rewards ~= "" then fields[#fields + 1] = {name = "Rewards", value = Webhook.text(rewards, 1024)} end
    local metrics = {}
    if performance.kills then metrics[#metrics + 1] = "Kills: " .. tostring(math.floor(performance.kills)) end
    if performance.damage then metrics[#metrics + 1] = "Damage: " .. string.format("%.0f", performance.damage) end
    if #metrics > 0 then fields[#fields + 1] = {name = "Performance", value = table.concat(metrics, "\n")} end
    local snapshot, stats = report.stats, report.stats and report.stats.totals
    if stats and stats.matches > 0 then
        fields[#fields + 1] = {name = "All-time statistics", value = string.format("%d matches · %dW/%dL · %.1f%%\nStreak %d · best %d · avg %s\nKills %.0f · damage %.0f",
            stats.matches, stats.wins, stats.losses, rate(stats), stats.current_streak, stats.best_streak,
            stats.timed_matches > 0 and duration(stats.duration_seconds / stats.timed_matches) or "—",
            stats.kills or 0, stats.damage or 0)}
    end
    local session = snapshot and snapshot.session
    if session and session.matches > 0 then
        fields[#fields + 1] = {name = "Current session", value = string.format("%d matches · %dW/%dL · %.1f%%\nAvg %s · kills %.0f · damage %.0f",
            session.matches, session.wins, session.losses, rate(session),
            session.timed_matches > 0 and duration(session.duration_seconds / session.timed_matches) or "—",
            session.kills or 0, session.damage or 0)}
    end
    local map = snapshot and snapshot.maps and snapshot.maps[table.concat({identity.mode ~= "" and identity.mode or "unknown",
        identity.levelId ~= "" and identity.levelId or "unknown", identity.difficulty ~= "" and identity.difficulty or "normal"}, "|")]
    if map then
        fields[#fields + 1] = {name = "This map", value = string.format("%d runs · %dW/%dL · %.1f%% · avg %s",
            map.matches, map.wins, map.losses, rate(map), map.timed_matches > 0 and duration(map.duration_seconds / map.timed_matches) or "—")}
    end
    return self.runtime:Codec().encode({username = "Saint Hub", allowed_mentions = {parse = {}}, embeds = {{
        title = Webhook.text(title, 256), description = Webhook.text(identity.name or "", 4096),
        color = report.result == "victory" and 5763719 or (report.result == "defeat" and 15548997 or 2236962), fields = fields}}})
end

local function discordResponse(runtime, body)
    if type(body) ~= "string" or #body > 65536 then return {} end
    local ok, decoded = pcall(function() return runtime:Codec().decode(body) end)
    return ok and type(decoded) == "table" and decoded or {}
end

local function result(code, status, decoded, attempts)
    local discordCode = tonumber(decoded and decoded.code)
    if not discordCode or discordCode % 1 ~= 0 or discordCode < 0 or discordCode > 1000000 then discordCode = nil end
    -- Raw exception/body/URL is deliberately not retained, even in lastResult.
    return {ok = code == "sent", code = code, status = status or 0, discordCode = discordCode, attempts = attempts or 0}
end

function Webhook:Send(event, rewards, callback)
    local url = Webhook.normalize(self.config:Get("webhook.ds_url"))
    if not self.scope.alive then return false, result("cancelled") end
    if not url then return false, result("invalidUrl") end
    if type(self.runtime.request) ~= "function" then return false, result("unsupported") end
    if self.busy or os.clock() - self.lastSent < 2 then return false, result("busy") end
    local encoded, body = pcall(self._Payload, self, event, rewards)
    if not encoded then return false, result("payload") end
    self.busy, self.lastSent = true, os.clock()
    local request, completed, attempts = self.scope:Child(), false, 0
    self.pending = request
    request:Add(function()
        if self.pending == request then self.pending = nil; self.busy = false end
    end)
    local function finish(outcome)
        if completed or not request.alive then return end
        completed = true
        self.lastResult = outcome
        request:Destroy()
        if not outcome.ok then
            warn(string.format("[SaintHub webhook] %s; HTTP %d; Discord %s (credentials omitted)",
                outcome.code, outcome.status, tostring(outcome.discordCode or "-")))
        end
        if callback and self.scope.alive then
            local ok = pcall(callback, outcome)
            if not ok then warn("[SaintHub webhook] Result callback failed (details omitted)") end
        end
    end
    request:Delay(self.timeout, function() finish(result("timeout", 0, nil, attempts)) end)
    local deliver
    deliver = function()
        if not request.alive then return end
        attempts = attempts + 1
        local ok, status, response, headers = pcall(self.runtime.HTTP, self.runtime, url, "POST", body)
        if not request.alive then return end
        if not ok then finish(result("transport", 0, nil, attempts)); return end
        status = tonumber(status) or 0
        if status % 1 ~= 0 or status < 100 or status > 599 then status = 0 end
        local decoded = discordResponse(self.runtime, response)
        if status >= 200 and status < 300 then finish(result("sent", status, nil, attempts)); return end
        local code = status == 429 and "rateLimited" or (status == 0 and "response" or "http")
        -- Only retry an explicit rejection, not an ambiguous transport failure (duplicate messages).
        if status == 429 and attempts < 3 then
            local retry = tonumber(decoded.retry_after)
            for name, value in pairs(type(headers) == "table" and headers or {}) do
                if tostring(name):lower() == "retry-after" and not retry then retry = tonumber(value) end
            end
            if retry and retry == retry and retry >= 0 and retry <= 5 then
                request:Delay(math.max(0.25, retry), deliver)
                return
            end
        end
        finish(result(code, status, decoded, attempts))
    end
    request:Spawn(deliver)
    return true -- queued, not delivered; callback reports the actual outcome
end

function Webhook:SendReport(report, callback)
    local original = self._Payload
    self._Payload = function() return self:_ReportPayload(report) end
    local queued, immediate = self:Send("Match finished", nil, callback)
    self._Payload = original
    return queued, immediate
end

function Webhook:Destroy() self.scope:Destroy() end

return Webhook
end

return require("app/Main")
